D.ClientTexts.JournalSection[2023]={Name={["0fffc1730fb392b8:10"]="投掷赫利克斯"},Description={["e326d914b8a44113:158"]="伐木场巨怪会把赫利克斯从后背上揪下来，然后把这只地精扔向某个玩家，持续10秒。当赫利克斯扑到某个玩家脸上后，他会持续地用拳头捶这名玩家，造成近战伤害。"}}
D.ClientTexts.JournalSection[2024]={Name={["6c60b01c24d141e3:9"]="放置炸弹"}}
D.ClientTexts.JournalSection[2025]={Name={["285f2737ebf478ca:10"]="赫利克斯的雇员"},Description={["2e00b74f9c22ab0a:142"]="赫利克斯的四名雇员会出现在玩家头顶的一根木头上。他们每个人都会周期性地对某个玩家投掷黏性炸弹。"}}
D.ClientTexts.JournalSection[2026]={Name={["355b262b534e7104:24"]="第二阶段：我不需要他！"},Description={["188615ba292d0ff3:109"]="在伐木场巨怪死后，赫利克斯·破甲会跌落在地。这时候他会更加频繁地使用黏性炸弹。"}}
D.ClientTexts.JournalSection[2027]={Name={["7c9a0307d2fd46c8:4"]="跳跃"},Description={["1d1ad57fedaad050:172"]="赫利克斯会跳到一名玩家的脸上，持续10秒。随后赫利克斯会立即选择一个新玩家，再跳上去。当赫利克斯附着在玩家身上时，他会使用拳头进行近战攻击。"}}
D.ClientTexts.JournalSection[2028]={Name={["6c60b01c24d141e3:9"]="放置炸弹"}}
D.ClientTexts.JournalSection[2029]={Name={["285f2737ebf478ca:10"]="赫利克斯的雇员"},Description={["5083875d1d6aaba6:70"]="玩家头顶的横梁上会出现四名额外的赫利克斯雇员。"}}
