D.ClientTexts.JournalSection[2188]={Name={["4e7c964f0a538d44:14"]="闪电澎湃"}}
D.ClientTexts.JournalSection[2189]={Name={["a83e2a27974e13e2:7"]="挤压"}}
D.ClientTexts.JournalSection[2190]={Name={["c472bd41f29f495e:14"]="疲倦诅咒"}}
D.ClientTexts.JournalSection[2191]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[2192]={Name={["d393d0888088576f:11"]="黑暗裂隙"}}
D.ClientTexts.JournalSection[2432]={Name={["45e40169a9fdab1a:19"]="极限风暴"}}
D.ClientTexts.JournalSection[2193]={Name={["d393d0888088576f:11"]="黑暗裂隙"}}
D.ClientTexts.JournalSection[2194]={Name={["1fd5055f5800c52a:18"]="石语者埃鲁纳克"},Description={["f287ca45fb12a3e6:257"]="遭遇战一开始，蛊心魔古厄夏会附在石语者埃鲁纳克的头上，将其控制住。在受到蛊心魔古厄夏的控制期间，埃鲁纳克会同玩家战斗。当埃鲁纳克的生命值处于50%时，蛊心魔古厄夏会从埃鲁纳克的头部脱离。随后玩家才可以和蛊心魔古厄夏战斗。"}}
D.ClientTexts.JournalSection[2195]={Name={["6b3d0d822a610259:11"]="余烬一击"}}
D.ClientTexts.JournalSection[2196]={Name={["f136eff3e387e64e:11"]="熔岩喷溅"}}
D.ClientTexts.JournalSection[2197]={Name={["6c9dc4daed70eaf5:8"]="熔岩箭"}}
D.ClientTexts.JournalSection[2198]={Name={["57b8169efaa719bf:11"]="大地碎片"}}
D.ClientTexts.JournalSection[2199]={Name={["04d92f9625d3d37b:18"]="蛊心魔古厄夏"}}
D.ClientTexts.JournalSection[2200]={Name={["f7fc147fe84ef8c0:11"]="吸收魔法"}}
D.ClientTexts.JournalSection[2201]={Name={["c7384389d75f15ec:7"]="意识迷雾"}}
D.ClientTexts.JournalSection[2202]={Name={["e8eb484e7e0908fd:16"]="无限痛苦"}}
D.ClientTexts.JournalSection[2203]={Name={["6b6ef1d35a4a9d4e:7"]="奴役"}}
D.ClientTexts.JournalSection[2204]={Name={["1eb03362973f1061:24"]="第一阶段：下等的入侵者！"},Description={["aa5e7cc1d87597ae:176"]="玩家与耐普图隆交谈后开启战斗，然后同意在他净化周围水体时保护他。如果耐普图隆死亡，战斗将被重置。\r\n\r\n第一阶段持续60秒。"}}
D.ClientTexts.JournalSection[2205]={Name={["ba38ad5e76f33bbf:17"]="深海鱼人入侵者"},Description={["51321db76fcca8b6:139"]="遭遇战一开始，会有一组6个深海鱼人入侵者游进房间，开始攻击耐普图隆。这个阶段总计会游进三组鱼人。"}}
D.ClientTexts.JournalSection[2206]={Name={["661dff4e9663215d:17"]="残忍的精神鞭笞者"},Description={["e5c1eeb3c0784cec:106"]="当遭遇战开始5秒钟后，一只残忍的精神鞭笞者会进入房间。这个阶段总计会有三只残忍的精神鞭笞者出现。"}}
D.ClientTexts.JournalSection[2207]={Name={["fb3a039c15b70755:10"]="暗影箭"}}
D.ClientTexts.JournalSection[2208]={Name={["c1b0032d1f586590:10"]="脑刺"}}
D.ClientTexts.JournalSection[2209]={Name={["834a24f0baf02fa9:12"]="暗影迷雾"}}
D.ClientTexts.JournalSection[2210]={Name={["18d7a8c93a0db1e4:18"]="顽强的巨兽"},Description={["5cbbbb6380e91738:74"]="当本阶段开始大约15秒后，另一只此类生物会进入房间。"}}
D.ClientTexts.JournalSection[2211]={Name={["6278a381ce5fb158:11"]="暗影冲击"}}
D.ClientTexts.JournalSection[2212]={Name={["df82da4e6d0105f9:11"]="枯萎喷射"}}
D.ClientTexts.JournalSection[2213]={Name={["c019d7305b6135a9:24"]="第二阶段：巨兽回归"},Description={["71529a6160bcf6d8:217"]="当第二阶段开始后，三只无面者工兵会从天花板上跳下来，开始对耐普图隆施法。厄祖玛特随后会将自己与房间相连，但是此时无法攻击他。杀掉全部三只无面者工兵即可进入下一阶段。"}}
D.ClientTexts.JournalSection[2214]={Name={["de48eb8ee236bb8b:11"]="枯萎兽"},Description={["a0c5db618c1ca628:29"]="这些敌人的移动速度非常慢。"}}
D.ClientTexts.JournalSection[2433]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[2215]={Name={["067b1d43dc7f0b20:11"]="恐怖光环"}}
D.ClientTexts.JournalSection[2216]={Name={["13ad5505758e8a56:6"]="厄祖玛特"},Description={["bc3ba55fed82f05a:21"]="第2阶段中无法被攻击。"}}
D.ClientTexts.JournalSection[2217]={Name={["87ee4254f8823f61:14"]="厄祖玛特的枯萎"}}
D.ClientTexts.JournalSection[2218]={Name={["b995c1967f98a5f1:14"]="无面者工兵"},Description={["d8e0b86974be464a:83"]="这些怪物会持续地向耐普图隆发射射线，杀掉全部三只无面者工兵即可结束第二阶段。"}}
D.ClientTexts.JournalSection[2219]={Name={["3394767f623bc18e:21"]="第三阶段：海潮涌动"},Description={["fb4ddf218b293b14:204"]="当三只无面者工兵全部被击杀后进入第三阶段。厄祖玛特会将他的毒气注入整个房间，这时候可以攻击他。当厄祖马特剩余生命值低于10%时，他就会撤退，玩家获得胜利。"}}
D.ClientTexts.JournalSection[2220]={Name={["13ad5505758e8a56:6"]="厄祖玛特"},Description={["6f79870fa48fda56:22"]="厄祖玛特可以被攻击了。"}}
D.ClientTexts.JournalSection[2221]={Name={["87ee4254f8823f61:14"]="厄祖玛特的枯萎"}}
D.ClientTexts.JournalSection[2222]={Name={["6c6d9e3a844b1e71:8"]="耐普图隆"}}
D.ClientTexts.JournalSection[2223]={Name={["4a5a6979241bdcf4:10"]="海潮涌动"}}
D.ClientTexts.JournalSection[2356]={Name={["103da43c6f225157:5"]="地震"}}
D.ClientTexts.JournalSection[2357]={Name={["4cb1750f1c3fda44:12"]="愤怒之土"},Description={["17a350221db7cff1:49"]="罗姆欧格的地震技能会召唤出愤怒之土。"}}
D.ClientTexts.JournalSection[2358]={Name={["548fe9dbcbf82124:11"]="悲哀锁链"},Description={["75e58d61ab2b563a:293"]="当剩余生命值达到66%和33%时，摧骨者罗姆欧格会召唤被称之为悲哀锁链的链状物质，将玩家拉近到他身旁，并使其定身。玩家必须选中并摧毁悲哀锁链来免于定身。罗姆欧格会在施放悲哀锁链后立即使用碎颅。"}}
D.ClientTexts.JournalSection[2359]={Name={["320a98ac1e9c815b:15"]="碎颅"}}
D.ClientTexts.JournalSection[2360]={Name={["9b5d1142bd5da0e1:14"]="致伤打击"}}
D.ClientTexts.JournalSection[2361]={Name={["328157aafee7ce9b:9"]="进化"}}
D.ClientTexts.JournalSection[2362]={Name={["10d887cdb318201a:18"]="加速光环"}}
D.ClientTexts.JournalSection[2363]={Name={["fa33db26ca817dd5:11"]="黑暗命令"}}
D.ClientTexts.JournalSection[2364]={Name={["a8145940c8cb4f0b:14"]="暮光狂热者"}}
D.ClientTexts.JournalSection[2365]={Name={["3ff48244edc8876f:22"]="祈求跪拜"}}
D.ClientTexts.JournalSection[2366]={Name={["78aef8f537154332:21"]="进化的暮光狂热者"},Description={["ceb18e6ed1f0f7e9:90"]="如果暮光狂热者获得100层进化效果，就会变成进化的暮光狂热者。"}}
D.ClientTexts.JournalSection[2367]={Name={["40b24a6a324bf3ed:10"]="力场冲击"}}
D.ClientTexts.JournalSection[2368]={Name={["d971817d1bffc6c0:13"]="重力打击"}}
D.ClientTexts.JournalSection[2369]={Name={["d8f3f89fb4d5b734:13"]="痛苦旋风"}}
D.ClientTexts.JournalSection[2370]={Name={["d9ceb17d253851b2:12"]="暗影突击"}}
D.ClientTexts.JournalSection[2371]={Name={["414b3138103714a5:16"]="水银护甲"}}
D.ClientTexts.JournalSection[2372]={Name={["9524ab72a45fafaf:27"]="过热的水银护甲"}}
D.ClientTexts.JournalSection[2373]={Name={["bfe62a5abcf139e9:8"]="热浪"}}
D.ClientTexts.JournalSection[2374]={Name={["d610190deafaae34:12"]="灼热金属"}}
D.ClientTexts.JournalSection[2375]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"}}
D.ClientTexts.JournalSection[2376]={Name={["018a9a640c732151:9"]="熔岩喷射"}}
D.ClientTexts.JournalSection[2377]={Name={["822c8615b4cde4be:11"]="束缚烈焰"},Description={["9e4401dfb9ef5494:98"]="当熔岩从炉架中迸发出来时，会有三个束缚烈焰出现并攻击附近的敌对玩家。"}}
D.ClientTexts.JournalSection[2378]={Name={["56ac5854799468fb:15"]="狂暴冲锋"}}
D.ClientTexts.JournalSection[2379]={Name={["34a78cef5b8e5b4c:10"]="火焰突变"}}
D.ClientTexts.JournalSection[2380]={Name={["bd71f29ca82545a5:14"]="恐吓咆哮"}}
D.ClientTexts.JournalSection[2381]={Name={["0e1752682285456f:9"]="熔岩喷吐"}}
D.ClientTexts.JournalSection[2382]={Name={["3a42a053d96f9292:20"]="来福、斑点和旺财"},Description={["b2087427f757de2e:128"]="在英雄难度下，如花的三只小崽子中会有两只一起出战。与其中任何一只开战都会引来如花的攻击。"}}
D.ClientTexts.JournalSection[2383]={Name={["007c42c96ea1303e:9"]="熔岩流淌"}}
D.ClientTexts.JournalSection[2384]={Name={["1af00ea096fae1a9:20"]="小型火焰吐息"}}
D.ClientTexts.JournalSection[2385]={Name={["0f8c285c547c7e29:14"]="变形"},Description={["ac67353f29206d2a:170"]="当升腾者领主奥西迪斯的生命值降到69%和34%时，他会随机选择一个奥西迪斯之影跳进去，与其交换位置。"}}
D.ClientTexts.JournalSection[2386]={Name={["bc4ad322edbf22b7:9"]="碎石拳"}}
D.ClientTexts.JournalSection[2387]={Name={["9d3ce3e6e23b9acb:18"]="暮光腐蚀"}}
D.ClientTexts.JournalSection[2388]={Name={["c47fcb1ff01671dc:11"]="雷霆一击"}}
D.ClientTexts.JournalSection[2389]={Name={["6129d8a2fe63e1a3:16"]="奥西迪斯之影"}}
D.ClientTexts.JournalSection[2390]={Name={["026663917c46eda6:7"]="慌乱"},Description={["53496d31d8df9680:116"]="奥西迪斯之影会攻击最近造成过威胁值的敌人，而不是威胁值最高的敌人。"}}
D.ClientTexts.JournalSection[2434]={Name={["e427a1753ee4804e:11"]="坠天之星"},Description={["74564fb48ee4a28d:49"]="阿萨德周期性地召唤坠天之星加入战斗。"}}
D.ClientTexts.JournalSection[2392]={Name={["ff0abd98c56bddeb:23"]="制造有毒的混合剂"}}
D.ClientTexts.JournalSection[2393]={Name={["1d27ef88c4f6df33:13"]="流水漩涡"}}
D.ClientTexts.JournalSection[2394]={Name={["60502e9b53159bea:14"]="水晶弹幕"}}
D.ClientTexts.JournalSection[2395]={Name={["23dc48196772d4e8:12"]="水晶碎片"}}
D.ClientTexts.JournalSection[2396]={Name={["9b91500b00119c32:13"]="抑制波"}}
D.ClientTexts.JournalSection[2397]={Name={["f4fe3c46789f9ddb:6"]="钻地"},Description={["8a173f5764dbdc1c:362"]="一段时间之后，克伯鲁斯会潜入地面，此时玩家无法攻击它。当克伯鲁斯潜入地下后，岩孔虫就会周期性地从某名玩家脚下冒出来，然后开始攻击。\r\n\r\n克伯鲁斯还会猛然从地下蹿出，发动凶猛冲击后钻入地下，反复四次。在第四次凶猛冲击后，克伯鲁斯会钻出地面，战斗恢复正常。"}}
D.ClientTexts.JournalSection[2398]={Name={["079bd66e32c2716d:9"]="岩孔虫"},Description={["ba11c6c129c7821e:87"]="岩孔虫生命值很低。如果不能迅速击杀他们，他们就会对当前目标使用岩石钻孔。"}}
D.ClientTexts.JournalSection[2399]={Name={["003b067c782aa045:8"]="岩石钻孔"}}
D.ClientTexts.JournalSection[2400]={Name={["4b9567d723b9cd1e:15"]="凶猛冲击"}}
D.ClientTexts.JournalSection[2401]={Name={["95d8edcaa304ca05:11"]="熔岩裂缝"}}
D.ClientTexts.JournalSection[2402]={Name={["cee937611fa09774:9"]="沙尘爆裂"}}
D.ClientTexts.JournalSection[2403]={Name={["b6d8d91369ecf834:10"]="钟乳石"}}
D.ClientTexts.JournalSection[2404]={Name={["23e3183c9ca976f3:12"]="水晶风暴"}}
D.ClientTexts.JournalSection[2405]={Name={["5c2b97411d30248c:10"]="大地冲击"}}
D.ClientTexts.JournalSection[2406]={Name={["6446921c87f600a1:7"]="割裂"}}
D.ClientTexts.JournalSection[2407]={Name={["08104332af9778f7:17"]="源质壁垒"}}
D.ClientTexts.JournalSection[2408]={Name={["dcad942f340842ca:21"]="源质刺盾"}}
D.ClientTexts.JournalSection[2409]={Name={["91de4940427b5b39:7"]="碎片崩飞"}}
D.ClientTexts.JournalSection[2435]={Name={["0d08e2e3ca92915a:13"]="奥术弹幕"}}
D.ClientTexts.JournalSection[2410]={Name={["14561dedf744f2d8:8"]="麻痹"}}
D.ClientTexts.JournalSection[2411]={Name={["1d6b494317b1a5ee:26"]="第一阶段：杀掉入侵者！"}}
D.ClientTexts.JournalSection[2412]={Name={["e64c21aca36e1351:12"]="血之诅咒"}}
D.ClientTexts.JournalSection[2413]={Name={["01f8bba6804110fd:9"]="强制之握"}}
D.ClientTexts.JournalSection[2414]={Name={["13f42cff384a27fc:11"]="引力井"}}
D.ClientTexts.JournalSection[2415]={Name={["0d1bf066e696fc57:14"]="虔诚的追随者"},Description={["eda0a00ab5025deb:89"]="虔诚的追随者会在战斗中冲过来协助高阶女祭司艾苏尔。这些生物的生命值很低。"}}
D.ClientTexts.JournalSection[2416]={Name={["59a501fab7685943:28"]="第二阶段：感受大地之怒！"},Description={["38e2569e81f0f60f:236"]="高阶女祭司艾苏尔本阶段开始时会施放能量护盾，然后她会悬浮在祭坛之上，施放3次地震碎片。施放结束后，她会返回地面。在此阶段中，冲过来协助她的虔诚的追随者会更多。"}}
D.ClientTexts.JournalSection[2417]={Name={["f2abf468e60dcfd1:12"]="能量护盾"}}
D.ClientTexts.JournalSection[2418]={Name={["09ba7e04624999f3:12"]="地震碎片"}}
D.ClientTexts.JournalSection[2419]={Name={["01e16babb67af970:13"]="旋风之盾"}}
D.ClientTexts.JournalSection[2420]={Name={["89fdeca9390d6d72:11"]="风暴边缘"}}
D.ClientTexts.JournalSection[2421]={Name={["30e313fa6f32103f:13"]="闪电箭"}}
D.ClientTexts.JournalSection[2422]={Name={["d00ddc86ed4881f1:13"]="召唤风暴"},Description={["5f57621f5f46d244:111"]="大宰相埃尔坦周期性地召唤潜伏风暴协助作战。它们会出现在大宰相埃尔坦的圆形平台的边缘。"}}
D.ClientTexts.JournalSection[2423]={Name={["7547d9c3d1f2a412:14"]="潜伏风暴"},Description={["5e53d69798bb8d52:62"]="潜伏风暴只有在没人注意的情况下才会攻击玩家。"}}
D.ClientTexts.JournalSection[2424]={Name={["30e313fa6f32103f:13"]="闪电箭"}}
D.ClientTexts.JournalSection[2425]={Name={["b1ed1af467d4c75b:11"]="召唤风"},Description={["243ccd0719645a22:238"]="阿尔泰鲁斯周期性地召唤风的力量，创造一股可能吹向四个基准方向的持续强风。玩家的位置，阿尔泰鲁斯的位置将随风向而变化，玩家还会受到阿尔泰鲁斯处于下风效果或是阿尔泰鲁斯占据上风效果影响。"}}
D.ClientTexts.JournalSection[2426]={Name={["394ee89621b29359:16"]="阿尔泰鲁斯处于下风"}}
D.ClientTexts.JournalSection[2427]={Name={["59248169de4e8ee0:18"]="阿尔泰鲁斯占据上风"}}
D.ClientTexts.JournalSection[2428]={Name={["711ee6a5f250643e:14"]="冰息术"}}
D.ClientTexts.JournalSection[2429]={Name={["4d43bf9fdc90e2ee:14"]="闪电冲击"}}
D.ClientTexts.JournalSection[2430]={Name={["64c366a3df180d50:13"]="扭曲之风"}}
D.ClientTexts.JournalSection[2431]={Name={["eec8aa74057529f3:22"]="不稳定的接地场"},Description={["8f46fb68bffe3a1b:159"]="阿萨德运用闪电的力量，在平台上的某个地方制造一个三角形的区域。任何针对身处该区域内的某个单位施放的法术都会被偏转。"}}
D.ClientTexts.JournalSection[2971]={Name={["89ff57438e1d74f8:21"]="孤单的翡翠雏龙"}}
D.ClientTexts.JournalSection[2436]={Name={["5aa25fdad6ea920b:11"]="静电缠握"}}
D.ClientTexts.JournalSection[2437]={Name={["900402b0b83850db:9"]="震荡波"}}
D.ClientTexts.JournalSection[2438]={Name={["9f2cb4f7c667372c:13"]="邪恶用心"}}
D.ClientTexts.JournalSection[2439]={Name={["4f94d5956373744a:10"]="锤拳"}}
D.ClientTexts.JournalSection[2440]={Name={["fc23ee153fb9a514:10"]="秘法陷阱"}}
D.ClientTexts.JournalSection[2441]={Name={["549001636bf9fd06:13"]="爆炸陷阱"},Description={["f21e109cbd1fc8ff:129"]="胡辛姆将军会提前开始所有陷阱的5秒倒计时。倒计时结束后，所有陷阱将爆炸。"}}
D.ClientTexts.JournalSection[2442]={Name={["8779dfb3e42a7838:7"]="锁喉"}}
D.ClientTexts.JournalSection[2443]={Name={["ad2116690c0a2ed2:13"]="粘性毒液"}}
D.ClientTexts.JournalSection[2444]={Name={["1741546d1fc48e4c:9"]="尘土抽击"}}
D.ClientTexts.JournalSection[2445]={Name={["d6b76a001940b79d:12"]="剧毒狂怒"}}
D.ClientTexts.JournalSection[2446]={Name={["f1e11ea7ab89a328:12"]="血之气息"}}
D.ClientTexts.JournalSection[2447]={Name={["f44296a547a8801e:17"]="狂乱的鳄鱼"},Description={["617c8a069b75ce13:127"]="这些邪恶的鳄鱼会周期性地从附近的河床里加入战斗。它们会攻击带有血之气息的玩家。"}}
D.ClientTexts.JournalSection[2448]={Name={["795f546b1213b22c:11"]="恶毒撕咬"}}
D.ClientTexts.JournalSection[2449]={Name={["7c943faadb194815:4"]="奥弗"}}
D.ClientTexts.JournalSection[2450]={Name={["37c073ed5b2aa9d2:17"]="麻木飞镖"}}
D.ClientTexts.JournalSection[2451]={Name={["b727f51d940c3d9a:9"]="旋风斩"}}
D.ClientTexts.JournalSection[2452]={Name={["3f7e9384373650b1:9"]="烟雾弹"}}
D.ClientTexts.JournalSection[2453]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[2454]={Name={["0bb1c110fbe8eedf:14"]="龙息术"}}
D.ClientTexts.JournalSection[2455]={Name={["3553dbd4227acb9d:24"]="第一阶段：异教徒退散！"}}
D.ClientTexts.JournalSection[2456]={Name={["11a34de0ad7677e3:13"]="反复鞭笞"}}
D.ClientTexts.JournalSection[2457]={Name={["cf7423d8ad66babd:12"]="衰老疫病"}}
D.ClientTexts.JournalSection[2458]={Name={["bf44843c515f583d:12"]="天堂之怒"}}
D.ClientTexts.JournalSection[2459]={Name={["32607893187371e0:17"]="天堂炽焰"},Description={["442ff07cd837aadb:210"]="高阶预言者巴林姆召唤一只火凤凰参战。如果天堂炽焰的生命值降到1%，它会变成一枚凤凰蛋，开始自愈。在大约20秒后，蛋中会孵化出一只新的天堂炽焰。"}}
D.ClientTexts.JournalSection[2460]={Name={["32607893187371e0:17"]="天堂炽焰"}}
D.ClientTexts.JournalSection[2461]={Name={["bc03d16a3e4802fd:10"]="忏悔"}}
D.ClientTexts.JournalSection[2462]={Name={["7114529dbbc1a988:23"]="第二阶段：跪地忏悔"},Description={["c6b893a4a5c65879:214"]="高阶预言者巴林姆施放忏悔之后，将会免疫所有伤害，并将玩家送入一片黑暗领域。玩家必须击败黑暗先驱才能结束第二阶段，回到自己的身体中，并继续与高阶预言者巴林姆作战。"}}
D.ClientTexts.JournalSection[2463]={Name={["b19da6a2afa2edd1:14"]="黑暗哀嚎"}}
D.ClientTexts.JournalSection[2464]={Name={["e933eb6dde73bb5e:9"]="灵魂撕裂"},Description={["442ff31a695af8e9:185"]="黑暗先驱随机切割一个玩家的灵魂，创造出一块灵魂碎块。灵魂碎块会向黑暗先驱移动。如果灵魂碎块抵达黑暗先驱身边，就会施放灵魂融噬。"}}
D.ClientTexts.JournalSection[2465]={Name={["79eff0dc8fce2a83:12"]="灵魂碎块"},Description={["2ae2291adafc480f:41"]="这些敌人的生命值很低，且移动缓慢。"}}
D.ClientTexts.JournalSection[2466]={Name={["8a52e6af55d1b9d4:11"]="灵魂融噬"}}
D.ClientTexts.JournalSection[2473]={Name={["14e827c74572f56a:19"]="黑暗先驱"},Description={["6f29d6c712ded97c:37"]="击败这只黑暗凤凰就可以结束第二阶段。"}}
D.ClientTexts.JournalSection[2474]={Name={["5d37f8e3e7e78498:30"]="第一阶段：南风起！"},Description={["5ccf3e33c4fdd48a:80"]="战斗开始时，希亚玛特漂浮在平台上，几乎不会受到任何伤害。"}}
D.ClientTexts.JournalSection[2475]={Name={["c630460b674acd7e:9"]="暴风箭"}}
D.ClientTexts.JournalSection[2476]={Name={["79a01a0c5fba200b:10"]="黑云压境"}}
D.ClientTexts.JournalSection[2477]={Name={["78439e1c0336ec3d:15"]="希亚玛特的仆从"},Description={["8241418064c14d67:186"]="在第一阶段中，希亚玛特召唤三个大型气元素作战。希亚玛特的仆从的入场间隔为45秒，或者在上一个希亚玛特的仆从死亡后立即入场。三个希亚玛特的仆从都死亡之后，战斗进入第二阶段。"}}
D.ClientTexts.JournalSection[2478]={Name={["30e9a9bd9d8ddb96:13"]="闪电新星"}}
D.ClientTexts.JournalSection[2479]={Name={["547c7a109e8deac3:12"]="落雷"}}
D.ClientTexts.JournalSection[2480]={Name={["f7c874933085ab7e:15"]="闪电充能"}}
D.ClientTexts.JournalSection[2481]={Name={["8e833963a762a782:14"]="希亚玛特的爪牙"},Description={["d146652035009d9f:85"]="在两个阶段中，希亚玛特大约每30秒召唤一次气元素入场。"}}
D.ClientTexts.JournalSection[2482]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[2483]={Name={["b4c9083caebbd5f7:12"]="暴风雨"}}
D.ClientTexts.JournalSection[2484]={Name={["597e7869ef06415c:9"]="消散"}}
D.ClientTexts.JournalSection[2485]={Name={["b262e977953b0cde:29"]="第二阶段：畏缩于风暴的来临吧！"},Description={["0897444acafe8d7d:115"]="在玩家杀死三个希亚玛特的仆从之后，战斗进入第二阶段，希亚玛特降落在平台上，玩家可以对其造成伤害。"}}
D.ClientTexts.JournalSection[2486]={Name={["6227aa357672f656:12"]="哀嚎之风"}}
D.ClientTexts.JournalSection[2487]={Name={["c630460b674acd7e:9"]="暴风箭"}}
D.ClientTexts.JournalSection[3019]={Name={["b095f85835187ab9:12"]="双重攻击"},Description={["2fc8e041d59f0932:39"]="奇美隆的下一次攻击为二连击。"}}
D.ClientTexts.JournalSection[2488]={Name={["26312eb14933f204:14"]="聚集风暴"}}
D.ClientTexts.JournalSection[2489]={Name={["d5fffbb25ac9ca63:12"]="燃烧之光"}}
D.ClientTexts.JournalSection[2490]={Name={["19dc0f044ca34f39:15"]="神圣清算"}}
D.ClientTexts.JournalSection[2491]={Name={["073f2d8ba4755b96:13"]="光明之盾"}}
D.ClientTexts.JournalSection[2492]={Name={["9bfa0371d39994c2:17"]="圣歌回响"}}
D.ClientTexts.JournalSection[2493]={Name={["824c89b8d740f18f:8"]="地穴毒蛇"},Description={["9847ac092696680a:46"]="这些蛇生活在安努尔的平台下方的深坑中。"}}
D.ClientTexts.JournalSection[2494]={Name={["af297c1f37c19b66:18"]="剧毒尖牙"}}
D.ClientTexts.JournalSection[2495]={Name={["02a8b6714057a918:10"]="大地震击"}}
D.ClientTexts.JournalSection[2496]={Name={["105cf61e562ff537:5"]="昏睡"}}
D.ClientTexts.JournalSection[2497]={Name={["d41db173479ca4a0:17"]="梦魇幻象"},Description={["18a555f8b9c0ed43:127"]="梦魇幻象的生命值很低，但是如果它走到目标身边，就会吞噬掉目标的灵魂。当一个玩家的梦魇被杀死后，该玩家就会醒来。"}}
D.ClientTexts.JournalSection[2498]={Name={["4d5613e027641b6b:14"]="落雷之云"}}
D.ClientTexts.JournalSection[2499]={Name={["576a89c43c04f5a9:15"]="叉状闪电"}}
D.ClientTexts.JournalSection[2500]={Name={["30ebf46b5a9a7ae2:13"]="闪电充能"},Description={["6a6cff0314f82bc0:122"]="乌苏雷变成一道闪电，随机冲向一个玩家。当他抵达目的地后，将开始施放闪电魔棒。"}}
D.ClientTexts.JournalSection[2501]={Name={["39465b30bc015e59:12"]="致命药膏"}}
D.ClientTexts.JournalSection[2502]={Name={["2239276e2719fd1b:6"]="消失"},Description={["bad3596097d787b3:81"]="雷纳塔基消失在阴影中。当他重新出现时，会随机伏击一个玩家。"}}
D.ClientTexts.JournalSection[2503]={Name={["c76249d6e4ada779:14"]="千刃"}}
D.ClientTexts.JournalSection[2504]={Name={["f2b1e0649059da79:6"]="天神下凡"}}
D.ClientTexts.JournalSection[2505]={Name={["ca75bc2134e90eba:7"]="追杀"}}
D.ClientTexts.JournalSection[2506]={Name={["02e058a3acc5ba4c:15"]="纠缠根须"}}
D.ClientTexts.JournalSection[2507]={Name={["6b7746445ea04795:11"]="裂痕"}}
D.ClientTexts.JournalSection[2508]={Name={["3ca7006c4e555829:11"]="赞吉利之火"}}
D.ClientTexts.JournalSection[2509]={Name={["89e72d5bc853560a:13"]="可怕的药水"}}
D.ClientTexts.JournalSection[2510]={Name={["21c9ae4cbb044083:10"]="巫毒箭"}}
D.ClientTexts.JournalSection[2511]={Name={["ab097836d23a9bd5:24"]="赞吉尔的秘密手段"},Description={["fdb89fb141e57ed6:116"]="赞吉尔会周期性的使用他的三种秘密巫毒手段，而且不会连续两次使用同一手段。"}}
D.ClientTexts.JournalSection[2512]={Name={["4e90ef243e7a48f5:29"]="赞吉尔的红色复活药剂"},Description={["0b6def8d7f73e798:41"]="赞吉尔召唤出一大群赞吉利僵尸。"}}
D.ClientTexts.JournalSection[2513]={Name={["3179ce4c46a87e99:13"]="赞吉利僵尸"},Description={["f6e684596716872a:40"]="一群赞吉利僵尸攻击玩家。"}}
D.ClientTexts.JournalSection[2514]={Name={["326d30f1918a4782:30"]="赞吉尔的蓝色复活药剂"},Description={["e28a513a80b45279:36"]="赞吉尔复活一个赞吉利狂暴者。"}}
D.ClientTexts.JournalSection[2515]={Name={["de0747eb6193d234:16"]="赞吉利狂暴者"},Description={["c02f937bbd94f47c:45"]="赞吉利狂暴者会随机选择一个玩家，只对其发动攻击。"}}
D.ClientTexts.JournalSection[2516]={Name={["a0578c97ccdd6f5c:20"]="赞吉尔的腐烂气息"}}
D.ClientTexts.JournalSection[2517]={Name={["b4cacbd02075c131:9"]="大锅"},Description={["e829eb0aadff2ed7:146"]="赞吉尔在自己的巢穴周围摆了三口实验用的大锅。每一口锅都有独特的药水，喝下锅中的药水可以获得特殊的效果。"}}
D.ClientTexts.JournalSection[2518]={Name={["000e55bf3da22eae:34"]="赞吉尔的霜灼药方坩埚"}}
D.ClientTexts.JournalSection[2519]={Name={["e3d00109a3770f02:30"]="赞吉尔的燃烧之血坩埚"}}
D.ClientTexts.JournalSection[2520]={Name={["5eaf22347cb402f9:30"]="赞吉尔的剧毒折磨坩埚"}}
D.ClientTexts.JournalSection[2521]={Name={["245f349ef76b3f81:16"]="静电瓦解"}}
D.ClientTexts.JournalSection[2522]={Name={["a1bc3e4540bd33ec:13"]="召唤闪电"}}
D.ClientTexts.JournalSection[2523]={Name={["b5a4a6cd4bc11880:7"]="勒紧"}}
D.ClientTexts.JournalSection[2524]={Name={["82b802560804abcf:12"]="翱翔的雄鹰"},Description={["975291e7183fe548:59"]="埃基尔松召唤一组翱翔的雄鹰。它们的生命值非常低。"}}
D.ClientTexts.JournalSection[2525]={Name={["d05ec8b25bd6e761:15"]="电能风暴"}}
D.ClientTexts.JournalSection[2526]={Name={["ff7a7d3450ba8d19:29"]="第一阶段：麻烦，真麻烦！"},Description={["213db921c06a2462:92"]="当雷奥利斯领主的盔甲完好无损时，他无视玩家的存在，但是玩家可以攻击他的腿部，控制其行动。"}}
D.ClientTexts.JournalSection[2527]={Name={["bf75bf6f3727af24:13"]="黑曜石护甲"}}
D.ClientTexts.JournalSection[2528]={Name={["e5e97c1a62360a0d:15"]="震荡践踏"}}
D.ClientTexts.JournalSection[2529]={Name={["21663053501534a4:15"]="热点火"}}
D.ClientTexts.JournalSection[2530]={Name={["a542ad60347a690f:10"]="痛饮岩浆"}}
D.ClientTexts.JournalSection[2531]={Name={["bb44e8a1468a7764:18"]="雷奥利斯的碎片"}}
D.ClientTexts.JournalSection[2532]={Name={["42eff10efd2bcfb1:15"]="雷奥利斯的火花"}}
D.ClientTexts.JournalSection[2533]={Name={["7e962bd302c157b8:12"]="地狱火之怒"}}
D.ClientTexts.JournalSection[2534]={Name={["89de87572b14e372:7"]="火山"}}
D.ClientTexts.JournalSection[2535]={Name={["f713d026ad0521ef:6"]="火山口"}}
D.ClientTexts.JournalSection[2537]={Name={["f87be6ce1e3a46ab:24"]="第二阶段：你们将燃烧殆尽！"},Description={["7d44791bdc881ad2:112"]="当雷奥利斯领主的剩余生命值处于25%时，他的黑曜石盔甲破碎。他将不再无视玩家，玩家也可以对其进行攻击。"}}
D.ClientTexts.JournalSection[2538]={Name={["729154de4a34beaf:10"]="献祭"}}
D.ClientTexts.JournalSection[2539]={Name={["a5ec0823881cb430:14"]="不受束缚的烈焰"}}
D.ClientTexts.JournalSection[2540]={Name={["37e6003b51d4b028:9"]="火焰箭"}}
D.ClientTexts.JournalSection[2541]={Name={["02ad00f5b1a1d3fc:10"]="大地之刺"}}
D.ClientTexts.JournalSection[2542]={Name={["a7ed2ad928a29e32:11"]="狂怒碎击"}}
D.ClientTexts.JournalSection[2543]={Name={["2e99bec5057baa08:20"]="混乱大地风暴"}}
D.ClientTexts.JournalSection[2544]={Name={["cef67fc5f6ecf320:14"]="尘骨恐魔"},Description={["8f2f961a1ca672e9:53"]="沙子中出现两名尘骨恐魔攻击玩家。"}}
D.ClientTexts.JournalSection[2545]={Name={["105d734182cc8b5c:5"]="重击"}}
D.ClientTexts.JournalSection[2546]={Name={["b04ce071a60d0984:13"]="宝石甲虫"},Description={["074eb476bbb96351:77"]="沙子中出现八只宝石甲虫攻击玩家。甲虫的生命值不高。"}}
D.ClientTexts.JournalSection[2547]={Name={["d88351089ac5ff91:9"]="流沙"}}
D.ClientTexts.JournalSection[2548]={Name={["daf6eed3fe98e472:10"]="沙尘旋涡"}}
D.ClientTexts.JournalSection[2549]={Name={["4d726736f5455f37:14"]="液态黑曜石"},Description={["7732922f577a8008:71"]="液态黑曜石会试图靠近雷奥利斯领主，然后使用熔合。"}}
D.ClientTexts.JournalSection[2550]={Name={["7c96ff18c3c75ec1:4"]="熔合"},Description={["68b3f99bb73bb388:72"]="液态黑曜石同雷奥利斯领主熔为一体，为他额外提供1%的伤害减免。"}}
D.ClientTexts.JournalSection[2551]={Name={["1c7eb9cb49f60bc0:13"]="复仇打击"}}
D.ClientTexts.JournalSection[2552]={Name={["6e0f2dd38c98f806:10"]="阿尔法光束"}}
D.ClientTexts.JournalSection[2553]={Name={["ba2dd7cc9e6a3f31:11"]="欧米加姿态"}}
D.ClientTexts.JournalSection[2554]={Name={["7526096694d9e4d9:13"]="破碎遗迹"}}
D.ClientTexts.JournalSection[2555]={Name={["e17a57c8424023e7:9"]="超级新星"}}
D.ClientTexts.JournalSection[2556]={Name={["443a3a768f57edd7:12"]="镜像"},Description={["27e57cb60eb649f3:529"]="当伊希斯特的生命值处于66%时，她将分裂成三个生物。每个生物都代表着她的一个主要技能。杀死其中一个的话，她在战斗中接下来的时间就无法使用该技能，但其余两种技能则会加强。\r\n\r\n当伊希斯特的生命值降到33%时，她会再次分裂成两个生物。这两个生物对应她剩下来的两个技能。杀死其中一个的话，她在战斗中接下来的时间就无法使用该技能，但最后一项技能则会进一步加强。"}}
D.ClientTexts.JournalSection[2557]={Name={["51000d56405190cf:10"]="星界之雨"},Description={["b5b5efe91ae04ebe:58"]="杀死该镜像，伊希斯特将无法使用星界之雨。"}}
D.ClientTexts.JournalSection[2558]={Name={["288467375141cbf6:13"]="星界之声"},Description={["cfc89fcae6d46d59:61"]="杀死该镜像，伊希斯特将无法使用星界之声。"}}
D.ClientTexts.JournalSection[2559]={Name={["701433010c6dfd98:9"]="星空之纱"},Description={["4623ea5493aae537:57"]="杀死该镜像，伊希斯特将无法使用星空之纱。"}}
D.ClientTexts.JournalSection[2560]={Name={["51000d56405190cf:10"]="星界之雨"}}
D.ClientTexts.JournalSection[2561]={Name={["288467375141cbf6:13"]="星界之声"},Description={["fb7edf0eab8c16c7:292"]="伊希斯特召唤为数不等的苍穹魔仆来协助她。苍穹魔仆的数量取决于玩家之前摧毁了多少只镜像。\r\n\r\n没有镜像被摧毁：一名苍穹魔仆\r\n摧毁一只镜像：两名苍穹魔仆\r\n摧毁两只镜像：三名苍穹魔仆"}}
D.ClientTexts.JournalSection[2562]={Name={["dd648d002d4bf43d:17"]="苍穹魔仆"},Description={["5622704bac824244:70"]="这些漂浮的恒星碎片会随机选择玩家施放奥术弹幕。"}}
D.ClientTexts.JournalSection[2563]={Name={["0d08e2e3ca92915a:13"]="奥术弹幕"}}
D.ClientTexts.JournalSection[2564]={Name={["701433010c6dfd98:9"]="星空之纱"}}
D.ClientTexts.JournalSection[2565]={Name={["25225858734627f3:6"]="枯萎"}}
D.ClientTexts.JournalSection[2566]={Name={["fec31cc91c4e4280:17"]="吞噬生命能量"}}
D.ClientTexts.JournalSection[2567]={Name={["218a6c739ba58d7e:11"]="新生豆荚"},Description={["26397647c06ab23a:100"]="阿穆纳伊周期性地随机选择14码外的一处地点召唤新生豆荚。新生豆荚生命值不高。"}}
D.ClientTexts.JournalSection[2568]={Name={["b9149c7e479ebf43:8"]="充能"}}
D.ClientTexts.JournalSection[2569]={Name={["feab12b21c040ac7:16"]="充能生长"}}
D.ClientTexts.JournalSection[2570]={Name={["600198d3fd82b4bc:13"]="快速生长"}}
D.ClientTexts.JournalSection[2571]={Name={["7a95f66aea135a73:17"]="血瓣花朵"},Description={["5e613c216b668522:83"]="阿穆纳伊随机选择一株新生豆荚，为其注入生命能量，将它变成血瓣花朵。"}}
D.ClientTexts.JournalSection[2572]={Name={["1df5420b0ce6ffe6:10"]="荆刺猛击"}}
D.ClientTexts.JournalSection[2573]={Name={["105f53ce1544d665:5"]="孢子"}}
D.ClientTexts.JournalSection[2574]={Name={["1200c2d6bc859d89:13"]="毒性孢子"}}
D.ClientTexts.JournalSection[2575]={Name={["530e21b5c0e645fc:14"]="献祭陷阱"}}
D.ClientTexts.JournalSection[2576]={Name={["6c90ae590a97854e:17"]="水晶牢笼陷阱"},Description={["a92cbe8cbf4b3779:288"]="沙恩诺克斯朝一名玩家的脚下发射一个牢笼陷阱。陷阱需要2秒才能组装完毕，在玩家或沙恩诺克斯的宠物踩到时触发，将目标囚禁在一块熔岩水晶中，令其无法做出移动或其他任何动作。只有打破水晶牢笼，才能放出被困在其中的玩家。"}}
D.ClientTexts.JournalSection[2577]={Name={["3f867454a452160d:11"]="弧形斩"}}
D.ClientTexts.JournalSection[2578]={Name={["ff4bd0f3c11d2d38:10"]="锯裂"}}
D.ClientTexts.JournalSection[2579]={Name={["8a7d16bb13a9dff2:9"]="掷矛"}}
D.ClientTexts.JournalSection[2580]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[2603]={Name={["bd34bdecb495ce31:11"]="流星猛击"}}
D.ClientTexts.JournalSection[2581]={Name={["484413d403bd306b:7"]="裂肢"}}
D.ClientTexts.JournalSection[2582]={Name={["7a2b07d4661cdf87:7"]="肢解"}}
D.ClientTexts.JournalSection[2583]={Name={["d375b7733620466a:8"]="狂脸"},Description={["405bcd92fa006c41:85"]="狂脸不受控制，会周期性地更换目标，从一个敌人冲向另一个敌人。"}}
