D.ClientTexts.JournalSection[2585]={Name={["af886a645f99fc31:16"]="狂乱护主"}}
D.ClientTexts.JournalSection[2586]={Name={["c8c9cd15e37edd78:13"]="争食"}}
D.ClientTexts.JournalSection[2587]={Name={["ff4bd0f3c11d2d38:10"]="锯裂"}}
D.ClientTexts.JournalSection[2588]={Name={["af886a645f99fc31:16"]="狂乱护主"}}
D.ClientTexts.JournalSection[2589]={Name={["c8c9cd15e37edd78:13"]="争食"}}
D.ClientTexts.JournalSection[2590]={Name={["f02453d54d856eb8:12"]="荣耀烈焰"}}
