D.ClientTexts.JournalSection[2592]={Name={["5d7779284c008929:15"]="磨难碎片"}}
D.ClientTexts.JournalSection[2593]={Name={["f05c2daee985a5f5:7"]="磨难"}}
D.ClientTexts.JournalSection[2594]={Name={["781e5e97300d14b4:9"]="饱受磨难"}}
D.ClientTexts.JournalSection[2595]={Name={["80125136b71d4ca5:13"]="磨难冲击波"}}
D.ClientTexts.JournalSection[2596]={Name={["1689d506c6ee64d1:10"]="活力火花"}}
D.ClientTexts.JournalSection[2597]={Name={["159c644a99cd4d87:10"]="生命之焰"}}
D.ClientTexts.JournalSection[2598]={Name={["c01672bd1d0a5bdc:15"]="贝尔洛克之剑"}}
D.ClientTexts.JournalSection[2599]={Name={["ef1487fad38e6669:15"]="毁灭之刃"}}
D.ClientTexts.JournalSection[2600]={Name={["9e8624ee7ac70de9:12"]="地狱火之刃"}}
D.ClientTexts.JournalSection[2601]={Name={["a6289d46eb35c3f1:9"]="倒计时"}}
D.ClientTexts.JournalSection[2602]={Name={["45071593c53ac6c6:17"]="黑暗噬体"}}
D.ClientTexts.JournalSection[2604]={Name={["b7a2a7177063c706:12"]="邪火风暴"}}
D.ClientTexts.JournalSection[2605]={Name={["5c728c542a89140d:11"]="集火"}}
D.ClientTexts.JournalSection[2606]={Name={["3c9e44072e2f3ed4:14"]="灼热暗影"}}
D.ClientTexts.JournalSection[2607]={Name={["7b075b10e5d4d64d:15"]="欧库塔尔之眼"}}
D.ClientTexts.JournalSection[2608]={Name={["090d7bc1db093c0a:15"]="欧库塔尔的凝视"}}
D.ClientTexts.JournalSection[2609]={Name={["b3a44533b915a220:22"]="欧库塔尔的毁灭"}}
D.ClientTexts.JournalSection[2610]={Name={["541c98f999d40916:10"]="斩首"}}
D.ClientTexts.JournalSection[2611]={Name={["717acf02f966c9bf:7"]="升级"}}
D.ClientTexts.JournalSection[2612]={Name={["6c952c2c1a5e5f67:15"]="毁灭猛击"}}
D.ClientTexts.JournalSection[2613]={Name={["52c93c4c96a9008f:12"]="血祭"}}
D.ClientTexts.JournalSection[2614]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[2615]={Name={["10126a928d5b543b:5"]="奥根"},Description={["2fd749d5c320fac4:110"]="奥根是血领主曼多基尔宠信的迅猛龙。亡灵奥根执行曼多基尔的命令，它能够看见并杀死被禁锢的灵魂。"}}
D.ClientTexts.JournalSection[2616]={Name={["9579af7b78f5940c:13"]="奥根之令"},Description={["502c3ceebb0458b1:161"]="血领主曼多基尔从奥根身上下来，下令让它杀死区域内的被禁锢的灵魂。如果奥根走到一个被禁锢的灵魂旁，他会将其杀死，然后立刻寻找一个新的被禁锢的灵魂作为下一个目标。"}}
D.ClientTexts.JournalSection[2617]={Name={["34ddeda87c6fbb6d:14"]="复活奥根"},Description={["09fa6941a6ffcfd4:101"]="如果奥根被玩家杀死，血领主曼多基尔将会把他复活。奥根会继续执行生前的命令。"}}
D.ClientTexts.JournalSection[2618]={Name={["9ba8ebacb7532db1:13"]="被禁锢的灵魂"},Description={["bfb230f7781d0186:124"]="会有八名被禁锢的灵魂就绪以协助玩家同血领主曼多基尔战斗。被禁锢的灵魂会在战斗中复活死亡的玩家。"}}
D.ClientTexts.JournalSection[2619]={Name={["19314a5652537ad5:6"]="复活"},Description={["73933faeff86fc79:92"]="被禁锢的灵魂会周期性地复活死去的玩家，并用灵魂的复仇强化他们。"}}
D.ClientTexts.JournalSection[2620]={Name={["f1db6ea60672666f:17"]="灵魂的复仇"}}
D.ClientTexts.JournalSection[2621]={Name={["c9992c60e35d7a53:11"]="烈焰吐息"}}
D.ClientTexts.JournalSection[2622]={Name={["41d86d2b835f2bb8:8"]="火焰炸弹"}}
D.ClientTexts.JournalSection[2623]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[2624]={Name={["cf4e4a314d77064e:14"]="龙鹰的卵"},Description={["046615923e50d3ff:115"]="36颗龙鹰的卵分布在加亚莱的平台周围。阿曼尼孵化者或加亚莱的“孵化所有卵”技能会令其孵化。"}}
D.ClientTexts.JournalSection[2625]={Name={["111b135506bfe1f0:16"]="阿曼尼孵化者"},Description={["c3efcd37d095045c:144"]="加亚莱会周期性地召唤两名阿曼尼孵化者，他们会前往平台相对的两侧，每1.5秒孵化三只阿曼尼龙鹰幼崽。"}}
D.ClientTexts.JournalSection[2626]={Name={["0eec97a379dbc3a6:24"]="阿曼尼龙鹰幼崽"},Description={["034700e63afa6477:28"]="这些生物的生命值不高。"}}
D.ClientTexts.JournalSection[2627]={Name={["c9d015a6e010b1f5:11"]="烈焰打击"}}
D.ClientTexts.JournalSection[2628]={Name={["cde2f8ec27935bef:12"]="孵化所有卵"},Description={["06623339e7aad8b4:120"]="当加亚莱的生命值还剩35%时，他会孵化余下所有龙鹰的卵。刚孵化出的阿曼尼龙鹰幼崽将会投入战斗。"}}
D.ClientTexts.JournalSection[2630]={Name={["04d9bc36876cc751:13"]="萨弗拉斯重击"}}
D.ClientTexts.JournalSection[2631]={Name={["6ca90e7cb7a533f9:8"]="熔岩波浪"}}
D.ClientTexts.JournalSection[2632]={Name={["d37236bd621e5c5c:15"]="拉格纳罗斯之怒"}}
D.ClientTexts.JournalSection[2633]={Name={["d4d5b3d273432571:14"]="拉格纳罗斯之手"}}
D.ClientTexts.JournalSection[2634]={Name={["0e17e63f52003334:9"]="熔岩陷阱"}}
D.ClientTexts.JournalSection[2635]={Name={["43bd73552c1a3170:17"]="熔岩陷阱喷发"}}
D.ClientTexts.JournalSection[2636]={Name={["eef6ea3c3e21d6c1:27"]="阶段转换：火焰仆从！"},Description={["10c5401c8a96ec8b:199"]="在生命值处于70%时，拉格纳罗斯将会施放爆裂打击，将萨弗拉斯嵌入平台中，并且在平台上制造出烈焰之子。拉格纳罗斯将潜入岩浆中45秒，或者直到所有的烈焰之子被消灭。"}}
D.ClientTexts.JournalSection[2637]={Name={["628cb86fd74813ea:10"]="烈焰之子"},Description={["0f3c1153409b02ae:105"]="烈焰之子们将会穿过平台，试图与萨弗拉斯重新结合，并在接触时引发一次超级新星。"}}
D.ClientTexts.JournalSection[2638]={Name={["d68274eb7af0f8d4:12"]="灼烧之速"}}
D.ClientTexts.JournalSection[2639]={Name={["e17a57c8424023e7:9"]="超级新星"}}
D.ClientTexts.JournalSection[2640]={Name={["1e7e3d48c0e74025:31"]="第二阶段：萨弗拉斯将成为你的末日！"}}
D.ClientTexts.JournalSection[2641]={Name={["04d9bc36876cc751:13"]="萨弗拉斯重击"}}
D.ClientTexts.JournalSection[2642]={Name={["6ca90e7cb7a533f9:8"]="熔岩波浪"}}
D.ClientTexts.JournalSection[2643]={Name={["3d22e029dba26542:14"]="噬体烈焰"}}
D.ClientTexts.JournalSection[2644]={Name={["1456521cf62fcc97:13"]="烈焰世界"}}
D.ClientTexts.JournalSection[2645]={Name={["f0ec59b5e8c95384:10"]="熔火之种"}}
D.ClientTexts.JournalSection[2646]={Name={["9de9a025c60edc5c:13"]="熔火地狱火"}}
D.ClientTexts.JournalSection[2647]={Name={["d920bb8bfa32c114:15"]="熔岩元素"},Description={["721f323ff2777cb2:76"]="熔岩元素生于熔火地狱火。它将随机选择一名玩家，对其进行集中攻击。"}}
D.ClientTexts.JournalSection[2648]={Name={["0e470fc1ab6cafb2:11"]="熔火之力"}}
D.ClientTexts.JournalSection[2649]={Name={["fc317d7ed785563b:29"]="阶段转换：烈焰来客！"},Description={["1c2aff1139e6e954:252"]="在生命值处于40%时，拉格纳罗斯将会施放爆裂打击，将萨弗拉斯嵌入平台中，并且在平台上制造出烈焰之子。拉格纳罗斯将潜入岩浆中45秒，或者直到所有的烈焰之子被消灭。\r\n\r\n拉格纳罗斯还会创造两个熔岩子嗣来攻击玩家。"}}
D.ClientTexts.JournalSection[2650]={Name={["628cb86fd74813ea:10"]="烈焰之子"},Description={["0f3c1153409b02ae:105"]="烈焰之子们将会穿过平台，试图与萨弗拉斯重新结合。烈焰之子在接触萨弗拉斯时会引发超级新星。"}}
D.ClientTexts.JournalSection[2651]={Name={["d68274eb7af0f8d4:12"]="灼烧之速"}}
D.ClientTexts.JournalSection[2652]={Name={["e17a57c8424023e7:9"]="超级新星"}}
D.ClientTexts.JournalSection[2653]={Name={["01835f25aca02918:9"]="熔岩子嗣"},Description={["66166b0ae2fdd1d5:41"]="平台的每一侧都会出现一名熔岩子嗣。"}}
D.ClientTexts.JournalSection[2654]={Name={["029fa78e95f22a8f:11"]="炽炎之热"}}
D.ClientTexts.JournalSection[2655]={Name={["c7d0b7e723e0bd24:29"]="第三阶段：滚出我的领域！"}}
D.ClientTexts.JournalSection[2656]={Name={["04d9bc36876cc751:13"]="萨弗拉斯重击"}}
D.ClientTexts.JournalSection[2657]={Name={["6ca90e7cb7a533f9:8"]="熔岩波浪"}}
D.ClientTexts.JournalSection[2658]={Name={["3d22e029dba26542:14"]="噬体烈焰"}}
D.ClientTexts.JournalSection[2659]={Name={["1456521cf62fcc97:13"]="烈焰世界"}}
D.ClientTexts.JournalSection[2660]={Name={["74211719bb484216:18"]="召唤活体流星"}}
D.ClientTexts.JournalSection[2661]={Name={["d8dcf9dab123b355:12"]="活体流星"},Description={["9dbc46c1a9cb7c4c:51"]="活体流星会随机锁定并追逐一个目标。"}}
D.ClientTexts.JournalSection[2662]={Name={["4c92ea8f564373f2:12"]="流星冲击"}}
D.ClientTexts.JournalSection[2663]={Name={["8c15cadec5150927:11"]="易燃"},Description={["2a64f8d7a22618ea:147"]="活体流星受到攻击时，它会引起燃烧，并且被击退数码。燃烧触发后，5秒内不会出现易燃。"}}
D.ClientTexts.JournalSection[2664]={Name={["70d9e108765fa9f3:10"]="燃烧"}}
D.ClientTexts.JournalSection[2665]={Name={["cca39b6b8e89fbf8:36"]="第四阶段：火焰之王的真正实力！"},Description={["d4a9a29a0fa17a05:127"]="火焰之王全力以赴，可以自由地绕着平台移动。艾泽拉斯强大的英雄们会前来援助玩家。"}}
D.ClientTexts.JournalSection[2666]={Name={["2f1102042f86a3b5:9"]="混乱之箭"}}
D.ClientTexts.JournalSection[2667]={Name={["22ef077d1bc89aec:12"]="混沌统治"}}
D.ClientTexts.JournalSection[2668]={Name={["112f6ee9c4d72cf8:10"]="混沌爆裂"}}
D.ClientTexts.JournalSection[2669]={Name={["00b2e7e9179d0878:11"]="混沌之种"}}
D.ClientTexts.JournalSection[2670]={Name={["a28b14648004186b:17"]="召唤混沌传送门"}}
D.ClientTexts.JournalSection[2671]={Name={["6e46af591385cb78:12"]="虚空哨兵"},Description={["c49e32b8767b8fe3:67"]="混沌传送门每次会召唤出一名这种难以被杀死的生物来。"}}
D.ClientTexts.JournalSection[2672]={Name={["97daa21e062a2ec3:11"]="虚空屏障"}}
D.ClientTexts.JournalSection[2673]={Name={["a0dff1b623a51779:10"]="虚空搜寻者"},Description={["324a69fb32b38976:52"]="混沌传送门每次会召唤出一名这种虚空生物来。"}}
D.ClientTexts.JournalSection[2674]={Name={["705a1b3a3b07decd:16"]="反魔法牢笼"}}
D.ClientTexts.JournalSection[2675]={Name={["bece3fc28208926d:8"]="虚空浮龙"},Description={["3fb21fe93976892e:57"]="混沌传送门每次会召唤出两条这种生命值不高的生物来。"}}
D.ClientTexts.JournalSection[2678]={Name={["db88f077e5f1a0fa:13"]="爆裂打击"}}
D.ClientTexts.JournalSection[2679]={Name={["db88f077e5f1a0fa:13"]="爆裂打击"}}
D.ClientTexts.JournalSection[2680]={Name={["1ab05b3fdc89c30a:11"]="极热"}}
D.ClientTexts.JournalSection[2681]={Name={["fac8eb197d2a4a08:15"]="强化萨弗拉斯"}}
D.ClientTexts.JournalSection[2682]={Name={["721064074943dea2:16"]="萨弗拉斯的烈焰"}}
D.ClientTexts.JournalSection[2683]={Name={["fab96aca4e2edef9:10"]="恐惧烈焰"}}
D.ClientTexts.JournalSection[2685]={Name={["3f95a49fbe9c0c6a:8"]="塞纳留斯"},Description={["a1fa731aa28b2e6f:234"]="尽管身为玛洛恩与艾露恩之子，半神和德鲁伊庇护者塞纳留斯也曾在幼年时得到巨龙伊瑟拉的照料。\r\n\r\n在战斗中，塞纳留斯会使用自然能量冰冻活体流星，减少由拉格纳罗斯的极热而造成的伤害。"}}
D.ClientTexts.JournalSection[2686]={Name={["9899e062d3ce28a1:14"]="冰障"}}
D.ClientTexts.JournalSection[2687]={Name={["fc44b98ad9cd4203:24"]="大德鲁伊哈缪尔·符文图腾"},Description={["c47607d1f8c67ec2:223"]="除了广受牛头人族人爱戴之外，勇敢的大德鲁伊哈缪尔·符文图腾还是塞纳里奥议会的卓越领袖。\r\n\r\n这名睿智的牛头人会协助玩家团队，安抚自然的怒火，并使用根须缠绕来困住拉格纳罗斯。"}}
D.ClientTexts.JournalSection[2688]={Name={["73a535f4de4bd5a9:15"]="诱捕根须"}}
D.ClientTexts.JournalSection[2689]={Name={["7bdb4be67088a2d9:18"]="玛法里奥·怒风"},Description={["065856dd9717ddbc:223"]="玛法里奥·怒风是有史以来最强大的暗夜精灵德鲁伊之一。他率领着塞纳留斯的军队在海加尔山防御战中对抗拉格纳罗斯的大军。\r\n\r\n玛法里奥会保护团队免受恐惧烈焰的伤害。"}}
D.ClientTexts.JournalSection[2690]={Name={["79a01a0c5fba200b:10"]="豪雨"}}
D.ClientTexts.JournalSection[2691]={Name={["f883c6db507bb848:6"]="灭焰之水"},Description={["1133ac94890bacad:92"]="灭焰之水使玩家免疫恐惧烈焰的伤害，并且能让玩家熄灭附近的恐惧烈焰。"}}
D.ClientTexts.JournalSection[2692]={Name={["ab902977cea40ac4:22"]="第一阶段：我誓要保卫这里！"}}
D.ClientTexts.JournalSection[2693]={Name={["fb3a039c15b70755:10"]="暗影箭"}}
D.ClientTexts.JournalSection[2694]={Name={["ae5c4c6be4f0cf64:11"]="痛苦波浪"}}
D.ClientTexts.JournalSection[2695]={Name={["0313912969d10e32:12"]="血泪"}}
D.ClientTexts.JournalSection[2696]={Name={["9f52e6d326f7db28:12"]="痛楚哀嚎"}}
D.ClientTexts.JournalSection[2697]={Name={["d95c38715d2d8722:13"]="痛苦鞭笞"}}
D.ClientTexts.JournalSection[2698]={Name={["4bf7f49ae772f3f3:30"]="第二阶段：领教贝瑟克的真正威力吧！"},Description={["c50e08f3e90ace80:110"]="当生命值还剩50%时，高阶祭司基尔娜拉变为贝瑟克的化身，并唤醒所有还在沉睡的猎豹。"}}
D.ClientTexts.JournalSection[2700]={Name={["0817104f29a0f6e8:17"]="远古之怒"}}
D.ClientTexts.JournalSection[2701]={Name={["8ae0965de38813fc:13"]="复仇重击"}}
D.ClientTexts.JournalSection[2702]={Name={["f9d10419dff58b64:10"]="伪装"},Description={["15b6894279930f81:120"]="贝瑟克的化身伪装自己，对玩家隐身。她随后会出现在随机一名玩家身后，并对其施放毁灭。"}}
D.ClientTexts.JournalSection[3118]={Name={["c4a8ffe72fc2f876:9"]="伊格纳休斯"},Description={["9b71d7ca787e4771:26"]="火之升腾者议员"}}
D.ClientTexts.JournalSection[2703]={Name={["18e8c45b3ea27f18:6"]="毁灭"}}
D.ClientTexts.JournalSection[2704]={Name={["2506c00cb515620f:14"]="贝瑟克猎豹"},Description={["88edc006279ad1ed:104"]="基尔娜拉的十六头猎豹正在沉睡，战斗打响后，任意攻击性技能或法术都会将它们唤醒。"}}
D.ClientTexts.JournalSection[2705]={Name={["059b2948a28cca07:11"]="裂伤"}}
D.ClientTexts.JournalSection[2706]={Name={["d267d807ce4ce2b0:19"]="玛拉卡斯的仆从"},Description={["1e3c572d39472ab0:57"]="四名仆从中的两名会陪伴妖术领主玛拉卡斯。"}}
D.ClientTexts.JournalSection[2707]={Name={["3a4fabe4888284df:13"]="阿莱松·安提雷"},Description={["bf50c32ea9a92fb5:20"]="一名血精灵神圣牧师。"}}
D.ClientTexts.JournalSection[2708]={Name={["9749733d1203e7aa:13"]="奥术洪流"}}
D.ClientTexts.JournalSection[2709]={Name={["461e5bcdb4d55b58:9"]="快速治疗"}}
D.ClientTexts.JournalSection[2710]={Name={["d18e780f803515a4:14"]="强力惩击"}}
D.ClientTexts.JournalSection[2711]={Name={["9bc37cc0b4a71e31:7"]="滑行者"},Description={["a7a00ab5e59ff014:9"]="一条大蛇。"}}
D.ClientTexts.JournalSection[2712]={Name={["ee75acf08347ce7b:9"]="卡扎克洛斯"},Description={["f2256348e1c9ff4f:6"]="一只小鬼。"}}
D.ClientTexts.JournalSection[2713]={Name={["404463fb06da5cb0:9"]="黑心"},Description={["d9fa206342cf4356:8"]="一个怨灵。"}}
D.ClientTexts.JournalSection[2714]={Name={["3d6f46842654ce0d:11"]="灵魂之箭"}}
D.ClientTexts.JournalSection[2715]={Name={["c98e8a608e98d3ed:10"]="吸取能量"}}
D.ClientTexts.JournalSection[2716]={Name={["7ae157d983337160:10"]="灵魂虹吸"}}
