D.ClientTexts.JournalSection[2719]={Name={["beb780532c184f0c:11"]="血之疫病"}}
D.ClientTexts.JournalSection[2720]={Name={["f69d85a49cdaacf7:13"]="枯萎凋零"}}
D.ClientTexts.JournalSection[2721]={Name={["a930d3ed2496abe6:10"]="血虫"}}
D.ClientTexts.JournalSection[2722]={Name={["a0474c3a754847cd:9"]="血虫"}}
D.ClientTexts.JournalSection[2723]={Name={["0f51155d7a6441a2:5"]="德鲁伊"}}
D.ClientTexts.JournalSection[2724]={Name={["02fb05bb4480bee0:6"]="猎人"}}
D.ClientTexts.JournalSection[2725]={Name={["7c9a7f1fff91daf2:4"]="法师"}}
D.ClientTexts.JournalSection[2726]={Name={["9b57d55e940d86c3:7"]="圣骑士"}}
D.ClientTexts.JournalSection[2727]={Name={["156b055c3a27b2ff:6"]="牧师"}}
D.ClientTexts.JournalSection[2728]={Name={["104c8d479ee42b5a:5"]="潜行者"}}
D.ClientTexts.JournalSection[2729]={Name={["1bb146dd6519124e:6"]="萨满"}}
D.ClientTexts.JournalSection[2730]={Name={["b6a247d80bf3e793:7"]="术士"}}
D.ClientTexts.JournalSection[2731]={Name={["b6a57a2b20347202:7"]="战士"}}
D.ClientTexts.JournalSection[2732]={Name={["f7d9bf8a514d7685:9"]="毒性喷吐"}}
D.ClientTexts.JournalSection[2733]={Name={["41d86d1c835e2b8b:8"]="火焰箭"}}
D.ClientTexts.JournalSection[2734]={Name={["c2d7c0a592bb3da2:11"]="心灵哀嚎"}}
D.ClientTexts.JournalSection[2735]={Name={["3b2196dddfe5961c:11"]="灵魂哀嚎"}}
D.ClientTexts.JournalSection[2736]={Name={["0788ffb65bb43bf1:7"]="台风"}}
D.ClientTexts.JournalSection[2737]={Name={["7f282724d5d2b977:8"]="月火"}}
D.ClientTexts.JournalSection[3020]={Name={["af310f46c889145b:14"]="嘲讽暗影"}}
D.ClientTexts.JournalSection[2738]={Name={["9c1444fede2fb8a7:9"]="生命绽放"}}
D.ClientTexts.JournalSection[2739]={Name={["0d62df7b7d1d08d2:13"]="爆炸陷阱"}}
D.ClientTexts.JournalSection[2740]={Name={["fc49c4d6e03bb581:12"]="冰冻陷阱"}}
D.ClientTexts.JournalSection[2741]={Name={["f61affee6ad7d06d:9"]="毒蛇陷阱"},Description={["c7c5f69dd078565a:80"]="玛拉卡斯放置一个陷阱，当第一个敌人接近时，陷阱会释放数条阿曼尼毒蛇攻击敌人。"}}
D.ClientTexts.JournalSection[2742]={Name={["0635492788d78990:9"]="冰霜新星"}}
D.ClientTexts.JournalSection[2743]={Name={["062eb3645a7bbe39:9"]="寒冰箭"}}
D.ClientTexts.JournalSection[2744]={Name={["1aeb88b9f3b97010:8"]="冰枪术"}}
D.ClientTexts.JournalSection[2745]={Name={["3bcda71a76e53d41:13"]="复仇之怒"}}
D.ClientTexts.JournalSection[2746]={Name={["362add2da3e56432:12"]="奉献"}}
D.ClientTexts.JournalSection[2747]={Name={["50e544593c5be122:9"]="圣光术"}}
D.ClientTexts.JournalSection[2748]={Name={["461e5bcdb4d55b58:9"]="快速治疗"}}
D.ClientTexts.JournalSection[2749]={Name={["ce9eeaf30d85c824:13"]="心灵尖啸"}}
D.ClientTexts.JournalSection[2750]={Name={["9c80bf282be7abe3:11"]="信仰飞跃"},Description={["0984d3eedef57b91:81"]="玛拉卡斯随机抓住友方目标的灵魂，使其立即移动到他身边。"}}
D.ClientTexts.JournalSection[2751]={Name={["b5f16ee9247bf006:15"]="暗言术：痛"}}
D.ClientTexts.JournalSection[2752]={Name={["3f7e9384373650b1:9"]="烟雾弹"}}
D.ClientTexts.JournalSection[2753]={Name={["8a55c20a400c8f3b:11"]="致伤药膏"}}
D.ClientTexts.JournalSection[2754]={Name={["b633139d77cb286c:12"]="切割"}}
D.ClientTexts.JournalSection[2755]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[2756]={Name={["003099a83b3b129f:13"]="火焰新星图腾"}}
D.ClientTexts.JournalSection[2757]={Name={["1af07630f132f5b3:11"]="治疗波"}}
D.ClientTexts.JournalSection[2758]={Name={["d23ece1f81af3776:10"]="末日灾祸"}}
D.ClientTexts.JournalSection[2759]={Name={["64292e82cbeac16d:18"]="痛苦无常"}}
D.ClientTexts.JournalSection[2760]={Name={["2a6bda2a49618a61:10"]="火焰之雨"}}
D.ClientTexts.JournalSection[2761]={Name={["abc3e8a67e4f4e01:12"]="致死打击"}}
D.ClientTexts.JournalSection[2762]={Name={["690ee6b0c5a70653:15"]="法术反射"}}
D.ClientTexts.JournalSection[2763]={Name={["610ca561fe7f57fc:10"]="英勇飞跃"}}
D.ClientTexts.JournalSection[2764]={Name={["c2b5bb2952cdc52c:21"]="第一阶段：烬网"},Description={["1b96a94dec7c970c:63"]="战斗开始时，贝丝缇拉克会退回到她的烬网顶上。"}}
D.ClientTexts.JournalSection[2892]={Name={["0b88c6d03c747bc9:3"]="电击"}}
D.ClientTexts.JournalSection[2765]={Name={["2091b415ddbf205e:10"]="火焰能量"},Description={["271bb2a44e879a4d:200"]="贝丝缇拉克的火焰能量随着时间流逝。此外当烬网工虫的能量耗尽时，也会从她那里吸取。只要贝丝缇拉克的火焰能量一用完，她就会燃烧自己，造成阴燃毁灭。"}}
D.ClientTexts.JournalSection[2766]={Name={["482174ba85ede2a7:10"]="余烬之火"}}
D.ClientTexts.JournalSection[2767]={Name={["5b07f3081438e2fb:10"]="流星灼烧"}}
D.ClientTexts.JournalSection[2768]={Name={["d37950ffc0032f9c:7"]="吞噬"}}
D.ClientTexts.JournalSection[2769]={Name={["63d0471b0b3cb9c0:21"]="阴燃毁灭"}}
D.ClientTexts.JournalSection[2770]={Name={["81350bf7fb0bce8e:16"]="烬网织网蛛"},Description={["7dc364ea882c6eb3:220"]="这些蜘蛛荡在网的下面。对其使用嘲讽类技能可以让它们落到地面上。被杀死后，玩家就可以借助它们留下的丝爬到烬网上去。"}}
D.ClientTexts.JournalSection[2771]={Name={["d0286a0beb3c7590:11"]="灼伤酸液"}}
D.ClientTexts.JournalSection[2772]={Name={["6a6d243cc5ca474d:12"]="烈焰织网"}}
D.ClientTexts.JournalSection[2773]={Name={["39d521301a37f32d:14"]="烬网工虫"},Description={["faab793d688360e8:148"]="这些大蜘蛛从烬网下的洞穴里爬出来。当它们的火焰能量耗尽时，它们会爬到贝丝缇拉克那儿去，从她身上吸取火焰能量。"}}
D.ClientTexts.JournalSection[2774]={Name={["d37950ffc0032f9c:7"]="吞噬"}}
D.ClientTexts.JournalSection[2775]={Name={["1fb5e2588e634091:15"]="沸腾泼溅"}}
D.ClientTexts.JournalSection[2776]={Name={["d0286a0beb3c7590:11"]="灼伤酸液"}}
D.ClientTexts.JournalSection[2777]={Name={["fd7cbb46b10b8cdd:6"]="凝视"}}
D.ClientTexts.JournalSection[2778]={Name={["e1c990e9f2b425a6:19"]="烬网幼蛛"},Description={["dd980b936fde9b80:93"]="这些小蜘蛛从烬网下的洞穴里爬出来。它们会本能地向烬网工虫那里爬去，寻求保护。"}}
D.ClientTexts.JournalSection[2779]={Name={["7580409565773118:12"]="渗毒"}}
D.ClientTexts.JournalSection[2780]={Name={["7c3e93d0a3445e85:17"]="肿胀的巢虫"},Description={["8da454f127d19714:86"]="这些不稳定的蜘蛛随机锁定一名玩家，并在接触目标后发生易燃爆炸。"}}
D.ClientTexts.JournalSection[2781]={Name={["232a543590431184:13"]="易燃爆炸"}}
D.ClientTexts.JournalSection[2782]={Name={["c9f58dcd420a3248:19"]="第二阶段：狂乱！"},Description={["3e7648f066685317:162"]="施放三次阴燃毁灭后，贝丝缇拉克变得狂乱。她将从烬网中走出来，并不再召唤子嗣的援助。"}}
D.ClientTexts.JournalSection[2783]={Name={["375deec4d5fb37d3:14"]="寡妇蛛之吻"}}
D.ClientTexts.JournalSection[2784]={Name={["482174ba85ede2a7:10"]="余烬之火"}}
D.ClientTexts.JournalSection[2785]={Name={["d37950ffc0032f9c:7"]="吞噬"}}
D.ClientTexts.JournalSection[2786]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[2787]={Name={["add8df7f50a2fc00:27"]="第一阶段：恶毒的迷宫"}}
D.ClientTexts.JournalSection[2791]={Name={["7900d24ca3a5c82f:29"]="第二阶段：解开尘世纷扰"},Description={["e35461e58dcc9300:83"]="在一段时间后，高阶祭司温诺希斯会变成蛇神赫希斯的化身。"}}
D.ClientTexts.JournalSection[2792]={Name={["dcbab80164e052e4:22"]="第三阶段：血毒触须！"},Description={["528b9bc5a788aa50:179"]="高阶祭司温诺希斯走向祭坛，把房间里所有的痛苦泪池吸收，然后施放血毒触须。血毒触须结束后，温诺希斯会进入毒性戒断的状态，然后回到第一阶段。"}}
D.ClientTexts.JournalSection[2793]={Name={["a9192eda0d6fe7e3:10"]="血毒触须"}}
D.ClientTexts.JournalSection[2893]={Name={["1061855acf601969:5"]="风暴"}}
D.ClientTexts.JournalSection[2794]={Name={["4638396158185bd2:15"]="毒性戒断"}}
D.ClientTexts.JournalSection[2795]={Name={["61c0184714b26550:17"]="赫希斯之耳语"}}
D.ClientTexts.JournalSection[2796]={Name={["3c81b13af2151ef1:9"]="剧毒联结"}}
D.ClientTexts.JournalSection[2797]={Name={["4c05bb3ef8cc252f:21"]="蛇神的祝福"}}
D.ClientTexts.JournalSection[2798]={Name={["b82fcbf6c380e579:16"]="痛苦泪池"}}
D.ClientTexts.JournalSection[2799]={Name={["49f88f483f5298c1:15"]="赫希斯之气息"}}
D.ClientTexts.JournalSection[2800]={Name={["58f506c0a35d68b5:16"]="剧毒漫溢"}}
D.ClientTexts.JournalSection[2801]={Name={["557f63741e0fc00d:11"]="毒云"}}
D.ClientTexts.JournalSection[2802]={Name={["60f71bcedc5a49d7:13"]="赫希斯之咒语"}}
D.ClientTexts.JournalSection[2803]={Name={["ea5b06adb45fd39e:14"]="毒爆"}}
D.ClientTexts.JournalSection[2804]={Name={["ef706edc29b7384f:28"]="第一阶段：向爪和牙致敬！"},Description={["41de6647683057b0:47"]="哈尔拉兹以山猫的化身开始战斗。"}}
D.ClientTexts.JournalSection[2805]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[2806]={Name={["b8aaa031dbe0ea2a:10"]="水图腾"}}
D.ClientTexts.JournalSection[2807]={Name={["a4190537ccf2c9b6:23"]="第二阶段：同狂野之灵战斗！"},Description={["9877f94c7a4e2315:192"]="当生命值还剩60%和30%时，哈尔拉兹分裂成两个形体：崇拜者哈尔拉兹和山猫之灵。这两个形体在阶段开始的时候都处于满生命值状态，当其中一名的生命值低于20%时，他们就会重新结合成为山猫的化身。"}}
D.ClientTexts.JournalSection[2808]={Name={["2303a54b6aa2e134:17"]="崇拜者哈尔拉兹"}}
D.ClientTexts.JournalSection[2809]={Name={["4e8b6cd238112657:14"]="闪电图腾"}}
D.ClientTexts.JournalSection[2810]={Name={["f154b3c91796bd2a:9"]="闪电"}}
D.ClientTexts.JournalSection[2811]={Name={["02a8b6714057a918:10"]="大地震击"}}
D.ClientTexts.JournalSection[2812]={Name={["35d5dc8211eb1e6f:10"]="烈焰震击"}}
D.ClientTexts.JournalSection[2813]={Name={["400c1b61c3b03a80:15"]="山猫之灵"}}
D.ClientTexts.JournalSection[2814]={Name={["dd65473cdd4a5963:10"]="碎甲"}}
D.ClientTexts.JournalSection[2815]={Name={["885d18d407182c61:10"]="山猫乱舞"}}
D.ClientTexts.JournalSection[2816]={Name={["fd7cbb46b10b8cdd:6"]="凝视"},Description={["bdde434dc99ad68e:60"]="山猫之灵凝视一个目标，只会对其进行攻击。"}}
D.ClientTexts.JournalSection[2817]={Name={["709cfe902c52342f:29"]="第三阶段：现在我要挠碎你！"},Description={["7a7440e31a4e2376:71"]="当生命值还剩25%时，哈尔拉兹保持在山猫的化身形态。"}}
D.ClientTexts.JournalSection[2818]={Name={["4e8b6cd238112657:14"]="闪电图腾"}}
D.ClientTexts.JournalSection[2894]={Name={["f56bd44c790722d5:13"]="肆掠之风"},Description={["bb598e9928b8d4aa:121"]="达卡拉在这一阶段不停地施放该法术。施放肆掠之风后，每枚旋羽都将朝一名玩家迅速移动。"}}
D.ClientTexts.JournalSection[2819]={Name={["f154b3c91796bd2a:9"]="闪电"}}
D.ClientTexts.JournalSection[2820]={Name={["85ff8f5776327d00:32"]="第一阶段：烈焰翔空"},Description={["594e6b7bdfa0c0b4:130"]="奥利瑟拉佐尔绕着竞技场飞翔，让她的手下围住敌人。她也会周期性地飞过竞技场的中央，朝敌人进行爪击。"}}
D.ClientTexts.JournalSection[2821]={Name={["c0f0b48f426bead4:25"]="第二阶段：这是我的天空！"},Description={["02fb7beb16be4fec:107"]="奥利瑟拉佐尔绕着小圈盘旋，5秒后移除所有玩家身上的烈焰之翼效果，然后开始发动终极一击。"}}
D.ClientTexts.JournalSection[2822]={Name={["b05d1ddb8901f39c:19"]="第三阶段：燃尽"},Description={["04599a35dee420c2:123"]="奥利瑟拉佐尔的熔火之力降到0时会坠落到地面，并变得虚弱。这一阶段持续到奥利瑟拉佐尔的能量槽获得50点熔火之力为止。"}}
D.ClientTexts.JournalSection[2823]={Name={["ed66e6b455ab9be5:24"]="第四阶段：涅槃重生！"},Description={["259cb376110ce6a9:90"]="熔火之力为50点时，奥利瑟拉佐尔的火焰再次被点燃。这一阶段持续到奥利瑟拉佐尔的熔火之力为100点为止。"}}
D.ClientTexts.JournalSection[2824]={Name={["7e1c7c00ec844873:9"]="火焰风暴"}}
D.ClientTexts.JournalSection[2825]={Name={["1135f83ae526456d:12"]="炽热山火"}}
D.ClientTexts.JournalSection[2826]={Name={["029d0773b0c2835e:11"]="炽热之爪"}}
D.ClientTexts.JournalSection[2827]={Name={["d51bd8ffbe76d998:7"]="羽蜕"},Description={["72033c249dbf96a7:44"]="奥利瑟拉佐尔开始羽蜕，在附近产生熔火之羽。"}}
D.ClientTexts.JournalSection[2828]={Name={["a1aa0fb3dd516890:13"]="熔火之羽"}}
D.ClientTexts.JournalSection[2829]={Name={["ded92827239e5214:12"]="烈焰之翼"}}
D.ClientTexts.JournalSection[2830]={Name={["fdb3b26eaf41f52f:6"]="飞行"},Description={["7c235b405aa64d3d:64"]="使用烈焰之翼飞行的玩家可以拥有不同的战斗体验。"}}
D.ClientTexts.JournalSection[2831]={Name={["572b35390c94ea86:12"]="炽炎之能"}}
D.ClientTexts.JournalSection[2832]={Name={["333cded9ade62b0e:13"]="奥利瑟拉之锋"}}
D.ClientTexts.JournalSection[2833]={Name={["9facefe24ac748d9:15"]="焚烧之云"}}
D.ClientTexts.JournalSection[2834]={Name={["28d0f5e1ac4b8338:20"]="炽炎之爪新兵"},Description={["d2d64fd1369bffd6:89"]="炽炎之爪新兵会周期性地飞来协助奥利瑟拉佐尔，同地面上的敌人战斗。"}}
D.ClientTexts.JournalSection[2835]={Name={["01434e8f9b2ed090:9"]="爆燃之火"}}
D.ClientTexts.JournalSection[2836]={Name={["33ed00f291954f37:18"]="饥饿的巢鸟"},Description={["470daf2191b050ea:167"]="在第一阶段早期，两只炽炎主母会产下两枚熔火之卵。几秒后它们会孵出饥饿的巢鸟。饥饿的巢鸟十分饥饿，如果不把肥硕的熔岩虫喂给它们吃的话，它们就会发脾气。"}}
D.ClientTexts.JournalSection[2837]={Name={["103f8d71aa080c68:9"]="印随"}}
D.ClientTexts.JournalSection[2838]={Name={["de5091b429df77b5:8"]="饱餐"}}
D.ClientTexts.JournalSection[2839]={Name={["02fad0223e26f88d:6"]="饥饿"}}
D.ClientTexts.JournalSection[2840]={Name={["cf6fa1b0ef8458f7:7"]="发脾气"}}
D.ClientTexts.JournalSection[2841]={Name={["7e1c7c00ec844873:9"]="火焰风暴"}}
D.ClientTexts.JournalSection[2842]={Name={["14ab4dc7644bca54:12"]="龟裂创伤"}}
D.ClientTexts.JournalSection[2895]={Name={["358b5c67b16fa20a:22"]="龙鹰精华"}}
D.ClientTexts.JournalSection[2843]={Name={["6080f43c82be664f:13"]="肥硕的熔岩虫"},Description={["5f0c52790962b8d0:168"]="在第一阶段，两组共八条熔岩虫会从熔火地面中钻出来。玩家无法攻击熔岩虫。如果饥饿的巢鸟位于一条熔岩虫旁边，它会冲过去将其吞掉，暂时进入饱餐状态。"}}
D.ClientTexts.JournalSection[2844]={Name={["6ca71aa804dbd56f:8"]="熔岩喷涌"}}
D.ClientTexts.JournalSection[2845]={Name={["764c27d733b0979e:21"]="烈焰之末使者"},Description={["6522e53da8c0d02a:137"]="在第一阶段，烈焰之末使者会周期性地出现，开始施放灾变流星。使者对所有伤害免疫，但是施放灾变流星后会立刻死亡。"}}
D.ClientTexts.JournalSection[2846]={Name={["4e129886003efdbf:9"]="灾变流星"}}
D.ClientTexts.JournalSection[2847]={Name={["cf72f3e06a18f07f:12"]="熔火流星"}}
D.ClientTexts.JournalSection[2848]={Name={["867a29013aaa231a:13"]="熔火巨石"}}
D.ClientTexts.JournalSection[2849]={Name={["5eb9776c5c4a7ef7:11"]="火焰漩涡"}}
D.ClientTexts.JournalSection[2850]={Name={["9bf08dfb6fc13acc:12"]="火焰飓风"}}
D.ClientTexts.JournalSection[2851]={Name={["572b35390c94ea86:12"]="炽炎之能"}}
D.ClientTexts.JournalSection[2852]={Name={["94c393b4930595df:7"]="燃尽"}}
D.ClientTexts.JournalSection[2853]={Name={["b3cd86b2aa8fbb59:17"]="绿龙精华"}}
D.ClientTexts.JournalSection[2854]={Name={["105f18460e5ffd5d:5"]="火花"}}
D.ClientTexts.JournalSection[2855]={Name={["3c55cb74bb05466f:22"]="炽炎之爪变形者"},Description={["ac114a13484c260e:74"]="在第二阶段开始的时候，两只炽炎之爪变形者会飞进场内，开始为奥利瑟拉佐尔充能。"}}
D.ClientTexts.JournalSection[2856]={Name={["63a6f766b9c6abed:8"]="燃烧"}}
D.ClientTexts.JournalSection[2857]={Name={["8ea7f76941d783ba:7"]="引燃"}}
D.ClientTexts.JournalSection[2858]={Name={["1c4ce7284dc5cfa1:13"]="炽热打击"}}
D.ClientTexts.JournalSection[2859]={Name={["029d0773b0c2835e:11"]="炽热之爪"}}
D.ClientTexts.JournalSection[2860]={Name={["d3703f657709f736:9"]="蓄满力量"}}
D.ClientTexts.JournalSection[2861]={Name={["68545ead0b4c399e:9"]="烈日之袭"}}
D.ClientTexts.JournalSection[2862]={Name={["33a68afd1c3da274:12"]="召唤太阳宝珠"}}
D.ClientTexts.JournalSection[2863]={Name={["4aa49578e6db0c77:11"]="地狱飞跃"}}
D.ClientTexts.JournalSection[2864]={Name={["7189d54be25bd88a:10"]="太阳风"}}
D.ClientTexts.JournalSection[2969]={Name={["058bc46707e58440:11"]="虚空之子"}}
D.ClientTexts.JournalSection[4396]={Name={["b71433918ce3ee3c:8"]="黑特雷尔"}}
D.ClientTexts.JournalSection[2865]={Name={["1aad47ec4749d677:9"]="太阳火焰"}}
D.ClientTexts.JournalSection[2866]={Name={["d1aca6a8b7c655b9:16"]="太阳祝福"}}
D.ClientTexts.JournalSection[2867]={Name={["f0b8f24058e85885:31"]="第一阶段：纳洛拉克驾到！"},Description={["be3397b38e11e20a:154"]="在战斗开始，纳洛拉克处于巨魔形态。他对坦克施放残忍打击，并周期性地朝最远的敌人发动奔袭，让他们下一次遭到奔袭攻击时受到的伤害显著提高。"}}
D.ClientTexts.JournalSection[2868]={Name={["2d84b8a135eeaf0c:12"]="残忍打击"}}
D.ClientTexts.JournalSection[2869]={Name={["10621d0bff5615ee:5"]="奔袭"}}
D.ClientTexts.JournalSection[2870]={Name={["8876c514352f0c65:26"]="第二阶段：召唤熊灵"},Description={["b3cb9775b41799f8:177"]="纳洛拉克变成一头熊。在熊形态下，他会用两种不同的流血效果撕裂肉体和刺裂攻击坦克。纳洛拉克同时也会放出震耳咆哮，短时间内沉默敌人。"}}
D.ClientTexts.JournalSection[2871]={Name={["0bbc8ce0ea775a6b:9"]="撕裂肉体"}}
D.ClientTexts.JournalSection[2872]={Name={["97366d9a6db8b189:15"]="刺裂"}}
D.ClientTexts.JournalSection[2873]={Name={["f69a163a96206ee1:13"]="震耳咆哮"}}
D.ClientTexts.JournalSection[2874]={Name={["39c0a0bc1606989f:12"]="充能之拳"}}
D.ClientTexts.JournalSection[2875]={Name={["2ddb875e97cda29b:29"]="第一阶段：没人敢欺负阿曼尼！"},Description={["f14a7dfc329f2dfb:112"]="在遭遇战的开始，达卡拉处于巨魔形态。他会对随机的玩家施放重伤投掷，并对附近的敌人使用旋风斩。"}}
D.ClientTexts.JournalSection[2876]={Name={["d8bdd50ded7c2508:13"]="重伤投掷"}}
D.ClientTexts.JournalSection[2877]={Name={["b727f51d940c3d9a:9"]="旋风斩"},Description={["738bfd8138a46a90:129"]="达卡拉向附近的敌人施展旋风斩。引导2秒后，他对8码内的敌人造成110%的普通近战伤害。"}}
D.ClientTexts.JournalSection[2878]={Name={["a0321c5813d0588d:28"]="第二阶段：给我来点新鲜花样！"},Description={["3a93ad2851bee0c7:46"]="达卡拉吸收熊灵或者山猫的精华。"}}
D.ClientTexts.JournalSection[2879]={Name={["8950d81befaefc1e:16"]="熊灵精华"}}
D.ClientTexts.JournalSection[2880]={Name={["10621d0bff5615ee:5"]="涌动"}}
D.ClientTexts.JournalSection[2881]={Name={["67e44416d00ff86d:21"]="压制重击"}}
D.ClientTexts.JournalSection[2882]={Name={["e5269d6ad5d323cf:17"]="麻痹蔓延"}}
D.ClientTexts.JournalSection[2883]={Name={["8956aaaccad95ce1:16"]="山猫精华"}}
D.ClientTexts.JournalSection[2884]={Name={["e05cd156d1764c27:9"]="阿曼尼山猫"},Description={["a322e2af3c80de7e:131"]="在变成山猫后，达卡拉立刻召唤两只阿曼尼山猫攻击玩家。这些山猫能够看破一切潜行和隐形效果。"}}
D.ClientTexts.JournalSection[2885]={Name={["931345f255b930cf:8"]="山猫冲锋"}}
D.ClientTexts.JournalSection[2886]={Name={["3da834eb4bd94c4c:8"]="利爪之怒"}}
D.ClientTexts.JournalSection[2887]={Name={["4a1b34a01b358bd9:28"]="第三阶段：还有更多的人会像你一样倒下！"},Description={["258cf227b3a02ec0:53"]="达卡拉吸收雄鹰或者龙鹰的精华。"}}
D.ClientTexts.JournalSection[2888]={Name={["b3a00c9f0cc6415a:17"]="雄鹰精华"}}
D.ClientTexts.JournalSection[2889]={Name={["4e8b6cd238112657:14"]="闪电图腾"},Description={["ef219411b9ca396a:82"]="达卡拉周期性地召唤一个闪电图腾攻击敌人。这个图腾生命值不高。"}}
D.ClientTexts.JournalSection[2890]={Name={["f154b3c91796bd2a:9"]="闪电"}}
D.ClientTexts.JournalSection[2891]={Name={["a7aad65121ad1164:14"]="旋羽"},Description={["2ef4c85f740758b0:181"]="在变成雄鹰后，达卡拉立刻为每个活着的玩家召唤一道旋羽。这些旋羽会持续到战斗结束，但只有在受到肆掠之风的影响时才会移动。"}}
D.ClientTexts.JournalSection[2896]={Name={["c9992c60e35d7a53:11"]="烈焰吐息"}}
D.ClientTexts.JournalSection[2897]={Name={["361e26f01eb7411f:10"]="烈焰旋风"}}
D.ClientTexts.JournalSection[2898]={Name={["25d3b1c4444ed077:12"]="火焰之柱"}}
D.ClientTexts.JournalSection[2899]={Name={["90adb77a514838dd:31"]="第一阶段：欢迎来看表演！"},Description={["8bb0926f0c667d5a:138"]="金度独自挑战玩家，在地上设置死魔区保护自己，并召唤哈卡之灵，用暗影闪电来强化自己的武器。"}}
D.ClientTexts.JournalSection[2900]={Name={["0dbf2e6f8455cc30:8"]="死魔区"}}
D.ClientTexts.JournalSection[2901]={Name={["54589ba59c084d74:15"]="哈卡之影"}}
D.ClientTexts.JournalSection[2902]={Name={["6b2302369d5ded39:32"]="第二阶段：当面唾弃神灵"},Description={["431b2703452598d6:125"]="金度把敌人和他一起送往灵魂世界。在那里，哈卡之灵被三条巨大的锁链困住，而他则从哈卡之灵那里获得莫大的力量。"}}
D.ClientTexts.JournalSection[2903]={Name={["63ae96870f15bd66:11"]="暗影尖刺"}}
D.ClientTexts.JournalSection[2904]={Name={["a1f6a44a46090775:15"]="古拉巴什灵魂"},Description={["ec647957b133a82c:99"]="当玩家在正常世界里击败古拉巴什灵魂战士后古拉巴什灵魂就会出现在灵魂世界里。"}}
D.ClientTexts.JournalSection[2905]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[2906]={Name={["3f797ba02991c1a7:8"]="抱摔"}}
D.ClientTexts.JournalSection[2907]={Name={["cd3e2b0bca04ba0a:10"]="破碎裂隙"}}
D.ClientTexts.JournalSection[2908]={Name={["cd75014425bf2a77:13"]="扭曲之魂"},Description={["8a8ef2ac2a936c5d:162"]="扭曲之魂从神殿周围的传送门中蜂拥而出，攻击玩家。扭曲之魂攻击时造成暗影伤害。这些生物的生命值很低。"}}
D.ClientTexts.JournalSection[2909]={Name={["4d537867a0bebba8:14"]="哈卡之链"},Description={["c5b3c646486b45cb:85"]="除非将所有三条哈卡之链摧毁，否则哈卡的复仇之火不会降临到金度头上。"}}
D.ClientTexts.JournalSection[2910]={Name={["26c2fee21602e3a5:14"]="脆骨壁垒"},Description={["487e238abe2458af:169"]="一道奥术能量组成的壁垒保护着哈卡之链，使它们免受所有攻击和法术的影响。巨大的古拉巴什巨魔灵魂正好可以用抱摔打破壁垒。"}}
D.ClientTexts.JournalSection[2911]={Name={["a1fbe03cbd91088d:13"]="专注"}}
D.ClientTexts.JournalSection[2912]={Name={["9d037112a759fd41:13"]="变形"},Description={["f0371f34a2ea94e1:178"]="如果敌人没有聚在一起，那么范达尔就变成一只猎豹；如果有7名或更多的敌人聚在一起，那么范达尔就变成一只蝎子。\r\n\r\n在每第三次变型时，范达尔会短暂恢复到暗夜精灵形态。"}}
D.ClientTexts.JournalSection[2913]={Name={["b3367171c15822ba:7"]="猎豹形态"},Description={["05b1503f56a413b0:63"]="如果敌人没有聚在一起，那么范达尔就变成一只猎豹。"}}
D.ClientTexts.JournalSection[2914]={Name={["bfa1331d1224deba:13"]="烈焰飞扑"}}
D.ClientTexts.JournalSection[2915]={Name={["411b9b3b6809c5ea:16"]="烈焰之魂"},Description={["98af99cbe526ea62:47"]="这些范达尔的幻影会攻击敌人，直到被杀死为止。"}}
D.ClientTexts.JournalSection[2916]={Name={["da0589b8dd63629d:10"]="肾上腺素"}}
D.ClientTexts.JournalSection[2917]={Name={["7c96ff0bc3c65e96:4"]="愤怒"}}
D.ClientTexts.JournalSection[2918]={Name={["832c17c63389cf2f:12"]="毒蝎形态"}}
D.ClientTexts.JournalSection[2919]={Name={["f03cb65a0d4dd0fb:11"]="烈焰镰刀"}}
D.ClientTexts.JournalSection[2920]={Name={["da0589b8dd63629d:10"]="肾上腺素"}}
D.ClientTexts.JournalSection[2921]={Name={["7c96ff0bc3c65e96:4"]="愤怒"}}
D.ClientTexts.JournalSection[2922]={Name={["76f4b3ea619035ab:12"]="暗夜精灵形态"},Description={["b281eab44d8a969f:233"]="当范达尔进入暗夜精灵形态，他会暂时用灼热旋风包围敌人，并额外施放一个法术。\r\n\r\n当他从猎豹形态变成毒蝎形态时，范达尔会释放出灼热之种。\r\n\r\n当他从毒蝎形态变成猎豹形态时，范达尔会施放燃烧宝珠。"}}
D.ClientTexts.JournalSection[2923]={Name={["9595cff1c3aad99e:12"]="灼热旋风"}}
D.ClientTexts.JournalSection[2924]={Name={["4e186ce27610f8e3:12"]="灼热之种"}}
D.ClientTexts.JournalSection[2925]={Name={["d03056507df7c6e7:11"]="燃烧宝珠"}}
D.ClientTexts.JournalSection[2926]={Name={["473897c5e4e69f14:9"]="太阳能量"},Description={["9aa456c19547bece:62"]="拉夏最初拥有100点太阳能量，他会用这些能量来施放法术。"}}
D.ClientTexts.JournalSection[2928]={Name={["d717541f022bc0fa:12"]="熔喉裂隙"}}
D.ClientTexts.JournalSection[2929]={Name={["9366132485b783bf:26"]="第一阶段：不能再次失败！"},Description={["58ed946a170a1f19:162"]="马洛拉克会周期性地将各种药剂瓶扔进锅里，产生不同的效果。前两瓶先后为红色、蓝色，或者反之，第三瓶是绿色，依此循环。"}}
D.ClientTexts.JournalSection[2930]={Name={["d8d21a84da862463:11"]="奥术风暴"}}
D.ClientTexts.JournalSection[2931]={Name={["c1d59180733be09b:18"]="释放畸变怪"},Description={["a7fc1afdcfabe3b4:89"]="马洛拉克从培养室中释放3个畸变怪，它们会攻击玩家。"}}
D.ClientTexts.JournalSection[2932]={Name={["e3c2f3cc9c6107b1:10"]="畸变"},Description={["89195629ca11bdf2:99"]="这些实验失败的产物使用生长催化剂增强附近盟友输出的伤害，并降低它们受到的伤害。"}}
D.ClientTexts.JournalSection[2933]={Name={["387a23857f9d2280:14"]="生长催化剂"}}
D.ClientTexts.JournalSection[2934]={Name={["192c47abad8be1c0:6"]="治愈"}}
D.ClientTexts.JournalSection[2935]={Name={["3e1bc58c4d2f5bef:7"]="红色瓶子"},Description={["18211d240fcb5d87:100"]="马洛拉克向锅中投掷一瓶红色瓶子，使自己获得烈焰吐息。红色瓶子的效果持续40秒。"}}
D.ClientTexts.JournalSection[2936]={Name={["6c6f22d03569e4b9:15"]="消蚀烈焰"}}
D.ClientTexts.JournalSection[2937]={Name={["cd66d05be4586e6e:14"]="灼热爆破"}}
D.ClientTexts.JournalSection[2938]={Name={["7eca26595ba642f8:8"]="蓝色瓶子"},Description={["faf9f67b70bad5cc:104"]="马洛拉克向锅中投掷一瓶蓝色瓶子，使自己获得冰冻魔法。蓝色瓶子的效果持续40秒。"}}
D.ClientTexts.JournalSection[2939]={Name={["5ba3f80ede9bf4af:11"]="酷寒"}}
D.ClientTexts.JournalSection[2940]={Name={["4367943492f834c7:11"]="快速冻结"}}
D.ClientTexts.JournalSection[2941]={Name={["57dad5a2a1798ee1:9"]="绿色瓶子"},Description={["6df3ab54883b56c7:143"]="马洛拉克向锅中投掷一瓶绿色瓶子。这瓶药剂会爆炸，并驱散畸变怪身上的生长催化剂。绿色瓶子的效果持续40秒。"}}
D.ClientTexts.JournalSection[2942]={Name={["b576af4fe3ce8ec8:17"]="衰弱的软泥怪"}}
D.ClientTexts.JournalSection[2943]={Name={["409cc548a3484f77:9"]="黑暗魔法"},Description={["585e731bed3204ce:181"]="维克多·奈法里奥斯勋爵向锅中注入黑暗魔法，使得邪恶废液从锅里喷洒出来。黑暗魔法的效果持续90秒。黑暗魔法还会使马洛拉克免疫嘲讽效果。"}}
D.ClientTexts.JournalSection[2970]={Name={["80099d2688475fad:17"]="龙的复仇"}}
D.ClientTexts.JournalSection[2945]={Name={["3d13437ff905d1be:17"]="黑暗吞噬"}}
D.ClientTexts.JournalSection[2946]={Name={["f807aa60a1b8a539:9"]="邪恶废液"},Description={["397a3f2bfac920a0:110"]="黑暗魔法制造出五个邪恶废液。这些可怕的软泥怪会随机挑选玩家并不断施放黑暗污泥，直到被杀死。"}}
D.ClientTexts.JournalSection[2947]={Name={["6303088b7762091c:10"]="黑暗污泥"}}
D.ClientTexts.JournalSection[2948]={Name={["624d10419ce1b528:29"]="第二阶段：意料之外的结果"},Description={["abf3b32224ffe155:172"]="当生命值降至25%时，马洛拉克不再向锅里扔药剂瓶。他会造成更高的近战伤害，获得一些新的技能，并立即释放培养室中的所有实验体。"}}
D.ClientTexts.JournalSection[2949]={Name={["ec99509f0191687a:10"]="倾巢而出"},Description={["b4df7562a8ee28df:85"]="马洛拉克从培养室中释放所有剩余的畸变怪和两个原型实验体。"}}
D.ClientTexts.JournalSection[2950]={Name={["0e12359e7a6846e1:9"]="熔岩喷射"}}
D.ClientTexts.JournalSection[2951]={Name={["352d046453f5295f:12"]="绝对零度"}}
D.ClientTexts.JournalSection[2952]={Name={["c1a7e7ca71e41ce9:8"]="酸性新星"}}
D.ClientTexts.JournalSection[2953]={Name={["4a2d0f522ea2038d:12"]="原型实验体"},Description={["9f0e1f27a84b8680:65"]="这些龙类实验体会使用生长催化剂增强盟友的攻击力。"}}
D.ClientTexts.JournalSection[2954]={Name={["387a23857f9d2280:14"]="生长催化剂"}}
D.ClientTexts.JournalSection[2956]={Name={["c1d59180733be09b:18"]="释放畸变怪"},Description={["a7fc1afdcfabe3b4:89"]="马洛拉克从培养室中释放3个畸变怪，它们会攻击玩家。"}}
D.ClientTexts.JournalSection[2957]={Name={["e3c2f3cc9c6107b1:10"]="畸变"},Description={["89195629ca11bdf2:99"]="这些实验失败的产物使用生长催化剂增强附近盟友输出的伤害，并降低它们受到的伤害。"}}
D.ClientTexts.JournalSection[2958]={Name={["387a23857f9d2280:14"]="生长催化剂"}}
D.ClientTexts.JournalSection[2959]={Name={["68f8f2535c649f7e:17"]="哈尔弗斯·碎龙者"}}
D.ClientTexts.JournalSection[2960]={Name={["51cfa021403a8f1c:17"]="致伤打击"}}
D.ClientTexts.JournalSection[2961]={Name={["180393999824f23a:15"]="狂乱攻击"}}
D.ClientTexts.JournalSection[2962]={Name={["fb40995f4412d2ac:10"]="暗影新星"}}
D.ClientTexts.JournalSection[2963]={Name={["fcb5241219858cfb:14"]="原龙巨兽"}}
D.ClientTexts.JournalSection[2964]={Name={["656b3c9a4402cdab:15"]="火球弹幕"}}
D.ClientTexts.JournalSection[2965]={Name={["7aaf541be8f9936a:15"]="灼热气息"}}
D.ClientTexts.JournalSection[2966]={Name={["41d831867c795275:8"]="火球术"}}
D.ClientTexts.JournalSection[2967]={Name={["27664a2642687b75:11"]="狂怒咆哮"}}
D.ClientTexts.JournalSection[2968]={Name={["df49831c1a9dd5cf:19"]="被囚禁的龙族"}}
D.ClientTexts.JournalSection[2972]={Name={["80099d2688475fad:17"]="龙的复仇"}}
D.ClientTexts.JournalSection[2973]={Name={["09c36b7903c8a16c:11"]="岩龙"}}
D.ClientTexts.JournalSection[2974]={Name={["80099d2688475fad:17"]="龙的复仇"}}
D.ClientTexts.JournalSection[2975]={Name={["8d5721b05c841e51:10"]="风暴骑手"}}
D.ClientTexts.JournalSection[2976]={Name={["80099d2688475fad:17"]="龙的复仇"}}
D.ClientTexts.JournalSection[2977]={Name={["e4f4fd55d3350a92:10"]="时光守卫"}}
D.ClientTexts.JournalSection[2978]={Name={["80099d2688475fad:17"]="龙的复仇"}}
D.ClientTexts.JournalSection[2979]={Name={["44568bad0897bb54:15"]="虚空失明"}}
D.ClientTexts.JournalSection[2980]={Name={["e6a77277e54cb08a:14"]="萎缩毒液"}}
D.ClientTexts.JournalSection[2981]={Name={["bc4da9c0d94f91f7:9"]="岩石之握"}}
D.ClientTexts.JournalSection[2982]={Name={["7c76a1f78ca79e04:12"]="旋风"}}
D.ClientTexts.JournalSection[2983]={Name={["c6ebb5c8bb4bc95b:12"]="时间延长"},Description={["ced5fd46e5736235:117"]="被释放之后，时光守卫扭曲哈尔弗斯的原龙巨兽身边的时间流，使其致命的火球速度降低。"}}
D.ClientTexts.JournalSection[2985]={Name={["6939d44f12b54f7a:7"]="瓦里昂娜"},Description={["5b72986eb201f3a7:196"]="战斗开始时，瑟纳利昂立即飞上空中，瓦里昂娜在地面上迎战。这对双生龙共享生命值，并交替飞上空中和落地作战。"}}
D.ClientTexts.JournalSection[2986]={Name={["7315aff3d01ffae2:17"]="地面技能"},Description={["c4a6466bcd6f7fe4:49"]="瓦里昂娜在地上时，会使用下列技能。"}}
D.ClientTexts.JournalSection[2987]={Name={["4ff8dcba1b9355cf:8"]="眩晕"}}
D.ClientTexts.JournalSection[2988]={Name={["8a93fc70b3b4990b:15"]="噬体烈焰"}}
D.ClientTexts.JournalSection[2989]={Name={["bec98a2f880cef72:13"]="暮光位移"},Description={["2fd11b545232fe9b:155"]="瓦里昂娜周期性地对其目标施加暮光位移。该效果可叠加。当瓦里昂娜对同一目标叠加到第五层效果时，就会对这个目标施放领域偏移。"}}
D.ClientTexts.JournalSection[2990]={Name={["7fb2465b25cb3bd0:15"]="领域偏移"}}
D.ClientTexts.JournalSection[2991]={Name={["c929268d3d9f8836:17"]="空中技能"},Description={["40cb4ed2775d9dc1:46"]="瓦里昂娜在空中时，会使用下列技能。"}}
D.ClientTexts.JournalSection[2992]={Name={["8c722f5fc270255e:17"]="暮光陨星"}}
D.ClientTexts.JournalSection[2993]={Name={["8f3c3c19df77308c:10"]="深呼吸"}}
D.ClientTexts.JournalSection[2994]={Name={["24fc998bd7213c9c:9"]="瑟纳利昂"},Description={["5d2eace184158550:197"]="战斗开始时，瑟纳利昂立即飞上空中，瓦里昂娜在地面上迎战。这对双生龙共享生命值，并交替飞上空中和落地作战。"}}
D.ClientTexts.JournalSection[2995]={Name={["7315aff3d01ffae2:17"]="地面技能"},Description={["3b2fb6a7b4032806:51"]="瑟纳利昂在地上时，会使用下列技能。"}}
D.ClientTexts.JournalSection[2996]={Name={["3d9b9c85ba3e621c:14"]="噬体魔法"}}
D.ClientTexts.JournalSection[3018]={Name={["58c1bc6a9374c71f:9"]="至死方休"}}
D.ClientTexts.JournalSection[2997]={Name={["263982fe70b575ef:14"]="卓越之焰"}}
D.ClientTexts.JournalSection[2998]={Name={["7fb2465b25cb3bd0:15"]="领域偏移"}}
D.ClientTexts.JournalSection[2999]={Name={["c929268d3d9f8836:17"]="空中技能"},Description={["5564488e61491c1f:48"]="瑟纳利昂在空中时，会使用下列技能。"}}
D.ClientTexts.JournalSection[3000]={Name={["ba61e1fc7445d95f:19"]="眩光毁灭"}}
D.ClientTexts.JournalSection[3001]={Name={["bd97fac7bb926a88:13"]="暮光冲击波"}}
D.ClientTexts.JournalSection[3002]={Name={["beb5ab42b4a1a39f:13"]="暮光领域"}}
D.ClientTexts.JournalSection[3003]={Name={["97c780368e60bccf:14"]="暮光哨兵"},Description={["7779d75211262965:238"]="在英雄难度下，暮光领域中会滋生神秘的暮光哨兵。在主物质位面的玩家眼中，它们看起来只是闪烁的暮光点，会随机攻击敌人，对暮光领域内外的玩家发射裂隙冲击。"}}
D.ClientTexts.JournalSection[3004]={Name={["79fc117016830753:9"]="裂隙冲击"}}
D.ClientTexts.JournalSection[3005]={Name={["2c95b36da6f8947c:12"]="暮光领域"}}
D.ClientTexts.JournalSection[3006]={Name={["bec98a2f880cef72:13"]="暮光位移"},Description={["4f6943be86b9461d:158"]="瑟纳利昂周期性地对其目标施加暮光位移。这个效果可以叠加。当瑟纳利昂对同一目标叠加到第五层效果时，就会对这个目标施放领域偏移。"}}
D.ClientTexts.JournalSection[3007]={Name={["25e4c96f61368344:16"]="不稳定的暮光"}}
D.ClientTexts.JournalSection[3008]={Name={["d50cb7915ce1f674:13"]="芬克·恩霍尔"},Description={["0db81aa0e850596f:265"]="知名的侏儒探险家芬克·恩霍尔被奈法利安抓获，在奇美隆死亡之前无法从牢笼中脱身。玩家可以在战斗开始之前与芬克·恩霍尔交谈，说服他启动胆汁喷洒机以协助作战。启动胆汁喷洒机会唤醒奇美隆。"}}
D.ClientTexts.JournalSection[3009]={Name={["8a0e848de8eb03e8:11"]="胆汁喷洒机"},Description={["3ddabfdb0c4f410a:160"]="芬克·恩霍尔启动胆汁喷洒机之后，它会在房间中四处移动，只要它处于正常运转状态下，就会持续向整个团队喷洒芬克的混合剂。奇美隆会周期性地将胆汁喷洒机打瘫痪。"}}
D.ClientTexts.JournalSection[3010]={Name={["0586e0669b1dddeb:15"]="芬克的混合剂"}}
D.ClientTexts.JournalSection[3011]={Name={["3eea2f74e92bd065:31"]="第一阶段：动真格"},Description={["12803a333015a0bc:183"]="奇美隆以突破和双重攻击来攻击他的当前目标，并不断地对整个团队喷洒腐蚀烂泥。他周期性地对团队施放屠杀，有时他的两颗头会屠杀之后产生争执。"}}
D.ClientTexts.JournalSection[3012]={Name={["8b5fc58b79c0ecf6:12"]="腐蚀烂泥"}}
D.ClientTexts.JournalSection[3013]={Name={["53251a34e0329da9:8"]="屠杀"},Description={["b4b4a82005f79a07:163"]="奇美隆对所有玩家造成巨大的伤害，基本可以杀死所有没有受到芬克的混合剂效果影响的玩家。\r\n\r\n屠杀有时会将胆汁喷洒机打瘫痪一小段时间。"}}
D.ClientTexts.JournalSection[3014]={Name={["7c96bb49bbe8672e:4"]="争执"}}
D.ClientTexts.JournalSection[3015]={Name={["0f2c9f4aeaa2899f:5"]="突破"}}
D.ClientTexts.JournalSection[3016]={Name={["b095f85835187ab9:12"]="双重攻击"},Description={["2fc8e041d59f0932:39"]="奇美隆的下一次攻击为二连击。"}}
D.ClientTexts.JournalSection[3017]={Name={["8d8db81969809472:26"]="第二阶段：恐怖的造物"},Description={["af5ead2748ca5786:108"]="当生命值降到20%以下时，奇美隆进入狂暴状态。这将使得他免疫嘲讽效果，并且大幅度降低玩家的治疗效果。"}}
D.ClientTexts.JournalSection[3021]={Name={["415ec37daa079112:33"]="第一阶段：我接受你们的挑战！"},Description={["152d14596187cc5e:189"]="奥拉基尔周期性地施放狂风、阵风冲击和冰雪风暴，还会随机选择一名玩家对其施放闪电打击。他会对所有近战范围内的目标施放静电震击，如果他的主目标离开近战范围，则会对其施放通电。"}}
D.ClientTexts.JournalSection[3022]={Name={["02eeda272fb17bb8:9"]="阵风冲击"}}
D.ClientTexts.JournalSection[3023]={Name={["9a0ec2ff5d245ede:10"]="狂风"}}
D.ClientTexts.JournalSection[3024]={Name={["1b74a5ab43be9a7e:8"]="冰雪风暴"}}
D.ClientTexts.JournalSection[3025]={Name={["1dfd515bd4e9859c:15"]="闪电打击"}}
D.ClientTexts.JournalSection[3027]={Name={["8360f6843acb386f:11"]="通电"},Description={["aba45bc151b81688:201"]="如果奥拉基尔的当前目标不在他的近战范围内，他就会对其引导一束闪电的能量，造成越来越高的自然伤害，直至目标回到奥拉基尔的近战范围。"}}
D.ClientTexts.JournalSection[3028]={Name={["bc9df994fb045a7d:33"]="第二阶段：你们的执着惹恼了我！"},Description={["5463cfdfb391a6e0:94"]="当生命值降到80%以下时，奥拉基尔不再施放阵风冲击，但是会持续降下酸雨，并召唤风暴火花。"}}
D.ClientTexts.JournalSection[3029]={Name={["9a0ec2ff5d245ede:10"]="狂风"}}
D.ClientTexts.JournalSection[3031]={Name={["8360f6843acb386f:11"]="通电"},Description={["aba45bc151b81688:201"]="如果奥拉基尔的当前目标不在他的近战范围内，他就会对其引导一束闪电的能量，造成越来越高的自然伤害，直至目标回到奥拉基尔的近战范围。"}}
D.ClientTexts.JournalSection[3032]={Name={["c1a9dc20250d83b1:8"]="酸雨"}}
D.ClientTexts.JournalSection[3033]={Name={["c635a884359c985f:9"]="风暴火花"}}
D.ClientTexts.JournalSection[3034]={Name={["ef8a14aabf974705:8"]="回馈"}}
D.ClientTexts.JournalSection[3035]={Name={["485b5172aa99b937:18"]="第三阶段：够了！"},Description={["c6edc05fe81b8f82:200"]="当生命值降到25%以下时，奥拉基尔击碎他的平台，将所有玩家抛到空中，使他们获得飞翔的能力。奥拉基尔不再施放狂风，但会开始施放闪电、闪电云层和闪电魔棒，并重新开始施放阵风冲击。"}}
D.ClientTexts.JournalSection[3036]={Name={["02eeda272fb17bb8:9"]="阵风冲击"}}
D.ClientTexts.JournalSection[3037]={Name={["efb75f53d33cb580:13"]="风暴之眼"}}
D.ClientTexts.JournalSection[3038]={Name={["f154b3c91796bd2a:9"]="闪电"}}
D.ClientTexts.JournalSection[3039]={Name={["c36bfecedbb7457d:12"]="闪电魔棒"}}
D.ClientTexts.JournalSection[3040]={Name={["4d5613e027641b6b:14"]="闪电云层"}}
D.ClientTexts.JournalSection[3061]={Name={["7315aff3d01ffae2:17"]="地面技能"},Description={["16bd2ae16585bb76:35"]="艾卓曼德斯开始在地面上战斗。"}}
D.ClientTexts.JournalSection[3072]={Name={["105ee06ee9ae61af:5"]="听声辨位"},Description={["3e2f7a93807e79c0:220"]="艾卓曼德斯双目失明，只能根据声音追踪敌人。战斗开始时，玩家有0点音量值，受到伤害则音量值提高。艾卓曼德斯会对音量值达到100的玩家引导毁灭，并迅速杀死他们。\r\n\r\n使用矮人先祖之盾可以重置所有玩家的音量值。"}}
D.ClientTexts.JournalSection[3073]={Name={["e39c47caf1df4247:21"]="矮人先祖之盾"}}
D.ClientTexts.JournalSection[3074]={Name={["20c1c76a8ed3aefd:15"]="共鸣冲击"},Description={["2d63151a3e7487ef:178"]="矮人先祖之盾的回音打断了艾卓曼德斯的施法。\r\n\r\n在空中时，艾卓曼德斯会选择使用了矮人先祖之盾的玩家作为咆哮烈焰吐息的目标。"}}
D.ClientTexts.JournalSection[3075]={Name={["7300f7a5ffc0a800:7"]="眩晕"}}
D.ClientTexts.JournalSection[3076]={Name={["499561717a6d5096:10"]="声纳脉冲"}}
D.ClientTexts.JournalSection[3077]={Name={["eb416c01ff259afc:10"]="声波调整"}}
D.ClientTexts.JournalSection[3078]={Name={["3ac40417acd632ac:11"]="音波吐息"}}
D.ClientTexts.JournalSection[3079]={Name={["f34f97e60c8b2e3f:13"]="灼热烈焰"}}
D.ClientTexts.JournalSection[3080]={Name={["8d72342fc316ccb4:13"]="咆哮烈焰"}}
D.ClientTexts.JournalSection[3081]={Name={["c929268d3d9f8836:17"]="空中技能"},Description={["657774bd069852a6:97"]="在战斗时，艾卓曼德斯周期性地飞到空中，对他的敌人降下毁灭之雨。"}}
D.ClientTexts.JournalSection[3082]={Name={["59ff1731a9dcfbd0:14"]="喧闹恶鬼"},Description={["38fe83bf56f8ea60:182"]="维克多·奈法里奥斯在战斗中出手干预，随机打开传送门，使喧闹恶鬼参战。每个喧闹恶鬼随机跳到一个玩家背后，并试图使该玩家的音量值提高。"}}
D.ClientTexts.JournalSection[3083]={Name={["5a2b1734b4f7f7a7:10"]="相位变换"},Description={["090bcf64c2220497:55"]="喧闹恶鬼不在玩家背后时免疫魔法。"}}
D.ClientTexts.JournalSection[3084]={Name={["046eb8ebbbd61048:9"]="可恶的喧闹"},Description={["e93de23cd09a81dd:89"]="当一个喧闹恶鬼跳到玩家背后时，会施放可恶的喧闹，使该玩家的音量值提高10点。"}}
D.ClientTexts.JournalSection[3085]={Name={["b49fa8c83c73cc45:9"]="声纳炸弹"}}
D.ClientTexts.JournalSection[3086]={Name={["5f356e929ed4c5bf:18"]="咆哮烈焰吐息"}}
D.ClientTexts.JournalSection[3087]={Name={["8d72342fc316ccb4:13"]="咆哮烈焰"}}
D.ClientTexts.JournalSection[3088]={Name={["16a21a8281c56e61:13"]="音速火球"}}
D.ClientTexts.JournalSection[3109]={Name={["f7dd43844887c6d1:23"]="第一阶段：胆敢入侵？"}}
D.ClientTexts.JournalSection[3110]={Name={["01130ec63e9060cb:8"]="费伦迪乌斯"},Description={["9c9fc00804b8c2f5:26"]="水之升腾者议员"}}
D.ClientTexts.JournalSection[3111]={Name={["ed40b09fe6f853b0:8"]="冻结"},Description={["0908146702feeb18:246"]="费伦迪乌斯释放冰霜爆发，对屋内所有玩家造成伤害。离费伦迪乌斯越远，伤害越低，近距离位置上的玩家会受到致命伤害。当费伦迪乌斯使用冻结时，受到浸水影响的玩家会被冰冻，并受到额外伤害。"}}
D.ClientTexts.JournalSection[3112]={Name={["84b67a0e010a756b:10"]="水流长枪"}}
D.ClientTexts.JournalSection[3113]={Name={["7229d788fb9627d9:9"]="水炸弹"}}
D.ClientTexts.JournalSection[3114]={Name={["bb4e483af93c1a19:11"]="浸水"}}
D.ClientTexts.JournalSection[3115]={Name={["fe1b10d97dde0d20:6"]="冻结"}}
D.ClientTexts.JournalSection[3116]={Name={["b21ae49fbaa1518e:10"]="寒冰之心"}}
D.ClientTexts.JournalSection[3117]={Name={["5cd39da9bb8b1dba:11"]="充盈冰霜"}}
D.ClientTexts.JournalSection[3119]={Name={["612b36e835b0abef:12"]="烈火之盾"}}
D.ClientTexts.JournalSection[3120]={Name={["4aa8261805f6ed67:11"]="地狱冲击"}}
D.ClientTexts.JournalSection[3121]={Name={["604bd678bd6b84dd:12"]="烈焰洪流"}}
D.ClientTexts.JournalSection[3122]={Name={["d54cceaa431a0447:12"]="燃烧之血"}}
D.ClientTexts.JournalSection[3123]={Name={["0f1a999ea8bc6c17:5"]="艾里昂"}}
D.ClientTexts.JournalSection[3124]={Name={["2fc64629349b6828:14"]="静电过载"}}
D.ClientTexts.JournalSection[3125]={Name={["48f0367d1937a460:9"]="泰拉斯卓"}}
D.ClientTexts.JournalSection[3126]={Name={["13e960b49ab4758d:11"]="重力核心"}}
D.ClientTexts.JournalSection[3127]={Name={["ceb4495c381be571:26"]="第二阶段：我们会来对付他们！"},Description={["d345e9a324063858:124"]="当费伦迪乌斯或伊格纳休斯中有一人降到25%生命值时，这两名议员都会撤退。然后艾里昂和泰拉斯卓会跳下来继续作战。"}}
D.ClientTexts.JournalSection[3128]={Name={["0f1a999ea8bc6c17:5"]="艾里昂"},Description={["4d3f7dc184faaa88:24"]="气之升腾者议员"}}
D.ClientTexts.JournalSection[3129]={Name={["015185a60039030d:9"]="呼风"}}
D.ClientTexts.JournalSection[3130]={Name={["5598bfd712e4887e:12"]="雷霆震荡"}}
D.ClientTexts.JournalSection[3131]={Name={["c36bfecedbb7457d:12"]="闪电魔棒"}}
D.ClientTexts.JournalSection[3132]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[3133]={Name={["6c72ac44cba4e0c1:8"]="消散"},Description={["b31e2e4c84b60df5:88"]="艾里昂化身成为旋风，出现在屋中的其它位置，然后施放闪电震爆。"}}
D.ClientTexts.JournalSection[3134]={Name={["4d43bf9fdc90e2ee:14"]="闪电震爆"}}
D.ClientTexts.JournalSection[3135]={Name={["48f0367d1937a460:9"]="泰拉斯卓"},Description={["9b5a00593d2cf988:26"]="土之升腾者议员"}}
D.ClientTexts.JournalSection[3136]={Name={["13f42cff384a27fc:11"]="引力井"}}
D.ClientTexts.JournalSection[3137]={Name={["37d0a14c5962c4b1:10"]="硬化外皮"}}
D.ClientTexts.JournalSection[3138]={Name={["1233081bd805663c:8"]="迸涌"}}
D.ClientTexts.JournalSection[3139]={Name={["103da43c6f225157:5"]="地震"}}
D.ClientTexts.JournalSection[3140]={Name={["01130ec63e9060cb:8"]="费伦迪乌斯"}}
D.ClientTexts.JournalSection[3141]={Name={["1579f57c2930a03f:9"]="冰霜宝珠"}}
D.ClientTexts.JournalSection[3142]={Name={["c4a8ffe72fc2f876:9"]="伊格纳休斯"}}
D.ClientTexts.JournalSection[3143]={Name={["f16c51dc44e8c105:11"]="烈焰风暴"}}
D.ClientTexts.JournalSection[3144]={Name={["a7b27f187ca12bc9:26"]="第三阶段：厄运难逃！"},Description={["a354c453b28a47cc:199"]="一旦艾里昂或泰拉斯卓的生命值降到25%，议员们就会变得躁动，所有参战者会被卷入一个静电场。四名议员会组合成源质畸体，战斗进入最后一阶段。"}}
D.ClientTexts.JournalSection[3145]={Name={["e1cc3fb5783d8c60:21"]="源质畸体"},Description={["823305dc7629cac1:101"]="源质畸体的起始生命值等同于四人合并时所剩生命值的总和。"}}
D.ClientTexts.JournalSection[3146]={Name={["d705665c0fcbc567:19"]="不稳定的电荷"}}
D.ClientTexts.JournalSection[3147]={Name={["91172b501512924d:12"]="重力碾压"}}
D.ClientTexts.JournalSection[3148]={Name={["6ca6ebcaff712ad1:8"]="熔岩之核"}}
D.ClientTexts.JournalSection[3149]={Name={["d83714d1d54be4e8:13"]="低温光环"}}
D.ClientTexts.JournalSection[3150]={Name={["e291bb69bbe9c8c6:12"]="烈焰升腾"}}
D.ClientTexts.JournalSection[3151]={Name={["d9917c40a92c0829:11"]="烈焰充盈"}}
D.ClientTexts.JournalSection[3152]={Name={["6d7643f9c86b3e08:13"]="旋风上抛"}}
D.ClientTexts.JournalSection[3153]={Name={["dd0ed7bdd31328c6:8"]="融入大地"}}
D.ClientTexts.JournalSection[3154]={Name={["92db043b018313a0:20"]="第一阶段：混乱降临！"}}
D.ClientTexts.JournalSection[3155]={Name={["3b43460bff92ba16:10"]="变节"}}
D.ClientTexts.JournalSection[3156]={Name={["86e26473f92f75e4:13"]="火焰援助令"}}
D.ClientTexts.JournalSection[3157]={Name={["e0c271574c8d8702:18"]="烈焰破坏"}}
D.ClientTexts.JournalSection[3158]={Name={["115b3054dfe78011:14"]="暗影之令"}}
D.ClientTexts.JournalSection[3160]={Name={["6668debc520dcfef:24"]="召唤腐蚀信徒"}}
D.ClientTexts.JournalSection[3161]={Name={["1dae0e3d774072ae:18"]="腐蚀信徒"},Description={["a5372d20365490f5:72"]="古加尔召唤这些上古之神的无面者仆从，以加速敌人的灭亡。"}}
D.ClientTexts.JournalSection[3162]={Name={["6736239dc171af96:9"]="堕落"}}
D.ClientTexts.JournalSection[3163]={Name={["78110c3ec7d913cd:11"]="脓血"},Description={["3cc199a4e25482dd:210"]="古加尔使所有腐蚀信徒的血液化脓，导致古神血雨形成活动的软泥怪。脓血还会使所有活着的腐蚀信徒体内的黑血沸腾，导致化脓之血效果。"}}
D.ClientTexts.JournalSection[3164]={Name={["bc5cec4ee08bee19:28"]="第二阶段：来吧，永恒的黑夜！"},Description={["6527f84eaec4c2c9:199"]="当古加尔的生命值降到25%时，他会召唤上古之神的全部力量，吸收所有仍然存活的腐蚀信徒和古神血雨的黑暗力量，将自己变成一个扭曲的怪物。"}}
D.ClientTexts.JournalSection[3165]={Name={["bc5c40cdc98ddc2e:14"]="堕落熔岩"}}
D.ClientTexts.JournalSection[3339]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["1c3b169d0b7d86e2:43"]="祖尔格拉布只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[3166]={Name={["f22ac81cb088d5cd:6"]="安舍尔"},Description={["a3797de1cf9e7d22:127"]="安舍尔在战斗开始时有0点风能量。他每秒获得1点风能量，达到90点时就会施放微风。"}}
D.ClientTexts.JournalSection[3167]={Name={["3081d01ab723049f:7"]="培育"}}
D.ClientTexts.JournalSection[3168]={Name={["eb07c43e956ee891:15"]="饥饿的食人花"},Description={["86e0d825262105e6:58"]="饥饿的食人花周期性地施放剧毒孢子，直到被杀死。"}}
D.ClientTexts.JournalSection[3169]={Name={["748667481d1e4ec5:11"]="剧毒孢子"}}
D.ClientTexts.JournalSection[3170]={Name={["912b6acd721a7636:14"]="抚慰轻风"}}
D.ClientTexts.JournalSection[3171]={Name={["2bd74147ec12919c:6"]="微风"}}
D.ClientTexts.JournalSection[3172]={Name={["19de6faa6a3c49ab:6"]="洛哈西"},Description={["620b72aebd8bedeb:130"]="洛哈西在战斗开始时有0点风能量。他每秒获得1点风能量，达到90点时就会施放飓风。"}}
D.ClientTexts.JournalSection[3173]={Name={["47c07ca727dabbe2:11"]="刺骨旋风"}}
D.ClientTexts.JournalSection[3174]={Name={["02e9a26d84951d70:9"]="强风冲击"}}
D.ClientTexts.JournalSection[3175]={Name={["f05ca7bc160a3635:7"]="龙卷风"}}
D.ClientTexts.JournalSection[3176]={Name={["97bfe52692b49cd1:9"]="飓风"}}
D.ClientTexts.JournalSection[3177]={Name={["3a8125539db08ad2:11"]="风暴护盾"}}
D.ClientTexts.JournalSection[3178]={Name={["0ffefecdc73dab8c:5"]="尼希尔"},Description={["38ad098264cde051:130"]="尼希尔在战斗开始时有0点风能量。他每秒获得1点风能量，达到90点时就会施放暴雨。"}}
D.ClientTexts.JournalSection[3179]={Name={["02f9aa83124fb3bc:9"]="刺骨寒风"}}
D.ClientTexts.JournalSection[3180]={Name={["d4fd3088136923f3:10"]="永冻"}}
D.ClientTexts.JournalSection[3181]={Name={["1b340446065f491d:8"]="浮冰"}}
D.ClientTexts.JournalSection[3182]={Name={["d698a097693ccdee:10"]="暴雨"}}
D.ClientTexts.JournalSection[3193]={Name={["dcbd51b8a8dde67f:20"]="第一防御矩阵"},Description={["ea4fbdcb2162a882:275"]="四个矮人魔像共享生命值，在指定时间内每次会激活两个。当魔像激活时，它有100点能量来使用技能。当魔像的能量降到50时，它会获得一个防御护盾，同时一个新的魔像也会激活。当魔像的能量用光后，它就会消失，而激活另一个魔像。"}}
D.ClientTexts.JournalSection[3194]={Name={["2e112c1cb1a9e64d:10"]="奥能金刚"}}
D.ClientTexts.JournalSection[3195]={Name={["a98c87997701bece:14"]="能量发生器"}}
D.ClientTexts.JournalSection[3196]={Name={["09d7d8e80be2eaf3:17"]="奥术歼灭者"}}
D.ClientTexts.JournalSection[3197]={Name={["574d9398ebaf5f1b:15"]="能量转化"},Description={["963bb067e0f2e554:103"]="奥能金刚的护盾将受到的伤害变成已转换能量，提供额外的法术伤害和施法速度加成。"}}
D.ClientTexts.JournalSection[3198]={Name={["b7508d3c06b23d33:14"]="已转换能量"}}
D.ClientTexts.JournalSection[3224]={Name={["5a3de3fd75a96118:23"]="腐蚀：畸变"}}
D.ClientTexts.JournalSection[3199]={Name={["6ca3d1a39f49964a:25"]="超载的能量发生器"}}
D.ClientTexts.JournalSection[3200]={Name={["f6414f34dbed2f9f:14"]="奥术反冲"}}
D.ClientTexts.JournalSection[3201]={Name={["1e17f94101ab73c2:8"]="电荷金刚"}}
D.ClientTexts.JournalSection[3202]={Name={["c18c795ae9afad1d:18"]="闪电导体"}}
D.ClientTexts.JournalSection[3203]={Name={["15c14767fdee66fa:19"]="电荷释能"}}
D.ClientTexts.JournalSection[3204]={Name={["e4e6053cb938271d:14"]="不稳定的护盾"}}
D.ClientTexts.JournalSection[3205]={Name={["64b108b67bb1d509:14"]="暗影灌注"},Description={["0710ad01664e0956:234"]="维克多·奈法里奥斯腐蚀闪电导体，使其变成暗影导体。暗影导体每2秒对附近的所有盟友造成暗影伤害，距离被暗影灌注的玩家距离越远，受到的伤害越高。"}}
D.ClientTexts.JournalSection[3207]={Name={["0e17e80b520e36a4:9"]="熔岩金刚"}}
D.ClientTexts.JournalSection[3208]={Name={["09a0bfac4f0b1b29:8"]="剧毒金刚"}}
D.ClientTexts.JournalSection[3209]={Name={["f640fb91acccf1d4:15"]="狂热"}}
D.ClientTexts.JournalSection[3210]={Name={["96cdfd615e9af1c4:14"]="古加尔之怒"}}
D.ClientTexts.JournalSection[3211]={Name={["0f294733d19a6d42:5"]="光芒"}}
D.ClientTexts.JournalSection[3212]={Name={["62c99ce6ec725237:16"]="强效暗影"}}
D.ClientTexts.JournalSection[3213]={Name={["05ba6803f05873d2:15"]="腐蚀碾压"}}
D.ClientTexts.JournalSection[3214]={Name={["f840f5b12a6e7c00:23"]="古神血雨"}}
D.ClientTexts.JournalSection[3215]={Name={["cd5a9d7c57168cc5:14"]="化脓之血"}}
D.ClientTexts.JournalSection[3216]={Name={["22708384efee4cd5:16"]="古神之血"},Description={["b8b1771ab6d3d81d:183"]="腐蚀信徒的血液凝结成为许多个邪恶的软泥怪，每个都会随机挑选一名玩家，并向其移动。古神之血碰到任何目标都会使他们的腐蚀术等级提高。"}}
D.ClientTexts.JournalSection[3217]={Name={["96cdfd615e9af1c4:14"]="古加尔之怒"}}
D.ClientTexts.JournalSection[3218]={Name={["d0f87d0957820d74:21"]="上古之神的腐蚀"}}
D.ClientTexts.JournalSection[3219]={Name={["03c47d6bbf435ef6:17"]="黑暗造物"},Description={["2ae5cb14200c3861:56"]="古加尔使地上的黑雾中伸出触须。"}}
D.ClientTexts.JournalSection[3220]={Name={["3e2cbdf84cedd0bd:16"]="黑暗的造物"},Description={["fde8d6f775f163e4:72"]="黑暗的造物不断地尝试随机对一名玩家引导衰弱光线。"}}
D.ClientTexts.JournalSection[3221]={Name={["247e086a78ca5daf:16"]="衰弱光线"}}
D.ClientTexts.JournalSection[3222]={Name={["b16bb6817d0475c8:22"]="腐蚀：加速"},Description={["daa2e216f45f4809:106"]="当堕落之血达到25%时，一个玩家获得腐蚀：加速效果，快速提高其腐蚀术的等级。"}}
D.ClientTexts.JournalSection[3223]={Name={["d5d2ce77dd492c74:19"]="腐蚀：疫病"}}
D.ClientTexts.JournalSection[3282]={Name={["b125aa579b4bedda:8"]="尾击"}}
D.ClientTexts.JournalSection[3225]={Name={["43f444d3a82a0e36:19"]="腐蚀：绝对"}}
D.ClientTexts.JournalSection[3226]={Name={["31a108d63a217045:32"]="第一阶段：我要亲手消灭你们！"}}
D.ClientTexts.JournalSection[3227]={Name={["10a8911d7b10172e:5"]="毁灭"}}
D.ClientTexts.JournalSection[3228]={Name={["c9992c60e35d7a53:11"]="烈焰吐息"}}
D.ClientTexts.JournalSection[3229]={Name={["984323d378c93750:14"]="暮光切割射线"}}
D.ClientTexts.JournalSection[3230]={Name={["bd97fac7bb926a88:13"]="暮光冲击波"}}
D.ClientTexts.JournalSection[3231]={Name={["a14d5a840c278b8b:14"]="暮光雏龙"},Description={["6afa5f15ad6a614a:72"]="希奈丝特拉周期性地召唤一组五条暮光雏龙来攻击入侵者。"}}
D.ClientTexts.JournalSection[3232]={Name={["2c91e07161c1ed98:12"]="暮光喷吐"}}
D.ClientTexts.JournalSection[3233]={Name={["7c029a97de5b1a20:15"]="暮光精华"}}
D.ClientTexts.JournalSection[3234]={Name={["b8c3e85862dd7587:21"]="第二阶段：我厌倦了这游戏！"},Description={["743b0432a268257d:108"]="当希奈丝特拉的生命值降到30%时，她会吸收周围的能量以恢复自己的力量，并撑起一道护盾。"}}
D.ClientTexts.JournalSection[3235]={Name={["782b1bca2e711db7:24"]="烈焰与暮光之战"},Description={["b6302d3f46deeb50:147"]="红龙凯雷斯特拉兹——凯伦是他的人类形态——会前来帮助玩家，与希奈丝特拉进行魔法对决。法力值高的一方可以获得优势。"}}
D.ClientTexts.JournalSection[3236]={Name={["f3d0b0c64c2f8f3f:12"]="血之专注"}}
D.ClientTexts.JournalSection[3237]={Name={["30ad0969ee57f690:11"]="法力壁垒"},Description={["04c7df89ced94350:91"]="一道强大的屏障笼罩希奈丝特拉，以损失法力值的代价持续为她恢复生命值。"}}
D.ClientTexts.JournalSection[3238]={Name={["8bc27006f89a7f3f:18"]="脉动的暮光之卵"},Description={["4de7fc8ff64976a8:64"]="希奈丝特拉在这些巨大的卵中储存了大量暮光能量。"}}
D.ClientTexts.JournalSection[3239]={Name={["6f85e069392bc458:19"]="暮光仇恨召唤者"},Description={["b4d7f1981f2ccb35:89"]="在凯伦和希奈丝特拉决斗时，这些暮光龙类会周期性地进入房间。"}}
D.ClientTexts.JournalSection[3240]={Name={["c9d1077b08644bcc:14"]="释放精华"}}
D.ClientTexts.JournalSection[3241]={Name={["1005704d5407aa22:11"]="战无不胜"}}
D.ClientTexts.JournalSection[3242]={Name={["bdbf74f85a8c0afd:13"]="暮光幼龙"},Description={["616c1bc82e64a1b9:82"]="暮光幼龙在凯伦和希奈丝特拉决斗时从洞穴边缘飞扑进来。"}}
D.ClientTexts.JournalSection[3243]={Name={["7105cc07dc589dd0:14"]="暮光之息"}}
D.ClientTexts.JournalSection[3244]={Name={["aa555604776cef83:13"]="吸收精华"}}
D.ClientTexts.JournalSection[3245]={Name={["0004169251b0b69d:18"]="第三阶段：去死吧！"},Description={["87a58c9ffe662820:223"]="当玩家摧毁脉动的暮光之卵之后，希奈丝特拉结束与凯伦的魔法决斗，开始愤怒地攻击玩家。由于从暮光龙卵中吸取了能量，她造成的伤害不再降低。"}}
D.ClientTexts.JournalSection[3246]={Name={["9f504a9c905c5167:15"]="红龙精华"}}
D.ClientTexts.JournalSection[3281]={Name={["715f4e0620a52013:17"]="暗影烈焰吐息"}}
D.ClientTexts.JournalSection[3247]={Name={["10a8911d7b10172e:5"]="毁灭"}}
D.ClientTexts.JournalSection[3248]={Name={["c9992c60e35d7a53:11"]="烈焰吐息"}}
D.ClientTexts.JournalSection[3249]={Name={["984323d378c93750:14"]="暮光切割射线"}}
D.ClientTexts.JournalSection[3250]={Name={["bd97fac7bb926a88:13"]="暮光冲击波"}}
D.ClientTexts.JournalSection[3251]={Name={["a14d5a840c278b8b:14"]="暮光雏龙"},Description={["6afa5f15ad6a614a:72"]="希奈丝特拉周期性地召唤一组五条暮光雏龙来攻击入侵者。"}}
D.ClientTexts.JournalSection[3252]={Name={["2c91e07161c1ed98:12"]="暮光喷吐"}}
D.ClientTexts.JournalSection[3253]={Name={["7c029a97de5b1a20:15"]="暮光精华"}}
D.ClientTexts.JournalSection[3264]={Name={["718165d2dbec7779:27"]="安保焚化措施"}}
D.ClientTexts.JournalSection[3265]={Name={["a2a825cfbc754684:15"]="获取目标"}}
D.ClientTexts.JournalSection[3266]={Name={["4ff660559f747ec0:12"]="火焰喷射器"}}
D.ClientTexts.JournalSection[3267]={Name={["f2e94be69dfe30fd:15"]="暗影包围"},Description={["f334674bfa62cdce:121"]="维克多·奈法里奥斯以阴影束缚选定目标的双脚，使其无法移动，直到火焰喷射器引导完成。"}}
D.ClientTexts.JournalSection[3268]={Name={["661e7d0c8ea4def7:7"]="屏障"}}
D.ClientTexts.JournalSection[3269]={Name={["3b7510fb63049354:12"]="化学炸弹"},Description={["7f319c877094d1f8:131"]="剧毒金刚会随机向一名玩家投掷一枚化学炸弹，在落点造成一片化学云雾。云中的任何单位受到的伤害都会提高。"}}
D.ClientTexts.JournalSection[3270]={Name={["aa27af12aadb5283:13"]="化学云雾"}}
D.ClientTexts.JournalSection[3271]={Name={["dcd2fe6f508e2b40:14"]="自动毒弹"}}
D.ClientTexts.JournalSection[3272]={Name={["0296c11d092a234a:10"]="毒液炸弹"},Description={["8873ab42847d40a5:150"]="剧毒金刚的自动毒弹制造的毒液炸弹会锁定攻击一名玩家。毒液炸弹会在接近目标近战范围后爆炸，产生一滩毒浆。"}}
D.ClientTexts.JournalSection[3273]={Name={["245b6f9ba15b8d06:12"]="毒浆"}}
D.ClientTexts.JournalSection[3274]={Name={["e6c5940cd9b244e3:17"]="浸毒外壳"},Description={["66ea7fa8f4a8bc23:73"]="对剧毒金刚的护盾造成伤害会使制造伤害的玩家受到浸透毒液的效果影响。"}}
D.ClientTexts.JournalSection[3275]={Name={["d9fbfa12f3737e8b:11"]="死亡之握"},Description={["54602f88955f9e45:113"]="维克多·奈法里奥斯有时会传送到一片化学云雾中心，然后施放死亡之握，将所有玩家拉入云雾中。"}}
D.ClientTexts.JournalSection[3276]={Name={["8360f6843acb386f:11"]="通电"}}
D.ClientTexts.JournalSection[3277]={Name={["4993ed6fc5c97c4c:21"]="第一阶段：复生吧，妹妹！"},Description={["9adfdc870ad07d50:77"]="奈法利安召来已经变成亡灵的妹妹奥妮克希亚，这两条龙会一起攻击玩家。"}}
D.ClientTexts.JournalSection[3278]={Name={["9d6257be823f5229:19"]="死亡之翼的子嗣"}}
D.ClientTexts.JournalSection[3279]={Name={["53c082a90ee7a0b6:8"]="奈法利安"}}
D.ClientTexts.JournalSection[3280]={Name={["697f38cf56c5ce3c:11"]="白骨冰雹"}}
D.ClientTexts.JournalSection[3283]={Name={["12d6903d060805b6:6"]="奥妮克希亚"}}
D.ClientTexts.JournalSection[3284]={Name={["bb1d9707e2023cf0:16"]="电能"},Description={["1ce9f55bffe0a4ec:145"]="奥妮克希亚会不断获得能量，当奈法利安施放通电时获得更多。如果奥妮克希亚的能量值全满，她就会触发电荷过载而爆炸，杀死所有玩家。"}}
D.ClientTexts.JournalSection[3285]={Name={["2a1f935331f6f258:18"]="闪电倾泻"}}
D.ClientTexts.JournalSection[3286]={Name={["715f4e0620a52013:17"]="暗影烈焰吐息"}}
D.ClientTexts.JournalSection[3287]={Name={["b125aa579b4bedda:8"]="尾击"}}
D.ClientTexts.JournalSection[3288]={Name={["9b464bd9f6f1bb62:18"]="电荷过载"}}
D.ClientTexts.JournalSection[3289]={Name={["7bef7ca5dc941e98:20"]="复生的坚骨战士"},Description={["bce8c2ac182092bb:209"]="在第一阶段早期，奈法利安落地之前，他会召唤复生的坚骨战士。这些骷髅的能量值会不断衰减，耗尽能量之后就会死亡，但是如果它们被暗影烈焰吐息或暗影爆燃火花击中，则会恢复能量。"}}
D.ClientTexts.JournalSection[3290]={Name={["c1fa664754d2635c:17"]="强化打击"}}
D.ClientTexts.JournalSection[3291]={Name={["cbb6499b32519f50:26"]="第二阶段：诅咒你，凡人！"},Description={["bac0e361b6d31cea:155"]="当玩家杀死奥妮克希亚之后，奈法利安会飞上空中，将屋内填满岩浆，只留三个可以立足的平台。然后奈法利安会在每个平台上召唤一个原型多彩龙人。"}}
D.ClientTexts.JournalSection[3292]={Name={["521dbfc294072e17:31"]="第三阶段：你将不得好死！"},Description={["ca5d06b8de9de83b:95"]="在玩家杀死所有原型多彩龙人之后，岩浆退去，奈法利安降落以结束战斗。"}}
D.ClientTexts.JournalSection[3295]={Name={["2bd742220e706181:8"]="统御"}}
D.ClientTexts.JournalSection[3296]={Name={["d6d61183f038e758:11"]="虹吸能量"},Description={["c03011eb3f82f012:101"]="被控制的玩家吸收奈法利安用来控制自己的无限力量中的一小部分，以获得被窃取的能量效果。"}}
D.ClientTexts.JournalSection[3297]={Name={["3e0ed0e7ea72f7fe:11"]="被窃取的能量"}}
D.ClientTexts.JournalSection[3298]={Name={["eefc8b1e7e791af1:12"]="解放你的思想"}}
D.ClientTexts.JournalSection[3299]={Name={["b70f01d5b7d5bbaa:18"]="原型多彩龙人"},Description={["bc5929895ae4eaa4:74"]="每座平台上都出现一个原型多彩龙人。它们站在原地，施放冲击新星。"}}
D.ClientTexts.JournalSection[3300]={Name={["7509354fb3ad5c04:9"]="冲击新星"}}
