D.ClientTexts.JournalSection[3306]={Name={["7bef7ca5dc941e98:20"]="复生的坚骨战士"},Description={["0199ebf1f2afd624:189"]="复生的坚骨战士可以在第三阶段复活。这些骷髅的能量值会不断衰减，耗尽能量之后就会死亡，但是如果它们被暗影烈焰吐息或暗影爆燃火花击中，则会恢复能量。"}}
