D.ClientTexts.JournalSection[3357]={Name={["903a82c0c9a8fa4f:13"]="召唤灰鳞矮人"},Description={["d5f44d4632f9383d:141"]="乌比斯将军周期性地从身后的废墟中召唤穴居人助战。一个恶毒的穴居人和三个洞窟穴居人会跳下来加入战斗。"}}
D.ClientTexts.JournalSection[3358]={Name={["10ad7d237ddeb702:14"]="恶毒的穴居人"},Description={["adfd8e625e271caf:59"]="恶毒的穴居人的生命值很低，且受到了莫德古德的怨念的诅咒。"}}
