D.ClientTexts.JournalSection[3364]={Name={["65834d5824540ba9:17"]="达加·燃影者"},Description={["446b79da090397e3:171"]="达加·燃影者独自与玩家作战，直至他的生命值降到30%以下。此时他会呼叫瓦里昂娜加入战斗。达加会骑在瓦里昂娜的背上继续作战。"}}
D.ClientTexts.JournalSection[3365]={Name={["72bbee111e3efee8:17"]="燃烧的暗影箭"}}
D.ClientTexts.JournalSection[3366]={Name={["95a34a79b33bd1ec:17"]="焰之祈祷"}}
D.ClientTexts.JournalSection[3367]={Name={["5473382eb12dcf75:20"]="被召唤的烈火幽灵"},Description={["00259fb8285cf557:147"]="这个生命值很低的怪物会随机跑向一名玩家，一切试图使其改变目标的努力都是徒劳的。如果它碰到目标玩家，则会施放超级新星。"}}
D.ClientTexts.JournalSection[3368]={Name={["e17a57c8424023e7:9"]="超级新星"}}
