D.ClientTexts.JournalSection[3679]={Name={["39e0497b695adcd0:31"]="青铜龙军团的祝福"}}
D.ClientTexts.JournalSection[3680]={Name={["f21a614148dfa63c:15"]="时光沙漏"},Description={["d63e7695692eb624:187"]="姆诺兹多偷取了时光沙漏，并把其禁锢在艾泽拉斯的时光之末中。在战斗中，玩家可以使用它施放5次时光倒转。"}}
D.ClientTexts.JournalSection[3681]={Name={["64a265bd3f3edc48:10"]="时光倒转"},Description={["2c871703518681d6:193"]="时光倒转效果可将时间拨回到战斗开始时，重置所有玩家的生命值，法力值和技能冷却。同时，移除姆诺兹多施放的所有扭曲炸弹。"}}
D.ClientTexts.JournalSection[3684]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["3c0b9799c533d24e:48"]="永恒之井只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[3875]={Name={["d30323e51c459af2:20"]="大地将你吞噬！"}}
D.ClientTexts.JournalSection[3876]={Name={["6802c9c169ef0266:17"]="共鸣水晶"}}
D.ClientTexts.JournalSection[3950]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["6b25859b6fa67358:48"]="暮光审判只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[3877]={Name={["bdb400df00c5b2d6:16"]="大地之怒"}}
D.ClientTexts.JournalSection[3878]={Name={["30c934bc456071eb:20"]="大地黑血"}}
D.ClientTexts.JournalSection[3879]={Name={["106184b8cf5b1831:5"]="践踏"}}
D.ClientTexts.JournalSection[3890]={Name={["2d6212ebff1f46c4:10"]="破甲"}}
D.ClientTexts.JournalSection[3891]={Name={["c8a9c8d2030f3c27:7"]="狂怒"}}
D.ClientTexts.JournalSection[3912]={Name={["1aeb88b9f3b97010:8"]="冰枪"}}
D.ClientTexts.JournalSection[3913]={Name={["84b66c488333545b:7"]="寒冰之墓"}}
D.ClientTexts.JournalSection[3914]={Name={["e7c6a7fbf2a45cd2:13"]="寒冰暴雨"},Description={["ea924ff82d16cf71:107"]="哈格拉引导法术并使平台被寒冰暴雨所覆盖。寒冰暴雨保护哈格拉免受任何攻击和法术的伤害。"}}
D.ClientTexts.JournalSection[3915]={Name={["135b854c668b1cb5:18"]="水壕"}}
D.ClientTexts.JournalSection[3918]={Name={["4e7bfe9eda5d90bf:14"]="闪电风暴"},Description={["9831e6d295cd2d63:222"]="哈格拉引导一场闪电风暴对平台上的玩家执行电刑。一层水之护盾保护着哈格拉免受任何攻击和法术的伤害。\r\n\r\n当玩家使每个水晶导体超载以后，哈格拉会遭到导体的反噬停止引导，并使她受到电刑效果的影响。"}}
D.ClientTexts.JournalSection[3919]={Name={["c20331f8aa58df51:16"]="水晶导体"}}
D.ClientTexts.JournalSection[3920]={Name={["dd908bfa3ca1edbb:10"]="腐蚀"},Description={["ac7ffe565d764d2b:236"]="这些在死亡之翼体内蔓延的触须，正是上古之神的腐蚀留下的巨大痕迹。当死亡之翼背上的装甲板掉落，露出破绽后，这些触须会第一时间出现并迅速修复伤口，使其它生物无机可乘。"}}
D.ClientTexts.JournalSection[3923]={Name={["9cc7da246dfe5a13:26"]="源质强化装甲板"},Description={["9142b26ae175de57:176"]="巨龙之魂的攻击被偏转后摧毁了死亡之翼后背上的一大块装甲板，同时也松动了另外三块装甲板。玩家必须全部移除这类装甲板，才能使萨尔有机会正中目标。"}}
D.ClientTexts.JournalSection[3929]={Name={["0512fbaa21ac2b1d:23"]="死亡之翼的免疫系统"},Description={["18c16b03b747aee0:159"]="组成死亡之翼免疫系统的生物从装甲板掉落后留下的孔中蔓延而出。随着掉落的装甲板越来越多，死亡之翼的防御动作也将变得越发激烈。"}}
D.ClientTexts.JournalSection[3930]={Name={["a49683058bac2174:16"]="贪婪触须"}}
D.ClientTexts.JournalSection[3932]={Name={["0aa348aced4359a1:13"]="灼热血浆"}}
D.ClientTexts.JournalSection[3942]={Name={["4e28d403f98af77e:11"]="寒冰手"}}
D.ClientTexts.JournalSection[3943]={Name={["b7000afeaff3aa1b:13"]="寒冰链"}}
D.ClientTexts.JournalSection[3944]={Name={["8620565cd1aac06f:7"]="冰墓"},Description={["fb8f37a5a8840744:68"]="阿奎里恩用冰墓封住萨尔。摧毁冰墓就可以救出萨尔。"}}
D.ClientTexts.JournalSection[3946]={Name={["00726637312f97e4:14"]="冻结仆从"},Description={["e7d6f2be579ea0ff:76"]="阿奎里恩的爪牙聚集在峡谷周围，并随机对下方的玩家投掷冰冻巨石。"}}
D.ClientTexts.JournalSection[3948]={Name={["88ba7e165955087d:14"]="冰霜洪流"}}
D.ClientTexts.JournalSection[3949]={Name={["187ab9f7ea1f44ee:10"]="冰冻巨石"}}
D.ClientTexts.JournalSection[3951]={Name={["f5ffe957023c2ad2:20"]="上层精灵的尖啸"}}
D.ClientTexts.JournalSection[3952]={Name={["30a3fd4d8018b6ca:10"]="黑箭"}}
D.ClientTexts.JournalSection[3953]={Name={["7bf526826d2b26c7:10"]="邪恶射击"}}
D.ClientTexts.JournalSection[3954]={Name={["922ce1660d28d99d:14"]="凋零之箭"}}
D.ClientTexts.JournalSection[3955]={Name={["0deff8ec8dc16bd3:24"]="上层精灵的召唤"},Description={["0d8c27fd098d8554:517"]="希尔瓦娜斯跃入空中，将所有敌人朝她拖曳过去。她将召唤8个的复活的食尸鬼，环绕在自己周围。所有食尸鬼之间会形成暗影连接，并且它们身后的地带会充满暗影能量。食尸鬼会不顾一切地向希尔瓦娜斯冲去。但复活的食尸鬼走到希尔瓦娜斯身边时，会施放献祭法术。\r\n\r\n穿越任意食尸鬼之间的连接或滞留在食尸鬼身后的阴影中，会每秒对玩家造成毁灭痛苦。击杀一个复活的食尸鬼能够切断其与附近其他食尸鬼的连接，并移除其身后的阴影地带。"}}
D.ClientTexts.JournalSection[3956]={Name={["78ed1d4d6d1ba80e:13"]="着魔的魔导师"},Description={["1f8be64c97ef6f6d:297"]="艾萨拉女王命令两名着魔的魔导师攻击玩家。当玩家击败一名着魔的魔导师或者经过足够长的时间，另外两名魔导师将加入战斗。每个着魔的魔导师各擅长三系法术中的一系。\r\n\r\n当玩家击败所有着魔的魔导师，艾萨拉女王会从战斗中撤退，玩家赢得战斗。"}}
D.ClientTexts.JournalSection[3957]={Name={["ccc46b7060002dcd:10"]="冰霜魔导师"}}
D.ClientTexts.JournalSection[3958]={Name={["1a84ea06598ee371:8"]="掷冰"}}
D.ClientTexts.JournalSection[3959]={Name={["d90fb34c3c520d4f:9"]="寒冷之焰"}}
D.ClientTexts.JournalSection[3960]={Name={["8d47f0d66ceea559:11"]="霜刃"}}
D.ClientTexts.JournalSection[3961]={Name={["7da55c28dd0b14fb:9"]="火焰魔导师"}}
D.ClientTexts.JournalSection[3962]={Name={["41d831867c795275:8"]="火球术"}}
D.ClientTexts.JournalSection[3963]={Name={["41d86d2b835f2bb8:8"]="火焰炸弹"}}
D.ClientTexts.JournalSection[3964]={Name={["750de92e4f85d9b1:9"]="冲击波"}}
D.ClientTexts.JournalSection[3965]={Name={["d85afaaccb0cf0eb:11"]="奥术魔导师"}}
D.ClientTexts.JournalSection[3966]={Name={["d8cb8407ac2557bc:11"]="奥术震击"}}
D.ClientTexts.JournalSection[3967]={Name={["2d524b2fc37753c8:10"]="奥术炸弹"}}
D.ClientTexts.JournalSection[3968]={Name={["4092f6fced5ee1a1:17"]="女王的奴仆"},Description={["4780ebd30bf97c16:123"]="女王艾萨拉魅惑一个随机目标，使其变成一个傀儡。只有当傀儡的提线被打断时，这个玩家才能被解救出来。"}}
D.ClientTexts.JournalSection[3969]={Name={["fd5d1207bcf972fe:14"]="绝对服从"}}
D.ClientTexts.JournalSection[3970]={Name={["ea6c2bdb1b627dd0:12"]="集中怒火"}}
D.ClientTexts.JournalSection[3971]={Name={["1c813426622b7e23:12"]="灵魂汲取"}}
D.ClientTexts.JournalSection[3972]={Name={["031f0ae769d28786:17"]="干扰之影"}}
D.ClientTexts.JournalSection[3973]={Name={["959ff487e4f3bdea:17"]="末日黑洞"},Description={["9819b3c1392d19e6:93"]="督军佐诺兹召唤一个末日黑洞。黑洞将不断向前移动直到它碰到并吸取一个灵魂。"}}
D.ClientTexts.JournalSection[3974]={Name={["bec2a188adff1449:8"]="虚空箭"}}
D.ClientTexts.JournalSection[3978]={Name={["106802ab49b7446e:17"]="召唤舒玛之血"}}
D.ClientTexts.JournalSection[3979]={Name={["fc159a4c2055e629:12"]="炽热蒸汽"}}
D.ClientTexts.JournalSection[3980]={Name={["57e99866cbdbaea1:14"]="微光血球"},Description={["d7585ad4dc092f31:80"]="当一个微光血球触及约萨希，会为约萨希注入舒玛的微光血。"}}
D.ClientTexts.JournalSection[3981]={Name={["1cbff48435f81863:13"]="冰蓝血球"},Description={["8ff62e2384a08ee2:83"]="当一个冰蓝血球触及约萨希，会赋予约萨希召唤法力虚空的能力。"}}
D.ClientTexts.JournalSection[3982]={Name={["fe82948ab26788d7:14"]="赤红血球"},Description={["28af49be1075f21b:79"]="当一个赤红血球触及约萨希，会赋予约萨希灼热之血技能。"}}
D.ClientTexts.JournalSection[3983]={Name={["273bd1f1728d0f80:11"]="漆黑血球"},Description={["49b5b2a756d7f1ea:157"]="当一个漆黑血球触及约萨希，血球中的腐蚀会渗透到舒玛之口中。这种邪恶的腐蚀效果会周期性地生成被遗忘的无面者，攻击玩家。"}}
D.ClientTexts.JournalSection[3984]={Name={["bf79c9bf6abdbc2c:12"]="被遗忘的无面者"},Description={["a54ec08194d88c26:36"]="这些生物的攻击目标是随机的。"}}
D.ClientTexts.JournalSection[3985]={Name={["1d8d7aa849c6a53d:12"]="灵魂切割"}}
D.ClientTexts.JournalSection[3986]={Name={["d66db32c9454daff:13"]="酸液血球"},Description={["f1839e0a254b650d:118"]="当一个酸液血球触及约萨希，舒玛之口会注入酸液血，刺激更多的消化酸液生成。"}}
D.ClientTexts.JournalSection[3987]={Name={["25fdbabe56e132b7:15"]="暗影血球"},Description={["33f7b26c29455db9:82"]="当一个暗影血球触及约萨希，会赋予约萨希深度腐蚀技能。"}}
D.ClientTexts.JournalSection[3988]={Name={["bf3b8d508d4adb43:15"]="怒火扩散"}}
D.ClientTexts.JournalSection[3989]={Name={["d13e564d7a7d08ec:13"]="苟拉斯之爪"}}
D.ClientTexts.JournalSection[3990]={Name={["ec7054e92c5269fa:12"]="苟拉斯之眼"}}
D.ClientTexts.JournalSection[4027]={Name={["73ac251e3eb2c76b:29"]="第一阶段：龙骑兵，攻击！"},Description={["a965a545f2db1b36:180"]="战争大师黑角会紧贴天火号飞行，监督麾下的暮光幼龙大军对武装飞船投掷毁灭之球，并命令他的精锐龙骑兵加入战斗。"}}
D.ClientTexts.JournalSection[4033]={Name={["548e38304b31349d:36"]="第二阶段：看来还得我亲自上阵"},Description={["69ebef8f79669ec4:107"]="当天火号上的守军击退三波龙骑兵后，战争大师黑角会亲自跳上飞船甲板。"}}
D.ClientTexts.JournalSection[4034]={Name={["b51df4ef7e22f418:18"]="战争大师黑角"}}
D.ClientTexts.JournalSection[4037]={Name={["a2a4d3627442ca15:13"]="攻击守护巨龙"},Description={["16f33c54c5206823:117"]="死亡之翼开始寻找他的下一个攻击目标。在其肢体触须仍然抓住的平台中，死亡之翼会攻击玩家最多的那个平台。"}}
D.ClientTexts.JournalSection[4038]={Name={["78077079717c4ee4:12"]="肢体触须"},Description={["a8c7a2425b0d3395:49"]="死亡之翼用自己的肢体抓住各个平台。"}}
D.ClientTexts.JournalSection[4039]={Name={["d54cceaa431a0447:12"]="燃烧之血"}}
D.ClientTexts.JournalSection[4040]={Name={["af740d3d69276d06:24"]="第一阶段：最后一战"},Description={["4551f4358d4e662e:72"]="只要死亡之翼畸变的肢体使他附着于平台之上，他就对他的敌人进行持续的攻击。"}}
D.ClientTexts.JournalSection[4046]={Name={["6b49b3dc552fd61b:21"]="第二阶段：垂死挣扎"},Description={["1dc420d3e7f0b2e2:58"]="死亡之翼的生命值降至20%的时候会降落到平台上。"}}
D.ClientTexts.JournalSection[4050]={Name={["7c9d793eef1dc8fd:4"]="侧翻"},Description={["4b92c7306fdbfa17:198"]="在整个战斗中，当死亡之翼感觉到所有玩家都站在他背脊的同一侧时，会试图将玩家从他的背上摔下去。在侧翻过程中，所有没有黏着在他背上的玩家或生物都将被他摔下。"}}
D.ClientTexts.JournalSection[4051]={Name={["b4e76715a73ddbfa:14"]="装甲板连接束"},Description={["3bbc51974002be08:128"]="当死亡之翼的一片装甲板被撬开之后，装甲板连接束就会暴露出来。摧毁那些纤维束正是移除装甲板的关键所在。"}}
D.ClientTexts.JournalSection[4052]={Name={["9eed85d09354b3f3:15"]="装甲板自我修复"},Description={["9b81a42a3605f309:148"]="当一块装甲板被掀起时，装甲板连接束会快速地收拢装甲板，使连接束不再受到进一步的伤害，并防止装甲板飞落。"}}
D.ClientTexts.JournalSection[4053]={Name={["b41ff41668b9e8bb:9"]="灼热之握"}}
D.ClientTexts.JournalSection[4054]={Name={["a954b60101d628e4:19"]="丑恶的融合怪"},Description={["67e882c30cc40814:122"]="这些不稳定的生物是由死亡之翼的熔火之血融合了源质装甲碎片和他原先的肌体形成的。"}}
D.ClientTexts.JournalSection[4562]={Name={["071dc6ccbaca86eb:11"]="腕眼者"}}
D.ClientTexts.JournalSection[4055]={Name={["bc5c40cdc98ddc2e:14"]="堕落熔岩"},Description={["3505330f0397597c:96"]="这些死亡之翼的体液活体显得非常脆弱，但是被杀死之后会形成一团无法摧毁的残渣。"}}
D.ClientTexts.JournalSection[4056]={Name={["0f2e7e157cafc9e0:5"]="爆炸"}}
D.ClientTexts.JournalSection[4057]={Name={["3f240176e8ce0aab:7"]="残渣"},Description={["8269b8b02140e747:155"]="消灭堕落熔岩会留下这个不可摧毁的残渣。它会缓慢地朝死亡之翼背上最近的洞口爬行，当它到达那里，它会重塑成一个新的堕落熔岩。"}}
D.ClientTexts.JournalSection[4058]={Name={["f73b31ee00e8596d:11"]="吸血"}}
D.ClientTexts.JournalSection[4059]={Name={["eb3d7ade5c8164c9:18"]="超热之核"}}
D.ClientTexts.JournalSection[4060]={Name={["7b09e6e556ae79b2:12"]="核能冲击"}}
D.ClientTexts.JournalSection[4061]={Name={["ca5fb1276d8bebc6:11"]="衰退"}}
D.ClientTexts.JournalSection[4062]={Name={["741a00eaba5efdaf:21"]="血之腐蚀：死亡"},Description={["4518dcec4ffb1809:212"]="死亡之翼的腐蚀在你的血脉中流动。如果没有被及时移除，这种腐蚀会在体内扎根，使你受到死亡之翼的血液的感染。当这个效果被驱散时，它会跳跃到一个新的目标身上，并且会变异成为血之腐蚀：大地。"}}
D.ClientTexts.JournalSection[4063]={Name={["ed66de85509aa4ae:16"]="死亡之翼的血液"}}
D.ClientTexts.JournalSection[4064]={Name={["742a30384c8f2145:21"]="血之腐蚀：大地"},Description={["ba577a7d4e78f8be:211"]="奈萨里奥的阴影在你的血脉中流动。如果没有被及时移除，这种腐蚀会在你体内扎根，使你受到奈萨里奥的血液的感染。当这个效果被驱散时，它会跳跃到一个新的目标身上，并且会变异成为血之腐蚀：死亡。"}}
D.ClientTexts.JournalSection[4065]={Name={["e7f7409e33e1a1ff:17"]="奈萨里奥的血液"}}
D.ClientTexts.JournalSection[4069]={Name={["058acd226954e211:14"]="束缚水晶"},Description={["30efb28f3f03220a:76"]="摧毁全部四个束缚水晶就能够打断哈格拉引导寒冰暴雨。"}}
D.ClientTexts.JournalSection[4070]={Name={["07a16e2b0a68ea58:24"]="被束缚的气元素"},Description={["10eb8d8adfc370b3:150"]="哈格拉在闪电风暴期间召唤元素来帮助她作战。当有玩家杀死一个元素时，会使得附近的一个水晶导体超载并对附近玩家施展电刑。"}}
D.ClientTexts.JournalSection[4072]={Name={["2509d270bde8d4a5:10"]="凋零意志"}}
D.ClientTexts.JournalSection[4076]={Name={["55a0d0f53ce0c9f4:15"]="猜忌幻境"},Description={["e09e08dee260db11:59"]="疑之煞强迫所有玩家面对他们自己的怀疑臆象。"}}
D.ClientTexts.JournalSection[4091]={Name={["21a642b931a65198:12"]="吸取精华"}}
D.ClientTexts.JournalSection[4092]={Name={["c745662b76ce76a6:19"]="佩罗萨恩之眼"},Description={["8e6daf9b69e32900:445"]="在伊利丹打断吸取精华之后，佩罗萨恩回到阴影中去伏击英雄们。他召唤他的佩罗萨恩之眼来搜索玩家的踪迹。玩家获得暗影斗篷的保护，帮助他们不被佩罗萨恩之眼找到。\r\n\r\n如果玩家能够在40秒内不被发现，佩罗萨恩就会现身，并且被衰竭效果削弱。\r\n\r\n如果佩罗萨恩之眼发现了一名玩家，佩罗萨恩会将这名玩家标记为“无能的猎物”，从阴影中一跃而出，攻击这名玩家。"}}
D.ClientTexts.JournalSection[4100]={Name={["34031d319e00dc68:13"]="无尽狂怒"}}
D.ClientTexts.JournalSection[4102]={Name={["4e129886003efdbf:9"]="大灾变"}}
D.ClientTexts.JournalSection[4103]={Name={["8b191388e6cd8967:18"]="灼疮触须"},Description={["52130aeff04ddb44:116"]="在生命值降至75%、50%和25%时，肢体触须会衍生出许多灼疮触须，这些触须对具有范围效果的技能免疫。"}}
