D.ClientTexts.JournalSection[4123]={Name={["d2349c19d3c26b2a:10"]="守护巨龙"},Description={["8c2892961b1ec727:417"]="守护巨龙们都将在对抗死亡之翼的战斗中提供援助。当死亡之翼开始释放大灾变的时候，每条巨龙将对各个肢体触须引导暴露弱点，使得触须受到的伤害提高100%。 \r\n\r\n当每条守护巨龙各自负责的触须被摧毁时，就开始引导专注法术，不再能够用他们的气息和特殊技能帮助玩家。在第二阶段开始后，守护巨龙们将继续帮助玩家。"}}
