D.ClientTexts.JournalSection[4190]={Name={["51d3b2c547230660:10"]="复活的食尸鬼"},Description={["11c1a9eac6563119:150"]="当复活的食尸鬼走到希尔瓦娜斯身边时，它将施放献祭法术。\r\n\r\n每摧毁一个复活的食尸鬼，可以切断其与附近食尸鬼的连接，并移除其后方的阴影地带。"}}
