D.ClientTexts.JournalSection[4200]={Name={["9780243cd9b7a10b:14"]="暮光工兵"},Description={["a337416f00798904:162"]="低空飞掠的幼龙会对飞船甲板空投携带有强力炸药的地精。这些工兵会冲入飞船舰桥的缺口，并引爆自己身上破坏力巨大的炸药。"}}
D.ClientTexts.JournalSection[4201]={Name={["3ad17099df987860:8"]="自毁"}}
D.ClientTexts.JournalSection[4202]={Name={["29c71ec3c62caa86:10"]="天火号"},Description={["56ed15521f0a4983:213"]="这艘巨大的武装飞船由空军上尉斯威茨指挥，搭载大量火炮以及两门鱼叉炮作为防御手段。虽然坚固，但这艘飞船也不是坚不可摧的，它无法承受太多伤害，否则追杀死亡之翼的行动就会无疾而终。"}}
D.ClientTexts.JournalSection[4564]={Name={["f70bfd716a05ec80:16"]="爬行者赫杜姆"}}
D.ClientTexts.JournalSection[4203]={Name={["07a510d45428e163:7"]="格里昂纳"},Description={["0eb0d55791fcbff4:62"]="战争大师黑角乘坐这条巨大的暮光幼龙征战天际。"}}
D.ClientTexts.JournalSection[4204]={Name={["8619b106bcedb997:17"]="暮光杀戮"}}
D.ClientTexts.JournalSection[4205]={Name={["48b9d4f9d4dd0b4a:11"]="鱼叉炮"}}
