D.ClientTexts.JournalSection[4270]={Name={["2c40ec1b9bd180ac:9"]="玛诺洛斯"},Description={["cc821ddae4c648f5:55"]="玛诺洛斯与伊利丹·怒风展开了一场殊死搏斗。"}}
D.ClientTexts.JournalSection[4239]={Name={["a6b82a4cd7a8bafb:13"]="魔力之源"}}
