D.ClientTexts.JournalSection[4243]={Name={["73fbfe4856cc650d:21"]="艾泽拉斯最后的守护者"}}
D.ClientTexts.JournalSection[4247]={Name={["d91fd8de04dcbff1:19"]="不稳定的畸变体"}}
D.ClientTexts.JournalSection[4248]={Name={["bec98a2f880cef72:13"]="暮光位移"},Description={["cbd13744444a52c7:185"]="在战斗开始时，奥卓克希昂将所有敌人与其一同拉入暮光领域。在那里玩家将承受他最强大的暮光攻击。暮光领域将使玩家获得英勇意志技能。"}}
D.ClientTexts.JournalSection[4249]={Name={["6112bff7004d90e6:10"]="英勇意志"}}
D.ClientTexts.JournalSection[4250]={Name={["099e93e64d83407d:11"]="黯淡之光"}}
D.ClientTexts.JournalSection[4251]={Name={["4850e6045be9bc8b:14"]="暮光审判"}}
D.ClientTexts.JournalSection[4252]={Name={["bd9d328166aec8d0:13"]="暮光爆发"}}
D.ClientTexts.JournalSection[4254]={Name={["b4d075072e089b4c:16"]="暮光崩裂"},Description={["6387849c5883ec11:273"]="6分钟过去了，奥卓克希昂变得极其不稳定，已经无法被控制。它体内的能量爆发形成大范围的爆炸，摧毁一切周围的敌人，以及它自己。\r\n\r\n在此次战斗中，如果守护巨龙们的护盾在任何时候消失，都会使奥卓克希昂立即触发暮光崩裂。"}}
D.ClientTexts.JournalSection[4255]={Name={["41d91a5581b70e8e:15"]="黑暗幽影"},Description={["ab72ef796ad3c4ca:209"]="受到暮光审判的影响，暮光能量波动会贯穿受害者的躯体，使其更容易受到暮光审判负面效果的伤害。当暮光审判对其造成额外伤害时，玩家将立即被杀死。"}}
D.ClientTexts.JournalSection[4256]={Name={["1e0f904c8c5b98e3:6"]="萨尔"},Description={["9a89b41f8770531c:74"]="萨尔对上方的冻结仆从投掷熔岩，控制它们的数量。"}}
D.ClientTexts.JournalSection[4262]={Name={["3ad5d178efeb2fb1:7"]="克卓莫"},Description={["a2c5ae5a9c9754e7:131"]="当生命值降至90%，莫卓克将自身分裂成两半，他的孪生兄弟克卓莫破石而出。他的孪生兄弟会在莫卓克施放技能数秒后施放同样的技能。"}}
D.ClientTexts.JournalSection[4263]={Name={["70b8f0e20cd0f7b3:8"]="软泥喷吐"}}
D.ClientTexts.JournalSection[4265]={Name={["fb3c87b2f7824565:10"]="暗影凝视"}}
D.ClientTexts.JournalSection[4266]={Name={["ba93b10e5030de2d:14"]="苟拉斯之鞭"}}
D.ClientTexts.JournalSection[4267]={Name={["62ce3253340021d0:19"]="苟拉斯的漆黑血"}}
D.ClientTexts.JournalSection[4393]={Name={["326790175e44ad52:8"]="多普雷尔"}}
D.ClientTexts.JournalSection[4271]={Name={["b706e0931d06ce18:16"]="禁卫队长瓦罗森"},Description={["8e62583639e4b077:90"]="为了防止玛诺洛斯正在引导的法术被打断，禁卫队长瓦罗森对玩家展开攻击。"}}
D.ClientTexts.JournalSection[4272]={Name={["66a55476d953aa65:16"]="伊利丹·怒风"},Description={["1d7f104dc1c00d1a:81"]="伊利丹用近身缠斗困住了玛诺洛斯，使得玩家们能够尽全力击败禁卫队长瓦罗森。"}}
D.ClientTexts.JournalSection[4273]={Name={["ea8827b011b78c6f:18"]="泰兰德·语风"},Description={["f5378b9c474af427:105"]="为了阻止从永恒之井涌出的末日守卫摧毁者，泰兰德就位准备施放月神射击。"}}
D.ClientTexts.JournalSection[4274]={Name={["7bdb4be67088a2d9:18"]="玛法里奥·怒风"},Description={["b225065acf50c6fb:303"]="玛法里奥·怒风利用半神塞纳留斯赋予的自然力量将艾泽拉斯生物的意志集中到盘旋于永恒之井的恶魔之门上。当玛诺洛斯的生命值还剩25%时，玛法里奥将施法令传送门剧烈爆炸，并将恶魔军团拉出艾泽拉斯。"}}
D.ClientTexts.JournalSection[4275]={Name={["ffe6f7ea4340fd2b:8"]="魔能吸取"},Description={["aadb2be7a71c6e4c:146"]="当禁卫队长瓦罗森存活时，如果玩家对玛诺洛斯造成了重大伤害，玛诺洛斯会牺牲禁卫队长瓦罗森并使自身生命值回满。"}}
D.ClientTexts.JournalSection[4276]={Name={["2eb73a293a113af6:20"]="恐惧魔王削弱者"},Description={["f16d4cecc3d3803f:85"]="每过一段时间恐惧魔王削弱者就会从永恒之井中出现，试图削弱泰兰德的力量。"}}
D.ClientTexts.JournalSection[4277]={Name={["248057c136580d3e:16"]="致残鞭笞"},Description={["5a751fd2679591f3:113"]="恐惧魔王削弱者困住泰兰德，阻止其采取任何行动并使末日守卫遍布整个区域。"}}
D.ClientTexts.JournalSection[4278]={Name={["408ac9ca62c85b85:9"]="黑暗长矛"}}
D.ClientTexts.JournalSection[4279]={Name={["0c89709ced3fa2a9:16"]="献祭光环"}}
D.ClientTexts.JournalSection[4280]={Name={["7a31335abb390a23:9"]="恶魔冲锋"}}
D.ClientTexts.JournalSection[4281]={Name={["55f2ff63eb22eed8:12"]="恶魔视界"}}
D.ClientTexts.JournalSection[4282]={Name={["e82c473cdb44b249:14"]="萨格拉斯之赐"}}
D.ClientTexts.JournalSection[4283]={Name={["6a26cc4a4d7650a7:15"]="艾露恩的祝福"},Description={["3b44d70feabc73f2:202"]="当一个恐惧魔王削弱者对泰兰德施放致残鞭笞时，泰兰德会向艾露恩祈求祝福。所有附近的盟友都将受到祝福影响，他们的攻击和法术都将对次级恶魔造成额外的奥术伤害。"}}
D.ClientTexts.JournalSection[4284]={Name={["9130a71698b2a38f:11"]="邪火新星"}}
D.ClientTexts.JournalSection[4285]={Name={["b7a2a7177063c706:12"]="邪火风暴"}}
D.ClientTexts.JournalSection[4286]={Name={["ffbf7bf4a43a596b:8"]="邪能刃"}}
D.ClientTexts.JournalSection[4287]={Name={["b0e300dd07717d84:12"]="虚空之门"},Description={["43f7f826647ea9c5:152"]="玛诺洛斯从扭曲虚空中召唤一道传送门，使他能够召唤其恶魔盟友。随着他生命值的降低，更多不同种类的恶魔将穿越传送门，悉数登场。"}}
D.ClientTexts.JournalSection[4288]={Name={["543ce3c7a6ec5f4e:13"]="被插入的魔刃"}}
D.ClientTexts.JournalSection[4289]={Name={["c728b8359b9f3168:10"]="魔法打击"}}
D.ClientTexts.JournalSection[4290]={Name={["5c9b17a486f3366f:16"]="永恒之水"}}
D.ClientTexts.JournalSection[4291]={Name={["10694bb1a23b564e:5"]="嘲讽"},Description={["147a1e52f53e88ad:46"]="伊利丹挑衅玛诺洛斯对他展开攻击。"}}
D.ClientTexts.JournalSection[4292]={Name={["4e138a0ea1650fbf:11"]="艾露恩之手"}}
D.ClientTexts.JournalSection[4294]={Name={["002e0a7ad13c3e37:8"]="地狱犬"},Description={["5aeeaf0577711a22:86"]="当生命值降至85%，玛诺洛斯从虚空之门中召唤一只较弱的地狱犬来帮助他作战。"}}
D.ClientTexts.JournalSection[4295]={Name={["001ee7af9aa38e98:8"]="恶魔卫士"},Description={["c713405bd39f6786:86"]="当生命值降至70%，玛诺洛斯从虚空之门中召唤一个恶魔卫士来帮助他作战。"}}
D.ClientTexts.JournalSection[4296]={Name={["d0532864406f1d3f:19"]="末日守卫摧毁者"},Description={["2b4aa5554fff1fd6:82"]="当生命值降至60%，更多的末日守卫摧毁者会从虚空之门中涌出。"}}
D.ClientTexts.JournalSection[4297]={Name={["6b8bf4547939540b:8"]="地狱火"},Description={["3197b45d85f4fe5a:72"]="当生命值降至50%，玛诺洛斯召唤一波地狱火来帮助他作战。"}}
D.ClientTexts.JournalSection[4298]={Name={["779efa8eceb6de8f:29"]="第一阶段：解决乌合之众"},Description={["5bda98190d140980:121"]="当伊利丹和泰兰德忙于对付玛诺洛斯及其他从永恒之井入侵的恶魔时，玩家必须全力击败禁卫队长瓦罗森。"}}
D.ClientTexts.JournalSection[4299]={Name={["d0532864406f1d3f:19"]="末日守卫摧毁者"},Description={["815e77fda9661300:89"]="这些从永恒之井涌入的大型恶魔企图保护玛诺洛斯，但是泰兰德会阻止他们。"}}
D.ClientTexts.JournalSection[4300]={Name={["44b2f613064cd838:26"]="第二阶段：烈焰与黑暗"},Description={["a19bf6641fb241ab:196"]="当玩家击败禁卫队长瓦罗森时，他的魔化之刃会掉落到地上。玩家可以将魔刃向玛诺洛斯投掷并插入其体内，蕴藏于魔刃中的魔法会对这只恶魔造成大量的伤害。"}}
D.ClientTexts.JournalSection[4301]={Name={["2c40ec1b9bd180ac:9"]="玛诺洛斯"},Description={["a071e2bdf5ad92c2:88"]="受伤的玛诺洛斯继续战斗，打开一扇虚空之门召唤其恶魔盟友。"}}
D.ClientTexts.JournalSection[4303]={Name={["baef163c70528019:33"]="第三阶段：你们的世界将分崩离析！"},Description={["867af7c048727b01:100"]="泰兰德在消灭地狱火大军之后体力不支，伊利丹将强化自己力量来结束与玛诺洛斯的战斗。"}}
D.ClientTexts.JournalSection[4304]={Name={["2c40ec1b9bd180ac:9"]="玛诺洛斯"},Description={["380c2ce055755e21:62"]="玛诺洛斯已经身负重伤，但他仍继续为其主人萨格拉斯顽抗到底。"}}
D.ClientTexts.JournalSection[4305]={Name={["66a55476d953aa65:16"]="伊利丹·怒风"},Description={["d17821d1a5c74d36:55"]="伊利丹将使用恶魔能量强化自己来结束这场战斗。"}}
D.ClientTexts.JournalSection[4306]={Name={["ea8827b011b78c6f:18"]="泰兰德·语风"},Description={["a60dc2d55df21ad4:88"]="泰兰德召唤一股强大的奥术能量冲击，摧毁所有的次级恶魔，但因体力不支而倒下。"}}
D.ClientTexts.JournalSection[4307]={Name={["0eccc4055cad3570:9"]="月神射击"},Description={["81613a6b32483da6:69"]="泰兰德用她的月神射击遏制恶魔们源源不断地从永恒之井中涌出。"}}
D.ClientTexts.JournalSection[4308]={Name={["66a55476d953aa65:16"]="伊利丹·怒风"},Description={["86a491a50acec638:66"]="伊利丹使用他擅长的恶魔猎手技能继续对抗玛诺洛斯。"}}
D.ClientTexts.JournalSection[4309]={Name={["ea8827b011b78c6f:18"]="泰兰德·语风"},Description={["30d90ac3088edb38:83"]="泰兰德的箭支耗尽了，她祈求艾露恩的帮助，对抗源源不断的恶魔部队。"}}
D.ClientTexts.JournalSection[4310]={Name={["543ce3c7a6ec5f4e:13"]="被插入的魔刃"}}
D.ClientTexts.JournalSection[4311]={Name={["9130a71698b2a38f:11"]="邪火新星"}}
D.ClientTexts.JournalSection[4312]={Name={["d713075e9da443a9:12"]="艾露恩之怒"},Description={["88b894545458186b:66"]="泰兰德施放一股奥术能量冲击，消灭附近的次级恶魔。"}}
D.ClientTexts.JournalSection[4317]={Name={["337647c6d51585d7:20"]="舒玛的微光血"}}
D.ClientTexts.JournalSection[4318]={Name={["46414bd481a4e0db:8"]="法力虚空"}}
D.ClientTexts.JournalSection[4319]={Name={["4ce8cede3e05fcbb:12"]="灼热之血"}}
D.ClientTexts.JournalSection[4320]={Name={["d15df4faeb550e51:13"]="消化酸液"}}
D.ClientTexts.JournalSection[4321]={Name={["d2710cf8b71df187:14"]="深度腐蚀"}}
D.ClientTexts.JournalSection[4322]={Name={["8d3b25def916b8f1:13"]="虚空散射"}}
D.ClientTexts.JournalSection[4323]={Name={["84b7d70907ebefc4:7"]="寒冰之潮"}}
D.ClientTexts.JournalSection[4324]={Name={["04076feea314586d:6"]="冰刺"}}
D.ClientTexts.JournalSection[4325]={Name={["cc4bad3681562d71:10"]="霜冻"}}
D.ClientTexts.JournalSection[4326]={Name={["ef8a14aabf974705:8"]="触电反噬"}}
D.ClientTexts.JournalSection[4394]={Name={["e72c8a8d6f64447a:9"]="格鲁雷尔"}}
D.ClientTexts.JournalSection[4395]={Name={["f7d678df77d010be:8"]="瓦勒雷尔"}}
D.ClientTexts.JournalSection[4327]={Name={["020ef11f26241fd4:16"]="雷电导管"}}
D.ClientTexts.JournalSection[4328]={Name={["a64635b1f907eb00:12"]="风暴之柱"}}
D.ClientTexts.JournalSection[4345]={Name={["4850e6045be9bc8b:14"]="暮光审判"}}
D.ClientTexts.JournalSection[4346]={Name={["383823b58897c81a:22"]="守护巨龙的保护"},Description={["9329b560c9a51c73:60"]="在玩家和奥卓克希昂对战的过程中，守护巨龙们会为他们提供有限的帮助。"}}
D.ClientTexts.JournalSection[4347]={Name={["25a6a38b815871fc:18"]="腐蚀寄生虫"}}
D.ClientTexts.JournalSection[4348]={Name={["25a6a38b815871fc:18"]="腐蚀寄生虫"},Description={["33ff2cb0e728c215:72"]="当腐蚀寄生虫的效果结束，寄生虫会离开宿主玩家。"}}
D.ClientTexts.JournalSection[4349]={Name={["827ad6f8c16b41ef:18"]="不稳定腐蚀"}}
D.ClientTexts.JournalSection[4350]={Name={["7766ba0c73641c63:15"]="凝固之血"},Description={["78ac6744e144a02d:110"]="死亡之翼开始出血，在附近区域生成若干凝固之血。凝固之血会向死亡之翼移动。"}}
D.ClientTexts.JournalSection[4351]={Name={["7766ba0c73641c63:15"]="凝固之血"}}
D.ClientTexts.JournalSection[4354]={Name={["7105cc07dc589dd0:14"]="暮光之息"}}
D.ClientTexts.JournalSection[4355]={Name={["8a832ded5df9587a:15"]="吞噬遮幕"}}
D.ClientTexts.JournalSection[4356]={Name={["12dd1aa2e6ac7cbf:8"]="甲板起火"}}
D.ClientTexts.JournalSection[4357]={Name={["0927c3d254277d59:9"]="舷侧攻击"}}
D.ClientTexts.JournalSection[4361]={Name={["2e6ac0e8bee914b5:10"]="软泥喷吐"}}
D.ClientTexts.JournalSection[4362]={Name={["4ee4159faee61c38:17"]="坠入暮光"}}
D.ClientTexts.JournalSection[4363]={Name={["2d147f4cf6ada2cf:14"]="活力虹吸"}}
D.ClientTexts.JournalSection[4364]={Name={["031f0ae769d28786:17"]="干扰之影"}}
D.ClientTexts.JournalSection[4365]={Name={["d15df4faeb550e51:13"]="消化酸液"}}
D.ClientTexts.JournalSection[4367]={Name={["8d3b25def916b8f1:13"]="虚空散射"},Description={["f8cbe03d451dc5ca:207"]="当末日黑洞和玩家发生撞击，它会产生虚空散射效果，造成50000点暗影伤害。这种虚空散射的力量会使黑洞往反方向跳跃，它吸取的灵魂会使造成的伤害每次散射提高5%。"}}
D.ClientTexts.JournalSection[4386]={Name={["0635492788d78990:9"]="冰霜新星"}}
D.ClientTexts.JournalSection[4387]={Name={["062eb3645a7bbe39:9"]="寒冰箭"}}
D.ClientTexts.JournalSection[4388]={Name={["cbf4b0944acdf1fb:10"]="霜甲术"},Description={["600b0475587a6b20:102"]="典狱官斯迪尔基斯将自己包裹在冰霜中，护甲值提高，对他发动近战攻击的攻击者会受到冰冻效果影响。"}}
D.ClientTexts.JournalSection[4389]={Name={["c2c6bc1a87086923:7"]="冰冻"}}
D.ClientTexts.JournalSection[4390]={Name={["0639fc8124ac0640:9"]="防护冰霜结界"}}
D.ClientTexts.JournalSection[4391]={Name={["85fa8c7c8777ce79:9"]="安格雷尔"}}
D.ClientTexts.JournalSection[4392]={Name={["f0bdf5889cb00a79:9"]="西斯雷尔"}}
D.ClientTexts.JournalSection[4398]={Name={["15d451d9f211f988:12"]="易怒"},Description={["c87ae46c9bf6e9bf:58"]="当受到玩家的近战爆击时，安格雷尔被激怒。"}}
D.ClientTexts.JournalSection[4399]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[4400]={Name={["1c93af97a9332772:6"]="打击"},Description={["9cb92fbd4c2d384a:54"]="安格雷尔使用武器对一名玩家造成物理伤害。"}}
D.ClientTexts.JournalSection[4401]={Name={["df5d7fa9e9482504:11"]="盾牌格挡"}}
D.ClientTexts.JournalSection[4402]={Name={["73d4f8d794ac3bda:11"]="破甲攻击"}}
D.ClientTexts.JournalSection[4403]={Name={["a1f6e44e81899993:10"]="盾墙"}}
D.ClientTexts.JournalSection[4404]={Name={["cbf4b0944acdf1fb:10"]="霜甲术"},Description={["16e2f83e2114739b:97"]="西斯雷尔将自己包裹在冰霜中，护甲值提高，对她发动近战攻击的攻击者会受到冰冻效果影响。"}}
D.ClientTexts.JournalSection[4405]={Name={["c2c6bc1a87086923:7"]="冰冻"}}
D.ClientTexts.JournalSection[4406]={Name={["644a53079a314a34:8"]="暴风雪"}}
D.ClientTexts.JournalSection[4407]={Name={["062eb3645a7bbe39:9"]="寒冰箭"}}
D.ClientTexts.JournalSection[4408]={Name={["0639fc8124ac0640:9"]="防护冰霜结界"}}
D.ClientTexts.JournalSection[4409]={Name={["0635492788d78990:9"]="冰霜新星"}}
D.ClientTexts.JournalSection[4410]={Name={["351700818fe48c3e:10"]="冰锥术"}}
D.ClientTexts.JournalSection[4411]={Name={["9c31d6a05875dacf:9"]="双武器"},Description={["2b47c93b51199168:32"]="多普雷尔双持匕首。"}}
D.ClientTexts.JournalSection[4412]={Name={["1f125628b9d8eab1:14"]="影袭"},Description={["8fe839b3a147e0fe:64"]="多普雷尔对一名玩家造成额外的物理伤害。"}}
D.ClientTexts.JournalSection[4413]={Name={["0677cb60aa0f9f49:8"]="背刺"},Description={["8f2a1cd1768a0292:78"]="多普雷尔从背后袭击一名玩家，对其造成大量的物理伤害。"}}
D.ClientTexts.JournalSection[4414]={Name={["0f85b97cba92ebeb:5"]="凿击"},Description={["ac439308fee14b3f:97"]="多普雷尔凿击一名玩家使其瘫痪。多普雷尔只能在玩家对面着他时使用此技能。"}}
D.ClientTexts.JournalSection[4415]={Name={["6446921c87f600a1:7"]="割裂"}}
D.ClientTexts.JournalSection[4416]={Name={["7cd6759a8ea828c5:7"]="闪避"}}
D.ClientTexts.JournalSection[4417]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"}}
D.ClientTexts.JournalSection[4418]={Name={["abc3e8a67e4f4e01:12"]="致死打击"}}
D.ClientTexts.JournalSection[4419]={Name={["a4dca5b265a73ee5:9"]="断筋"}}
D.ClientTexts.JournalSection[4420]={Name={["f713e99eaff97ee7:6"]="癫狂"},Description={["7769b40d13374f5c:88"]="当格鲁雷尔的生命值依次降至66%及33%时，他都会将当前目标的威胁值清零。"}}
D.ClientTexts.JournalSection[4421]={Name={["21cf4f7a148254ab:12"]="鲁莽"}}
D.ClientTexts.JournalSection[4422]={Name={["7c97d17f18e203c8:4"]="治疗"},Description={["e8148cf88f1d7195:37"]="瓦勒雷尔为自己或一名盟友治疗。"}}
D.ClientTexts.JournalSection[4423]={Name={["e7da96a54cae163c:15"]="治疗祷言"}}
