D.ClientTexts.JournalSection[5498]={Name={["e9ab3df2cba4eda3:9"]="凋零缠绕"}}
D.ClientTexts.JournalSection[5499]={Name={["a45c70da8930711f:19"]="次级暗影裂隙"},Description={["062c2c024c7df4cd:114"]="高阶术士奈瑟库斯在一名玩家脚下制造裂隙，并每秒对裂隙中的玩家造成一次暗影伤害。"}}
