D.ClientTexts.JournalSection[5516]={Name={["68a7cbdd5852a818:21"]="第二阶段：第二节课"},Description={["c127d9b75398e232:210"]="指导者寒心的肉身死亡后，使她复活的邪恶魔法会逃回护命匣。\r\n\r\n指导者寒心灵魂的碎片逃离护命匣，并激活散落在教室里的魔法宝典。"}}
D.ClientTexts.JournalSection[5518]={Name={["ae42d7f86f52d521:20"]="暴乱的奥术典籍"}}
