D.ClientTexts.JournalSection[5523]={Name={["fb3a039c15b70755:10"]="暗影箭"}}
D.ClientTexts.JournalSection[5524]={Name={["f58dc4b18c2903f6:20"]="第一阶段：第一节课"}}
D.ClientTexts.JournalSection[5532]={Name={["e686b76cde54b4db:16"]="奇能迅击"}}
D.ClientTexts.JournalSection[5533]={Name={["13eaf98a24d1ba17:11"]="引力流"}}
D.ClientTexts.JournalSection[5534]={Name={["13bb38246649cb0f:16"]="扭曲幻象"}}
D.ClientTexts.JournalSection[5535]={Name={["be16ac4fd123956a:15"]="幻影旋风"}}
D.ClientTexts.JournalSection[8671]={Name={["8dae3dc5062424ae:10"]="声波场"}}
D.ClientTexts.JournalSection[5536]={Name={["d7f764f72031350e:20"]="野牛人的试炼"},Description={["6b1c2884ea873a0b:87"]="年轻的野牛人将面对自己的争吵和危殆。他必须找到这两者之间的一个平衡点来释放自己的灵魂。"}}
D.ClientTexts.JournalSection[5537]={Name={["9fb7751e1558f9f9:24"]="射日勇士"},Description={["41801e0363d92b42:170"]="在过去的日子里，天上有五个太阳灼烧着大地。大火在潘达利亚大地上蔓延，直到有一天赵·追日者向天空射出了无畏之箭，消灭了其中四个太阳。"}}
D.ClientTexts.JournalSection[5538]={Name={["8089c5e03d4e1dcb:11"]="炎阳光线"}}
D.ClientTexts.JournalSection[5540]={Name={["408fb0dfb0d1224c:11"]="游荡恶煞"}}
D.ClientTexts.JournalSection[5541]={Name={["527f1e0a741841c5:12"]="纠缠凝视"}}
D.ClientTexts.JournalSection[5542]={Name={["6aa0ba537be84a2e:34"]="第二阶段：追日者的腐化！"},Description={["981a6764d5f9ce49:85"]="游荡恶煞控制了赵·追日者！你必须击败他，来净化他的腐化！"}}
D.ClientTexts.JournalSection[5543]={Name={["6a742b04b83832a9:12"]="赵·追日者"}}
D.ClientTexts.JournalSection[5544]={Name={["3aa2a9eef607e47d:14"]="地狱火箭矢"}}
D.ClientTexts.JournalSection[5547]={Name={["3be431a1be8cb720:14"]="争吵和危殆"}}
D.ClientTexts.JournalSection[5548]={Name={["0f14aae3abe4d0b4:5"]="痛苦"}}
D.ClientTexts.JournalSection[5549]={Name={["127450ccbc68cff3:9"]="强烈"}}
D.ClientTexts.JournalSection[5550]={Name={["c070e42c76999189:11"]="消散"}}
D.ClientTexts.JournalSection[5551]={Name={["1bbbb39cef7f9c6f:8"]="寒冰之怒"}}
D.ClientTexts.JournalSection[5552]={Name={["647ca8114dce629e:7"]="生锈"}}
D.ClientTexts.JournalSection[5553]={Name={["01ca76455cc51f22:9"]="骨针"}}
D.ClientTexts.JournalSection[5554]={Name={["e84c2b2da6d359e0:9"]="灵魂烈焰"}}
D.ClientTexts.JournalSection[5558]={Name={["d937e165ed5dcd6c:27"]="第一阶段：把他们的骨头给我带来！"},Description={["5e3da36e24bfd8dd:203"]="黑暗院长加丁使莉莉安·沃斯转而攻击她以前的盟友，并用她威力强大的技能为他邪恶的目的搜集更多尸体。虽然她尝试与他的黑暗意志抗争，但她现在不能控制自己的行为。"}}
D.ClientTexts.JournalSection[5560]={Name={["556177532bd283f6:8"]="骨堆"},Description={["b1063bd46ef8d3e1:104"]="骨堆散落在进行召唤的房间里。使用骨堆会让一名玩家获得一层骨甲术效果。"}}
D.ClientTexts.JournalSection[5561]={Name={["0085e78af530519b:9"]="骨甲术"},Description={["31feba265432a10f:68"]="将一系列旋转的白骨围绕施法者，吸收一次白骨法术。"}}
D.ClientTexts.JournalSection[5563]={Name={["fb4337e5293576c2:10"]="暗影剃刀"}}
D.ClientTexts.JournalSection[5564]={Name={["2e51fb22849c7e73:12"]="死亡之握"},Description={["095412a55b70f516:55"]="莉莉安吸取黑暗能量并将所有玩家拉到她所在的位置。"}}
D.ClientTexts.JournalSection[5565]={Name={["0a4dd5452ae49dd2:24"]="第二阶段：你的灵魂归我啦！"},Description={["ecbcfb8ee046db1b:161"]="当莉莉安的生命值降低至60%时，她的意志就将崩溃。黑暗院长加丁强有力地将她那饱受折磨的灵魂从体内撕离，然后命令莉莉安的灵魂攻击玩家。"}}
D.ClientTexts.JournalSection[5567]={Name={["02a5dccf9abdc2b2:11"]="炽热之魂"}}
D.ClientTexts.JournalSection[5568]={Name={["5546d4ad0053d0e0:16"]="释放痛苦"},Description={["660f575fec6eea30:186"]="莉莉安近战攻击玩家时，她的苦痛会得到进一步释放。每次近战攻击，莉莉安都将再一次释放炽热之魂。然而，莉莉安灵魂的移动速度大大降低。"}}
D.ClientTexts.JournalSection[5569]={Name={["2f56af8fa08b780c:31"]="第三阶段：一具完美的尸体"},Description={["c6b228083d34237f:240"]="莉莉安灵魂的生命值降低至25%时，黑暗院长加丁会复活莉莉安的肉身，为莉莉安的灵魂作战。\r\n\r\n被复活的尸体保留着莉莉安·沃斯在第一阶段使用的所有技能。"}}
D.ClientTexts.JournalSection[5576]={Name={["3fdba895b507d9cc:9"]="黯焰"}}
D.ClientTexts.JournalSection[5577]={Name={["aa0c153313ce6f0a:11"]="凝视之怒"},Description={["a02aadbaee2b90d9:84"]="莉莉安的灵魂锁定一名玩家。她只会试着攻击那位玩家，并免疫嘲讽。"}}
D.ClientTexts.JournalSection[8374]={Name={["db7baf4c4f04cae3:11"]="螳螂妖虫群"},Description={["dd22bb0e314395f3:40"]="召集额外的扎尔提克螳螂妖前来助战。"}}
D.ClientTexts.JournalSection[5580]={Name={["f6bb0a9a80aac2d9:23"]="最终阶段：死亡，通灵师！"},Description={["eb578f86884a19a5:129"]="莉莉安肉身的生命值降低至1%时，她将聚集最后的力量和灵魂重新合体，与黑暗院长加丁拼死一搏。"}}
D.ClientTexts.JournalSection[5585]={Name={["0417e92d3a8eccb4:12"]="发疯"}}
D.ClientTexts.JournalSection[5586]={Name={["e16a309a1d0e8a65:11"]="震地"}}
D.ClientTexts.JournalSection[5588]={Name={["261c4ed4d92fa3eb:13"]="滚动的酒桶"},Description={["8a5636260825ef01:175"]="乌克乌克的随从不断扔出滚动的酒桶，酒桶会穿过房间直至撞到墙、玩家或者乌克乌克自己。生命值降低至90%、60%和30%时，随从扔出更多的酒桶。"}}
D.ClientTexts.JournalSection[5589]={Name={["7faf1ad66124e873:13"]="酒桶爆炸"}}
D.ClientTexts.JournalSection[5590]={Name={["b9cfdc26f370bf43:12"]="胡萝卜吐息"}}
D.ClientTexts.JournalSection[5591]={Name={["de1d5c5036f4b5b1:8"]="席卷之风"}}
D.ClientTexts.JournalSection[5593]={Name={["547ca8362b1b271f:7"]="跳跳兔"},Description={["52b1e9db36ecdec8:64"]="跳跳兔是最小的兔妖，只会到处跳，咬东西！"}}
D.ClientTexts.JournalSection[5595]={Name={["288fe54624f784f7:8"]="酒雾之箭"}}
D.ClientTexts.JournalSection[5596]={Name={["b240894680aff6f5:15"]="酿酒工艺：啤酒"},Description={["ab375fdeb9af6029:72"]="高老伯的新发酵工艺使炎诛获得两种啤酒酿造技能中的一种。"}}
D.ClientTexts.JournalSection[5598]={Name={["45d248f3f4f0b8c8:17"]="酿酒工艺：烈酒"},Description={["5b1f55a1d67c2466:77"]="高老伯修改了祖传秘方，使炎诛获得两种烈酒酿造技能中的一种。"}}
D.ClientTexts.JournalSection[5601]={Name={["5672e6d54c4715b0:12"]="炙炎拳"}}
D.ClientTexts.JournalSection[5602]={Name={["f036f4628cdba9f9:13"]="火焰风暴踢"}}
D.ClientTexts.JournalSection[5603]={Name={["3d2b3436f6fff2ed:11"]="升燃之火"}}
D.ClientTexts.JournalSection[5604]={Name={["f8e7c444180abff3:13"]="炙灼之土"}}
D.ClientTexts.JournalSection[5606]={Name={["a4007aaaacbd4f81:13"]="穿刺投掷"}}
D.ClientTexts.JournalSection[5607]={Name={["dc3b7baa9c0dac4f:12"]="死亡之花"}}
D.ClientTexts.JournalSection[5608]={Name={["b2a8c87bb3b063de:7"]="召唤猎犬"},Description={["aa2ce5642a4f0151:90"]="生命值降低至90%、80%、70%和60%时，驯犬者布兰恩将召唤一只顺从的猎犬进入战斗。"}}
D.ClientTexts.JournalSection[5609]={Name={["ecc7138d705e9c70:13"]="顺从的猎犬"},Description={["4dd35a3ed0e720b1:78"]="这只大型猎犬接受过驯犬者布兰恩的训练，会服从他的主人发出的任何命令。"}}
D.ClientTexts.JournalSection[5611]={Name={["a95660ed2f9ed30c:10"]="血性之怒"}}
D.ClientTexts.JournalSection[5612]={Name={["068b88784d6eb3a3:28"]="第一阶段：宁静之水，升腾吧！"},Description={["33e39a3b2e01310e:75"]="贤者马里用护盾保护自己，并用喷泉里的堕落之水攻击玩家。"}}
D.ClientTexts.JournalSection[5613]={Name={["781c37b340569108:15"]="堕落之水"}}
D.ClientTexts.JournalSection[5614]={Name={["84b67a0e010a756b:10"]="水流长枪"}}
D.ClientTexts.JournalSection[5616]={Name={["cf967aa0a9ee6781:18"]="腐蚀活水"},Description={["36e77a530f21ae64:150"]="受到贤者马里的控制后，喷泉中的煞魔腐蚀之水凝结成水元素。\r\n\r\n打败腐蚀活水会使它分裂成三滴腐蚀血滴。"}}
D.ClientTexts.JournalSection[5617]={Name={["90f79eee5568243f:14"]="腐蚀血滴"},Description={["50aec11ee3e44f9f:77"]="腐蚀血滴比腐蚀活水更小更弱，它会攻击玩家。"}}
D.ClientTexts.JournalSection[5618]={Name={["195106d21ef0d6bf:10"]="煞能残渣"}}
D.ClientTexts.JournalSection[5619]={Name={["7ffde877333ac07e:35"]="第二阶段：看那湍流之水的力量！"},Description={["862a32477d663a52:85"]="玩家击败四个腐蚀活水后，贤者马里将释放出他剩余的所有能量。"}}
D.ClientTexts.JournalSection[5620]={Name={["8cf0b06a5d83ac0d:8"]="冲刷"}}
D.ClientTexts.JournalSection[5621]={Name={["4d48dfdefe348d69:29"]="第一阶段：让你见识我的力量！"},Description={["53ecaf6beebbb458:64"]="古·穿云召唤碧空翔龙来帮他打败入侵者。"}}
D.ClientTexts.JournalSection[5624]={Name={["0af6a822c4ce8fad:31"]="第二阶段：放马过来！"},Description={["ef25b6403057ba0b:93"]="古·穿云进入冥想状态，并免疫所有伤害。碧空翔龙开始攻击。"}}
D.ClientTexts.JournalSection[5627]={Name={["4cccca3e598fa45d:23"]="第三阶段：别让我失望！"},Description={["1b7ada762dfe2ab3:66"]="玩家打败碧空翔龙后，古·穿云再次加入战斗。"}}
D.ClientTexts.JournalSection[5629]={Name={["2b8105953b562a32:15"]="召唤闪电"}}
D.ClientTexts.JournalSection[5630]={Name={["5ad6f2f11520fe4c:11"]="静电力场"}}
D.ClientTexts.JournalSection[5631]={Name={["8514ad6b5fa767c4:12"]="充能灵魂"},Description={["15dadbf4fe461abd:63"]="碧空翔龙用护盾保护古·穿云，使他免疫所有伤害。"}}
D.ClientTexts.JournalSection[5632]={Name={["f62a2bdf735e3eea:15"]="闪电吐息"}}
D.ClientTexts.JournalSection[5633]={Name={["79b176226cc048e5:14"]="磁力帷幕"}}
D.ClientTexts.JournalSection[5634]={Name={["4ccd5c523962696f:15"]="灵魂过载"},Description={["9d0d8c427b393d5b:85"]="对周围的敌人造成周期性的自然伤害，频率和所失去的生命值成正比。"}}
D.ClientTexts.JournalSection[5635]={Name={["462be83968660e8e:15"]="指挥官杜兰德"},Description={["4fd53b39c37bab06:94"]="血色十字军的新指挥官对玩家发动迅疾的连续闪电打击。"}}
D.ClientTexts.JournalSection[5636]={Name={["4a2d8dc543c5f8a4:12"]="钢铁闪耀"}}
D.ClientTexts.JournalSection[5637]={Name={["dff8bd757a239522:13"]="冲刺打击"}}
D.ClientTexts.JournalSection[5638]={Name={["14f3f7de2678dcb1:23"]="大检察官怀特迈恩"},Description={["97ea3a8e2f23fead:110"]="血色十字军的大检察官在指挥官杜兰德倒下时来助他一臂之力，使其复活与自己并肩战斗。"}}
D.ClientTexts.JournalSection[5639]={Name={["f514b821653b8fb4:16"]="真言术：盾"}}
D.ClientTexts.JournalSection[5640]={Name={["51662b63d2f5df0c:9"]="神圣惩击"}}
D.ClientTexts.JournalSection[5641]={Name={["fb34123efad48d9b:16"]="群体复活"},Description={["c75b9aad618cd7b8:88"]="大检察官怀特迈恩复活100码范围内所有阵亡的血色仲裁者来帮助她。"}}
D.ClientTexts.JournalSection[5642]={Name={["14577ff4da4f4c03:8"]="捕猎时间"}}
D.ClientTexts.JournalSection[5643]={Name={["24fa5948f4b53e1d:14"]="穿刺打击"}}
D.ClientTexts.JournalSection[5644]={Name={["69cec47172def3fa:14"]="惊声尖啸"},Description={["89875ceed2446fe5:85"]="跳跳大王会周期性地发出尖啸，召唤跳跳兔、蹦蹦兔和跳舞兔来帮忙。"}}
D.ClientTexts.JournalSection[5645]={Name={["028f7a73080be854:6"]="蹦蹦兔"},Description={["979887030fdc283a:57"]="体型更大的蹦蹦兔嘴上叼着一桶酒精炸药。"}}
D.ClientTexts.JournalSection[5646]={Name={["0d59013437a65c67:13"]="酒精炸药"}}
D.ClientTexts.JournalSection[5647]={Name={["f49086ad8301a0da:6"]="跳舞兔"},Description={["8fea13b3cc967bf6:33"]="大个跳舞兔拿着一把重锤。"}}
D.ClientTexts.JournalSection[5648]={Name={["4a9ebc132b5d6890:12"]="大棒槌"},Description={["684da3a9582c954e:104"]="跳舞兔死后会丢弃自己的大棒槌。玩家可以捡起大棒槌，获得三层粉碎技能效果。"}}
D.ClientTexts.JournalSection[5649]={Name={["1c0bdb82bbb24bc5:6"]="粉碎！"}}
D.ClientTexts.JournalSection[5650]={Name={["4613e94dd14fcbe2:17"]="酿酒工艺：麦酒"},Description={["338dd8508f21f519:65"]="高老伯的疯狂实验使炎诛获得两种麦酒酿造技能中的一种。"}}
D.ClientTexts.JournalSection[5692]={Name={["7f99a82e0dffaa29:12"]="紫晶之池"}}
D.ClientTexts.JournalSection[5651]={Name={["0f297f97d8664038:5"]="鼓胀"}}
D.ClientTexts.JournalSection[5652]={Name={["2664594a186310b1:12"]="幻灭酒雾"}}
D.ClientTexts.JournalSection[5653]={Name={["4b3076eabb4665f5:12"]="水泡护盾"},Description={["914da359675e7208:97"]="炎诛用8个小水泡盖住自己。每个水泡使炎诛受到的伤害降低10%。该效果可叠加。"}}
D.ClientTexts.JournalSection[5654]={Name={["b83855277bea85be:19"]="发酵酒灵"},Description={["2c7f3ef8d4bb6323:48"]="炎诛召唤发酵酒灵协助他。"}}
D.ClientTexts.JournalSection[5655]={Name={["a35944d65570ce71:7"]="活力发酵"}}
D.ClientTexts.JournalSection[5656]={Name={["bf172d35b6acfae8:11"]="碳酸饱和"}}
D.ClientTexts.JournalSection[5657]={Name={["20b9b82db0c422c2:11"]="碳酸气泡"}}
D.ClientTexts.JournalSection[5658]={Name={["697907295fa5de32:10"]="泡沫之墙"}}
D.ClientTexts.JournalSection[5659]={Name={["1061e31df87d3fe8:5"]="泡沫弹力"},Description={["770377dd3384d84e:62"]="炎诛的泡沫属性可使玩家跳得特别高。"}}
D.ClientTexts.JournalSection[5660]={Name={["b5d7c898cad5097f:11"]="扫射"}}
D.ClientTexts.JournalSection[5662]={Name={["da341bf99a501fe4:18"]="科里克提克干扰者"},Description={["9a66a28b508b3536:61"]="这些螳螂妖在空中飞行，不断用酸液炸弹轰炸平台。"}}
D.ClientTexts.JournalSection[5663]={Name={["c1a15216438951bf:8"]="酸液炸弹"}}
D.ClientTexts.JournalSection[5664]={Name={["c11a7991b0c6186c:16"]="科里克提克突袭者"},Description={["9c8b23a388bd961c:72"]="在突袭者加杜卡进行扫射时，螳螂妖突袭者会攻击平台上的玩家。"}}
D.ClientTexts.JournalSection[5666]={Name={["2b525a25e39e87e0:12"]="恶毒流质"}}
D.ClientTexts.JournalSection[5667]={Name={["180393999824f23a:15"]="狂乱攻击"}}
D.ClientTexts.JournalSection[5668]={Name={["c6eb4ace145262d1:16"]="科里克提克虫群"},Description={["adb919d7fa69e2de:66"]="数批援军不断攀上城墙来协助指挥官瑞魔克。"}}
D.ClientTexts.JournalSection[5670]={Name={["31da71c0b55374ad:8"]="泰坦寒气"}}
D.ClientTexts.JournalSection[5672]={Name={["fe1b00cf2f4cb44c:16"]="毁灭风暴"}}
D.ClientTexts.JournalSection[5673]={Name={["96aee415ad612cf0:14"]="毁灭之弧"}}
D.ClientTexts.JournalSection[5674]={Name={["131f04069099a2d1:10"]="泰坦火花"},Description={["c657c8f617c513e7:43"]="任何构造体死亡时，都会释放泰坦火花。"}}
D.ClientTexts.JournalSection[5676]={Name={["6dcb447f28c67992:16"]="皇帝的勇气"},Description={["9c8aadf09f7c4035:97"]="皇帝的勇气携带一根长柄武来侵袭对手，并用护盾和护甲构成一堵强大的防御之墙。"}}
D.ClientTexts.JournalSection[5677]={Name={["6450bd0889bd5665:17"]="皇帝的力量"},Description={["d0b942c7db35d0b4:93"]="装备重型护甲的皇帝的力量用巨大的双手铁锤制造出惊天动地的打击。"}}
D.ClientTexts.JournalSection[5678]={Name={["809273b801ebc871:13"]="皇帝的狂怒"},Description={["4e203ab267ebc503:128"]="皇帝的狂怒是最小的陶俑战士，擅长挥舞双斧快速发动攻击，他们曾一度位于雷神机械军的前锋位置。"}}
D.ClientTexts.JournalSection[5691]={Name={["e6f7fb7f922f1fde:16"]="紫晶守护者"}}
D.ClientTexts.JournalSection[5695]={Name={["8f611ca999ef9f42:15"]="白色地砖"},Description={["d670932738a80476:218"]="当一名玩家站在这些地砖上时，这些地砖将从活体紫晶、活体蓝晶、活体青玉和活体红玉中吸收能量。每块地砖可吸收一层能量。当前屋里每块充能地砖都可使每名玩家获得一层充能之瓦效果。"}}
D.ClientTexts.JournalSection[5696]={Name={["62dab2ffed736220:21"]="活体紫青水晶"},Description={["75858cff4117929a:117"]="支撑紫晶守护者的能量形成一个水晶。使用这块水晶的玩家会受到活体紫晶效果的影响。"}}
D.ClientTexts.JournalSection[5704]={Name={["08f622928b80ccfd:17"]="科里克提克破坏者"},Description={["3e4e164187e2ccb8:44"]="科里克提克破坏者会周期性地加入战斗。"}}
D.ClientTexts.JournalSection[5705]={Name={["866354dc8523d091:7"]="轰炸"}}
D.ClientTexts.JournalSection[5724]={Name={["0fa2120d16e0412e:18"]="虚无之触"}}
D.ClientTexts.JournalSection[5725]={Name={["bbdf7d7cebbcb6d5:14"]="聚集之疑"}}
D.ClientTexts.JournalSection[5726]={Name={["51e699354aff0158:15"]="剑曦和秦希"},Description={["feaacf309ba2c07b:61"]="剑曦和秦希在90秒后激活并共享生命值。"}}
D.ClientTexts.JournalSection[5727]={Name={["80df1abae44bd19b:19"]="投机打击"}}
D.ClientTexts.JournalSection[5728]={Name={["ad1a636ecacfb31b:13"]="磁化护甲"}}
D.ClientTexts.JournalSection[5729]={Name={["106184b8cf5b1831:5"]="践踏"}}
D.ClientTexts.JournalSection[5730]={Name={["42a7696b641df6a6:14"]="专注打击"},Description={["949ef38f66b0a39c:113"]="每个皇帝的狂怒随机将锁定一名玩家，只对该玩家进行攻击，直至将其杀死或狂怒无法再进行攻击为止。"}}
D.ClientTexts.JournalSection[5731]={Name={["eff604f2e306da65:9"]="解除护甲"},Description={["05e2322546954366:84"]="皇帝的狂怒装备很少的护甲，并且很容易受到所有群体控制效果的影响。"}}
D.ClientTexts.JournalSection[5732]={Name={["0804bce8f3e075c9:14"]="专注防御"},Description={["e785ab10fb97a5a1:141"]="皇帝的勇气协助剑曦或秦希，锁定一名坦克玩家，只对该玩家进行攻击，直至将其杀死或皇帝的勇气无法再进行攻击为止。"}}
D.ClientTexts.JournalSection[5733]={Name={["1b94dbfcf16b0b6f:14"]="阻碍猛刺"}}
D.ClientTexts.JournalSection[5734]={Name={["39438b3644768523:9"]="半身覆甲"},Description={["40ee959e2cc64503:194"]="皇帝的勇气装备护甲，保护他们身体的正面部分。半身覆甲会格挡或偏转玩家在皇帝的勇气正面施加的伤害，但皇帝的勇气仍然很容易受到移动限制效果的影响。"}}
D.ClientTexts.JournalSection[5735]={Name={["5de31d138f81f41c:15"]="充能粉碎"}}
D.ClientTexts.JournalSection[5736]={Name={["d36e3e8ee0af3387:9"]="全身覆甲"},Description={["7b00044acbef7b71:81"]="皇帝的力量装备重型护甲，使其免疫所有群体控制效果。"}}
D.ClientTexts.JournalSection[5737]={Name={["414567583d0ca0ff:13"]="专注能量"},Description={["19258f3b140f9c22:113"]="一个新造的泰坦火花锁定一名玩家，只对该玩家进行攻击，直至将其杀死或泰坦火花无法再进行攻击为止。"}}
D.ClientTexts.JournalSection[5738]={Name={["ec9dddd9d24c145e:16"]="造物之能"}}
D.ClientTexts.JournalSection[5739]={Name={["d08e0bce68b9a9af:13"]="暗影爪牙"},Description={["e8c0782967577aaa:89"]="暗影爪牙只存在于灵魂世界中，但会用灵魂之握在真实世界中对玩家造成伤害。"}}
D.ClientTexts.JournalSection[5740]={Name={["7403431fa424caa4:14"]="灵魂之握"}}
D.ClientTexts.JournalSection[5741]={Name={["fb3a039c15b70755:10"]="暗影箭"}}
D.ClientTexts.JournalSection[5742]={Name={["3eb51fa9f0d4f470:11"]="灵魂图腾"},Description={["7270886432c61a81:72"]="缚灵者戈拉亚周期性地随机在一个位置召唤灵魂图腾。"}}
D.ClientTexts.JournalSection[5743]={Name={["c7a16409e0e19a70:14"]="灵魂世界"}}
D.ClientTexts.JournalSection[5744]={Name={["a810030f0198d1e6:20"]="灵魂支配"},Description={["79244e305b28c4a1:216"]="治疗身处灵魂世界的玩家将会使其的灵魂受到灵魂支配的充能。灵魂支配的效果根据受到治疗的玩家的职业和专精的区别而不同，治疗时间越久效果越好。"}}
D.ClientTexts.JournalSection[5753]={Name={["5b23a839ce5f9cba:11"]="巫毒娃娃"}}
D.ClientTexts.JournalSection[5756]={Name={["0fa5596e58b4efed:10"]="放逐"}}
D.ClientTexts.JournalSection[5757]={Name={["766b948c21e6266b:14"]="灵魂撕裂者"},Description={["0acf50898d73fb2e:58"]="灵魂撕裂者试图撕裂被放逐受害者的灵魂。"}}
D.ClientTexts.JournalSection[5758]={Name={["e933eb6dde73bb5e:9"]="灵魂撕裂"}}
D.ClientTexts.JournalSection[5759]={Name={["fe1564c3a6c630d4:6"]="狂暴"}}
D.ClientTexts.JournalSection[5760]={Name={["b8a45a16be00cd8b:9"]="脆弱灵魂"}}
D.ClientTexts.JournalSection[5761]={Name={["b6cd285d174e2a56:14"]="活体紫晶"}}
D.ClientTexts.JournalSection[5762]={Name={["b324f04523eb2e3a:19"]="活体冰蓝水晶"},Description={["75679f4b8e5eec4e:113"]="支撑蓝晶守护者的能量形成一块水晶。使用这块水晶的玩家会受到活体蓝晶效果的影响。"}}
D.ClientTexts.JournalSection[5763]={Name={["c2346863332db0bc:12"]="活体蓝晶"}}
D.ClientTexts.JournalSection[5764]={Name={["187183a4455ca355:17"]="活体翠绿水晶"},Description={["84a67049ded0bf04:109"]="支撑青玉守护者的能量形成一块水晶。使用这块水晶的玩家会受到活体青玉效果的影响。"}}
D.ClientTexts.JournalSection[5765]={Name={["324398a2b7130c61:10"]="活体青玉"}}
D.ClientTexts.JournalSection[5766]={Name={["414ae0f52c85648c:19"]="活体赤红水晶"},Description={["f74074ab5b5279f2:113"]="支撑红玉守护者的能量形成一块水晶。使用这块水晶的玩家会受到活体红玉效果的影响。"}}
D.ClientTexts.JournalSection[5767]={Name={["d194bf1335c6eaea:12"]="活体红玉"}}
