D.ClientTexts.JournalSection[5787]={Name={["a46472b4c7f92823:11"]="水泡"},Description={["863cd98e9408b7b7:110"]="贤者马里在自己周围制造了一个巨大的水泡，使他免疫所有伤害，并将触到水泡的玩家击退。"}}
D.ClientTexts.JournalSection[5788]={Name={["46ec66412614ffd4:11"]="水泡爆炸"}}
