D.ClientTexts.JournalSection[5790]={Name={["45f37219756ecf36:10"]="煞能之触"}}
D.ClientTexts.JournalSection[5791]={Name={["ee2e26614dbd5d2e:13"]="大地污染"}}
D.ClientTexts.JournalSection[5792]={Name={["bf05a6d8b75dca5f:15"]="驱逐腐蚀"}}
D.ClientTexts.JournalSection[5793]={Name={["4cc09bc50a7a551a:11"]="长老睿盖尔"}}
D.ClientTexts.JournalSection[5794]={Name={["abd2091deb056160:10"]="长老阿萨尼"}}
D.ClientTexts.JournalSection[5795]={Name={["e38f81a794ad1662:10"]="烧尽"}}
D.ClientTexts.JournalSection[5796]={Name={["2f9749ddc8041aec:8"]="献祭"}}
D.ClientTexts.JournalSection[5797]={Name={["eb0be00f6a67ca66:11"]="严酷教训"},Description={["1894f022ed0cc8ed:76"]="黑暗院长加丁随机将一名玩家传送到他的书房，单独进行严酷的教导！"}}
D.ClientTexts.JournalSection[5798]={Name={["59a0eb66e8eb6815:18"]="作废的试验样本"},Description={["ddd9e05f9f6d051a:94"]="黑暗院长将这些以前的试验样本保存在附近的房间里。它们会攻击进入它们房间的任何人。"}}
D.ClientTexts.JournalSection[5799]={Name={["50141d0dc463bcac:16"]="新鲜的试验样本"},Description={["580dd7fd3bd2577a:103"]="黑暗院长将试验样本囚禁在附近的房间，并让其暂且存活以用于试验。每个试验样本都受到爆燃之痛。"}}
D.ClientTexts.JournalSection[5800]={Name={["0d6066acbaaac03b:13"]="爆燃之痛"}}
D.ClientTexts.JournalSection[5801]={Name={["30e313fa6f32103f:13"]="闪电箭"}}
D.ClientTexts.JournalSection[8644]={Name={["e9079dc2b3bbd3bb:8"]="摔绊"}}
D.ClientTexts.JournalSection[5802]={Name={["16d4e2246cbee935:15"]="闪电囚笼"}}
D.ClientTexts.JournalSection[5804]={Name={["4e7bfe9eda5d90bf:14"]="闪电风暴"}}
D.ClientTexts.JournalSection[5805]={Name={["d975ad311693c3fc:22"]="无可抗拒的腐蚀"}}
D.ClientTexts.JournalSection[5807]={Name={["104973b98d93fcb8:5"]="起立！"}}
D.ClientTexts.JournalSection[5808]={Name={["ead847f102462e3e:13"]="失败的学生"},Description={["3c93bacfcbb670ac:60"]="黑暗院长复活失败的学生的尸体来攻击玩家。"}}
D.ClientTexts.JournalSection[5809]={Name={["fd342e0e9f455daf:10"]="书房"}}
D.ClientTexts.JournalSection[5810]={Name={["61e04e701ae47cad:17"]="惊魂碎击"}}
D.ClientTexts.JournalSection[5811]={Name={["1934bc6fbf815a8a:11"]="烟雾之刃"}}
D.ClientTexts.JournalSection[5812]={Name={["cd9337bdbb7e0dba:8"]="煞能尖刺"}}
D.ClientTexts.JournalSection[5813]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[5814]={Name={["85bc6a1398e8e710:10"]="渐燃之恨"}}
D.ClientTexts.JournalSection[5815]={Name={["cc5d44b77ac801ac:8"]="煞能震爆"}}
D.ClientTexts.JournalSection[5816]={Name={["54308f4eb4d1d2b3:10"]="憎恨之握"}}
D.ClientTexts.JournalSection[5817]={Name={["aa4718fdddee89ba:14"]="蚀心之怨"},Description={["829b457e53f30c1d:103"]="祝踏岚在自己身边召唤一个强大的怨恨畸体，将玩家拉向它，并向它脚下的地面下毒。"}}
D.ClientTexts.JournalSection[5818]={Name={["278de3d650e070a7:13"]="煞能腐蚀"}}
D.ClientTexts.JournalSection[5819]={Name={["7229d779fb9527ac:9"]="水箭"}}
D.ClientTexts.JournalSection[5820]={Name={["18dbf18f18f378f4:15"]="净化之水"}}
D.ClientTexts.JournalSection[5821]={Name={["781c37b340569108:15"]="腐蚀之水"}}
D.ClientTexts.JournalSection[5822]={Name={["18700ffdb2e3ab3e:8"]="净化"}}
D.ClientTexts.JournalSection[5823]={Name={["d975ad311693c3fc:22"]="无可抗拒的腐蚀"}}
D.ClientTexts.JournalSection[5824]={Name={["f54a0702969f1efd:12"]="恐惧爪牙"},Description={["ab11be31963f6cd8:96"]="恐惧爪牙从永春台涌出，追逐剩余生命值最低守护者。"}}
D.ClientTexts.JournalSection[5825]={Name={["3bf598a3a07b21c4:16"]="堕落精华"}}
D.ClientTexts.JournalSection[8645]={Name={["661e5b398ab66360:7"]="齐射"}}
D.ClientTexts.JournalSection[5826]={Name={["0fa199de500d3237:13"]="恐惧精华"}}
D.ClientTexts.JournalSection[5827]={Name={["01945d5d0c361836:6"]="仇恨"},Description={["2346ea5c48c4c7ed:237"]="占据祝踏岚的恨之煞触摸玩家的思想。玩家的仇恨会随着时间的延长而增长，而且被踏岚的攻击命中后，仇恨还会进一步增长。恨之煞使仇恨全满的玩家受到憎恨之雾的影响，必须通过冥思才能解除该效果。"}}
D.ClientTexts.JournalSection[5828]={Name={["fd96260401c78505:10"]="憎恨之雾"}}
D.ClientTexts.JournalSection[5829]={Name={["636619b2b8104e9b:8"]="冥思"},Description={["1aa1577333ecf48c:73"]="通过冥想将憎恨之雾从你的脑子里清除。冥想时，你无法移动或作出动作。"}}
D.ClientTexts.JournalSection[5830]={Name={["943ea19519ca921a:12"]="怨恨之环"}}
D.ClientTexts.JournalSection[5832]={Name={["1a026fad503c9980:13"]="暗影之池"}}
D.ClientTexts.JournalSection[5833]={Name={["1975d4ed8f74313e:23"]="大型堕落精华"}}
D.ClientTexts.JournalSection[5834]={Name={["16a02a6852fcc73d:20"]="大型恐惧精华"}}
D.ClientTexts.JournalSection[5835]={Name={["012161d3323d16fe:15"]="暴虐之蒙恩"},Description={["584c53c41092790f:100"]="疯王被玩家打败后会以虚弱的状态继续战斗，只使用癫狂之吼技能。"}}
D.ClientTexts.JournalSection[5836]={Name={["29d1e9ff9482b3d4:14"]="癫狂之吼"}}
D.ClientTexts.JournalSection[5837]={Name={["f713e99eaff97ee7:6"]="疯乱"}}
D.ClientTexts.JournalSection[5838]={Name={["21a5b976ec6990c3:9"]="怯懦"}}
D.ClientTexts.JournalSection[5839]={Name={["3c8ba37198ecf0a8:12"]="疯狂心智"}}
D.ClientTexts.JournalSection[5840]={Name={["1f7b5c35ca059cf8:9"]="癫狂"},Description={["6f5e718fd31fc182:49"]="疯王被激怒，获得的疯狂等级加倍。"}}
D.ClientTexts.JournalSection[5841]={Name={["8731ed1d98741b2a:17"]="无情之齐昂"},Description={["315a1d4ccf55ac97:104"]="战王被玩家打败后会以虚弱的状态继续战斗，只使用侧援指令技能。"}}
