D.ClientTexts.JournalSection[5844]={Name={["dc5542427f37f7af:10"]="歼灭"}}
D.ClientTexts.JournalSection[5845]={Name={["93557af13e79692a:16"]="密封之盾"},Description={["013e1332b17a8d05:169"]="战王使用密封之盾，免疫所有攻击和法术。当密封之盾期间受到伤害性的技能或法术时，齐昂会回敬一次额外的攻击。"}}
D.ClientTexts.JournalSection[5846]={Name={["bd8304e057d638b9:15"]="迅弓之速不台"},Description={["4a82cf286fcab09d:96"]="匪王被玩家打败后会以虚弱的状态继续战斗，只使用掠夺技能。"}}
D.ClientTexts.JournalSection[5847]={Name={["ae07158343bf59e6:7"]="掠夺"}}
