D.ClientTexts.JournalSection[6012]={Name={["c1aaa8565af73d05:8"]="酸液喷射"}}
D.ClientTexts.JournalSection[5850]={Name={["c5d196459e0837dc:13"]="盗匪诡计"}}
D.ClientTexts.JournalSection[5851]={Name={["67466b3ccf0f8019:11"]="巧取豪夺"}}
D.ClientTexts.JournalSection[5852]={Name={["6cad9c6163e68596:22"]="永影之提安"},Description={["0f127bf4aef5ce37:105"]="巫王被玩家打败后会以虚弱的状态继续战斗，只使用不灭之影技能。"}}
D.ClientTexts.JournalSection[5853]={Name={["b5d919bc3978e11f:14"]="不灭之影"}}
