D.ClientTexts.JournalSection[5861]={Name={["320a65033ace13c0:12"]="定身箭矢"}}
D.ClientTexts.JournalSection[5862]={Name={["49cf70e4812861cd:19"]="复活堕落的十字军"}}
D.ClientTexts.JournalSection[5863]={Name={["089312b082293c61:14"]="堕落的十字军"},Description={["3d90b8023a19fe43:51"]="堕落的十字军被打败后，尸体保留下来。"}}
D.ClientTexts.JournalSection[5864]={Name={["c73876a2dd47d005:7"]="心智腐烂"}}
D.ClientTexts.JournalSection[5865]={Name={["28a8ca390e596684:10"]="灵魂强风"}}
D.ClientTexts.JournalSection[5866]={Name={["4f92f2e3c2ddfb1c:9"]="放逐灵魂"}}
D.ClientTexts.JournalSection[5867]={Name={["5eaaf4cc4ea670db:11"]="被放逐的灵魂"}}
D.ClientTexts.JournalSection[5868]={Name={["9ccc74bc1e6138f7:22"]="召唤灌魔幽灵"},Description={["9f7a289ee12cf1d1:40"]="萨尔诺斯在其附近召唤一个灌魔幽灵。"}}
D.ClientTexts.JournalSection[5869]={Name={["ee4dcffd66570b36:16"]="灌魔幽灵"},Description={["e77f6a5098ec7bdd:93"]="灌魔幽灵会尝试占据距离最近的堕落的十字军的尸体，使其变成一个灌魔僵尸。"}}
D.ClientTexts.JournalSection[5870]={Name={["13d7ad337705e762:15"]="灌魔僵尸"},Description={["0f0af34f1dbd22ee:55"]="灌魔僵尸是非常强大而且很难消灭的亡灵。"}}
D.ClientTexts.JournalSection[5871]={Name={["28a647f12c9c2be6:10"]="灵魂之箭"}}
D.ClientTexts.JournalSection[5873]={Name={["11dbdb3b4cd35390:25"]="魔古勇士的精质"}}
D.ClientTexts.JournalSection[5874]={Name={["40088daca4ab5f2d:15"]="拳之魂"}}
D.ClientTexts.JournalSection[5875]={Name={["4d8ac932698c0405:14"]="闪电之拳"}}
D.ClientTexts.JournalSection[5876]={Name={["c4f5db640f5e7573:9"]="震中"}}
D.ClientTexts.JournalSection[5881]={Name={["e50cf491cc8e0564:21"]="被偷走的石之精质"},Description={["2a5af680610f6521:85"]="担任坦克角色的玩家可得到觉醒的雕像留下的精质碎片。"}}
D.ClientTexts.JournalSection[5882]={Name={["b23bd6dd6e512e20:20"]="废灵壁垒"}}
D.ClientTexts.JournalSection[5883]={Name={["abc8f35342cf30c6:16"]="反射罩"},Description={["f0d2affbe937d320:150"]="携带被偷走的岩石精华的玩家可以对一名盟友施加反射罩，使玩家可以复制下一次攻击该名盟友的有害法术。"}}
D.ClientTexts.JournalSection[5884]={Name={["c39af68d6663361e:15"]="虹吸之盾"}}
D.ClientTexts.JournalSection[5885]={Name={["30dd767e7a1f6529:12"]="烈焰之矛"}}
D.ClientTexts.JournalSection[5886]={Name={["c934b97c2d736b3d:13"]="野性火花"}}
D.ClientTexts.JournalSection[5887]={Name={["efe30a986a13d8af:9"]="引导火焰"}}
D.ClientTexts.JournalSection[5888]={Name={["48feba3e8ec2c243:14"]="极速奥能"}}
D.ClientTexts.JournalSection[5889]={Name={["b27e75cde6dd8908:15"]="奥术回响"}}
D.ClientTexts.JournalSection[5890]={Name={["f1ff6244f62e37a9:16"]="灵魂之力"}}
D.ClientTexts.JournalSection[5891]={Name={["c39af68d6663361e:15"]="虹吸之盾"}}
D.ClientTexts.JournalSection[5892]={Name={["b4979896dd4fc309:14"]="暗影链"}}
D.ClientTexts.JournalSection[5893]={Name={["c47fcb1ff01671dc:11"]="雷霆一击"}}
D.ClientTexts.JournalSection[5894]={Name={["3650fd997d6b6a98:8"]="击倒"},Description={["8ddcc54b6f2e61d4:120"]="战争使者沃姆罗格随机选择一名玩家，并将其击倒，清除所有威胁值，并对被他击倒的目标造成大量的仇恨。"}}
D.ClientTexts.JournalSection[5895]={Name={["7c96b8c3bbd46250:4"]="恐惧"}}
D.ClientTexts.JournalSection[5896]={Name={["d02ef7a9189e227e:11"]="燃烧之槌"}}
D.ClientTexts.JournalSection[5897]={Name={["750de92e4f85d9b1:9"]="冲击波"}}
D.ClientTexts.JournalSection[5898]={Name={["e5bcee8c1c7da90b:15"]="横扫攻击"}}
D.ClientTexts.JournalSection[5899]={Name={["6fcc2ab884065d1b:10"]="刃舞"},Description={["c42be8c33ea8e9e8:123"]="酋长卡加斯·刃拳进入刃舞状态，随机向多名玩家冲锋，对该玩家和附近的所有玩家造成物理伤害。"}}
D.ClientTexts.JournalSection[5900]={Name={["b095f85835187ab9:12"]="双重攻击"},Description={["ad9dd8a46970ec37:65"]="酋长卡加斯·刃拳的近战攻击有一定几率发动一次额外的攻击。"}}
D.ClientTexts.JournalSection[5901]={Name={["f65ed2cf04cf4d54:6"]="冲锋"}}
D.ClientTexts.JournalSection[5902]={Name={["30e313fa6f32103f:13"]="闪电箭"},Description={["6c5fd96d441bfa70:66"]="背叛者门努用闪电冲击一名玩家，造成自然伤害。"}}
D.ClientTexts.JournalSection[5903]={Name={["ec2b60076887c8cc:21"]="腐蚀地缚图腾"}}
D.ClientTexts.JournalSection[5904]={Name={["d26e77d561dd1c20:21"]="腐蚀石肤图腾"}}
D.ClientTexts.JournalSection[5905]={Name={["6e3fdfe8def87e2d:18"]="门努的治疗图腾"}}
D.ClientTexts.JournalSection[5906]={Name={["55247b7a8a92b229:18"]="堕落新星图腾"},Description={["b282bd5d545bbe0c:107"]="背叛者门努召唤一个新星图腾，在18秒后或被摧毁后对附近的所有玩家造成火焰伤害。"}}
D.ClientTexts.JournalSection[6013]={Name={["06d4c08fb0c9b9a8:12"]="猛禽一击"},Description={["b4357120939a0ba7:59"]="沼地领主穆塞雷克攻击一名玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[5907]={Name={["d8f801c6006a2575:13"]="重伤"}}
D.ClientTexts.JournalSection[5908]={Name={["5e7383acf164f94f:13"]="黏性苔藓"}}
D.ClientTexts.JournalSection[5909]={Name={["72332dc81304131f:9"]="水弹乱射"}}
D.ClientTexts.JournalSection[5910]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[5911]={Name={["7375a891f9275096:19"]="鲁莽鼓舞"}}
D.ClientTexts.JournalSection[5915]={Name={["043b51dac394edc7:17"]="杰翰的随从"},Description={["341a126718bebc02:66"]="杰翰一直与四个受训于不同战斗风格的蜥蜴人同行"}}
D.ClientTexts.JournalSection[5917]={Name={["acd85486edc8cad3:12"]="鼓舞呐喊"},Description={["89b316eb648ca0f0:101"]="在死亡时，杰翰发出最后的集结呐喊，使他的随从中所有剩余的成员获得鲁莽鼓舞的效果。"}}
D.ClientTexts.JournalSection[5918]={Name={["2d0248e1d469454e:16"]="格林托克铁皮战士"}}
D.ClientTexts.JournalSection[5919]={Name={["f947b17f4f73e9ea:13"]="钢铁保护者"}}
D.ClientTexts.JournalSection[5920]={Name={["f33af2b0d5535f45:15"]="格林托克潜藏者"}}
D.ClientTexts.JournalSection[5921]={Name={["105ab4ba9a257669:5"]="敲击"}}
D.ClientTexts.JournalSection[5922]={Name={["1d858dc51517f642:14"]="格林托克神谕师"}}
D.ClientTexts.JournalSection[5923]={Name={["4d26555e5a66dbbb:14"]="净化之焰"}}
D.ClientTexts.JournalSection[5924]={Name={["0c5328033f4d7f8e:14"]="格林托克妖术师"}}
D.ClientTexts.JournalSection[5925]={Name={["c9e13adf23d5c802:13"]="消沉巫术"}}
D.ClientTexts.JournalSection[5926]={Name={["156081bcc5b2bf2b:18"]="酋长的卫兵"},Description={["5f6299630f9923c2:63"]="酋长的卫兵来为酋长卡加斯·刃拳作战。"}}
D.ClientTexts.JournalSection[5927]={Name={["8b120135b4261864:12"]="野蛮的卫兵"}}
D.ClientTexts.JournalSection[5928]={Name={["c7c85273eeb78818:11"]="嗜血"}}
D.ClientTexts.JournalSection[5929]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[5930]={Name={["608c71bdf4d016b0:11"]="狂暴卫兵"}}
D.ClientTexts.JournalSection[5931]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"},Description={["2c0c236c05534659:72"]="狂暴卫兵发动顺劈斩，对一名玩家及离其最近的盟友造成物理伤害。"}}
D.ClientTexts.JournalSection[5932]={Name={["2fe9d27da2c8ace0:8"]="上钩拳"},Description={["bc22eb39c0af210c:72"]="狂暴卫兵使用上钩拳攻击一名玩家，造成物理伤害并将其击退。"}}
D.ClientTexts.JournalSection[5933]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[5934]={Name={["4a7c693a3de40be3:17"]="神射手卫士"}}
D.ClientTexts.JournalSection[5935]={Name={["6a6cec59b064e4f8:11"]="驱散射击"}}
D.ClientTexts.JournalSection[5936]={Name={["61f6acc92b8b1836:14"]="火焰射击"}}
D.ClientTexts.JournalSection[5937]={Name={["1b7d4d8356e8a67e:6"]="沸魂"}}
D.ClientTexts.JournalSection[5938]={Name={["e54601f2cf582441:11"]="无尽怒气"}}
D.ClientTexts.JournalSection[5939]={Name={["bbbe2f2598f1aace:14"]="艰涩思维"}}
D.ClientTexts.JournalSection[5940]={Name={["0b8880a53426785c:3"]="忿怒"},Description={["f095b4312cdf46ac:58"]="由怒之煞的无尽怒气召唤的具象之怒。"}}
D.ClientTexts.JournalSection[5941]={Name={["c4d0337f869d33ca:21"]="第一阶段：渐燃之怒"},Description={["6c5f4b8d9373c1f0:38"]="怒之煞的怒气在50秒内增长。"}}
D.ClientTexts.JournalSection[5942]={Name={["4626a46fbde3a4d8:12"]="渐燃之怒"}}
D.ClientTexts.JournalSection[5943]={Name={["9de1d7a52cbf5cb6:18"]="攻击行为"}}
D.ClientTexts.JournalSection[5944]={Name={["c0979e6cb8a69623:23"]="第二阶段：释放愤怒"},Description={["5feca1d41276015f:112"]="怒气值达到100时，怒之煞对敌人释放愤怒。该阶段将一直持续，直到怒之煞的怒气值降低至0。"}}
D.ClientTexts.JournalSection[5945]={Name={["a722f3e421fee977:14"]="释放愤怒"}}
D.ClientTexts.JournalSection[5946]={Name={["3edae385cbb57a80:18"]="召唤援军"},Description={["7488dd2ba23e9698:102"]="当将军帕瓦拉克的生命值降低至65%和35%时，他会躲在壁垒中，并召唤援军。"}}
D.ClientTexts.JournalSection[5947]={Name={["945bb41d9750d8bc:7"]="壁垒"}}
D.ClientTexts.JournalSection[5948]={Name={["bde4921ee65c8d49:17"]="空中轰炸"},Description={["b4b7aebdc006c98a:57"]="将军帕瓦拉克召唤希克提克琥珀工兵轰炸玩家。"}}
D.ClientTexts.JournalSection[5949]={Name={["2e2c5e7113260958:14"]="攻城炸药"}}
D.ClientTexts.JournalSection[5950]={Name={["0a0d2ad8106497bf:14"]="投掷炸药"}}
D.ClientTexts.JournalSection[5951]={Name={["6b38d7118c6cfe36:13"]="地面攻击"},Description={["6e5e70c2aa6d3f8b:65"]="将军帕瓦拉克召唤数波希克提克士兵为其作战。"}}
D.ClientTexts.JournalSection[5952]={Name={["196ba115ddcb111a:15"]="希克提克士兵"}}
D.ClientTexts.JournalSection[5953]={Name={["14d12b979043f694:13"]="锯齿利刃"}}
D.ClientTexts.JournalSection[5955]={Name={["50feaeff2946b790:9"]="利刃冲锋"}}
D.ClientTexts.JournalSection[5956]={Name={["d8afc2a743c571f2:7"]="风暴"}}
D.ClientTexts.JournalSection[5957]={Name={["862f12c76dd2b740:9"]="腐蚀毒液"}}
D.ClientTexts.JournalSection[5958]={Name={["b3dab91228db6b75:16"]="召唤腐蚀血球"},Description={["25654432f644d837:48"]="宰相金巴卡从树上召唤三个腐蚀血球。"}}
D.ClientTexts.JournalSection[5959]={Name={["3ad17099df987860:8"]="引爆"},Description={["3a892490b68e78ef:89"]="宰相金巴卡尝试引爆腐蚀毒液，造成的伤害值由腐蚀毒液的面积决定。"}}
D.ClientTexts.JournalSection[5960]={Name={["c1c568fae7460ee9:10"]="树脂残渣"}}
D.ClientTexts.JournalSection[5961]={Name={["7157c58052472b83:13"]="地狱冲锋"},Description={["736eaf5e8642a475:104"]="阿达罗格锁定着一名玩家，向其所在位置冲锋，并对冲击区域附近的所有玩家造成物理伤害。"}}
D.ClientTexts.JournalSection[5962]={Name={["c9992c60e35d7a53:11"]="烈焰吐息"},Description={["2dceb5b7e4a194a2:52"]="阿达罗格喷吐火焰，对一名玩家造成火焰伤害。"}}
D.ClientTexts.JournalSection[5963]={Name={["d586724672d5097d:15"]="扭曲元素"},Description={["cc9bdc0583ce7caa:76"]="黑暗萨满柯兰萨向一个敌人发射一支扭曲魔法之箭，造成暗影伤害。"}}
D.ClientTexts.JournalSection[5964]={Name={["63b0e280cc2c5f29:11"]="暗影风暴"}}
D.ClientTexts.JournalSection[5965]={Name={["6ca71b2904dfd668:8"]="岩浆喷吐"}}
D.ClientTexts.JournalSection[5966]={Name={["b82b00bf1eede3d8:8"]="下潜"},Description={["1fc4cddf79d4e592:64"]="焰喉在施放5次熔岩喷吐后下潜并出现在新的位置。"}}
D.ClientTexts.JournalSection[5967]={Name={["17915a9f8d6450b0:11"]="震地猛击"}}
D.ClientTexts.JournalSection[5968]={Name={["8c55538b99e1f9da:13"]="大地破裂"},Description={["4e10177a3612faf5:85"]="熔岩守卫戈多斯撕裂大地，对一名玩家造成物理伤害，并将其击退。"}}
D.ClientTexts.JournalSection[5969]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[5970]={Name={["5c2b97411d30248c:10"]="地面猛击"}}
D.ClientTexts.JournalSection[8646]={Name={["233570c08265b8cd:6"]="箭幕"}}
D.ClientTexts.JournalSection[5971]={Name={["a430eb6ca04cbb6d:16"]="旋风之斧"}}
D.ClientTexts.JournalSection[5972]={Name={["50ffb8b484c82625:9"]="利刃陷阱"}}
D.ClientTexts.JournalSection[5973]={Name={["d645fdf1b5ed616c:13"]="烈焰之环"}}
D.ClientTexts.JournalSection[5974]={Name={["cc7d536d35efdb62:15"]="死从天降！"}}
D.ClientTexts.JournalSection[5977]={Name={["13e93f895f87606a:16"]="毒液箭雨"}}
D.ClientTexts.JournalSection[5979]={Name={["f6ffd765a4388b90:9"]="酸液喷泉"}}
D.ClientTexts.JournalSection[5980]={Name={["2fe9d27da2c8ace0:8"]="上钩拳"},Description={["7039239876e3aa29:71"]="夸格米拉对一名玩家使用上钩拳，造成物理伤害，并将其击退。"}}
D.ClientTexts.JournalSection[5981]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"},Description={["623b2408062b32cb:73"]="夸格米拉发动顺劈斩，对一名玩家及离其最近的盟友造成物理伤害。"}}
D.ClientTexts.JournalSection[5982]={Name={["4d4feda1c016915e:15"]="包围之风"}}
D.ClientTexts.JournalSection[5983]={Name={["4d5613e027641b6b:14"]="落雷之云"}}
D.ClientTexts.JournalSection[5984]={Name={["1bab738b04efca5e:9"]="内爆"}}
D.ClientTexts.JournalSection[5985]={Name={["d224b4028fa73d13:22"]="盘牙水元素"},Description={["3507abc0b54592e7:59"]="两个盘牙水元素在战斗中保卫水术师瑟丝比娅。"}}
D.ClientTexts.JournalSection[5986]={Name={["538c3a343da89e79:15"]="水箭之雨"}}
D.ClientTexts.JournalSection[5996]={Name={["0ee54eec2ac4bdd5:14"]="充电网"}}
D.ClientTexts.JournalSection[5997]={Name={["58754f8f7e4198a6:14"]="超级缩小射线"}}
D.ClientTexts.JournalSection[5998]={Name={["e4d71748875cd3cf:8"]="锯齿利刃"}}
D.ClientTexts.JournalSection[5999]={Name={["e04b6aaae18534bb:20"]="斯蒂里格技师"},Description={["bd169bfb343ae53c:101"]="当机械师斯蒂里格的生命值降低至75%，50%和25%时，他会召唤斯蒂里格技师来修理他。"}}
D.ClientTexts.JournalSection[6000]={Name={["192ddc68372d172d:6"]="修理"}}
D.ClientTexts.JournalSection[6001]={Name={["569afe089f655983:13"]="纳迦蒸馏器"},Description={["bfadc741408d39b0:115"]="督军卡利瑟里斯从附近的纳迦蒸馏器抽取能量，如果在12秒后蒸馏器没有被摧毁，他就会获得督军之怒。"}}
D.ClientTexts.JournalSection[6002]={Name={["227cf9b92652ac76:13"]="督军之怒"}}
D.ClientTexts.JournalSection[6003]={Name={["690ee6b0c5a70653:15"]="法术反射"}}
D.ClientTexts.JournalSection[6004]={Name={["95f7fabb14a3575a:9"]="裂颅"}}
D.ClientTexts.JournalSection[6005]={Name={["04c0331d8f03a4ae:6"]="穿刺"}}
D.ClientTexts.JournalSection[6006]={Name={["43209e359bb4ac9a:16"]="幽暗沼泽蘑菇"},Description={["85e79ffb2e9d8438:92"]="霍加尔芬在随机位置召唤幽暗沼泽蘑菇，20秒后爆炸生成一片孢子云。"}}
D.ClientTexts.JournalSection[6007]={Name={["a7ae7f05f4efabf0:10"]="孢子之云"}}
D.ClientTexts.JournalSection[6008]={Name={["dbeb67572443658e:10"]="邪恶孢子"}}
D.ClientTexts.JournalSection[6009]={Name={["af70212ca78306bd:10"]="酸息术"}}
D.ClientTexts.JournalSection[6010]={Name={["1e0f912f8c629a98:6"]="痛击"},Description={["6eefd878e64d6b97:52"]="加兹安有一定几率施放痛击，额外发动一次攻击。"}}
D.ClientTexts.JournalSection[6011]={Name={["d6657593f9ae38bc:9"]="扫尾"}}
D.ClientTexts.JournalSection[6015]={Name={["57090b32bd591d37:12"]="力冠三军库乌艾"},Description={["b1138ca284a887f3:67"]="格尔桑氏族喜欢使用拳套，并且重视他们的魁麟伙伴。"}}
D.ClientTexts.JournalSection[6016]={Name={["a56db7954ef46f54:8"]="穆辛巴"},Description={["b5be02ceab7a1feb:86"]="穆辛巴是力冠三军库乌艾忠诚的伙伴，会在玩家打败其主人后停止战斗。"}}
D.ClientTexts.JournalSection[6017]={Name={["18e8c45b3ea27f18:6"]="毁灭"}}
D.ClientTexts.JournalSection[6018]={Name={["900402b0b83850db:9"]="震荡波"},Description={["67cb48ecff5c1c49:146"]="力冠三军库乌艾向前方发送一道震荡波。所有被震荡波击中的目标都会被抛到空中。玩家将受到物理伤害，伤害的数值由掉落的高度决定。"}}
D.ClientTexts.JournalSection[6019]={Name={["c09ed4c357faa314:14"]="鬼谋神算冥谷子"},Description={["7059426c4fd0a49f:49"]="哈飒克氏族精通基于风与闪电的魔法。"}}
D.ClientTexts.JournalSection[6020]={Name={["f8dc7d7e6f0acde9:15"]="回旋风暴"}}
D.ClientTexts.JournalSection[6021]={Name={["ad6fcc1177bcba96:13"]="磁场"}}
D.ClientTexts.JournalSection[6022]={Name={["30e313fa6f32103f:13"]="闪电箭"}}
D.ClientTexts.JournalSection[6023]={Name={["589f582d9625b594:20"]="势不可挡哈伊岩"},Description={["d8a4c9355be7b154:60"]="克尔格西氏族都是强大的战士，他们喜欢使用大型武器，并钟爱火焰魔法。"}}
D.ClientTexts.JournalSection[6024]={Name={["d1ea3eeb3d1acb4e:11"]="燃烧"}}
D.ClientTexts.JournalSection[6025]={Name={["0d8654918468b36c:6"]="流星"}}
D.ClientTexts.JournalSection[6026]={Name={["8cd643e38975a3fa:13"]="外伤打击"}}
D.ClientTexts.JournalSection[6027]={Name={["b093779bf6955e4e:10"]="多重射击"}}
D.ClientTexts.JournalSection[6028]={Name={["3da9d826a2c4347d:10"]="威慑"}}
D.ClientTexts.JournalSection[6029]={Name={["759fc28dfcfeeae2:9"]="击退"},Description={["d5a584c15216478a:60"]="沼地领主穆塞雷克击退一名玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[6030]={Name={["105af072a10b4fbf:5"]="射击"},Description={["58289e1434644c41:62"]="沼地领主穆塞雷克用弓箭朝一名玩家射击，造成物理伤害。"}}
D.ClientTexts.JournalSection[6031]={Name={["7c95316c33b25c9f:4"]="克劳恩"},Description={["292eea9e652fd499:51"]="沼地领主穆塞雷克命令克劳恩随机攻击一名玩家。"}}
D.ClientTexts.JournalSection[6032]={Name={["7c9a80f4ff9fde6b:4"]="重殴"},Description={["4ece60595e11c982:42"]="克劳恩重殴一名玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[6033]={Name={["76ef44d627d2102b:11"]="回响咆哮"}}
D.ClientTexts.JournalSection[6034]={Name={["72f2acf9023365d2:11"]="野性冲锋"},Description={["3bb55a28b969b4e7:21"]="克劳恩向一名玩家冲锋。"}}
D.ClientTexts.JournalSection[6035]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[6036]={Name={["a1212023a41d734a:8"]="飘浮"},Description={["0bb2ec21e876eafc:79"]="黑色阔步者的超能力使一名玩家飘浮，使其悬浮在空中。"}}
D.ClientTexts.JournalSection[6037]={Name={["aea1a777f3d52d22:12"]="静电充能"}}
D.ClientTexts.JournalSection[6038]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[6039]={Name={["2fc727cbc9e31354:12"]="孢子漫游者"},Description={["77f8d174d579c03b:52"]="黑色阔步者召唤孢子漫游者为其作战。"}}
D.ClientTexts.JournalSection[6040]={Name={["30e313fa6f32103f:13"]="闪电箭"},Description={["8ae9cec3e9243524:62"]="孢子漫游者用闪电冲击玩家，造成自然伤害。"}}
D.ClientTexts.JournalSection[6041]={Name={["d6f6e7195420dc86:11"]="蜘蛛疫病"}}
D.ClientTexts.JournalSection[6042]={Name={["b645fd9590769774:17"]="安卡哈守护者"},Description={["8135b64810633397:55"]="纳多克斯长老在战斗中召唤安卡哈守护者为其作战。"}}
D.ClientTexts.JournalSection[6043]={Name={["2bf3ae39594f64b4:12"]="守护者的光环"}}
D.ClientTexts.JournalSection[6044]={Name={["39465b30bc015e59:12"]="致命毒药"}}
D.ClientTexts.JournalSection[6045]={Name={["1c4b4e059984ac3a:6"]="疾跑"}}
D.ClientTexts.JournalSection[6046]={Name={["ebbcc46b071bc2a2:16"]="安卡哈群行蛛"},Description={["455aa891350eef28:56"]="纳多克斯长老在战斗中召唤安卡哈群行蛛为其战斗。"}}
D.ClientTexts.JournalSection[6047]={Name={["1062eeef540fb298:5"]="虫群"}}
D.ClientTexts.JournalSection[6048]={Name={["1c4b4e059984ac3a:6"]="疾跑"}}
D.ClientTexts.JournalSection[6049]={Name={["29cf4e9a582082c1:9"]="蜘蛛之怒"}}
D.ClientTexts.JournalSection[6050]={Name={["ba7e43678ea0df20:18"]="制造烈焰之球"}}
D.ClientTexts.JournalSection[6051]={Name={["c7c85273eeb78818:11"]="嗜血"}}
D.ClientTexts.JournalSection[6052]={Name={["2239276e2719fd1b:6"]="消失"},Description={["d33de8cd7742402c:96"]="塔达拉姆王子从视野中消失，并出现在一名玩家背后，使用吸血鬼的拥抱攻击该玩家。"}}
D.ClientTexts.JournalSection[6053]={Name={["57078729feb512d6:18"]="吸血鬼的拥抱"}}
D.ClientTexts.JournalSection[6054]={Name={["57078729feb512d6:18"]="吸血鬼的拥抱"}}
D.ClientTexts.JournalSection[6055]={Name={["02bf92048a4401f9:13"]="飓风打击"},Description={["1541b4c7d0c92c2a:110"]="耶戈达·觅影者对附近所有玩家发动飓风打击，造成物理伤害，并将其击退。"}}
D.ClientTexts.JournalSection[6056]={Name={["5598bfd712e4887e:12"]="雷霆震击"}}
D.ClientTexts.JournalSection[6057]={Name={["30e313fa6f32103f:13"]="闪电箭"},Description={["71d206ba1f7c271b:68"]="耶戈达·觅影者用闪电冲击一名玩家，造成自然伤害。"}}
D.ClientTexts.JournalSection[6058]={Name={["95515cb621db3729:18"]="暮光支配"},Description={["3a3433aff6b92b9c:188"]="当耶戈达·觅影者生命值降低至50%时，他会召唤一名暮光志愿者上前。暮光志愿者走到耶戈达·觅影者身边时将牺牲自己，并使耶戈达获得使者的礼物效果。"}}
D.ClientTexts.JournalSection[6059]={Name={["f19e843526bdbd8e:15"]="使者的礼物"}}
D.ClientTexts.JournalSection[6060]={Name={["7c9aa212038958b7:4"]="迷你"}}
D.ClientTexts.JournalSection[6061]={Name={["7c947883ffd2e5b4:4"]="猛击"},Description={["2bff4e734c8bffb4:47"]="埃曼尼塔猛击一名玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[6062]={Name={["02e058a3acc5ba4c:15"]="纠缠根须"}}
D.ClientTexts.JournalSection[6063]={Name={["038e0b4e21c67975:15"]="健康的蘑菇"},Description={["fdb138e924380b92:46"]="健康的蘑菇被摧毁时将释放高能蘑菇效果。"}}
D.ClientTexts.JournalSection[6064]={Name={["bc4f09170ba8f2bc:12"]="高能蘑菇"}}
D.ClientTexts.JournalSection[6065]={Name={["e4b5884e1f9ea4dd:17"]="有毒的蘑菇"},Description={["b98b6d39bff598c0:48"]="有毒的蘑菇被杀死时将释放毒云。"}}
D.ClientTexts.JournalSection[6066]={Name={["557f63741e0fc00d:11"]="毒云"}}
D.ClientTexts.JournalSection[6067]={Name={["ae40a79914d23590:8"]="精神鞭笞"}}
D.ClientTexts.JournalSection[6068]={Name={["f143b497de6370a2:16"]="暗影箭雨"},Description={["d69fce3ca0c7573d:72"]="传令官沃拉兹发射黑暗魔法飞弹，对所有玩家造成暗影伤害。"}}
D.ClientTexts.JournalSection[6069]={Name={["1bb5d0b6ddc224cf:6"]="碎裂"},Description={["bd6450d97738a5dc:119"]="传令官沃拉兹诅咒一名玩家，当其受到伤害时将额外受到暗影伤害。该效果每3秒只能触发一次。"}}
D.ClientTexts.JournalSection[6070]={Name={["89945e34cd4a3c73:8"]="疯狂"},Description={["8c5884ee869f489d:168"]="传令官沃拉兹使所有玩家陷入疯狂，使其对每个盟友产生一个扭曲面容的幻象。玩家会陷入疯狂之中，直到他们杀死面前所有扭曲面容为止。"}}
D.ClientTexts.JournalSection[6071]={Name={["cb52cc0b86ec7690:14"]="看守者希尔希克"}}
D.ClientTexts.JournalSection[6072]={Name={["bedb76fd2722a2be:7"]="蛛网裹体"}}
D.ClientTexts.JournalSection[6073]={Name={["edba89ef7c1ff33e:19"]="希尔希克的看守者"},Description={["8d9a73eb60b4cda8:159"]="一个看守者死亡时，看门者克里克希尔就会从剩余的看守者中再召唤一名来攻击玩家。所有的看守者都倒下后，克里克希尔就会自己攻击玩家。"}}
D.ClientTexts.JournalSection[6074]={Name={["56a3274c18571cc5:11"]="毒药喷洒"}}
D.ClientTexts.JournalSection[8658]={Name={["68e16bd82bf7c203:8"]="奔踏"}}
D.ClientTexts.JournalSection[6075]={Name={["7d535b4bce9884cc:12"]="感染撕咬"}}
D.ClientTexts.JournalSection[6076]={Name={["a3ccd0e956b4273a:13"]="看守者加什拉"}}
D.ClientTexts.JournalSection[6077]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[6078]={Name={["bedb76fd2722a2be:7"]="蛛网裹体"}}
D.ClientTexts.JournalSection[6079]={Name={["7d535b4bce9884cc:12"]="感染撕咬"}}
D.ClientTexts.JournalSection[6080]={Name={["b4206853c4571c0a:13"]="看守者纳尔伊"}}
D.ClientTexts.JournalSection[6081]={Name={["075ea64aa2081727:11"]="致盲之网"}}
D.ClientTexts.JournalSection[6082]={Name={["bedb76fd2722a2be:7"]="蛛网裹体"}}
D.ClientTexts.JournalSection[6083]={Name={["7d535b4bce9884cc:12"]="感染撕咬"}}
D.ClientTexts.JournalSection[6084]={Name={["ae40a79914d23590:8"]="精神鞭笞"}}
D.ClientTexts.JournalSection[6085]={Name={["c472bd41f29f495e:14"]="疲倦诅咒"}}
D.ClientTexts.JournalSection[6086]={Name={["84b41962476730c9:25"]="永春台"},Description={["472ed93cc8ed14a3:86"]="惧之煞潜伏在平台顶上，试图吞噬从平台中央发射出来的纯净之光。"}}
D.ClientTexts.JournalSection[6088]={Name={["791ed22cde953b67:11"]="恐惧之嗣"},Description={["477d2a326fc737d3:161"]="煞魔周期性地召唤一对恐惧之嗣来攻击玩家。每个恐惧之嗣都受到黑暗能量壁垒的保护，可以偏转来自正面的法术和攻击。"}}
D.ClientTexts.JournalSection[6089]={Name={["b37cba3167cdf146:15"]="外部神龛"},Description={["73e073a0b2c8d055:162"]="被不详蔑笑传送的这组玩家必须击败三个被煞魔附体的弩手中的一个。曾经的平台守护者杨国师、康成和昆锦纶会攻击玩家。"}}
D.ClientTexts.JournalSection[6090]={Name={["fe42533ab8cbf0b3:15"]="恐惧之境"},Description={["41d2836403f89bbf:184"]="在英雄难度下，惧之煞在生命值降至66%时，会退回恐惧之境，并同时将玩家拖入其中。这片潮湿的绝境是由煞魔所制造而来，煞魔在此处可获得一组新的技能。"}}
D.ClientTexts.JournalSection[6091]={Name={["1d8a0999f11df9be:9"]="纯净之光"},Description={["5468d0a1f0c35434:251"]="一道很窄、未被腐蚀的光束从平台的中心射向天空。当一名玩家站在这个光束上时，它就会弯曲，并形成一堵保护墙，这堵墙会在这位光芒勇士所在的位置呈“V”字形反向延伸。这会吸引惧之煞的注意，并锁定这位勇士。"}}
D.ClientTexts.JournalSection[6092]={Name={["9814b8025faa7895:11"]="光辉之墙"}}
D.ClientTexts.JournalSection[6093]={Name={["92407ccef74b27c7:12"]="恐惧吐息"}}
D.ClientTexts.JournalSection[6094]={Name={["7edc241aa4f30f4f:10"]="诡异颅骨"}}
D.ClientTexts.JournalSection[6095]={Name={["1cd69d5253377ce9:13"]="不详蔑笑"},Description={["bffba003a3aa88e4:108"]="煞魔邪恶地奸笑，将一队玩家传送至某一个外部神龛，使其与平台上堕落的守护者战斗。"}}
D.ClientTexts.JournalSection[6096]={Name={["b194db9ea424d937:14"]="伸展打击"}}
D.ClientTexts.JournalSection[6097]={Name={["da01c977a26475fa:15"]="穿刺之箭"}}
D.ClientTexts.JournalSection[6098]={Name={["105af072a10b4fbf:5"]="射击"}}
D.ClientTexts.JournalSection[6099]={Name={["fba721b4839df9b3:10"]="恐惧喷射"}}
D.ClientTexts.JournalSection[6273]={Name={["bde3b9418197eb80:7"]="治愈腿部"},Description={["c864f44801f38f1f:67"]="加拉隆周期性地治疗自己的一条断腿，使其恢复所有的生命值。"}}
D.ClientTexts.JournalSection[6100]={Name={["dc3b7baa9c0dac4f:12"]="死亡之花"}}
D.ClientTexts.JournalSection[6101]={Name={["e738581af11f5d89:8"]="无畏"}}
D.ClientTexts.JournalSection[6102]={Name={["0b1c280178d23aae:16"]="宿怨打击"}}
D.ClientTexts.JournalSection[6103]={Name={["df57ed8203aa980f:14"]="赤裸惊恐"}}
D.ClientTexts.JournalSection[6104]={Name={["b89900e3c415125a:10"]="龙卷水涌"}}
D.ClientTexts.JournalSection[6105]={Name={["5642c7b0fc27fbff:14"]="因畏惧而蜷缩"}}
D.ClientTexts.JournalSection[6106]={Name={["b82b00bf1eede3d8:8"]="下潜"}}
D.ClientTexts.JournalSection[6107]={Name={["fba6dc2e7b54f781:10"]="惊惧之嗣"},Description={["d0342fd868e95bd1:108"]="这个生物会注视着当前的光芒勇士。如果一名新的玩家变成光芒勇士，惊惧之嗣就会改变目标。"}}
D.ClientTexts.JournalSection[6108]={Name={["cd933820bb810e77:8"]="煞之脊刺"}}
D.ClientTexts.JournalSection[6109]={Name={["7ae50eabec0f9f4a:15"]="无尽黑暗"},Description={["98a2f9d99b1ea6b6:58"]="惊惧之嗣将立即杀死进入其近战范围的当前目标。"}}
D.ClientTexts.JournalSection[6110]={Name={["1d8a0999f11df9be:9"]="纯净之光"}}
D.ClientTexts.JournalSection[6112]={Name={["5bbb95c2b3966fab:13"]="光芒流转"},Description={["190122d5befda720:72"]="光芒勇士可以使用这个技能将纯净之光转给一个选定的友方玩家。"}}
D.ClientTexts.JournalSection[6114]={Name={["5f9c85f92cba2846:20"]="梦境守望者"},Description={["87fdbed16fa2cc9c:74"]="德姆塞卡尔、德拉维沃尔、摩弗拉斯和哈扎斯誓死保卫伊兰尼库斯的阴影。"}}
D.ClientTexts.JournalSection[6122]={Name={["14462c9a8f3cc2b3:12"]="愤怒横扫"}}
D.ClientTexts.JournalSection[6141]={Name={["41e1a22996e29c70:8"]="火焰射击"}}
D.ClientTexts.JournalSection[6142]={Name={["1defd7d67d7fbc23:13"]="火炮弹幕"}}
D.ClientTexts.JournalSection[6171]={Name={["fa2f4837ae22ca36:12"]="能量涡流"}}
D.ClientTexts.JournalSection[6172]={Name={["625a01f1ad73b022:16"]="泰坦之触"}}
D.ClientTexts.JournalSection[6173]={Name={["845e358f9d9fc97c:11"]="能量超载"}}
D.ClientTexts.JournalSection[6174]={Name={["a79172cfb92ad5ba:30"]="第一阶段：进入防御模式"},Description={["e58b86b7ba2889d8:163"]="伊拉贡激活能量涡流，用星界气息发动攻击，并召唤星界保护者帮助保护纳拉克煞引擎。\r\n\r\n生命值降低至85%和50%时，第一阶段结束。"}}
D.ClientTexts.JournalSection[6175]={Name={["569a77818898c294:28"]="第二阶段：主能源关闭"},Description={["cd74ca7f77d54630:286"]="伊拉贡尝试通过制造能量电荷来对以太焦镜充能，从而重新激活纳拉克煞引擎。当玩家一次性摧毁所有的能量电荷后，伊拉贡会继续制造更多的能量电荷。这一制造过程会永久性地削弱他的物理形态。\r\n\r\n只要有一个能量电荷离开了能量涡流，第二阶段就会结束。"}}
D.ClientTexts.JournalSection[6176]={Name={["45bb72a1ffddd3ca:26"]="第三阶段：能源导入稳定"},Description={["9baaba90d86105fb:185"]="伊拉贡重新激活了纳拉克煞引擎，禁用能量涡流，并激活所有以太焦镜。伊拉贡此时免受一切伤害。\r\n\r\n玩家摧毁所有的以太焦镜后，第三阶段结束。"}}
D.ClientTexts.JournalSection[6177]={Name={["9aff313e1b728985:20"]="保护者显形"},Description={["f4eda3b3854221ee:87"]="当伊拉贡剩余的生命值高于50%时，它会召唤一名星界保护者来攻击玩家。"}}
D.ClientTexts.JournalSection[6178]={Name={["7a4d4d7de413083a:18"]="星界保护者"},Description={["a252bb609b41d1e7:90"]="星界保护者是一个纯净能量构造体，是纳拉克煞引擎的主要防御力量。"}}
D.ClientTexts.JournalSection[6359]={Name={["b82b00bf1eede3d8:8"]="潜地"},Description={["513eb91bf8261516:91"]="当阿努巴拉克的生命值降至75%、50%和25%时，他会潜地，并召唤蛛魔来保护他。"}}
D.ClientTexts.JournalSection[6179]={Name={["aaeed8ef8c121698:7"]="相位转移"},Description={["5bc9f0b77d9b4236:205"]="星界保护者处于熔化状态，由能量涡流的巨大能量凝聚在一起。当保护者的生命值还剩25%以上，并存在于能量涡流的边界以外时，玩家对其造成的伤害降低90%。"}}
D.ClientTexts.JournalSection[6182]={Name={["0fd324a391480d78:12"]="电弧能量"}}
D.ClientTexts.JournalSection[6183]={Name={["6a23489224ca397d:13"]="封闭回路"}}
D.ClientTexts.JournalSection[6184]={Name={["5a1592d1520edbf8:15"]="星界气息"}}
D.ClientTexts.JournalSection[6185]={Name={["73f00159b39149b2:13"]="静态熔焰"}}
D.ClientTexts.JournalSection[6186]={Name={["26d8fe87e3268bf6:17"]="横扫千军"}}
D.ClientTexts.JournalSection[6187]={Name={["f09a0160a7b15421:9"]="吸取能量"}}
D.ClientTexts.JournalSection[6189]={Name={["cd553df91572fe3c:12"]="能量电荷"},Description={["13668753485cff9a:97"]="能量电荷是伊拉贡身体的一小部分，含有重新启动纳拉克煞引擎所需的奥术能量。"}}
D.ClientTexts.JournalSection[6190]={Name={["dca2180f92689102:9"]="释放"}}
D.ClientTexts.JournalSection[6191]={Name={["e8c166efc12acd2a:10"]="超能冲锋"}}
D.ClientTexts.JournalSection[6192]={Name={["5df045aa657d5481:17"]="辐射能量"}}
D.ClientTexts.JournalSection[6193]={Name={["1a3c8ac441934089:13"]="以太焦镜"},Description={["6788b0b038238ca1:171"]="当纳拉克煞引擎开始运转时，以太焦镜激活，将能量喷涌到周围的平台中。损坏全部的六个以太焦镜会暂时禁用纳拉克煞引擎。"}}
D.ClientTexts.JournalSection[6194]={Name={["8934e745cf497c96:13"]="能量导管"}}
D.ClientTexts.JournalSection[6195]={Name={["2903992a88839b99:10"]="过载"}}
D.ClientTexts.JournalSection[6196]={Name={["c4a864ad669b951c:14"]="不稳定的能量"}}
D.ClientTexts.JournalSection[6197]={Name={["68e646d3b414fe0c:13"]="能量凋零"}}
D.ClientTexts.JournalSection[6198]={Name={["acb8ee244df4269d:11"]="宇宙火花"},Description={["5c80d3f7225e48aa:41"]="伊拉贡制造的小型的纯净能量构造体。"}}
D.ClientTexts.JournalSection[6199]={Name={["106184b8cf5b1831:5"]="践踏"}}
D.ClientTexts.JournalSection[6200]={Name={["6cd36fa7cedfb550:15"]="萨尔因好战者"},Description={["c4862586514ce8af:76"]="头领萨莱斯的好战者周期性地从炮舰尾部上跳下来与玩家战斗。"}}
D.ClientTexts.JournalSection[6201]={Name={["633b0373b55800b0:12"]="穿刺拖曳"}}
D.ClientTexts.JournalSection[6203]={Name={["8a7d308b2edb5ef8:12"]="尘风"},Description={["20238e843901e02b:91"]="尼诺洛克奋力扇动翅膀，制造一股强风，快速扇开周围的敌人。"}}
D.ClientTexts.JournalSection[6204]={Name={["8b28046927c805ce:12"]="粘稠沥青"}}
D.ClientTexts.JournalSection[6205]={Name={["fed3597fad7365da:14"]="快干树脂"}}
D.ClientTexts.JournalSection[6360]={Name={["d5ab138af32f7883:15"]="阿努巴尔刺客"}}
D.ClientTexts.JournalSection[8660]={Name={["e18f5297f50a55f6:15"]="灵魂链接图腾"}}
D.ClientTexts.JournalSection[6206]={Name={["a8ae85abfd8629b4:9"]="灵魂越界"}}
D.ClientTexts.JournalSection[6207]={Name={["a8ae85abfd8629b4:9"]="灵魂越界"}}
D.ClientTexts.JournalSection[6209]={Name={["5b7bbbe999ae9ca2:13"]="灵魂爆炸"}}
D.ClientTexts.JournalSection[6214]={Name={["82950bb328861538:7"]="树苗"},Description={["117350a3ed036878:39"]="当迁跃扭木处接触树苗时，树苗会对其进行治疗。"}}
D.ClientTexts.JournalSection[6216]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"},Description={["3deae8da0d8343fd:79"]="血卫士伯鲁恩发动顺劈斩，对一名玩家及其最近的盟友造成物理伤害。"}}
D.ClientTexts.JournalSection[6217]={Name={["d2c4a418a31ce64d:15"]="复仇的幻影"},Description={["3ea00c24bf6f9ea9:49"]="不可宽恕者由四个复仇的幻影陪伴。"}}
D.ClientTexts.JournalSection[6220]={Name={["105f5e7416ae00cd:5"]="喷射"}}
D.ClientTexts.JournalSection[6221]={Name={["7c97e2df1add4282:4"]="躲藏"},Description={["a250ed298cada702:159"]="雷施躲避玩家。当她处于隐藏状态时不能被选定成为攻击目标，但范围攻击仍可击中她。在被玩家击中足够的次数后，雷施会自动现身。"}}
D.ClientTexts.JournalSection[6222]={Name={["fe9e87f8b4a2b33d:8"]="滚开！"}}
D.ClientTexts.JournalSection[6223]={Name={["c34040464d3ea52f:7"]="保护"},Description={["ab7d1d5063c2d149:186"]="在生命值降至80%、60%、40%和20%时，雷施就用一个无懈泡泡来包裹自己，并驱动多个元素保护自己。她的泡泡将一直存在，直到她的一个复生的保护者被击败。"}}
D.ClientTexts.JournalSection[6224]={Name={["a276e1aad933050f:17"]="复生的保护者"},Description={["2bda528bb02a9eb8:156"]="雷施在施放保护时，会用散落在这个区域内的护腕复活这些元素。效果结束时，这些元素会变成水，洒落在地。"}}
D.ClientTexts.JournalSection[6225]={Name={["4ca2d2a3ea022f66:8"]="恐怖迷雾"}}
D.ClientTexts.JournalSection[6236]={Name={["ba0186ee25f2b0c7:12"]="煽动咆哮"}}
D.ClientTexts.JournalSection[6240]={Name={["75283ca5e88e2ff2:29"]="第一阶段：熄灭太阳"},Description={["210491aeaec3d429:115"]="玩家必须熄灭天上的太阳。击败每个太阳会使游荡恶煞出现，并攻击赵·追日者和玩家。"}}
D.ClientTexts.JournalSection[6241]={Name={["0b88ab9b3916142c:3"]="太阳"}}
D.ClientTexts.JournalSection[6243]={Name={["81a63904969370c9:28"]="第一阶段：有价值的试验对象？"}}
D.ClientTexts.JournalSection[6244]={Name={["e637afd0ce3044d9:12"]="琥珀雕刻刀"}}
D.ClientTexts.JournalSection[6245]={Name={["5df8ca008857d41f:15"]="寄生增长"}}
D.ClientTexts.JournalSection[6246]={Name={["74d1f4f265a8dbb1:33"]="第二阶段：昂舒克的最伟大创造"},Description={["c80a2ebeb494798d:154"]="当昂舒克的生命值降低至70%时，他召唤一个巨大的琥珀畸怪为他作战。昂舒克将继续用第一阶段的所有技能发动攻击。"}}
D.ClientTexts.JournalSection[6247]={Name={["92c6cc1b289c97c8:26"]="施放昂舒克"},Description={["46270575faed3fa0:216"]="他的伟大创造毁灭后，昂舒克将把室内琥珀的能量引导出来，准备最后的决战。昂舒克不再使用琥珀雕刻刀，而是以大幅提高的频率施放生命重塑。"}}
D.ClientTexts.JournalSection[6248]={Name={["6cf67b4d35f1a22a:11"]="生命重塑"},Description={["eece2c13483492b8:132"]="昂舒克向一名玩家释放一股琥珀，将其塑造为一个由流动的琥珀组成的巨大畸形体，并对其他玩家和怪物敌对。"}}
D.ClientTexts.JournalSection[6249]={Name={["810efc1e59bc6f79:16"]="变异构造体"},Description={["6aa9dade8bfe83c1:221"]="变形后，从最大值100点开始，玩家以每秒2点的速度持续消耗意志以继续控制扭曲的外形。意志消耗殆尽后，玩家便会死亡，变异构造体会继续不受控制地行动。"}}
D.ClientTexts.JournalSection[6250]={Name={["55ca387e8ffdcc55:11"]="琥珀打击"}}
D.ClientTexts.JournalSection[6455]={Name={["108fa042e2ac2689:5"]="维雷克"}}
D.ClientTexts.JournalSection[6251]={Name={["07d9154c7987b76b:9"]="冲破束缚"}}
D.ClientTexts.JournalSection[6252]={Name={["1a2bd57a973f91f1:18"]="无法动弹"}}
D.ClientTexts.JournalSection[6253]={Name={["105d734182cc8b5c:5"]="冲撞"}}
D.ClientTexts.JournalSection[6254]={Name={["5a4f5f6770799e02:16"]="琥珀畸怪"},Description={["45f8b86c8af061f3:131"]="这个巨兽由昂舒克采用流动的琥珀塑造而成，它是昂舒克在用螳螂妖琥珀创造生命的研究中的成功之作。"}}
D.ClientTexts.JournalSection[6255]={Name={["d81a524d45208b32:14"]="琥珀爆炸"}}
D.ClientTexts.JournalSection[6256]={Name={["335c07101c1642cd:12"]="强力践踏"}}
D.ClientTexts.JournalSection[6257]={Name={["0f71c9b5e530625c:5"]="猛掷"}}
D.ClientTexts.JournalSection[6258]={Name={["7999afb087791883:20"]="集中突变"}}
D.ClientTexts.JournalSection[6259]={Name={["ddb784e6c940bcc7:12"]="销蚀琥珀"}}
D.ClientTexts.JournalSection[6260]={Name={["231392ccd0313107:13"]="不稳定的琥珀"}}
D.ClientTexts.JournalSection[6261]={Name={["7a1a5cd5e4175f3a:11"]="活化琥珀"}}
D.ClientTexts.JournalSection[6262]={Name={["a953b5a649010057:10"]="血肉模糊"}}
D.ClientTexts.JournalSection[6263]={Name={["d81a524d45208b32:14"]="琥珀爆炸"}}
D.ClientTexts.JournalSection[6264]={Name={["75fc759cb11218c3:13"]="琥珀甲壳"}}
D.ClientTexts.JournalSection[6265]={Name={["7c96ff0bc3c65e96:4"]="狂怒"}}
D.ClientTexts.JournalSection[6266]={Name={["0f3efe2a3681e51b:5"]="重碾"}}
D.ClientTexts.JournalSection[6267]={Name={["d5231d05f96a6510:10"]="信息素"}}
D.ClientTexts.JournalSection[6268]={Name={["0ef6c52ea646e49d:8"]="敏感"}}
D.ClientTexts.JournalSection[6269]={Name={["bc165dcefbcda343:14"]="信息素痕迹"}}
D.ClientTexts.JournalSection[6270]={Name={["dfa079eea510df13:13"]="加拉隆的腿部"},Description={["3b29ded4288cd62d:48"]="玩家只攻击加拉隆的腿部。"}}
D.ClientTexts.JournalSection[6271]={Name={["7a807317f9c401b8:9"]="致命弱点"}}
D.ClientTexts.JournalSection[6272]={Name={["208ac19e8ea8c3d9:9"]="断腿"}}
D.ClientTexts.JournalSection[6274]={Name={["954d81405dbfb329:19"]="逃跑的囚犯"},Description={["37c27cf0b03e063d:184"]="螳螂妖在对砮皂寺的首次攻击中抓住了这三个熊猫人，但这些囚犯能够冲破束缚并对其反击。现在他们准备不惜一切代价结束围攻。"}}
D.ClientTexts.JournalSection[6278]={Name={["8da51fb86d5f5d93:10"]="腐蚀焦油"}}
D.ClientTexts.JournalSection[6279]={Name={["35e0d765b3172c36:17"]="第一阶段：进攻！"},Description={["41260e3cb575c073:49"]="指挥官沃加克命令自己的军队攻击玩家。"}}
D.ClientTexts.JournalSection[6280]={Name={["2b5596e4315dae7d:15"]="希克提克虫群"},Description={["d04fe81467d5bd07:79"]="身着轻甲、训练有素的希克提克虫群是沃加克军队的中坚力量。"}}
D.ClientTexts.JournalSection[6281]={Name={["1ad00b3f53760926:17"]="希克提克琥珀飞翼"},Description={["4f8a2bb1569e2e66:68"]="希克提克琥珀飞翼飞到平台顶部轰击玩家。"}}
D.ClientTexts.JournalSection[6282]={Name={["f6b13b4f002edc2a:18"]="希克提克毁灭者"},Description={["7b4edf226d28f54b:50"]="这些迅捷无常的螳螂妖携带着炸药。"}}
D.ClientTexts.JournalSection[6283]={Name={["2d209ce922fd209a:15"]="希克提克战士"},Description={["cdf5d3d75e518334:48"]="希克提克战士缓慢地向敌人所在位置推进。"}}
D.ClientTexts.JournalSection[6284]={Name={["27f5b4a4c22feca1:34"]="第二阶段：你的防御没有阻止我！"},Description={["b8b34ab6b99480b1:76"]="指挥官沃加克在手下的士兵快被玩家打败时入场。"}}
D.ClientTexts.JournalSection[6285]={Name={["3e18b442260c4501:11"]="速度飞升"}}
D.ClientTexts.JournalSection[6286]={Name={["dff8bd757a239522:13"]="冲刺打击"}}
D.ClientTexts.JournalSection[6287]={Name={["c76249d6e4ada779:14"]="千刃"}}
D.ClientTexts.JournalSection[6289]={Name={["866354dc8523d091:7"]="轰击"}}
D.ClientTexts.JournalSection[6290]={Name={["7a1b3a99e2bc1664:13"]="不稳定的冲击"}}
D.ClientTexts.JournalSection[6294]={Name={["ffaf2108cf6ce535:7"]="受创"},Description={["b0927e2813b0c979:78"]="在英雄难度下，加拉隆在生命值降低至33%时获得受创效果。"}}
D.ClientTexts.JournalSection[6295]={Name={["d5231d05f96a6510:10"]="信息素"},Description={["f1ef13fb3aa6ad66:75"]="加拉隆获得受创效果后会忽视信息素的锁定效果。"}}
D.ClientTexts.JournalSection[6296]={Name={["eff99d25fd3af8fc:11"]="近战攻击"},Description={["7dc325e0770aa10d:94"]="加拉隆在拥有受创效果后会使用普通近战攻击技能，并极大地提高速度。"}}
D.ClientTexts.JournalSection[6297]={Name={["b6345dcff6f3f12a:16"]="邪风"},Description={["3fab7b406a43f001:130"]="尼诺洛克在战斗过程中两次升空飞到桥的另一端。着陆后，尼诺洛克便周期性地引导尘风，直到被打断为止。"}}
D.ClientTexts.JournalSection[6299]={Name={["c32d64b0f9077f67:8"]="虫群"},Description={["c30abc4acbab751f:55"]="风领主梅尔加拉克与自己最信任的战士并肩作战。"}}
D.ClientTexts.JournalSection[6300]={Name={["200aacb45430096b:21"]="瑟拉提克琥珀诱捕者"}}
D.ClientTexts.JournalSection[6301]={Name={["4ea1c94727d32fee:11"]="琥珀监牢"}}
D.ClientTexts.JournalSection[6302]={Name={["3f240176e8ce0aab:7"]="残渣"}}
D.ClientTexts.JournalSection[6303]={Name={["facefa82631e94bd:14"]="腐蚀树脂"}}
D.ClientTexts.JournalSection[6304]={Name={["672bbcdce39fdff9:18"]="腐蚀树脂之池"}}
D.ClientTexts.JournalSection[6305]={Name={["b718814dd5503c5e:21"]="扎尔提克助战者"}}
D.ClientTexts.JournalSection[6306]={Name={["bde3ada78026bf34:7"]="治疗"}}
D.ClientTexts.JournalSection[6307]={Name={["e7f72853b9ca01ac:10"]="加速"}}
D.ClientTexts.JournalSection[6310]={Name={["c2cb55201cf49487:8"]="黑夜"},Description={["b26dd1887d9efdc5:244"]="烛龙在黑夜与腐蚀他思想的煞魔抗争。在黑夜使烛龙的生命值降低至零可永久性地将煞魔对他的影响清除。能量值达到100点时，他将暂时净化煞魔的影响并绽放出阳光将黑夜变成白昼。"}}
D.ClientTexts.JournalSection[6311]={Name={["6e1b037ecd5fec19:12"]="恐惧之影"}}
D.ClientTexts.JournalSection[6312]={Name={["23e9e4d737c36ad4:10"]="梦魇"}}
D.ClientTexts.JournalSection[6313]={Name={["b1fb8c01c3ad0b00:12"]="暗影吐息"}}
D.ClientTexts.JournalSection[6314]={Name={["b11278d088db877b:7"]="阳光"},Description={["fb45cc9865f8c8c9:259"]="烛龙试图反抗煞魔，这使得他能够保护玩家不受恐惧之影的影响。烛龙将一束阳光召唤到战场上，使沐浴阳光的玩家免疫恐惧之影的影响。阳光的保护区域会随着更多玩家加入而缩小。"}}
D.ClientTexts.JournalSection[6315]={Name={["1e087ac430f22b0b:6"]="白昼"},Description={["2646f1fc92693cc7:260"]="烛龙在白昼战胜了腐蚀他思想的煞魔。玩家在白昼可治疗和协助烛龙，并在白昼使其剩余的生命值升至100%可永久性地将煞魔对他的影响清除。能量值达到100点时，煞魔将腐蚀他的思想并迎来黑夜。"}}
D.ClientTexts.JournalSection[6316]={Name={["816e65bc667d274d:14"]="恐惧实体"},Description={["5cf36b5a31bd1129:111"]="恐惧实体在煞魔对付烛龙时产卵。玩家摧毁恐惧实体后会迸出五个惊恐的产物。"}}
D.ClientTexts.JournalSection[6317]={Name={["49ecd36b9c3b5d20:9"]="暗影恐怖"}}
D.ClientTexts.JournalSection[6318]={Name={["0d34d0922723c745:11"]="惊恐的产物"},Description={["43051ad8510c887d:57"]="玩家摧毁恐惧实体后会出现五个惊恐的产物。"}}
D.ClientTexts.JournalSection[6319]={Name={["fe1776295d5d02d6:6"]="惊恐"}}
D.ClientTexts.JournalSection[6320]={Name={["1454769faee561b8:11"]="不稳定的煞魔"},Description={["b1fd3fbfe8eabd2a:105"]="不稳定的煞魔出现在烛龙周围，并走近他，若接触到烛龙，会对其造成巨大的暗影伤害。"}}
D.ClientTexts.JournalSection[6321]={Name={["9eda17b458b49f49:12"]="无常箭"}}
D.ClientTexts.JournalSection[6322]={Name={["d3c95bd154c5bfe4:11"]="动荡"}}
D.ClientTexts.JournalSection[6323]={Name={["40813931a9c0f2ec:9"]="阳炎吐息"}}
D.ClientTexts.JournalSection[6324]={Name={["47c83cfc16ecc77f:13"]="沐浴在光明中"}}
D.ClientTexts.JournalSection[6325]={Name={["4264c310f0b80647:15"]="不谐力场"},Description={["597f3387f74f37ea:279"]="女皇制造一个不谐力场，干扰与魔法有关的声音。不谐力场会吸收附近的魔法效果，直至其共鸣枯竭为止。共鸣一旦枯竭，力场就会爆发音速倾泻。\r\n\r\n玩家在不谐力场内施放魔法效果也会消耗共鸣。"}}
D.ClientTexts.JournalSection[6326]={Name={["4aa9208bfc0f7016:14"]="音速倾泻"}}
D.ClientTexts.JournalSection[6327]={Name={["014d3c448ef7da59:9"]="召唤腐化之水"},Description={["b20fde4dba3f4b9c:85"]="贤者马里从四个较小喷泉中的一个中召唤腐蚀活水来攻击玩家。"}}
D.ClientTexts.JournalSection[6328]={Name={["cb355c8128b7f668:13"]="回旋之刃"}}
D.ClientTexts.JournalSection[6329]={Name={["6ba36a6f29072f06:12"]="刃雨"}}
D.ClientTexts.JournalSection[6331]={Name={["21cf4f7a148254ab:12"]="鲁莽"}}
D.ClientTexts.JournalSection[6332]={Name={["f87d6ac58350080a:14"]="同甘共苦"},Description={["d92f698afd472a91:67"]="梅尔加拉克的每队虫群都与它们的其他虫群伙伴共享生命值。"}}
D.ClientTexts.JournalSection[6333]={Name={["cacedeb180fdc5ce:13"]="穿刺之矛"}}
D.ClientTexts.JournalSection[6334]={Name={["4cdfd97facc19d36:24"]="库尔提克精英剑圣"}}
D.ClientTexts.JournalSection[6335]={Name={["a7966c3a2f4dea21:14"]="库尔提克打击"}}
D.ClientTexts.JournalSection[6336]={Name={["264b9aa6c3d3bb0d:25"]="第一阶段：危险的战斗！"}}
D.ClientTexts.JournalSection[6337]={Name={["e27becd0b3033b03:16"]="女皇邪眼"}}
D.ClientTexts.JournalSection[6338]={Name={["63a538220aba85ad:12"]="恐惧尖啸"}}
D.ClientTexts.JournalSection[6339]={Name={["8c03f7663fa464d5:11"]="恐怖嚎叫"}}
D.ClientTexts.JournalSection[6340]={Name={["97ec1438df68469f:28"]="第二阶段：女皇撤退！"},Description={["35e02d5001f88893:182"]="当女皇的煞能耗完时，她会退回到虫茧中，并召唤她的皇家卫士。一旦她的煞能补充完毕，或者所有的赛特提克风刃武士都被击败，女皇将重新出场。"}}
D.ClientTexts.JournalSection[6341]={Name={["7563fe66951884fb:30"]="第三阶段：终极腐蚀！"},Description={["17f27d2325e4e2a0:95"]="生命值降低至30%时，惧之煞将击破女皇的护体，并对她灌注强烈的腐蚀。"}}
D.ClientTexts.JournalSection[6343]={Name={["e27becd0b3033b03:16"]="女皇邪眼"}}
D.ClientTexts.JournalSection[6344]={Name={["d37496264fa551c3:11"]="警觉之眼"}}
D.ClientTexts.JournalSection[6345]={Name={["b4c469c233a1772b:12"]="暴风斩"}}
D.ClientTexts.JournalSection[6346]={Name={["29bddd850c045aa6:12"]="无影击"}}
D.ClientTexts.JournalSection[6347]={Name={["e8da3bd3d4503db4:8"]="疾风步"}}
D.ClientTexts.JournalSection[6348]={Name={["12744efebc5acc81:9"]="强攻"}}
