D.ClientTexts.JournalSection[6428]={Name={["8689807ea55fdd73:24"]="第一阶段：她的恩赐数之不尽"},Description={["af26d0dbc8d619c0:266"]="皇家宰相佐尔洛克随机飞向房间中的一个平台，然后从那攻击玩家。当佐尔洛克失去总生命值的20%时，他改变位置到另一个平台。皇家宰相佐尔洛克在每个平台时都会获得一项技能，但移动到另一个平台时会失去该技能。"}}
D.ClientTexts.JournalSection[6429]={Name={["59234c2c393cf39b:31"]="第二阶段：我们不会让她失望"},Description={["10aab8a7c7abecd8:169"]="当皇家宰相佐尔洛克的生命值降低至40%时，他会飞向大厅的中心，并吸入狂热信息素。皇家宰相佐尔洛克现在可以使用第一阶段的所有技能。"}}
D.ClientTexts.JournalSection[6430]={Name={["fb65d01a3ee12dd3:6"]="突现"},Description={["01581e5bebec6b9a:141"]="当达卡莱巨像的生命值降低至50%和被击败时，达卡莱元素会从达卡莱巨像体内涌出，使其停止活动。"}}
D.ClientTexts.JournalSection[6431]={Name={["0fecc3f57f5ecff8:5"]="融合"},Description={["5dcc1d96accca943:83"]="当达卡莱元素的生命值降低至50%时，它会重新融入达卡莱巨像体内。"}}
D.ClientTexts.JournalSection[6432]={Name={["d37ab2c643bbab13:7"]="策反"},Description={["c748a1cb1e607bee:169"]="皇家宰相佐尔洛克使用女皇的纯声来动摇两名随机玩家的忠诚，使其为螳螂妖帝国作战。策反持续到受害者的生命值降低至50%为止。"}}
D.ClientTexts.JournalSection[6433]={Name={["c78f0ec698fa82fd:16"]="狂热信息素"}}
D.ClientTexts.JournalSection[6434]={Name={["f11759d6cd364947:16"]="吸入信息素"}}
