D.ClientTexts.JournalSection[6489]={Name={["f575dbccb4a4be2d:11"]="恐惧之心"},Description={["d3cba677c617a73a:200"]="女皇随机对准一名玩家目标，并向其所在方向释放出一股慑人心魄的黑暗能量。如果有一名玩家站在恐惧之心和目标玩家之间，那他将受到此次攻击的伤害。"}}
D.ClientTexts.JournalSection[6491]={Name={["01ef7058236d8e0b:8"]="黑暗之箭"},Description={["2d6f8c7d7a419faa:110"]="格林托克妖术师向当前目标发射一支黑暗之箭，造成相当于其近战攻击造成伤害的暗影伤害。"}}
D.ClientTexts.JournalSection[6492]={Name={["41d86d1c835e2b8b:8"]="火矢"},Description={["c090168386e51440:108"]="格林托克神谕师向当前目标发射一支火矢，造成相当于其近战攻击造成伤害的火焰伤害。"}}
D.ClientTexts.JournalSection[6493]={Name={["f1995aec5f34a26f:6"]="惊慌"}}
D.ClientTexts.JournalSection[6494]={Name={["830cf79301994c34:10"]="腐蚀血球"},Description={["3632514845135ca7:58"]="腐蚀血球尝试与腐蚀毒液凝结，增大它的体积。"}}
D.ClientTexts.JournalSection[6528]={Name={["0bbc8ce0ea775a6b:9"]="撕裂肉体"}}
D.ClientTexts.JournalSection[6544]={Name={["03969f5dc1e52912:19"]="女皇的仆从"}}
D.ClientTexts.JournalSection[6545]={Name={["2f14bcd3b84a0a58:11"]="勇气卫队"}}
D.ClientTexts.JournalSection[6546]={Name={["03969f5dc1e52912:19"]="女皇的仆从"}}
D.ClientTexts.JournalSection[6547]={Name={["5f2bb28bbcd27bd4:9"]="煞能量"}}
D.ClientTexts.JournalSection[6548]={Name={["607335d673e2dbd3:12"]="琥珀宝珠"}}
D.ClientTexts.JournalSection[6550]={Name={["09b648d7bef15e9a:14"]="夜之黑暗"},Description={["15a64f4c25d6f7df:120"]="夜之黑暗在随机位置出现，并向最近的阳光移动。夜之黑暗接触到阳光之后会将其熄灭。"}}
D.ClientTexts.JournalSection[6551]={Name={["cacaabd1b9d1b400:13"]="灼日圣光"}}
D.ClientTexts.JournalSection[6552]={Name={["18ffc083b4183cb0:9"]="琥珀陷阱"}}
D.ClientTexts.JournalSection[6553]={Name={["8d676ed98006daec:10"]="音速之刃"}}
D.ClientTexts.JournalSection[6554]={Name={["2ced6b8902e6bec2:14"]="援军"},Description={["c844b229a82ecef0:140"]="风领主梅尔加拉克的虫群死亡后，他会召唤一组新的战士来代替它们。虫群死亡45秒后，他会召唤援军。"}}
D.ClientTexts.JournalSection[6555]={Name={["21cf4f7a148254ab:12"]="鲁莽"}}
D.ClientTexts.JournalSection[6562]={Name={["40011fb2a4c700a3:15"]="共享技能"},Description={["e7182e2e81cf3ba7:43"]="四个守护者都可以使用这些技能。"}}
D.ClientTexts.JournalSection[6563]={Name={["154c352a00721dc7:9"]="能量消失"},Description={["193e590a2aa56fd1:129"]="当守护者的生命值降低至75%和40%时，他们中的一个会关闭房间内所有充能之瓦的能源，以防止玩家使用该能量。"}}
D.ClientTexts.JournalSection[6564]={Name={["1228b53b2d86cf48:19"]="灾难性故障"}}
D.ClientTexts.JournalSection[6565]={Name={["fec308ef702f17dc:22"]="贪婪能量触须"}}
D.ClientTexts.JournalSection[6566]={Name={["07191dbeb15240bb:13"]="回响傀儡"},Description={["41e9db7b41a69cba:286"]="在英雄难度下，皇家宰相佐尔洛克会在他到过的前两个平台留下自己的镜像。在战斗的第二阶段，他会随机召唤出回响傀儡来协助他作战。\r\n回响傀儡会继承皇家宰相佐尔洛克的一个技能，并会持续使用该技能直至被击败。"}}
D.ClientTexts.JournalSection[6567]={Name={["d53b0a012743aa10:12"]="燃烧的琥珀"}}
D.ClientTexts.JournalSection[6568]={Name={["979e1765cd8b2d8e:17"]="音波衰减的回响"},Description={["871366f703fa6222:85"]="音波衰减的回响会使用佐尔洛克的音波衰减技能，并对玩家发动近战攻击。"}}
D.ClientTexts.JournalSection[6569]={Name={["b3912903ac3a590a:19"]="力与魄的回响"},Description={["3fe89b33d27e9ba2:89"]="力与魄的回响会使用佐尔洛克的力与魄技能，并对玩家发动近战攻击。"}}
D.ClientTexts.JournalSection[6574]={Name={["d37c93599a7b8f80:12"]="烟雾散去"}}
D.ClientTexts.JournalSection[6575]={Name={["610ca561fe7f57fc:10"]="英勇飞跃"}}
D.ClientTexts.JournalSection[6576]={Name={["6c6f3eff8eb3441a:12"]="乱刃风暴"}}
D.ClientTexts.JournalSection[6577]={Name={["89674a31ba54b396:16"]="女皇赞歌"},Description={["cafdc8fe70350371:270"]="皇家宰相佐尔洛克完成转换时，他会提高声音赞美女皇。未能与皇家宰相佐尔洛克展开近身战斗会导致他对该区域内的所有玩家造成物理伤害，直到玩家死亡。与皇家宰相佐尔洛克展开近身战斗会移除这个效果。"}}
D.ClientTexts.JournalSection[6578]={Name={["89674a31ba54b396:16"]="女皇赞歌"},Description={["ae7b1840e5d78fa3:229"]="皇家宰相佐尔洛克召唤的任何回响在没有激活使用其任一技能且没有展开近身战斗时都会使用女皇赞歌。与回响展开近身战斗会移除这个效果。"}}
D.ClientTexts.JournalSection[6579]={Name={["fc2e3b1cad43aec5:6"]="吐气"}}
D.ClientTexts.JournalSection[6581]={Name={["bcef35af0d3f2140:14"]="疾跑"}}
D.ClientTexts.JournalSection[6625]={Name={["4d8ac932698c0405:14"]="闪电之拳"}}
D.ClientTexts.JournalSection[6633]={Name={["ccb7f88ad539b181:8"]="煞能宝珠"}}
D.ClientTexts.JournalSection[6634]={Name={["288fe54624f784f7:8"]="酒雾之箭"}}
D.ClientTexts.JournalSection[6638]={Name={["428d3fe53e423c38:9"]="雷施的希望"}}
D.ClientTexts.JournalSection[6639]={Name={["099e93e64d83407d:11"]="黯淡之光"}}
D.ClientTexts.JournalSection[6648]={Name={["7c9abb9a067db5bf:4"]="武僧"}}
D.ClientTexts.JournalSection[6649]={Name={["3366e129c6e75c8c:13"]="旭日东升踢"}}
D.ClientTexts.JournalSection[6650]={Name={["a456a73142dc64e8:9"]="妖术珠"}}
D.ClientTexts.JournalSection[6651]={Name={["e1929201508fa992:12"]="复苏之雾"}}
D.ClientTexts.JournalSection[6654]={Name={["d37ab2c643bbab13:7"]="策反"},Description={["75c235db2f15d6ec:170"]="皇家宰相佐尔洛克使用女皇的纯声来动摇随机五名玩家的忠诚，使其为螳螂妖帝国作战。策反持续到受害者的生命值降低至50%为止。"}}
D.ClientTexts.JournalSection[6655]={Name={["45a0e5e8346fbe63:10"]="灵魂回归"},Description={["75956f1b971a91e2:68"]="灵魂回归使玩家的灵魂回到在真实世界中的躯体中。"}}
D.ClientTexts.JournalSection[6656]={Name={["8ba4f0239990af3a:17"]="复苏之魂"},Description={["43ff8d3e5e208a11:120"]="当一名在灵魂世界的玩家恢复了其所有生命值时，他的灵魂也受到复苏。拥有复苏之魂的玩家将获得灵魂回归这一技能。"}}
D.ClientTexts.JournalSection[6657]={Name={["45a0e5e8346fbe63:10"]="灵魂回归"},Description={["75956f1b971a91e2:68"]="灵魂回归使玩家的灵魂回到在真实世界中的躯体中。"}}
D.ClientTexts.JournalSection[6658]={Name={["50b35f87af60952c:11"]="毁灭意志"},Description={["a8415d6145522bc4:143"]="每当昂舒克对被变成变异构造体的玩家造成近战伤害时，他对琥珀的控制使目标的意志开始瓦解，吸取40点意志。"}}
D.ClientTexts.JournalSection[6659]={Name={["50b35f87af60952c:11"]="毁灭意志"},Description={["0cc581440e59e571:157"]="当琥珀畸怪对被变成变异构造体的玩家造成近战伤害时，它与琥珀的协调使目标的意志开始瓦解，吸取40点意志。"}}
D.ClientTexts.JournalSection[6660]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["2ad5ad3007e4d103:37"]="尤尔只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[6661]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["ba9c2e3408f25b8f:38"]="安苏只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[6662]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["5aa7e814c6c4092d:50"]="血卫士伯鲁恩只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[6664]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["75140d79b66b77ae:49"]="凶残的伊克只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[6665]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["fc334a2101af400e:52"]="冰封指挥官只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[6666]={Name={["44c738887dac6cdb:24"]="腐蚀不谐力场"}}
D.ClientTexts.JournalSection[6694]={Name={["30e8551139986054:13"]="闪电鞭笞"}}
D.ClientTexts.JournalSection[6695]={Name={["d8cb8407ac2557bc:11"]="奥术震击"}}
D.ClientTexts.JournalSection[6696]={Name={["fb3a1de218b165cf:10"]="暗影灼烧"}}
D.ClientTexts.JournalSection[6697]={Name={["e8d0d517baee156a:8"]="风爆弹"}}
D.ClientTexts.JournalSection[6698]={Name={["60a5686f76acbb72:14"]="暗影攻击"},Description={["25dd867d92ef5d70:193"]="戈拉亚会周期性使用下列特殊攻击来代替普通攻击：\r\n\r\n- 扫堂腿\r\n- 锤拳\r\n- 右直拳\r\n- 左钩拳\r\n\r\n这些特殊攻击会对目标造成暗影伤害，并且无视任何伤害吸收效果。"}}
D.ClientTexts.JournalSection[6699]={Name={["1e0f912f8c629a98:6"]="痛击"}}
D.ClientTexts.JournalSection[6700]={Name={["724fbc6f5456db32:11"]="恐惧痛击"}}
D.ClientTexts.JournalSection[6714]={Name={["50ec014dd4355b24:16"]="先王的阵列"}}
D.ClientTexts.JournalSection[6715]={Name={["9d6b8ec0531e4031:21"]="不稳定的能量"}}
D.ClientTexts.JournalSection[6716]={Name={["a7f1bb19c2857a56:12"]="动荡能量"},Description={["f2ed18b6671db825:210"]="被横扫千军击中时，强大的能量波动会穿透受害者，使其更易受到横扫千军的有害效果的伤害。如果玩家再次受到横扫千军的伤害，则会立即死亡。"}}
D.ClientTexts.JournalSection[6717]={Name={["efd757f48e1db62d:13"]="联结焦镜"},Description={["eee94fb10a6b39b2:83"]="在以太焦镜本体以及与其相连的联结焦镜的生命值都降为零之前，以太焦镜无法被关闭。"}}
D.ClientTexts.JournalSection[6718]={Name={["b23bd6dd6e512e20:20"]="废灵壁垒"}}
D.ClientTexts.JournalSection[6719]={Name={["cf975e73bb928d7a:16"]="黑暗聚集体"}}
D.ClientTexts.JournalSection[6720]={Name={["cf975e73bb928d7a:16"]="黑暗聚集体"}}
D.ClientTexts.JournalSection[6781]={Name={["d574545c7b1207b1:15"]="死亡幻像"}}
D.ClientTexts.JournalSection[6797]={Name={["d37ab2c643bbab13:7"]="策反"},Description={["761fd5897330f080:171"]="皇家宰相佐尔洛克使用女皇的纯声来动摇三名随机玩家的忠诚，使其为螳螂妖帝国作战。策反持续到受害者的生命值降低至50%为止。"}}
D.ClientTexts.JournalSection[6812]={Name={["9e519d4923f42dd4:13"]="狂暴之怒"}}
D.ClientTexts.JournalSection[6813]={Name={["6effb831f3a761d8:16"]="最终宿命"},Description={["0eda7517f6e329e8:105"]="6分钟后，戈拉亚将进入狂暴状态并施放最终宿命。最终宿命将立即杀死所有玩家。"}}
D.ClientTexts.JournalSection[6814]={Name={["6effb831f3a761d8:16"]="最终宿命"},Description={["f9779c476997c8e2:106"]="15分钟后，戈拉亚将进入狂暴状态并施放最终宿命。最终宿命将立即杀死所有玩家。"}}
D.ClientTexts.JournalSection[6860]={Name={["3fba6d8f7f7cf2be:7"]="弧光新星"}}
D.ClientTexts.JournalSection[6964]={Name={["ac7363c7d367c3de:27"]="有害变异：困惑心智"}}
D.ClientTexts.JournalSection[6861]={Name={["1f441e354cc5e65c:15"]="闪电之链"}}
D.ClientTexts.JournalSection[6862]={Name={["d3f85de6c46ffeb7:12"]="静电护盾"}}
D.ClientTexts.JournalSection[6863]={Name={["8c498811f2b9adec:10"]="风暴云"}}
D.ClientTexts.JournalSection[6865]={Name={["226a1cbae22b384d:22"]="熔火之星罗沙克"}}
D.ClientTexts.JournalSection[6866]={Name={["49addba72198b5be:23"]="风暴召唤者魁兹扎尔"}}
D.ClientTexts.JournalSection[6867]={Name={["8a0beb44cf3ac7d5:21"]="寒冰先知玳刃"}}
D.ClientTexts.JournalSection[6868]={Name={["ef515d933f087c6c:18"]="铁穹的背水一战"},Description={["53a28dcb16e99da2:105"]="在他的精锐魁麟坐骑被击败后，铁穹将亲自与你们战斗。除了之前已经拥有的技能，铁穹还将获得新技能。"}}
D.ClientTexts.JournalSection[6869]={Name={["a7e83356379c0ae9:18"]="魁麟精英"},Description={["a63f77f97fe97f5a:43"]="铁穹将骑上魁麟精英作战。"}}
D.ClientTexts.JournalSection[6870]={Name={["a5ec0823881cb430:14"]="脱缰烈焰"}}
D.ClientTexts.JournalSection[6871]={Name={["6d3f025021cbacf7:8"]="烧灼"}}
D.ClientTexts.JournalSection[6874]={Name={["04c0331d8f03a4ae:6"]="穿刺"}}
D.ClientTexts.JournalSection[6875]={Name={["10ccb854f72c3173:10"]="投掷长矛"}}
D.ClientTexts.JournalSection[6876]={Name={["8cafdb3d98d1a89a:15"]="弧形闪电"}}
D.ClientTexts.JournalSection[6877]={Name={["0421e16c8261cb41:9"]="风暴"}}
D.ClientTexts.JournalSection[6878]={Name={["2f1ce7aad9d5c521:12"]="旋转狂风"}}
D.ClientTexts.JournalSection[6879]={Name={["02b152c35d18fc28:9"]="冷酷凝视"}}
D.ClientTexts.JournalSection[6880]={Name={["3b1ac83c71780def:12"]="严重致伤"}}
D.ClientTexts.JournalSection[6881]={Name={["821035e5dc24db1e:11"]="动脉出血"}}
D.ClientTexts.JournalSection[6882]={Name={["0f0da9fefdff1a75:18"]="衰变光束"},Description={["ea06c64804c53ca3:232"]="杜鲁姆聚焦一束纯粹毁灭力量的射线并射向正前方。被射线命中的玩家会立即死亡。在聚焦这束射线的过程中，杜鲁姆会缓慢转动他的朝向，与此同时他的斜视之眼会在平台上创造一个被炙眼灼光效果覆盖的迷宫。"}}
D.ClientTexts.JournalSection[6883]={Name={["a88a0edff67955c4:9"]="斜视之眼"},Description={["ef27544df034eca2:96"]="每当杜鲁姆引导衰变光束时，它的斜视之眼就会在平台上制造出炙眼灼光的迷宫。"}}
D.ClientTexts.JournalSection[6884]={Name={["71e57b0ae5c7c0d3:9"]="心灵之眼"},Description={["c54a6d390cd1124c:56"]="杜鲁姆召唤一只可周期性施放意志之力的心灵之眼。"}}
D.ClientTexts.JournalSection[6885]={Name={["4add3285ab093d44:9"]="饥饿之眼"},Description={["e1bac682849b7b43:51"]="杜鲁姆会召唤一只饥饿之眼，饥饿之眼会对玩家使用生命吸取。"}}
D.ClientTexts.JournalSection[6886]={Name={["7d635338666d2ffd:7"]="邪恶之眼"},Description={["2ff99c19a9722544:54"]="杜鲁姆的邪恶之眼会周期性对玩家施放黑暗寄生。"}}
D.ClientTexts.JournalSection[6887]={Name={["ab398d165da39149:13"]="权衡之眼"},Description={["466185feb33f851f:63"]="杜鲁姆会召唤一只权衡之眼对玩家使用纠缠凝视。"}}
D.ClientTexts.JournalSection[6889]={Name={["7369320eb8e4662b:10"]="寒冰之墙"},Description={["b5dce7accbf38e51:190"]="杜鲁姆召唤三道冰墙以阻挡玩家绕平台移动。每道冰墙的各个墙面共享生命值，当任何一面承受足够的伤害时，墙体将直接破碎。"}}
D.ClientTexts.JournalSection[6890]={Name={["7c97374ce87bfb25:4"]="凝视"}}
D.ClientTexts.JournalSection[6965]={Name={["09bcf3fc6bfe6b0b:32"]="有益变异：强化神经键"}}
D.ClientTexts.JournalSection[6891]={Name={["d3c702b0e9740567:13"]="光谱排列"}}
D.ClientTexts.JournalSection[6892]={Name={["6712727c42910aff:10"]="猩红雾行兽"},Description={["208ef73675f5e047:53"]="猩红雾行兽只有在红色之眼的红光范围内才会显形。"}}
D.ClientTexts.JournalSection[6893]={Name={["752f2b19dd572504:12"]="猩红绽放"}}
D.ClientTexts.JournalSection[6894]={Name={["8b61f6cd33da2f74:12"]="腐蚀尖刺"}}
D.ClientTexts.JournalSection[6895]={Name={["b32e4dc82decd9fb:8"]="琥珀雾行兽"},Description={["54cca4b85c131cb5:52"]="琥珀雾行兽只有在黄色之眼的强光范围内才会显形。"}}
D.ClientTexts.JournalSection[6896]={Name={["6d31cd88fe1bbdd5:16"]="琥珀反击"}}
D.ClientTexts.JournalSection[6897]={Name={["8d2278d10885908c:12"]="琥珀爆发"}}
D.ClientTexts.JournalSection[6898]={Name={["c9198528c98e678f:8"]="碧蓝雾行兽"},Description={["6f2c14321ab765e7:44"]="碧蓝雾行兽只有在蓝色之眼的蓝光范围内才会显形。"}}
D.ClientTexts.JournalSection[6899]={Name={["494158076c304514:8"]="寒冷抓握"},Description={["d3c668badd4a357f:110"]="碧蓝雾行兽在蓝色之眼的锥形蓝光范围内显形后会对所有玩家造成越来越高的冰霜伤害。"}}
D.ClientTexts.JournalSection[6900]={Name={["5ba3f80ede9bf4af:11"]="酷寒"},Description={["2622ccf71285e020:73"]="玩家消灭一只碧蓝雾行兽后，它会在平台的随机位置重生。"}}
D.ClientTexts.JournalSection[6901]={Name={["841e6b61e3d62640:7"]="炙眼灼光"}}
D.ClientTexts.JournalSection[6902]={Name={["728f72d47b4e85b1:8"]="严厉之眼"},Description={["db61204cb4476c8d:354"]="严厉之眼是斜视之眼在杜鲁姆平台周围的迷宫中的一部分。严厉之眼将回望杜鲁姆并锁定其前方反向三十度锥形范围内的玩家。锥形底部位于平台边缘，并在平台中央杜鲁姆的位置收束成一点。\r\n\r\n该区域内最近的玩家将成为厉眼凝视的受害者。"}}
D.ClientTexts.JournalSection[6903]={Name={["c47e83182f551985:9"]="厉眼凝视"},Description={["f9955136ef23f04b:84"]="严厉之眼对最近的5名玩家造成奥术伤害，伤害值取决于玩家与严厉之眼间的距离。"}}
D.ClientTexts.JournalSection[6904]={Name={["c47e83182f551985:9"]="厉眼凝视"},Description={["e9bb6d13dd50200e:84"]="严厉之眼对最近的2名玩家造成奥术伤害，伤害值取决于玩家与严厉之眼间的距离。"}}
D.ClientTexts.JournalSection[6905]={Name={["74edfa01d7f61154:11"]="意志之力"},Description={["b8dcb303f0b10754:119"]="心灵之眼会专注地凝视一名随机玩家。在意志之力施放完毕后依然停留在其视线范围的玩家都将被击退。"}}
D.ClientTexts.JournalSection[6906]={Name={["9c3b83f37646809c:9"]="生命吸取"}}
D.ClientTexts.JournalSection[6907]={Name={["15322de0681dc97d:12"]="黑暗寄生"},Description={["e843089fe5a444bc:217"]="黑暗寄生物进入受害者的体内，每秒造成暗影伤害。寄生物寄宿在宿主体内的时间越长，造成的伤害越高。\r\n\r\n驱散黑暗寄生效果会使该效果转变为黑暗天灾。"}}
D.ClientTexts.JournalSection[6908]={Name={["5bf8a5a593dcc868:10"]="黑暗天灾"},Description={["22a6b61962170872:169"]="黑暗寄生效果被净化之后，它会转换为黑暗天灾。黑暗天灾持续时间相当于黑暗寄生的剩余持续时间并且每3秒孵化一只徘徊之眼。"}}
D.ClientTexts.JournalSection[6909]={Name={["5960cfa7885e081c:12"]="徘徊之眼"},Description={["8b16f6acd6b7f5f7:73"]="徘徊之眼从黑暗天灾的受害者之上诞生，并随机攻击一名玩家。"}}
D.ClientTexts.JournalSection[6910]={Name={["f8892afa1ed98637:6"]="吞噬"}}
D.ClientTexts.JournalSection[6911]={Name={["b020b02b9b98cf84:13"]="纠缠凝视"}}
D.ClientTexts.JournalSection[6912]={Name={["854cc3373a8a0942:26"]="灼热之矛：炽燃余烬"}}
D.ClientTexts.JournalSection[6913]={Name={["2b0bab38c3c8521f:22"]="电击之矛：风暴雷云"}}
D.ClientTexts.JournalSection[6914]={Name={["0dbf2e6f8455cc30:8"]="攻击盲区"},Description={["f17fd3e777d3cfb0:127"]="玳刃使用护盾定向保护自己。玩家站在这片护盾所形成的攻击盲区内时，其遭到和进行的攻击都无法命中目标。"}}
D.ClientTexts.JournalSection[6915]={Name={["fe153e66a257a537:6"]="冰冻术"}}
D.ClientTexts.JournalSection[6916]={Name={["d05a705f197c8e82:23"]="霜冻之矛：冻结之血"}}
D.ClientTexts.JournalSection[6917]={Name={["ee100817c2b55b98:9"]="碎击拳"}}
D.ClientTexts.JournalSection[6918]={Name={["3cd1eafe035c1481:11"]="怒火中烧"}}
D.ClientTexts.JournalSection[6919]={Name={["87aab31263c2f75d:13"]="灼热飓风"}}
D.ClientTexts.JournalSection[6920]={Name={["ae809bf3203a2010:13"]="冻结飓风"}}
D.ClientTexts.JournalSection[6947]={Name={["eedad42a04d755cb:16"]="原生打击"}}
D.ClientTexts.JournalSection[6948]={Name={["aa8bf5ccfdfda65f:14"]="畸形之血"}}
D.ClientTexts.JournalSection[6949]={Name={["328157aafee7ce9b:9"]="进化"}}
D.ClientTexts.JournalSection[6950]={Name={["ade0cb5615755e35:20"]="变异：腹部毒囊"}}
D.ClientTexts.JournalSection[6951]={Name={["cece82594ec4b6bc:19"]="变异：毒气鱼鳔"}}
D.ClientTexts.JournalSection[6952]={Name={["5b149ddf57103598:21"]="变异：酸性脊刺"}}
D.ClientTexts.JournalSection[6953]={Name={["dc73087fe6e63c98:23"]="变异：病源腺体"}}
D.ClientTexts.JournalSection[6954]={Name={["1ce774875d633180:23"]="变异：代谢增速"}}
D.ClientTexts.JournalSection[6955]={Name={["ef06e2c3cb194e52:25"]="变异：迸裂脓疮"}}
D.ClientTexts.JournalSection[6956]={Name={["7a749c42128d9101:11"]="活化液体"},Description={["3d92562493d6cd4f:99"]="活化液体从普利莫修斯的巢穴周围的池塘中渗出，并缓慢地向普利莫修斯移动。"}}
D.ClientTexts.JournalSection[6957]={Name={["a4d27d23edfa3072:16"]="变异普利莫修斯"},Description={["24a47f5340ada8a6:88"]="当活化液体到达普利莫修斯身边，它将被吸收，并提高普利莫修斯的当前变异等级。"}}
D.ClientTexts.JournalSection[6958]={Name={["b16c31bcfd23f9b1:13"]="变异之池"},Description={["a9beac15334d08ca:82"]="当一个活化液体死亡时，将留下一个变异之池，可使普利莫修斯或玩家发生变异。"}}
D.ClientTexts.JournalSection[6959]={Name={["a4d27d23edfa3072:16"]="变异普利莫修斯"},Description={["bf7295e172e11ee6:92"]="当普利莫修斯踏入变异之池，它将被吸收，并提高普利莫修斯的当前变异等级。"}}
D.ClientTexts.JournalSection[6960]={Name={["953abdc26bcb3347:12"]="变异玩家"}}
D.ClientTexts.JournalSection[6961]={Name={["295edd2a8e1c3427:26"]="有益变异：厚重之骨"}}
D.ClientTexts.JournalSection[6962]={Name={["10364e1067dae907:28"]="有害变异：脆弱之骨"}}
D.ClientTexts.JournalSection[6963]={Name={["e4bfca2fb1f17fea:25"]="有益变异：清醒心智"}}
D.ClientTexts.JournalSection[8663]={Name={["28a647f12c9c2be6:10"]="灵魂之箭"}}
D.ClientTexts.JournalSection[6966]={Name={["42b0444f2dd94202:30"]="有害变异：迟钝神经键"}}
D.ClientTexts.JournalSection[6967]={Name={["ef0e66a527621524:28"]="有益变异：视力敏锐"}}
D.ClientTexts.JournalSection[6968]={Name={["6e210f2c767c71d1:32"]="有害变异：视力损伤"}}
D.ClientTexts.JournalSection[6969]={Name={["9a7cbc8dfce66c14:13"]="恐怖黏液怪"},Description={["e858c35a4998c021:64"]="由生成普利莫修斯的同一种液体形成的重度变异生物。"}}
D.ClientTexts.JournalSection[6970]={Name={["30b2beb2ab6202bb:10"]="黑血"}}
D.ClientTexts.JournalSection[6971]={Name={["89df0aa946ec9daa:13"]="致命变异"}}
D.ClientTexts.JournalSection[6972]={Name={["9de9a025c60edc5c:13"]="地狱熔火"}}
D.ClientTexts.JournalSection[6973]={Name={["4b0d569063e172ed:14"]="熔火过载"}}
D.ClientTexts.JournalSection[6974]={Name={["a5ec0823881cb430:14"]="脱缰烈焰"}}
D.ClientTexts.JournalSection[6975]={Name={["6d3f025021cbacf7:8"]="烧灼"}}
D.ClientTexts.JournalSection[6976]={Name={["a0f7dc5001bcf073:14"]="决心之刺"},Description={["25213aad669138b0:87"]="莫拉比突刺一名玩家，造成物理伤害。该攻击不能被格挡、躲闪或招架。"}}
D.ClientTexts.JournalSection[6977]={Name={["1832676dec8f9890:12"]="大地震颤"}}
D.ClientTexts.JournalSection[6978]={Name={["97dc7d684d1b3f93:12"]="麻痹嚎叫"}}
D.ClientTexts.JournalSection[6979]={Name={["9a1b869812d14b1b:10"]="魔精狂怒"},Description={["f96fa74a6f432a03:93"]="莫拉比陷入狂怒，使其施法速度根据他所受到的伤害成比例提高。"}}
D.ClientTexts.JournalSection[6980]={Name={["dd553c9cd595ae9f:28"]="第一阶段：犸托斯的高阶先知"}}
D.ClientTexts.JournalSection[6981]={Name={["e12e6ce8490002a5:26"]="第二阶段：犸托斯的化身"}}
D.ClientTexts.JournalSection[6982]={Name={["a0f134b3d105de2c:14"]="决断突刺"}}
D.ClientTexts.JournalSection[6983]={Name={["103da43c6f225157:5"]="地震"}}
D.ClientTexts.JournalSection[6984]={Name={["b7063e0912e5a174:11"]="麻痹怒吼"}}
D.ClientTexts.JournalSection[6985]={Name={["0f8c285c547c7e29:14"]="变形"}}
D.ClientTexts.JournalSection[6986]={Name={["68e16bd82bf7c203:8"]="奔踏"},Description={["9521c715db3271a8:98"]="迦尔达拉召唤一头犀牛之魂冲撞玩家，造成物理伤害并将他们击飞。"}}
D.ClientTexts.JournalSection[6987]={Name={["cc68ff04ab79492d:13"]="旋风劈砍"}}
D.ClientTexts.JournalSection[6988]={Name={["0eb6bc7b53fd13ee:8"]="刺破"}}
D.ClientTexts.JournalSection[6989]={Name={["f9d4323db2962492:25"]="第一阶段：阿卡里的高阶先知"}}
D.ClientTexts.JournalSection[6990]={Name={["68890b1cfd283e59:23"]="第二阶段：阿卡里的化身"}}
D.ClientTexts.JournalSection[6991]={Name={["fec57c80505163ff:14"]="穿刺冲锋"},Description={["925f736e579837b1:68"]="迦尔达拉向一名玩家冲锋，将其击退并造成物理伤害。"}}
D.ClientTexts.JournalSection[6992]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[6993]={Name={["106184b8cf5b1831:5"]="践踏"},Description={["0c615c3c45ef2b71:88"]="迦尔达拉践踏地面，造成物理伤害，并将10码范围内的所有玩家击飞。"}}
D.ClientTexts.JournalSection[6994]={Name={["513014dc79a9cba5:7"]="伊克之噬"},Description={["d291c07461af2a71:51"]="伊克狠咬目标，对其造成物理伤害。"}}
D.ClientTexts.JournalSection[6995]={Name={["513983b894051235:7"]="伊克之秽"}}
D.ClientTexts.JournalSection[6996]={Name={["85ae20eb76760f5a:9"]="伊克之跃"},Description={["e2bf35556e0165fc:25"]="伊克跳向一名远处的玩家。"}}
D.ClientTexts.JournalSection[6997]={Name={["0530cde6d68661ed:10"]="伊克之狂暴"}}
D.ClientTexts.JournalSection[6998]={Name={["18baad15e86f59d0:11"]="火焰之头"}}
D.ClientTexts.JournalSection[7000]={Name={["c571e02d7936b62a:7"]="燃烬"}}
D.ClientTexts.JournalSection[7001]={Name={["0798aab7b41992ea:11"]="燃烧血肉"}}
D.ClientTexts.JournalSection[7002]={Name={["c4b4974b771ef0e0:10"]="冰霜之头"}}
D.ClientTexts.JournalSection[7004]={Name={["d6b1fe7349eeccb0:12"]="毒素之头"}}
D.ClientTexts.JournalSection[7005]={Name={["2d556961d5a79a46:10"]="奥术之头"}}
D.ClientTexts.JournalSection[7006]={Name={["137e4e1b00ef1710:17"]="一体多头"},Description={["5a00f65c8bffccab:110"]="当墨格瑞拉被砍掉一个头后，他的身体受到相当于这颗头的最大生命值的伤害，并在其位置长出两颗新头。"}}
D.ClientTexts.JournalSection[7008]={Name={["666279d900ae3484:12"]="寒冰洪流"}}
D.ClientTexts.JournalSection[7009]={Name={["429739fc3ae91d13:12"]="极寒冰流"}}
D.ClientTexts.JournalSection[7011]={Name={["c1a9dc20250d83b1:8"]="酸雨"}}
D.ClientTexts.JournalSection[7012]={Name={["2736815b314f4ba8:8"]="腐蚀护甲"}}
D.ClientTexts.JournalSection[7015]={Name={["fbe1744ca8d48f25:9"]="魔力散射"}}
D.ClientTexts.JournalSection[7024]={Name={["5a455c5fc682d3c8:12"]="战斗姿态"}}
D.ClientTexts.JournalSection[7025]={Name={["abc3e8a67e4f4e01:12"]="致死打击"}}
D.ClientTexts.JournalSection[7026]={Name={["7c9df7721c1f6885:4"]="猛击"},Description={["cb79fced1a1aeade:51"]="比亚格里将军猛击一名玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[7027]={Name={["15a3a095c3ea8b8c:6"]="拳击"}}
D.ClientTexts.JournalSection[7028]={Name={["d7603d0ad18ec43b:10"]="战争光环"}}
D.ClientTexts.JournalSection[7029]={Name={["7cd7f6e80972b1f7:15"]="狂暴姿态"}}
D.ClientTexts.JournalSection[7030]={Name={["b727f51d940c3d9a:9"]="旋风斩"}}
D.ClientTexts.JournalSection[7031]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"}}
D.ClientTexts.JournalSection[7032]={Name={["12b3db33e1b10102:9"]="拦截"}}
D.ClientTexts.JournalSection[7033]={Name={["9e48a15316e489ea:13"]="狂暴光环"}}
D.ClientTexts.JournalSection[7034]={Name={["f0a1609cf79fd963:15"]="防御姿态"}}
D.ClientTexts.JournalSection[7035]={Name={["b50fa371cf011b0c:8"]="钢铁形态"}}
D.ClientTexts.JournalSection[7036]={Name={["759fc28dfcfeeae2:9"]="击退"}}
D.ClientTexts.JournalSection[7037]={Name={["690ee6b0c5a70653:15"]="法术反射"},Description={["a2d0f8f9d4ea49d2:72"]="比亚格里将军将击中他的下一个魔法法术反射给它的施放者。"}}
D.ClientTexts.JournalSection[7038]={Name={["55840e0796a1a756:13"]="防御光环"}}
D.ClientTexts.JournalSection[7039]={Name={["de6a2e0ad9fca45d:21"]="雷铸军官"}}
D.ClientTexts.JournalSection[7040]={Name={["3fbf31271d43abf8:7"]="焊接"}}
D.ClientTexts.JournalSection[7041]={Name={["f876c203eb5c9ede:10"]="新生钢铁"}}
D.ClientTexts.JournalSection[7042]={Name={["7c97d18718e203d0:4"]="高热"}}
D.ClientTexts.JournalSection[7043]={Name={["1dd6c7d2df504f01:6"]="淬火"},Description={["9d8519383187ea2d:44"]="沃尔坎敲打他的铁砧，制造熔岩魔像。"}}
D.ClientTexts.JournalSection[7044]={Name={["1e5fd1d157ab4488:15"]="粉碎践踏"},Description={["061add3444f41033:118"]="当沃尔坎的生命值下降至25%时，他会践踏地面，对所有玩家造成物理伤害，并使所有脆弱的魔像碎裂。"}}
D.ClientTexts.JournalSection[7045]={Name={["0da4046842b2ae19:11"]="熔岩魔像"}}
D.ClientTexts.JournalSection[7046]={Name={["4cf5ae30a9c3efa1:16"]="献祭打击"}}
D.ClientTexts.JournalSection[7047]={Name={["d9862fad2c79f244:15"]="霜王玛拉克"}}
D.ClientTexts.JournalSection[7048]={Name={["e730f786fd650d7b:9"]="卡兹拉金"}}
D.ClientTexts.JournalSection[7049]={Name={["eae86d3081383b29:17"]="沙行者苏尔"}}
D.ClientTexts.JournalSection[7050]={Name={["dc59a123ca67e60a:19"]="高阶祭司玛尔里"}}
D.ClientTexts.JournalSection[7051]={Name={["866fc1ef102b7070:19"]="戈拉亚的灵魂"},Description={["1b80f283a9122ce8:314"]="缚灵者戈拉亚的灵魂随机选择控制一名议员，强化他们的技能，并使他们生成黑暗能量。议员承受的伤害达到其最大生命值的25%时，灵魂将会离开。\r\n\r\n灵魂离开后，会选择新的议员，将黑暗能量重置为0，并留下滞留气息效果。"}}
D.ClientTexts.JournalSection[7052]={Name={["6f2b979995cb373a:17"]="滞留气息"}}
D.ClientTexts.JournalSection[7053]={Name={["40daffb40249ce0f:9"]="黑暗之力"}}
D.ClientTexts.JournalSection[7054]={Name={["7cab69378610bab8:13"]="冰寒突击"}}
D.ClientTexts.JournalSection[7055]={Name={["3152a98444c93839:10"]="刺骨之寒"}}
D.ClientTexts.JournalSection[7056]={Name={["062e9ad7578f631c:9"]="霜寒刺骨"}}
D.ClientTexts.JournalSection[7057]={Name={["3f7355b526545cf2:8"]="身体发热"}}
D.ClientTexts.JournalSection[7058]={Name={["b964cb2b3717fb48:14"]="无畏冲锋"}}
D.ClientTexts.JournalSection[7059]={Name={["5b7ba78143248f5a:8"]="过载"}}
D.ClientTexts.JournalSection[7080]={Name={["f65ed2cf04cf4d54:6"]="冲锋"},Description={["e1dfbf8417047d61:80"]="赫利东朝一名随机玩家发起冲锋，到达目标所在的位置后他将施放双重扫击技能。"}}
D.ClientTexts.JournalSection[7060]={Name={["dca2180f92689102:9"]="电能释放"}}
D.ClientTexts.JournalSection[7061]={Name={["cff79b7c7d4eda39:8"]="沙尘箭"}}
D.ClientTexts.JournalSection[7062]={Name={["d88351089ac5ff91:9"]="流沙"}}
D.ClientTexts.JournalSection[7063]={Name={["d9714c955b8b3694:8"]="诱捕"}}
D.ClientTexts.JournalSection[7064]={Name={["5de8d5089510eb99:9"]="定身"}}
D.ClientTexts.JournalSection[7065]={Name={["d02176601d6d4545:9"]="沙尘暴"}}
D.ClientTexts.JournalSection[7066]={Name={["3248895459da658d:10"]="活化沙砾"},Description={["7278eb01a287e830:166"]="每次沙尘暴发生时，活化沙砾就会从流沙池中涌出，并四处活动直至被杀死。\r\n\r\n当活化沙砾死亡时，会在原地生成新的流沙池。"}}
D.ClientTexts.JournalSection[7067]={Name={["29e81d21d5eba4e0:9"]="强韧"}}
D.ClientTexts.JournalSection[7068]={Name={["58113e99ee9c73e8:17"]="暗流涌动"}}
D.ClientTexts.JournalSection[7069]={Name={["0069ca7d25efaafe:13"]="神灵之怒"}}
D.ClientTexts.JournalSection[7070]={Name={["5798f2bee3715e15:16"]="受祝福的神灵"}}
D.ClientTexts.JournalSection[7071]={Name={["0069ca7d25efaafe:13"]="神灵之怒"}}
D.ClientTexts.JournalSection[7072]={Name={["99279babe2721330:17"]="受庇护的神灵"}}
D.ClientTexts.JournalSection[7073]={Name={["f73a1629d04de692:11"]="扭曲命运"}}
D.ClientTexts.JournalSection[7074]={Name={["79eff0dc8fce2a83:12"]="灵魂残片"}}
D.ClientTexts.JournalSection[7075]={Name={["4470a6ca9534c6cb:8"]="冷却"},Description={["a9d3cfd7b6c6d418:115"]="熔岩魔像会逐渐冷却，每秒损失2%的最大生命值。冷却过程中，熔岩魔像的移动速度也将减慢。"}}
D.ClientTexts.JournalSection[7076]={Name={["4470a6ca9534c6cb:8"]="冷却"},Description={["1aea197645246f59:115"]="熔岩魔像会逐渐冷却，每秒损失1%的最大生命值。冷却过程中，熔岩魔像的移动速度也将减慢。"}}
D.ClientTexts.JournalSection[7077]={Name={["91de4940427b5b39:7"]="碎裂"}}
D.ClientTexts.JournalSection[7078]={Name={["e6c42d2ba794f8ac:14"]="三重穿刺"}}
D.ClientTexts.JournalSection[7079]={Name={["dfd75fa851758ba9:11"]="双重扫击"}}
D.ClientTexts.JournalSection[7081]={Name={["294638c6572673b3:10"]="法拉基部族"},Description={["93b7c38042d1f2c3:53"]="战神贾拉克将召唤法拉基部族首先入场。"}}
D.ClientTexts.JournalSection[7082]={Name={["8464e3d0683f7b73:12"]="古拉巴什部族"},Description={["0ee195a363a42b70:63"]="战神贾拉克将召唤古拉巴什部族第二个入场。"}}
D.ClientTexts.JournalSection[7083]={Name={["6e06a52f50d76cf6:11"]="达卡莱部族"},Description={["5eedd3614746f0f0:61"]="战神贾拉克将召唤达卡莱部族第三个入场。"}}
D.ClientTexts.JournalSection[7084]={Name={["c1e22f4c6120a8df:8"]="阿曼尼部族"},Description={["8eec51b77590e642:57"]="战神贾拉克将召唤阿曼尼部族最后入场。"}}
D.ClientTexts.JournalSection[7085]={Name={["58dfa3fc373407ff:12"]="赞达拉部族"},Description={["7345cce86b3760ff:88"]="战神贾拉克和他忠实的赞达拉统领们将协助赫利东作战。"}}
D.ClientTexts.JournalSection[7086]={Name={["454d4fdb77d7bcac:19"]="赞达拉恐龙统领"},Description={["0e5bc3ab530da41c:57"]="赞达拉恐龙统领会周期性地跳入战场。"}}
D.ClientTexts.JournalSection[7087]={Name={["486e63b92475f6c8:12"]="战神贾拉克"},Description={["c32db0e01d4f9e61:113"]="在召唤过所有四个部族，或赫利东的生命值降到30%以下时，战神贾拉克将亲自上阵。"}}
D.ClientTexts.JournalSection[7088]={Name={["b5ce0bf71f9b4bfa:10"]="兽性咆哮"}}
D.ClientTexts.JournalSection[7089]={Name={["356694023cb9ceed:7"]="狂暴"}}
D.ClientTexts.JournalSection[7090]={Name={["aaef6d7e192573cd:12"]="龙形治愈"}}
D.ClientTexts.JournalSection[7091]={Name={["60b7482345e63d8a:8"]="恐龙形态"}}
D.ClientTexts.JournalSection[7092]={Name={["f5668bbeb07e8747:12"]="控制宝珠"},Description={["53b93ff6b83818b5:241"]="当赞达拉恐龙统领变形后，它会丢下控制宝珠。操作宝珠的玩家可暂时控制赫利东的心智，并强迫其冲撞一座部族之门。摧毁部族之门可防止该部族的成员继续进入战场。"}}
D.ClientTexts.JournalSection[7093]={Name={["6955142564dcbfb6:8"]="恐怖咆哮"}}
D.ClientTexts.JournalSection[7094]={Name={["beb898a87f8374ff:8"]="头痛"}}
D.ClientTexts.JournalSection[7095]={Name={["4e06df4a83506bd7:12"]="龟裂"}}
D.ClientTexts.JournalSection[7096]={Name={["33e1dd027cd2ee1b:20"]="苏利萨斯凝石者"},Description={["6a1fc61fe5376824:87"]="一旦受到召唤，苏利萨斯凝石者不断会从法拉基部族之门涌出，直至大门被摧毁。"}}
D.ClientTexts.JournalSection[7097]={Name={["a3794566ce4ab8a3:17"]="法拉基散兵"},Description={["e94ef5e3d1b4b5f2:84"]="一旦受到召唤，法拉基散兵不断会从法拉基部族之门涌出，直至大门被摧毁。"}}
D.ClientTexts.JournalSection[7098]={Name={["1c9e132f2aa4abcc:18"]="法拉基瘠行者"},Description={["3b36ab1b4fe3cd62:94"]="当法拉基巨魔被召唤时，总共三名法拉基瘠行者会跳进战场加入战斗。"}}
D.ClientTexts.JournalSection[7099]={Name={["9982dfd024d022eb:18"]="古拉巴什血领主"},Description={["064f8a376aaf8c34:87"]="一旦受到召唤，古拉巴什血领主会不断从古拉巴什部族之门中涌出，直至大门被摧毁。"}}
D.ClientTexts.JournalSection[7100]={Name={["9e8406eb503b37d8:20"]="古拉巴什剧毒祭司"},Description={["8bbb72a121e94c96:98"]="当古拉巴什巨魔被召唤时，总共三名古拉巴什剧毒祭司会跳进战场加入战斗。"}}
D.ClientTexts.JournalSection[7101]={Name={["adde40f59119e1f8:20"]="复生的达卡莱战士"},Description={["647f4b9b38ceb006:88"]="一旦受到召唤，复生的达卡莱战士不断会从达卡莱部族之门涌出，直至大门被摧毁。"}}
D.ClientTexts.JournalSection[7102]={Name={["e75af73e2b494653:21"]="复生的达卡莱勇士"},Description={["9a4c4fe4f5c2f7a5:89"]="一旦受到召唤，复生的达卡莱勇士不断会从达卡莱部族之门涌出，直至大门被摧毁。"}}
D.ClientTexts.JournalSection[7103]={Name={["d51b5bbd8d2637d8:21"]="达卡莱冰封督军"},Description={["3002e032a1b8ab23:98"]="当达卡莱巨魔被召唤时，总共三名达卡莱冰封督军会跳进战场加入战斗。"}}
D.ClientTexts.JournalSection[7104]={Name={["befd1f7868bcf095:18"]="阿曼尼保卫者"},Description={["9574ed5b2dcac772:83"]="一旦受到召唤，阿曼尼保卫者会不断从阿曼尼部族之门中涌出，直至大门被摧毁。"}}
D.ClientTexts.JournalSection[7105]={Name={["4ef3d7ddc8b08f82:20"]="阿曼尼烈焰法师"},Description={["b816e840aeef425f:85"]="一旦受到召唤，阿曼尼烈焰法师会不断从阿曼尼部族之门中涌出，直至大门被摧毁。"}}
D.ClientTexts.JournalSection[7106]={Name={["dca9330fa574648c:12"]="阿曼尼战熊"},Description={["b23ca741eb5d2f4e:86"]="当阿曼尼巨魔被召唤时，总共三只阿曼尼战熊会跳进战场加入战斗。"}}
D.ClientTexts.JournalSection[7107]={Name={["4f32cffda927bfd0:20"]="阿曼尼狂兽萨满"},Description={["a493cd7a8ea377b9:92"]="驾驭着强大的阿曼尼战熊的阿曼尼狂兽萨满只有在他们胯下的战熊倒下之后才能被攻击。"}}
D.ClientTexts.JournalSection[7108]={Name={["bc4d6395d1018e8a:9"]="岩石凝视"}}
D.ClientTexts.JournalSection[7109]={Name={["269a543aca4cb449:15"]="耀眼阳光"}}
D.ClientTexts.JournalSection[7278]={Name={["1ff0e67073519761:16"]="复生的巫医"}}
D.ClientTexts.JournalSection[7110]={Name={["d00185a2c438b371:8"]="流沙陷阱"}}
D.ClientTexts.JournalSection[7111]={Name={["29ca0c7673488f8d:13"]="撕裂冲锋"}}
D.ClientTexts.JournalSection[7112]={Name={["0fbd95766dc888df:15"]="毒箭之雨"}}
D.ClientTexts.JournalSection[7113]={Name={["58f506c0a35d68b5:16"]="剧毒渗透者"},Description={["cb6139a766bcee80:50"]="古拉巴什剧毒祭司能够召唤一个剧毒渗透者。"}}
D.ClientTexts.JournalSection[7114]={Name={["0fbd95766dc888df:15"]="毒箭之雨"}}
D.ClientTexts.JournalSection[7115]={Name={["e08b9c26a1fe6df1:12"]="活化毒素"}}
D.ClientTexts.JournalSection[7116]={Name={["7e16a3cfdd7741ca:23"]="心智失控"},Description={["5d666748788287a3:153"]="邪恶的死灵魔法唤起达卡莱部族成员的残骸，使其丧失理智和思想。复活的达卡莱巨魔会对随机目标发起攻击。"}}
D.ClientTexts.JournalSection[7117]={Name={["390b7c56762302c3:12"]="致命瘟疫"}}
D.ClientTexts.JournalSection[7118]={Name={["7e16a3cfdd7741ca:23"]="心智失控"},Description={["5d666748788287a3:153"]="邪恶的死灵魔法唤起达卡莱部族成员的残骸，使其丧失理智和思想。复活的达卡莱巨魔会对随机目标发起攻击。"}}
D.ClientTexts.JournalSection[7119]={Name={["390b7c56762302c3:12"]="致命瘟疫"}}
D.ClientTexts.JournalSection[7120]={Name={["abc3e8a67e4f4e01:12"]="致死打击"}}
D.ClientTexts.JournalSection[7121]={Name={["1579f57c2930a03f:9"]="冰冻宝珠"}}
D.ClientTexts.JournalSection[7122]={Name={["41d831867c795275:8"]="火球术"}}
D.ClientTexts.JournalSection[7123]={Name={["106310ad57fe2e1a:5"]="横扫"}}
D.ClientTexts.JournalSection[7124]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[7125]={Name={["571daed3d8fd7c34:14"]="混乱妖术"}}
D.ClientTexts.JournalSection[7126]={Name={["23ac3b4654f88eeb:18"]="闪电新星图腾"}}
D.ClientTexts.JournalSection[7127]={Name={["318da5bbff980500:9"]="心能之环"}}
D.ClientTexts.JournalSection[7128]={Name={["dac47fc14bfd2b36:12"]="托多斯的呼唤"},Description={["4a3404bce12d27ed:86"]="托多斯发出一阵震耳的呼唤声，召来数只小乌龟加入战斗并攻击玩家。"}}
D.ClientTexts.JournalSection[7129]={Name={["1ad5e06b528ab6ee:11"]="旋龟"}}
D.ClientTexts.JournalSection[7130]={Name={["ef5440230ae3d77a:13"]="旋转龟壳"}}
D.ClientTexts.JournalSection[7131]={Name={["0b9d3b484fa778bd:10"]="龟缩"},Description={["e8a205ba5da50bfb:178"]="旋龟在生命值较低时会缩进壳中，免疫所有伤害。在此状态下，玩家可以用脚踢龟壳，令接触到它的所有生物获得龟壳震荡效果。"}}
D.ClientTexts.JournalSection[7132]={Name={["26b7cdf411722d6b:13"]="隐藏之雾"},Description={["e821b60448992269:91"]="墨格瑞拉的身体和远端的头被厚重的雾气遮蔽，无法直接攻击。"}}
D.ClientTexts.JournalSection[7134]={Name={["b3010cc110a25564:15"]="龟壳震荡"}}
D.ClientTexts.JournalSection[7135]={Name={["c4e886511e1930be:18"]="狂暴岩石吐息"}}
D.ClientTexts.JournalSection[7279]={Name={["fb3a039c15b70755:10"]="暗影箭"},Description={["2fc45ab16d768fac:70"]="复生的巫医朝一名玩家射出一道黑魔法箭，对其造成暗影伤害。"}}
D.ClientTexts.JournalSection[7137]={Name={["003cfbb32b5b08c0:8"]="岩崩"}}
D.ClientTexts.JournalSection[7138]={Name={["e0bc2e4f9e93139a:10"]="震地践踏"}}
D.ClientTexts.JournalSection[7139]={Name={["19c4f0c99477ee74:12"]="猛咬"}}
D.ClientTexts.JournalSection[7140]={Name={["d92c69b6378322d7:15"]="岩洞吸血蝠"}}
D.ClientTexts.JournalSection[7141]={Name={["89b3745c545f0cd1:12"]="吸血弱者"}}
D.ClientTexts.JournalSection[7146]={Name={["0f3efe2a3681e51b:5"]="重压"}}
D.ClientTexts.JournalSection[7147]={Name={["14f760b412b2f97b:10"]="焰甲冲击"}}
D.ClientTexts.JournalSection[7148]={Name={["4fb675880c0e6525:11"]="渐燃之怒"}}
D.ClientTexts.JournalSection[7149]={Name={["e5ef82aa7b201553:12"]="穿刺咆哮"}}
D.ClientTexts.JournalSection[7150]={Name={["11cbbb5bde1d8b96:14"]="灵火光束"}}
D.ClientTexts.JournalSection[7162]={Name={["bffbe2f3a374e9b8:23"]="墨格瑞拉的元素之血"}}
D.ClientTexts.JournalSection[7171]={Name={["23dc585f6965117a:12"]="晶化甲壳"}}
D.ClientTexts.JournalSection[7176]={Name={["610e72418e8d5880:10"]="仅限英雄难度"},Description={["0551f6d38125eb7c:40"]="只有在英雄难度下才能挑战莱登。"}}
D.ClientTexts.JournalSection[7177]={Name={["b80597d7e18a4072:12"]="暗影之魂"}}
D.ClientTexts.JournalSection[7178]={Name={["0a4fa06c8ef85743:23"]="第一阶段：雷霆万钧！"},Description={["f51502c047ff33ab:151"]="雷神装备他的战斧“雷霆”。雷霆可精确打击目标并在落地时召唤闪电轰击地面。雷神将为附近的所有导管充能。"}}
D.ClientTexts.JournalSection[7179]={Name={["1b8b307d9afb49ca:16"]="电能释放"}}
D.ClientTexts.JournalSection[7181]={Name={["541c98f999d40916:10"]="斩首"}}
D.ClientTexts.JournalSection[7182]={Name={["098bd1dbf23992d0:13"]="雷霆打击"}}
D.ClientTexts.JournalSection[7186]={Name={["b8156b46dfb87727:33"]="阶段转换：导管超能"},Description={["bd0e9c5d4e6d7c14:215"]="当生命值降至65%时，雷神会施放导管超能，免疫所有伤害并同时激活所有四根导管，使所有导管进入超能状态并提升一个等级。雷神的导管超能只能维持45秒。"}}
D.ClientTexts.JournalSection[7191]={Name={["f93ce9500655a503:18"]="导管短路"}}
D.ClientTexts.JournalSection[7192]={Name={["dd4a18be9b22d74d:29"]="第二阶段：电闪雷鸣！"},Description={["fcd4474226ca0d9d:111"]="雷神装备他的长戟“惊电”，使其可从天空中召唤闪电。雷神将为附近的所有导管充能。"}}
D.ClientTexts.JournalSection[7193]={Name={["1b8b307d9afb49ca:16"]="电能释放"}}
D.ClientTexts.JournalSection[7195]={Name={["8b8b1b345c4fd799:11"]="熔解削砍"}}
D.ClientTexts.JournalSection[7196]={Name={["5624f9e381f5386a:19"]="召唤球状闪电"}}
D.ClientTexts.JournalSection[7340]={Name={["a7f9d26fcee36b7e:14"]="天灾领主"}}
D.ClientTexts.JournalSection[7197]={Name={["30ee79c13ccbc2a2:13"]="闪电之鞭"}}
D.ClientTexts.JournalSection[7202]={Name={["b8156b46dfb87727:33"]="阶段转换：导管超能"}}
D.ClientTexts.JournalSection[7203]={Name={["f93ce9500655a503:18"]="导管短路"}}
D.ClientTexts.JournalSection[7209]={Name={["b99708bdb871e404:38"]="第三阶段：雷电之主！"},Description={["bea749f51a0aa4e6:239"]="雷神同时装备战斧“雷霆”和长戟“惊电”来对付敌人。雷神将施展压倒能量并消耗掉雷电王座中的所有电能，摧毁所有还在运转的导管，使其无法再被激活。"}}
D.ClientTexts.JournalSection[7210]={Name={["37ff61290570ca04:17"]="压倒能量"}}
D.ClientTexts.JournalSection[7212]={Name={["098bd1dbf23992d0:13"]="雷霆打击"}}
D.ClientTexts.JournalSection[7214]={Name={["5624f9e381f5386a:19"]="召唤球状闪电"}}
D.ClientTexts.JournalSection[7215]={Name={["525d34c4743516eb:13"]="球状闪电"}}
D.ClientTexts.JournalSection[7220]={Name={["30ee79c13ccbc2a2:13"]="闪电之鞭"}}
D.ClientTexts.JournalSection[7237]={Name={["43ed157282b7d59f:17"]="雷电导管"},Description={["053dc11635e7fe61:320"]="当雷神位于雷电导管的充能范围内时，他将为其充能，使雷神获得针对该雷电导管的额外技能。充能时间越长，导管的能级越高，雷神获得的技能伤害值也越高。\r\n\r\n当导管能级达到100时，它将提高导管的等级，导管的能量也将归零。"}}
D.ClientTexts.JournalSection[7238]={Name={["b757bd00d5491853:24"]="北部导管：静电冲击"}}
D.ClientTexts.JournalSection[7239]={Name={["7987218c6a8136f5:26"]="东部导管：散射闪电链"}}
D.ClientTexts.JournalSection[7240]={Name={["f4df89930e188f28:17"]="散射闪电"}}
D.ClientTexts.JournalSection[7241]={Name={["eabe502e98b2efd1:23"]="南部导管：超载"}}
D.ClientTexts.JournalSection[7242]={Name={["e0c6ddbedd8df345:24"]="西部导管：弹跳闪电"}}
D.ClientTexts.JournalSection[7243]={Name={["17e28df2b566484f:16"]="失控能量"},Description={["d022f435dee6d9f2:87"]="当弹跳闪电击中地面且没有被玩家吸收时，则会形成失控能量。"}}
D.ClientTexts.JournalSection[7245]={Name={["ff277c6ea1287ae9:15"]="崩解闪电"}}
D.ClientTexts.JournalSection[7516]={Name={["110d56dfa8a0cf84:17"]="埃蕾希·晨歌"}}
D.ClientTexts.JournalSection[7247]={Name={["525d34c4743516eb:13"]="球状闪电"}}
D.ClientTexts.JournalSection[7248]={Name={["30e313fa6f32103f:13"]="闪电箭"}}
D.ClientTexts.JournalSection[7249]={Name={["c6fe16e4a8f1295d:16"]="暴乱狂风"}}
D.ClientTexts.JournalSection[7250]={Name={["30e313fa6f32103f:13"]="闪电箭"}}
D.ClientTexts.JournalSection[7251]={Name={["97116ab7353bacfa:17"]="迷雾重重"},Description={["860f21d049c2601f:219"]="从未有学者记录过关于莱登的力量的具体细节。或许是因为这些记忆早已湮没在了历史的长河之中，又或许是因为从未有人从与风暴守护者的战斗中生还并讲述自己的经历……"}}
D.ClientTexts.JournalSection[7252]={Name={["2fc64629349b6828:14"]="静电过载"}}
D.ClientTexts.JournalSection[7253]={Name={["525d34c4743516eb:13"]="球状闪电"},Description={["85bc137386b1dbd6:75"]="艾欧纳尔向目标投掷球状闪电，随机对一名玩家造成自然伤害。"}}
D.ClientTexts.JournalSection[7254]={Name={["6c72ac44cba4e0c1:8"]="散布"},Description={["ba5b190b99921c58:93"]="当艾欧纳尔的生命值降至50%时，他会散布艾欧纳尔的火花追逐玩家，持续15秒。"}}
D.ClientTexts.JournalSection[7255]={Name={["2b8da1341337ba65:12"]="艾欧纳尔的火花"}}
D.ClientTexts.JournalSection[7256]={Name={["95487c70ffa0e41f:10"]="弧光灼烧"}}
D.ClientTexts.JournalSection[7257]={Name={["71740ed9714e8946:9"]="冰封地面"}}
D.ClientTexts.JournalSection[7258]={Name={["fb49da929a805685:16"]="脉冲震荡"},Description={["1ae42dad3e94432e:161"]="洛肯每2秒震击所有玩家并造成自然伤害。目标离洛肯越远，受到的伤害越高。此外，自然类效果对所有玩家的伤害提高25%。"}}
D.ClientTexts.JournalSection[7259]={Name={["30e9a9bd9d8ddb96:13"]="闪电新星"}}
D.ClientTexts.JournalSection[7260]={Name={["d770261f53a1f958:12"]="电弧"},Description={["74ab777fef081788:113"]="洛肯震击一名玩家，立即造成自然伤害，并使其震击周围的盟友，并对他们造成自然伤害。"}}
D.ClientTexts.JournalSection[7265]={Name={["a12dfdb1d9cac9f6:15"]="震荡打击"}}
D.ClientTexts.JournalSection[7266]={Name={["6c663c4881267539:16"]="绝望降临"}}
D.ClientTexts.JournalSection[7267]={Name={["a921dec3c292da44:14"]="亵渎尖啸"}}
D.ClientTexts.JournalSection[7268]={Name={["e78b76e1a234096c:12"]="绝望"}}
