D.ClientTexts.JournalSection[7273]={Name={["84b7d5c607e1ed55:7"]="冰墙"},Description={["94cc0fe174a574ce:94"]="阿尔萨斯召唤一道冰墙挡住玩家的去路。冰墙将一直存在，直到阿尔萨斯的所有爪牙都被击败。"}}
D.ClientTexts.JournalSection[7274]={Name={["537f55f297776b6d:17"]="冷酷严冬"}}
D.ClientTexts.JournalSection[7275]={Name={["d168b70cb84cfdad:14"]="阿尔萨斯的爪牙"},Description={["b9d37568ca6ed8b5:89"]="每制造出一道冰墙，阿尔萨斯就召唤出一波爪牙来消灭被困在冰墙内的玩家。"}}
D.ClientTexts.JournalSection[7276]={Name={["a71182bc17d2effb:11"]="暴怒的食尸鬼"}}
D.ClientTexts.JournalSection[7277]={Name={["7c9a0307d2fd46c8:4"]="跳跃"},Description={["576dcda3f9e36166:36"]="暴怒的食尸鬼跳向玩家所在的位置。"}}
