D.ClientTexts.JournalSection[7282]={Name={["9a59e0db2cc9affa:20"]="笨拙的憎恶"}}
D.ClientTexts.JournalSection[7283]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"},Description={["3c0eae2d2465a002:85"]="笨拙的憎恶劈砍一名玩家，对目标及其附近最近的盟友造成物理伤害。"}}
D.ClientTexts.JournalSection[7284]={Name={["d6231a23af157e0e:10"]="呕吐"}}
D.ClientTexts.JournalSection[7285]={Name={["5c2b97411d30248c:10"]="砸击地面"}}
D.ClientTexts.JournalSection[7286]={Name={["91de4940427b5b39:7"]="碎裂"},Description={["5f14a3afe401681a:96"]="克莱斯塔卢斯将所有被石化的玩家击碎，根据距离对他们的盟友造成不等的物理伤害。"}}
D.ClientTexts.JournalSection[7287]={Name={["a7cabc3b6513faa8:11"]="投掷石块"},Description={["c5b308ffc2e829cc:58"]="克莱斯塔卢斯向一名玩家投掷石块，造成物理伤害。"}}
