D.ClientTexts.JournalSection[7316]={Name={["30ebc0b954acbf9a:13"]="闪电之环"}}
D.ClientTexts.JournalSection[7317]={Name={["f92c5cc8e055577d:15"]="铸铁矮人"},Description={["047dec34c7d43d07:81"]="进入战斗后，塑铁者斯约尼尔开始从附近的熔炉中召唤出铸铁矮人。"}}
D.ClientTexts.JournalSection[7318]={Name={["fa4b61173d530a2c:15"]="铸铁穴居人"},Description={["c48321942b21af41:102"]="当塑铁者斯约尼尔的生命值降至75%时，他会开始从附近的熔炉中召唤出铸铁穴居人。"}}
D.ClientTexts.JournalSection[7319]={Name={["fe1564c3a6c630d4:6"]="狂乱"}}
D.ClientTexts.JournalSection[7320]={Name={["14b61779002ff626:13"]="畸形的淤泥怪"},Description={["5e51f81c354fbf61:99"]="当塑铁者斯约尼尔的生命值降至50%时，他会开始从附近的熔炉中召唤出畸形的淤泥怪。"}}
D.ClientTexts.JournalSection[7321]={Name={["55a496e18c1528ae:10"]="铁淤泥"},Description={["03d5c5c2ff46a053:45"]="畸形的淤泥怪融合成一个铁淤泥。"}}
D.ClientTexts.JournalSection[7322]={Name={["274386804a7b94cf:12"]="土灵矮人"},Description={["1af635addb4fc2a2:100"]="当塑铁者斯约尼尔的生命值降至25%时，他会开始从附近的熔炉中召唤出土灵矮人。"}}
D.ClientTexts.JournalSection[7323]={Name={["1f441e354cc5e65c:15"]="闪电之链"}}
D.ClientTexts.JournalSection[7324]={Name={["4e756821abfcc418:14"]="闪电震击"},Description={["d152609f14826900:52"]="铸铁穴居人震击一名玩家，造成自然伤害。"}}
D.ClientTexts.JournalSection[7325]={Name={["3f1417c6a9b24e05:8"]="融合"}}
D.ClientTexts.JournalSection[7326]={Name={["7b720a078d2e4444:11"]="毒箭之雨"},Description={["5b792b48e24d57e3:44"]="铁淤泥对所有玩家造成自然伤害。"}}
