D.ClientTexts.JournalSection[7338]={Name={["cd7a99d02b947c83:10"]="剧毒废渣"}}
D.ClientTexts.JournalSection[7339]={Name={["fb3a039c15b70755:10"]="暗影箭"},Description={["3d3cb3fa1ccf1dc3:59"]="科瑞克朝一名玩家射出一道黑魔法箭，对其造成暗影伤害。"}}
D.ClientTexts.JournalSection[7341]={Name={["83ba349773222c6a:13"]="蛮力冲撞"}}
D.ClientTexts.JournalSection[7342]={Name={["494692ae6c8d04a3:8"]="霜牙"}}
D.ClientTexts.JournalSection[7343]={Name={["48e3934001698599:8"]="寒冰冲击"}}
D.ClientTexts.JournalSection[7344]={Name={["fa67a47182319bf8:11"]="邪恶强化"}}
D.ClientTexts.JournalSection[7345]={Name={["cbf79ef3b6451ff2:15"]="天灾领主的烙印"},Description={["c38c466aa06f02a1:196"]="天灾领主泰兰努斯标记一名玩家，使被标记的敌人造成的所有伤害被反射到施法者的主目标身上，并使被标记敌人所造成的治疗量提高并被反射到施法者身上。"}}
D.ClientTexts.JournalSection[7346]={Name={["db9db0ee65b42f87:14"]="霜牙印记"},Description={["662a1ca1e8d862f8:49"]="天灾领主泰兰努斯命令霜牙攻击一名玩家。"}}
D.ClientTexts.JournalSection[7347]={Name={["f1690b7d7c7b944c:9"]="霜降"}}
D.ClientTexts.JournalSection[7348]={Name={["0ed9981c43bc7aef:13"]="季鹍的族裔"},Description={["e6c4c010dffa1359:253"]="季鹍的子嗣遍布栖木并且经历不同的成长阶段。经过一段时间的孵化后，季鹍的凤凰蛋将孵化出雏鸟。经过季鹍喂食之后，雏鸟将成长为幼鸟。而季鹍幼鸟的蛋和成熟的季鹍凤凰蛋都将孵化出幼年凤凰。"}}
D.ClientTexts.JournalSection[7349]={Name={["66ec3f2db0f26a5a:16"]="季鹍的凤凰蛋"},Description={["f4650f3fec68c6e4:106"]="季鹍栖木周围下层巢穴中的蛋会周期性地孵化。一旦孵化完成，一只雏鸟即会出现。"}}
D.ClientTexts.JournalSection[7350]={Name={["ca2fe7eab43ba5fd:10"]="雏鸟"},Description={["dcaf5407887c4ed2:164"]="雏鸟孵化后，会立刻召唤季鹍喂养它们。如果雏鸟感觉到附近有食物，就会设法进食。如果雏鸟成功进食，就会进化成幼鸟。"}}
D.ClientTexts.JournalSection[7351]={Name={["363d3ba4959e6e9b:10"]="幼鸟"},Description={["bb443bae207c1a39:54"]="幼鸟会随机攻击玩家并产下即将孵化的蛋。"}}
D.ClientTexts.JournalSection[7352]={Name={["0aeb86be4724e7e1:6"]="孵蛋"},Description={["b06c16fd1b62ffa8:82"]="幼鸟会产下即将孵化的蛋。当这些蛋孵化后，会生出幼年凤凰。"}}
D.ClientTexts.JournalSection[7353]={Name={["0f393c8a5d4ec22b:5"]="嘶鸣"}}
D.ClientTexts.JournalSection[7354]={Name={["e274d82b1bbb85fa:9"]="喂养幼雏"},Description={["bb94cc57c2ca9e9e:384"]="季鹍向自己的雏鸟喷吐饲料球。如果有雏鸟索要食物，则季鹍会将此技能对准其所在的方向，否则食物将随机散落在季鹍的平台各处。食物落地后，将形成饲料池。\r\n\r\n当饲料球在空中飞行时，拥有飞行效果的玩家可以进行拦截，以防止饲料池形成。这将使玩家获得黏呼呼的效果，但同时也会获得原始营养的效果。"}}
D.ClientTexts.JournalSection[7355]={Name={["1bfe0c63e905153c:6"]="黏呼呼的"}}
D.ClientTexts.JournalSection[7356]={Name={["17f6945f1f849c0e:6"]="飞羽满天"}}
D.ClientTexts.JournalSection[7357]={Name={["0b88650031211739:3"]="鸣叫"}}
D.ClientTexts.JournalSection[7358]={Name={["0b88650031211739:3"]="鸣叫"}}
D.ClientTexts.JournalSection[7359]={Name={["7448092028434a59:14"]="灵巧之翼"}}
D.ClientTexts.JournalSection[7360]={Name={["fdaae323c5d2c8d0:6"]="飞行"}}
