D.ClientTexts.JournalSection[7377]={Name={["760d38634593b166:9"]="心灵震爆"},Description={["b4d535780f5861ad:44"]="玛尔加尼斯随机对玩家造成暗影伤害。"}}
D.ClientTexts.JournalSection[7378]={Name={["9a7781e34ef9b60e:13"]="吸血鬼之触"},Description={["a1e46b74ca337a1d:69"]="玛尔加尼斯的吸血鬼之触为他自己恢复生命值，相当于其近战攻击伤害的50%。"}}
D.ClientTexts.JournalSection[7379]={Name={["cb7b8dbd85a9872e:12"]="腐臭蜂群"}}
