D.ClientTexts.JournalSection[7382]={Name={["f7919954823954ef:21"]="腐化的灵魂碎片"},Description={["9ffe7cf8cfce26f7:93"]="腐化的灵魂碎片向布隆亚姆移动。如果碎片到达布隆亚姆的身边，他将吞噬这个灵魂碎片。"}}
D.ClientTexts.JournalSection[7383]={Name={["a1e8afc2c42baf8f:11"]="吞噬灵魂"}}
D.ClientTexts.JournalSection[7384]={Name={["e93c08fd94f48d36:9"]="灵魂风暴"}}
D.ClientTexts.JournalSection[7385]={Name={["fb3a039c15b70755:10"]="暗影箭"},Description={["4fc2cab809f24557:95"]="当布隆亚姆处于灵魂风暴中时，他会随机朝一名玩家射出一道黑魔法箭，对其造成暗影伤害。"}}
D.ClientTexts.JournalSection[7386]={Name={["7c96b8c3bbd46250:4"]="恐惧"}}
D.ClientTexts.JournalSection[7387]={Name={["3a4cbe4c1cd23f31:12"]="灵魂倒映"},Description={["78ed325df5bd0f94:120"]="噬魂者映射目标的灵魂！噬魂者所造成的伤害的一部分会被映射给目标。"}}
D.ClientTexts.JournalSection[7388]={Name={["fa002db2542db62b:12"]="幽灵冲击"}}
D.ClientTexts.JournalSection[7389]={Name={["a8c12e641e8dd91b:11"]="灵魂之井"}}
D.ClientTexts.JournalSection[7390]={Name={["a6d940d4908a2f5d:14"]="灵魂解禁"}}
D.ClientTexts.JournalSection[7391]={Name={["61e2b1468164cd4b:12"]="哀嚎之魂"}}
D.ClientTexts.JournalSection[7392]={Name={["41d86d2b835f2bb8:8"]="火焰炸弹"}}
D.ClientTexts.JournalSection[7393]={Name={["84b3232a6c137217:7"]="寒冰新星"}}
