D.ClientTexts.JournalSection[7395]={Name={["443a3a768f57edd7:12"]="镜像"},Description={["8da9ec5048909fb9:75"]="当大魔导师泰蕾丝塔的生命值降至50%时，会分裂成3个镜像。"}}
