D.ClientTexts.JournalSection[7400]={Name={["7ce43d01eeb79aa2:9"]="火焰冲击"},Description={["3951b522d03144ad:77"]="大魔导师泰蕾丝塔的火焰镜像用烈焰冲击一名玩家，造成火焰伤害。"}}
D.ClientTexts.JournalSection[7401]={Name={["1b5e8f279f52efb8:6"]="灼烧"},Description={["6b89505f272a00fc:69"]="大魔导师泰蕾丝塔的火焰镜像灼烧一名玩家，对其造成火焰伤害。"}}
D.ClientTexts.JournalSection[7402]={Name={["cc8282967b9e1a37:10"]="冰霜镜像"}}
D.ClientTexts.JournalSection[7403]={Name={["644a53079a314a34:8"]="暴风雪"}}
D.ClientTexts.JournalSection[7404]={Name={["84ac528d36d8cf1a:7"]="冰刺"},Description={["8bc50b027cadaf35:68"]="大魔导师泰蕾丝塔的冰霜镜像随机对一名玩家造成冰霜伤害。"}}
D.ClientTexts.JournalSection[7405]={Name={["105f18460e5ffd5d:5"]="火花"},Description={["7d93cfe06e06a645:58"]="阿诺玛鲁斯朝一名玩家射出一道魔法箭，对其造成奥术伤害。"}}
D.ClientTexts.JournalSection[7406]={Name={["45e93cc8989d844d:16"]="奥术吸引"}}
D.ClientTexts.JournalSection[7407]={Name={["1bf2b6aed6c43081:10"]="制造裂隙"},Description={["e1f1a878a361c6a1:59"]="阿诺玛鲁斯撕裂空间结构，在自己附近打开一道混乱裂隙。"}}
D.ClientTexts.JournalSection[7408]={Name={["93d1ef35bdf78fe0:11"]="混乱裂隙"}}
D.ClientTexts.JournalSection[7409]={Name={["427402569384c715:23"]="召唤狂乱的法力怨灵"},Description={["1c844bd485b7ff29:69"]="混乱裂隙会不停地召唤狂乱的法力怨灵，直至其被摧毁。"}}
D.ClientTexts.JournalSection[7410]={Name={["79adcbda5eb028dd:18"]="混乱能量爆炸"}}
D.ClientTexts.JournalSection[7411]={Name={["a5ae7b68c6dce8ed:25"]="混乱充能爆炸"}}
D.ClientTexts.JournalSection[7412]={Name={["c420c5b71b428496:17"]="狂乱的法力怨灵"}}
D.ClientTexts.JournalSection[7413]={Name={["3f3704d8ef4b7093:14"]="奥术飞弹"}}
D.ClientTexts.JournalSection[7414]={Name={["e0e1b6f3681c71ee:10"]="裂隙之盾"}}
D.ClientTexts.JournalSection[7415]={Name={["67982ab7c4fd12da:11"]="裂隙充能"},Description={["d5b288f3d9dc9988:130"]="阿诺玛鲁斯将自己的混乱能量引导进附近的裂隙中，提高混乱能量爆炸的影响范围以及它们制造狂乱的法力怨灵的速度。"}}
D.ClientTexts.JournalSection[7416]={Name={["690ee6b0c5a70653:15"]="法术反射"},Description={["d8effa4e37bf19fb:78"]="塑树者奥莫洛克的皮肤微微发光，将接下来的4个法术反射给施法者。"}}
D.ClientTexts.JournalSection[7417]={Name={["f628357aaec1249f:7"]="践踏"}}
D.ClientTexts.JournalSection[7418]={Name={["9ffa5516da527743:13"]="水晶之刺"}}
D.ClientTexts.JournalSection[7419]={Name={["ca819dbbd61e4d2a:24"]="召唤水晶纠结者"}}
D.ClientTexts.JournalSection[7420]={Name={["81c6cd3cfb50efe9:18"]="水晶纠结者"}}
D.ClientTexts.JournalSection[7421]={Name={["fe1564c3a6c630d4:6"]="狂乱"},Description={["da1f4437c932fb74:101"]="当塑树者奥莫洛克的生命值降至30%时，他会陷入狂乱，造成的物理伤害提高。"}}
D.ClientTexts.JournalSection[7422]={Name={["8079e31d43742dae:11"]="极度冰寒"}}
D.ClientTexts.JournalSection[7423]={Name={["265505a3e3d0c32c:17"]="水晶烈焰吐息"}}
D.ClientTexts.JournalSection[7424]={Name={["d6657593f9ae38bc:9"]="扫尾"},Description={["4dff2e1a877ae707:95"]="克莉斯塔萨摆动她的尾巴，对在其身后锥形范围内的所有玩家造成物理伤害，并将他们击退。"}}
D.ClientTexts.JournalSection[7425]={Name={["7a129c9de2ffc888:13"]="水晶锁链"}}
D.ClientTexts.JournalSection[7426]={Name={["46e3d5db9ce32ade:11"]="晶化"}}
D.ClientTexts.JournalSection[7427]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[7428]={Name={["cb1b8e74858e92fb:20"]="仅限英雄难度"},Description={["fc334a2101af400e:52"]="冰封指挥官只在英雄难度下开放。"}}
D.ClientTexts.JournalSection[7429]={Name={["b727f51d940c3d9a:9"]="旋风斩"}}
D.ClientTexts.JournalSection[7430]={Name={["c4a66cb4bebd35c1:11"]="战斗怒吼"}}
D.ClientTexts.JournalSection[7431]={Name={["f65ed2cf04cf4d54:6"]="冲锋"}}
D.ClientTexts.JournalSection[7432]={Name={["770582ed9c1ee776:16"]="破胆怒吼"}}
D.ClientTexts.JournalSection[7433]={Name={["b727f51d940c3d9a:9"]="旋风斩"}}
D.ClientTexts.JournalSection[7434]={Name={["c4a66cb4bebd35c1:11"]="战斗怒吼"}}
D.ClientTexts.JournalSection[7435]={Name={["f65ed2cf04cf4d54:6"]="冲锋"}}
D.ClientTexts.JournalSection[7436]={Name={["770582ed9c1ee776:16"]="破胆怒吼"}}
D.ClientTexts.JournalSection[7437]={Name={["79947950eae2ec93:15"]="雷霆践踏"},Description={["cbc57f1ebfb65bb3:97"]="审讯者达库斯践踏大地，对所有玩家造成物理伤害，并将其击飞。"}}
D.ClientTexts.JournalSection[7438]={Name={["6236a6a92de18e22:20"]="召唤不稳定的宝珠"}}
D.ClientTexts.JournalSection[7439]={Name={["04e55163c8915a72:9"]="魔法牵引"},Description={["5c9e0234db45781d:46"]="审讯者达库斯将所有玩家传送到自己身边。"}}
D.ClientTexts.JournalSection[7440]={Name={["4b519ad8bd8506b9:12"]="魔法增效"}}
D.ClientTexts.JournalSection[7441]={Name={["977e659a1172b571:13"]="能量核心"},Description={["9ac3b6717cac0240:113"]="瓦尔洛斯·云击为部分平台充能，对这部分平台上的所有玩家造成奥术伤害。"}}
D.ClientTexts.JournalSection[7442]={Name={["049e4c98681e46a3:20"]="召唤碧蓝魔环上尉"},Description={["3f6fe070eb874e31:47"]="召唤一名召唤碧蓝魔环上尉来消灭玩家。"}}
D.ClientTexts.JournalSection[7443]={Name={["c172e59cb36d89e5:16"]="碧蓝魔环上尉"}}
D.ClientTexts.JournalSection[7444]={Name={["2d521f24be7eb5d5:10"]="奥术光束"}}
D.ClientTexts.JournalSection[7445]={Name={["062eb3735a7cbe66:9"]="寒冰炸弹"},Description={["12a715a90514e432:142"]="法师领主伊洛姆发射一枚寒冰炸弹，造成冰霜伤害并冻结地面，对同一区域内的玩家造成周期性伤害并降低其移动速度。"}}
D.ClientTexts.JournalSection[7446]={Name={["21c84654ff78fdef:8"]="定时炸弹"}}
D.ClientTexts.JournalSection[7447]={Name={["bd478d98006d2ad3:24"]="强化魔爆术"},Description={["edf07debd8ae7a9c:95"]="法师领主伊洛姆施放致命的魔法冲击波，对其视线范围内的所有玩家造成奥术伤害。"}}
D.ClientTexts.JournalSection[7448]={Name={["0d08e2e3ca92915a:13"]="奥术弹幕"},Description={["0ce2d13dadd8085e:71"]="魔网守护者埃雷苟斯向一名玩家发射魔法弹幕，造成奥术伤害。"}}
D.ClientTexts.JournalSection[7449]={Name={["f9b8ab2a4bbc6c53:12"]="奥术箭雨"},Description={["563edf04d4cc416b:75"]="魔网守护者埃雷苟斯施放一道魔法冲击波，对所有玩家造成奥术伤害。"}}
D.ClientTexts.JournalSection[7450]={Name={["fa8da85895b2268f:14"]="暴怒攻击"}}
D.ClientTexts.JournalSection[7451]={Name={["45beb705ee66d492:22"]="召唤魔网雏龙"},Description={["0a2c5a0ef35ace33:77"]="魔网守护者埃雷苟斯周期性地召唤若干魔网雏龙攻击玩家。"}}
D.ClientTexts.JournalSection[7452]={Name={["8c00e52b77e6848c:16"]="大型魔网雏龙"}}
D.ClientTexts.JournalSection[7453]={Name={["2d524b20c376539b:10"]="奥术箭"},Description={["0b35cc32754b8453:66"]="大型魔网雏龙向玩家发射魔法箭，造成奥术伤害。"}}
D.ClientTexts.JournalSection[7454]={Name={["dcf78ac165e4d6e8:11"]="位面转移"}}
D.ClientTexts.JournalSection[7455]={Name={["9ddc1474d1684909:13"]="位面畸体"}}
D.ClientTexts.JournalSection[7721]={Name={["ac0e11ef125c37aa:14"]="复仇之魂"}}
D.ClientTexts.JournalSection[7456]={Name={["de378672464b9a57:16"]="位面扭曲"}}
D.ClientTexts.JournalSection[7457]={Name={["57bc4352687ed813:11"]="大地之盾"}}
D.ClientTexts.JournalSection[7458]={Name={["20bab202690fc7e9:9"]="治疗链"}}
D.ClientTexts.JournalSection[7459]={Name={["a0415dbd7872ace4:9"]="嗜血"}}
D.ClientTexts.JournalSection[7460]={Name={["30e313fa6f32103f:13"]="闪电箭"},Description={["1c3c190440a1aeb1:56"]="埃雷克姆用闪电冲击一名玩家，造成自然伤害。"}}
D.ClientTexts.JournalSection[7461]={Name={["02b1de4008f8c0d1:10"]="解缚"}}
D.ClientTexts.JournalSection[7462]={Name={["6ed46f519c3bf2ea:11"]="埃雷克姆卫兵"},Description={["9e903840540b5aad:31"]="两名埃雷克姆卫兵将伴随埃雷克姆出场。"}}
D.ClientTexts.JournalSection[7463]={Name={["d4da249a36234221:14"]="恐怖嚎叫"}}
D.ClientTexts.JournalSection[7464]={Name={["14ab4dc7644bca54:12"]="龟裂创伤"}}
D.ClientTexts.JournalSection[7465]={Name={["1c93af97a9332772:6"]="打击"},Description={["53652c61f16c92f0:51"]="埃雷克姆卫兵打击一名玩家，对其造成物理伤害。"}}
D.ClientTexts.JournalSection[7466]={Name={["240e11f37ae6307a:14"]="风暴释放"},Description={["cfccfaa3fc38b368:81"]="如果埃雷克姆的两名卫兵都被杀死，他将进入激怒状态，并使用新的技能攻击玩家。"}}
D.ClientTexts.JournalSection[7467]={Name={["3b5f4bac7179935b:11"]="风暴打击"}}
D.ClientTexts.JournalSection[7468]={Name={["e8d320dd7802b6be:8"]="风怒"}}
D.ClientTexts.JournalSection[7469]={Name={["02a8b6714057a918:10"]="大地震击"}}
D.ClientTexts.JournalSection[7470]={Name={["ae6c5e121cfa60a7:9"]="旋光链接"}}
D.ClientTexts.JournalSection[7471]={Name={["56b73c21ba16ccde:15"]="腐蚀唾液"}}
D.ClientTexts.JournalSection[7472]={Name={["c320b3ce3e0a0337:9"]="痛苦射线"},Description={["ad0ddbd38f3412f0:66"]="摩拉格周期性地随机向玩家施放射线，造成暗影伤害。"}}
D.ClientTexts.JournalSection[7473]={Name={["c320b3ce3e0a0337:9"]="痛苦射线"}}
D.ClientTexts.JournalSection[7474]={Name={["0375392f125ad0d2:14"]="受难射线"}}
D.ClientTexts.JournalSection[7475]={Name={["239e8d363f57d2f5:16"]="保护水泡"}}
D.ClientTexts.JournalSection[7476]={Name={["0f2e7e157cafc9e0:5"]="爆裂"}}
D.ClientTexts.JournalSection[7477]={Name={["1c47e2507e704ce7:6"]="泼溅"}}
D.ClientTexts.JournalSection[7478]={Name={["578add2441d16445:12"]="艾库隆的水珠"}}
D.ClientTexts.JournalSection[7479]={Name={["0fecc3f57f5ecff8:5"]="融合"},Description={["41b4f3fed1cdba65:109"]="艾库隆的水珠会向艾库隆移动并试图与之融合，牺牲自己来为其恢复3%的最大生命值。"}}
D.ClientTexts.JournalSection[7480]={Name={["b762f2fe8060a6c1:10"]="水之冲击"},Description={["775c59bda2665744:77"]="艾库隆朝一名玩家射出水之冲击，造成冰霜伤害并将其击退。"}}
D.ClientTexts.JournalSection[7481]={Name={["538c3a343da89e79:15"]="水箭之雨"}}
D.ClientTexts.JournalSection[7482]={Name={["2d524b20c376539b:10"]="奥术箭"},Description={["560202f6ad17f317:56"]="谢沃兹向一名玩家发射魔法箭，造成奥术伤害。"}}
D.ClientTexts.JournalSection[7483]={Name={["f9e4ad1eee26a327:19"]="奥术弹雨"}}
D.ClientTexts.JournalSection[7484]={Name={["cb7aadcb0db1cbe8:12"]="奥术冲击"}}
D.ClientTexts.JournalSection[7485]={Name={["b8f5b476d39f73b7:14"]="灵体之球"},Description={["27dc07a9b1d3e336:47"]="谢沃兹召唤灵体之球并向自己移动。"}}
D.ClientTexts.JournalSection[7486]={Name={["633d38f00ad5e6cf:15"]="魔爆术"}}
D.ClientTexts.JournalSection[7487]={Name={["d899337c2a026c7f:11"]="奥术能量"}}
D.ClientTexts.JournalSection[7488]={Name={["41d86d1c835e2b8b:8"]="火焰箭"},Description={["e1b4beb46062b5d5:37"]="拉文索尔对一名玩家造成火焰伤害。"}}
D.ClientTexts.JournalSection[7489]={Name={["c9992c60e35d7a53:11"]="烈焰吐息"}}
D.ClientTexts.JournalSection[7490]={Name={["6c9ddf20f06b496f:8"]="熔岩灼烧"}}
D.ClientTexts.JournalSection[7491]={Name={["5118152262132927:17"]="灼烧之焰"}}
D.ClientTexts.JournalSection[7492]={Name={["d1b2ca9bf2201c34:16"]="召唤虚空斥候"},Description={["64083b69be8dfe80:40"]="湮灭者祖拉玛特召唤一名虚空斥候。"}}
D.ClientTexts.JournalSection[7493]={Name={["a0e5091ccaddfcf3:10"]="虚空斥候"},Description={["e305710bde3ee814:89"]="虚空斥候移入虚空之中，对并未移入虚空的玩家隐形。"}}
D.ClientTexts.JournalSection[7494]={Name={["f143b497de6370a2:16"]="暗影箭雨"},Description={["fa34436ffd34843e:68"]="虚空斥候对所有玩家发射黑暗魔法箭，造成暗影伤害。"}}
D.ClientTexts.JournalSection[7495]={Name={["98468e552189664e:9"]="虚空转移"}}
D.ClientTexts.JournalSection[7496]={Name={["835be1ca7d165bc5:16"]="黑暗遮蔽"}}
D.ClientTexts.JournalSection[7497]={Name={["c01d5ef31b1a552a:20"]="无法控制的能量"}}
D.ClientTexts.JournalSection[7498]={Name={["d6657593f9ae38bc:9"]="扫尾"},Description={["f962720246cce70b:106"]="塞安妮苟萨摆动她的尾巴，对在其身后锥形范围内的所有玩家造成物理伤害，并打断他们正在施放的法术。"}}
D.ClientTexts.JournalSection[7499]={Name={["644a53079a314a34:8"]="暴风雪"}}
D.ClientTexts.JournalSection[7500]={Name={["f8b68d00f69072fb:12"]="奥术真空"},Description={["8a6f0a3e06e7229b:32"]="塞安妮苟萨将所有玩家召唤到自己身边。"}}
D.ClientTexts.JournalSection[7501]={Name={["aaaa0656740a1fab:15"]="法力毁灭"}}
D.ClientTexts.JournalSection[7502]={Name={["c2867a5b2b5bd8c0:8"]="竞技"},Description={["380a844bfc653c46:145"]="玩家在一场竞技战斗中要面对三位随机选出的部落勇士。每位玩家必须装备一支银色长枪，并骑着银色战马与勇士们交战。"}}
D.ClientTexts.JournalSection[7503]={Name={["bb698891e2cf5faa:14"]="银色战马"}}
D.ClientTexts.JournalSection[7504]={Name={["1e0fe64f963bd0b8:6"]="刺击"},Description={["279da1a6c7232bc9:69"]="玩家向前刺出长枪，对目标造成物理伤害。"}}
D.ClientTexts.JournalSection[7505]={Name={["dff65ca7d0d70ee8:14"]="碎盾"},Description={["f72352bdb09a7376:115"]="玩家将他们的长枪投过战场，对目标造成物理伤害并移除其身上一层防御。"}}
D.ClientTexts.JournalSection[7506]={Name={["f65ed2cf04cf4d54:6"]="冲锋"},Description={["17f4bd05c10c188e:88"]="玩家向前冲锋，造成物理伤害，并从目标身上移除一层防御效果。"}}
D.ClientTexts.JournalSection[7507]={Name={["f880396b3178dd76:6"]="防御"},Description={["5104b3d23cf4f43b:138"]="玩家保护自己，受到的伤害降低30%。敌人的碎盾或冲锋攻击将移除一层防御效果。该效果最多可叠加3次。"}}
D.ClientTexts.JournalSection[7508]={Name={["f628357aaec1249f:7"]="践踏"},Description={["f933652856afee63:151"]="玩家可以骑着坐骑，践踏从坐骑上被击落的勇士。被践踏的敌人会昏迷15秒，并无法获得新的坐骑。"}}
D.ClientTexts.JournalSection[7509]={Name={["84d5ac6812e717b9:12"]="勇士"},Description={["9aea04a42b4d9b8f:110"]="三位随机选出的勇士骑在银色战斗座狼的背上面对玩家，使用与银色战马相同的技能。"}}
D.ClientTexts.JournalSection[7510]={Name={["c2b71fee21603f43:8"]="近战厮杀"},Description={["b6462836952f4b7d:72"]="当所有勇士都在竞技中被击败后，玩家必须与其展开近身对决。"}}
D.ClientTexts.JournalSection[7511]={Name={["63f0db272170b744:20"]="碎颅者莫克拉"}}
D.ClientTexts.JournalSection[7512]={Name={["12b3db33e1b10102:9"]="拦截"},Description={["e3eaa76fa6c29510:60"]="碎颅者莫克拉向一名玩家冲锋，造成物理伤害。"}}
D.ClientTexts.JournalSection[7513]={Name={["70e60bb2f36e7f91:10"]="剑刃风暴"}}
D.ClientTexts.JournalSection[7514]={Name={["abc3e8a67e4f4e01:12"]="致死打击"}}
D.ClientTexts.JournalSection[7515]={Name={["c461b0d0ecffef61:12"]="旋转投掷"},Description={["a729421cb289b4af:43"]="碎颅者莫克拉将一名玩家向后扔去。"}}
D.ClientTexts.JournalSection[7517]={Name={["41d831867c795275:8"]="火球术"},Description={["5449329fdc9e0c4a:66"]="埃蕾希·晨歌向玩家投掷一发火球，造成火焰伤害。"}}
D.ClientTexts.JournalSection[7518]={Name={["f4de5eef35b1c11c:9"]="变形术"}}
D.ClientTexts.JournalSection[7519]={Name={["750de92e4f85d9b1:9"]="冲击波"}}
D.ClientTexts.JournalSection[7520]={Name={["0f901dda7230c4ab:5"]="急速"}}
D.ClientTexts.JournalSection[7521]={Name={["4b6e4f25cfbc5f3c:13"]="鲁诺克·蛮鬃"}}
D.ClientTexts.JournalSection[7522]={Name={["1af07630f132f5b3:11"]="治疗波"},Description={["3a4a47b287ec9873:46"]="鲁诺克·蛮鬃召唤自然魔法治疗一名盟友。"}}
D.ClientTexts.JournalSection[7523]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[7524]={Name={["57bc4352687ed813:11"]="大地之盾"}}
D.ClientTexts.JournalSection[7525]={Name={["1c5c1f61ef84b2c2:12"]="妖术治愈"}}
D.ClientTexts.JournalSection[7526]={Name={["4060e44197faa1a4:8"]="祖尔托"}}
D.ClientTexts.JournalSection[7527]={Name={["105af072a10b4fbf:5"]="射击"},Description={["95c7796c127ec813:47"]="祖尔托朝一名玩家射击，对其造成物理伤害。"}}
D.ClientTexts.JournalSection[7528]={Name={["b093779bf6955e4e:10"]="多重射击"}}
D.ClientTexts.JournalSection[7529]={Name={["f3dc6027c0f25134:15"]="雷光箭矢"}}
D.ClientTexts.JournalSection[7530]={Name={["e1bbfe4c65156a6f:9"]="逃脱"},Description={["33e92b7d63e3578a:56"]="祖尔托试图摆脱玩家，向后纵跃。"}}
D.ClientTexts.JournalSection[7531]={Name={["70f5709602c736e1:19"]="死亡猎手维赛里"}}
D.ClientTexts.JournalSection[7532]={Name={["39465b30bc015e59:12"]="致命毒药"}}
D.ClientTexts.JournalSection[7533]={Name={["c1ad281f95818dc8:11"]="刀扇"}}
D.ClientTexts.JournalSection[7534]={Name={["034fade7c3b2058e:12"]="毒药瓶"}}
D.ClientTexts.JournalSection[7535]={Name={["e8f16310a44f4b3d:10"]="刺骨"},Description={["09b880dfa3478316:63"]="死亡猎手维赛里突刺一名玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[7536]={Name={["c2867a5b2b5bd8c0:8"]="竞技"},Description={["1ed247e2c5b6cb35:150"]="玩家在一场竞技战斗中要面对三位随机选出的联盟勇士。每位玩家必须装备一支银色长枪，并骑着银色战斗座狼与勇士们交战。"}}
D.ClientTexts.JournalSection[7537]={Name={["53663ea154c2d0ba:16"]="银色战斗座狼"}}
D.ClientTexts.JournalSection[7538]={Name={["1e0fe64f963bd0b8:6"]="刺击"},Description={["279da1a6c7232bc9:69"]="玩家向前刺出长枪，对目标造成物理伤害。"}}
D.ClientTexts.JournalSection[7539]={Name={["dff65ca7d0d70ee8:14"]="碎盾"},Description={["f72352bdb09a7376:115"]="玩家将他们的长枪投过战场，对目标造成物理伤害并移除其身上一层防御。"}}
D.ClientTexts.JournalSection[7540]={Name={["f65ed2cf04cf4d54:6"]="冲锋"},Description={["17f4bd05c10c188e:88"]="玩家向前冲锋，造成物理伤害，并从目标身上移除一层防御效果。"}}
D.ClientTexts.JournalSection[7541]={Name={["f880396b3178dd76:6"]="防御"},Description={["5104b3d23cf4f43b:138"]="玩家保护自己，受到的伤害降低30%。敌人的碎盾或冲锋攻击将移除一层防御效果。该效果最多可叠加3次。"}}
D.ClientTexts.JournalSection[7542]={Name={["f628357aaec1249f:7"]="践踏"},Description={["f933652856afee63:151"]="玩家可以骑着坐骑，践踏从坐骑上被击落的勇士。被践踏的敌人会昏迷15秒，并无法获得新的坐骑。"}}
D.ClientTexts.JournalSection[7543]={Name={["84d5ac6812e717b9:12"]="勇士"},Description={["14ffe564009eea0f:110"]="三位随机选出的勇士骑在银色战马的背上面对玩家，使用与银色战斗座狼相同的技能。"}}
D.ClientTexts.JournalSection[7544]={Name={["c2b71fee21603f43:8"]="近战厮杀"},Description={["b6462836952f4b7d:72"]="当所有勇士都在竞技中被击败后，玩家必须与其展开近身对决。"}}
D.ClientTexts.JournalSection[7545]={Name={["5a9186e173ebe0ae:19"]="雅克布·奥勒留斯元帅"}}
D.ClientTexts.JournalSection[7546]={Name={["12b3db33e1b10102:9"]="拦截"},Description={["7cc8d529303f1a7a:59"]="雅克布·奥勒留斯元帅向一名玩家冲锋，造成物理伤害。"}}
D.ClientTexts.JournalSection[7547]={Name={["70e60bb2f36e7f91:10"]="剑刃风暴"}}
D.ClientTexts.JournalSection[7548]={Name={["abc3e8a67e4f4e01:12"]="致死打击"}}
D.ClientTexts.JournalSection[7549]={Name={["c461b0d0ecffef61:12"]="旋转投掷"},Description={["71d1ec96981e8cc5:42"]="雅克布·奥勒留斯元帅将一名玩家向后扔去。"}}
D.ClientTexts.JournalSection[7550]={Name={["3d4dbd40aff1c603:16"]="安布罗斯·雷钉"}}
D.ClientTexts.JournalSection[7551]={Name={["41d831867c795275:8"]="火球术"},Description={["88ef0b205e11298b:65"]="安布罗斯·雷钉向玩家投掷一发火球，造成火焰伤害。"}}
D.ClientTexts.JournalSection[7552]={Name={["f4de5eef35b1c11c:9"]="变形术"}}
D.ClientTexts.JournalSection[7553]={Name={["750de92e4f85d9b1:9"]="冲击波"}}
D.ClientTexts.JournalSection[7554]={Name={["0f901dda7230c4ab:5"]="急速"}}
D.ClientTexts.JournalSection[7555]={Name={["d352e6477d151028:7"]="克罗索斯"}}
D.ClientTexts.JournalSection[7556]={Name={["1af07630f132f5b3:11"]="治疗波"},Description={["3d46cb140d478287:40"]="克罗索斯召唤自然魔法治疗一名盟友。"}}
D.ClientTexts.JournalSection[7557]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[7558]={Name={["57bc4352687ed813:11"]="大地之盾"}}
D.ClientTexts.JournalSection[7559]={Name={["1c5c1f61ef84b2c2:12"]="妖术治愈"}}
D.ClientTexts.JournalSection[7560]={Name={["fe9ebf7223b78c01:15"]="娅琳·永歌"}}
D.ClientTexts.JournalSection[7561]={Name={["105af072a10b4fbf:5"]="射击"},Description={["2a36b77d9782d876:54"]="娅琳·永歌朝一名玩家射击，对其造成物理伤害。"}}
D.ClientTexts.JournalSection[7562]={Name={["b093779bf6955e4e:10"]="多重射击"}}
D.ClientTexts.JournalSection[7563]={Name={["f3dc6027c0f25134:15"]="雷光箭矢"}}
D.ClientTexts.JournalSection[7564]={Name={["e1bbfe4c65156a6f:9"]="逃脱"},Description={["0911ccae289065e7:63"]="娅琳·永歌试图摆脱玩家，向后纵跃。"}}
D.ClientTexts.JournalSection[7565]={Name={["aa393a9aa1714e4b:15"]="拉娜·硬锤"}}
D.ClientTexts.JournalSection[7566]={Name={["39465b30bc015e59:12"]="致命毒药"}}
D.ClientTexts.JournalSection[7567]={Name={["c1ad281f95818dc8:11"]="刀扇"}}
D.ClientTexts.JournalSection[7568]={Name={["034fade7c3b2058e:12"]="毒药瓶"}}
D.ClientTexts.JournalSection[7569]={Name={["e8f16310a44f4b3d:10"]="刺骨"},Description={["7f1680e315b34c80:59"]="拉娜·硬锤突刺一名玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[7570]={Name={["e495ce513a0aa68c:9"]="复仇"},Description={["4664b07b6f3efcc0:82"]="纯洁者耶德瑞克的近战攻击有一定几率使他的下一次近战攻击造成爆击。"}}
D.ClientTexts.JournalSection[7571]={Name={["ccbc18fc21115483:8"]="光芒耀眼"}}
D.ClientTexts.JournalSection[7572]={Name={["0bf884ab6eeaf862:15"]="制裁之锤"}}
D.ClientTexts.JournalSection[7573]={Name={["0461988f59c18e50:20"]="正义之锤"},Description={["64349dc2df7f533d:141"]="纯洁者耶德瑞克向一名玩家掷出战锤，造成神圣伤害。如果目标没有受制裁之锤效果影响，则可接住这把战锤并将其扔回给耶德瑞克。"}}
D.ClientTexts.JournalSection[7574]={Name={["51662b63d2f5df0c:9"]="神圣惩击"},Description={["c7b3be8b2992fc70:65"]="银色神官帕尔崔丝随机重击一名玩家，造成神圣伤害。"}}
D.ClientTexts.JournalSection[7575]={Name={["10472d46d1026c8d:5"]="恢复"}}
D.ClientTexts.JournalSection[7576]={Name={["dba692674f1d320a:8"]="神圣之火"}}
D.ClientTexts.JournalSection[7577]={Name={["248582dd29e69a42:12"]="唤起回忆"},Description={["ce778c84bf118a3d:93"]="当银色神官帕尔崔丝的生命值降至50%时，她会从你过去的战斗中召唤一只生物。"}}
D.ClientTexts.JournalSection[7578]={Name={["4fb81dccbeae3c6b:15"]="往日回忆"}}
D.ClientTexts.JournalSection[7579]={Name={["097ff645c7793cbe:15"]="梦魇乍醒"}}
D.ClientTexts.JournalSection[7580]={Name={["8b11312ca9d1c0b9:16"]="昔日阴影"}}
D.ClientTexts.JournalSection[7581]={Name={["4f47a0c438b018e7:9"]="旧患"}}
D.ClientTexts.JournalSection[7582]={Name={["d89246a425b5c7df:21"]="阶段1：黑骑士"}}
D.ClientTexts.JournalSection[7583]={Name={["3c6edd418681b08a:14"]="缓死"}}
D.ClientTexts.JournalSection[7584]={Name={["4a2b446d5d65d800:8"]="冰冷触摸"},Description={["c0500c718281d46c:93"]="黑骑士用冰冷的双手抓住一名玩家，造成冰霜伤害并使其感染冰霜疫病。"}}
D.ClientTexts.JournalSection[7585]={Name={["cc482f2b45f7bc60:10"]="冰霜疫病"}}
D.ClientTexts.JournalSection[7586]={Name={["d9cf7915d4fb6ee4:12"]="暗影打击"},Description={["719a0281accf058c:93"]="黑骑士恶毒地攻击一名玩家，造成物理伤害并使其感染血之疫病。"}}
D.ClientTexts.JournalSection[7587]={Name={["beb780532c184f0c:11"]="血之疫病"}}
D.ClientTexts.JournalSection[7588]={Name={["478b72aa534cb665:17"]="复活银色先锋"},Description={["afdbd30243c8bfdb:52"]="黑骑士将一名银色先锋复活为无脑的食尸鬼。"}}
D.ClientTexts.JournalSection[7589]={Name={["96d319f7d60428fe:17"]="复活的银色先锋"}}
D.ClientTexts.JournalSection[7590]={Name={["7c95316c33b25c9f:4"]="爪击"},Description={["2a5acf9dce7d44e4:58"]="复活的银色先锋爪击一名玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[7591]={Name={["7c9a0307d2fd46c8:4"]="跳跃"},Description={["9207d08332faf7b6:70"]="复活的银色先锋随机跳到一名玩家身后，造成物理伤害。"}}
D.ClientTexts.JournalSection[7592]={Name={["603e35159218b4fc:12"]="食尸鬼爆炸"}}
D.ClientTexts.JournalSection[7593]={Name={["066233b4868e910b:16"]="阶段2：不死"},Description={["3e02f314a140ba55:147"]="当黑骑士死亡时，他会复活成骷髅并继续战斗。他会继承生前的暗影打击、冰冷触摸和湮灭技能并获得新技能。"}}
D.ClientTexts.JournalSection[7594]={Name={["afd26196899b16e9:19"]="阶段3：来世"},Description={["aeefc38878cea19b:131"]="当黑骑士的骷髅被摧毁后，他会变成鬼魂并背水一战。作为鬼魂，他将失去先前形态下的所有技能。"}}
D.ClientTexts.JournalSection[7595]={Name={["e2490c10182a4301:10"]="湮灭"},Description={["4544aa433a560138:180"]="黑骑士凶残地攻击一名玩家，玩家感染的疾病数量越多，造成的物理伤害越高。湮灭击中目标后，将移除其身上所有的疾病效果。"}}
D.ClientTexts.JournalSection[7596]={Name={["fb79e016ed9dfb93:11"]="亵渎"}}
D.ClientTexts.JournalSection[7597]={Name={["7d5d5ec290a5aae1:13"]="亡者大军"},Description={["4479f2fd7b558d6a:57"]="黑骑士召唤一整支食尸鬼大军为其作战。"}}
D.ClientTexts.JournalSection[7598]={Name={["603e35159218b4fc:12"]="食尸鬼爆炸"}}
D.ClientTexts.JournalSection[7599]={Name={["75c18aa9d4d73698:11"]="死亡撕咬"}}
D.ClientTexts.JournalSection[7600]={Name={["9099bca62ebb1717:14"]="死亡标记"}}
D.ClientTexts.JournalSection[7601]={Name={["fb3a039c15b70755:10"]="暗影箭"},Description={["2530c97ce090197b:68"]="凯雷塞斯王子朝一名玩家射出一道黑魔法箭，对其造成暗影伤害。"}}
D.ClientTexts.JournalSection[7602]={Name={["063892459ff76bd4:9"]="冰霜之墓"}}
D.ClientTexts.JournalSection[7603]={Name={["d40c6d17cbf3d272:14"]="维库骷髅"},Description={["605ae10131820928:73"]="在交战时，凯雷塞斯王子会召唤几个维库骷髅与他并肩作战。"}}
D.ClientTexts.JournalSection[7604]={Name={["7ec623c0d9be2721:9"]="衰老"}}
D.ClientTexts.JournalSection[7605]={Name={["6af1eab2e8e6f0af:11"]="势不可挡"},Description={["69bec1a22062a331:109"]="只要凯雷塞斯王子还活着，维库骷髅就无法被阻挡，并在被杀死20秒后再度复活。"}}
D.ClientTexts.JournalSection[7606]={Name={["8e205d29cff709ea:17"]="成熟的季鹍凤凰蛋"},Description={["cd5b3e76dbe313c7:90"]="成熟的季鹍凤凰蛋需要更长的孵化时间，但在孵化完成后，将诞生一只幼年凤凰。"}}
D.ClientTexts.JournalSection[7607]={Name={["97f5b7279db7116e:8"]="幼年凤凰"},Description={["99386ff1416e2e14:131"]="幼年凤凰迅速飞上天空并在季鹍的主平台上空盘旋。幼年凤凰只要还活着，就会周期性对随机目标施放尖啸。"}}
D.ClientTexts.JournalSection[8664]={Name={["3cf1e1934c280a04:15"]="阿格姆"}}
D.ClientTexts.JournalSection[7608]={Name={["0f393c8a5d4ec22b:5"]="嘶鸣"}}
D.ClientTexts.JournalSection[7609]={Name={["fe149a04b00c66b5:22"]="建筑师斯卡瓦尔德"}}
D.ClientTexts.JournalSection[7610]={Name={["f65ed2cf04cf4d54:6"]="冲锋"}}
D.ClientTexts.JournalSection[7611]={Name={["2286122033db5857:11"]="石头打击"},Description={["32a73a7a4f38aaf5:81"]="建筑师斯卡瓦尔德打击一名玩家，对其造成物理伤害并将其击退。"}}
D.ClientTexts.JournalSection[7612]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[7613]={Name={["b672f9f8c6fd1f21:18"]="斯卡瓦尔德之魂"},Description={["ae3502296ec99974:97"]="当建筑师斯卡瓦尔德倒下后，他会变成无法被选作攻击目标的鬼魂继续战斗，直到达尔隆被击败。"}}
D.ClientTexts.JournalSection[7614]={Name={["28ca625807766ae1:20"]="控制者达尔隆"}}
D.ClientTexts.JournalSection[7615]={Name={["fb3a039c15b70755:10"]="暗影箭"},Description={["420d3d1af067c09d:80"]="控制者达尔隆随机朝一名玩家射出一道黑魔法箭，对其造成暗影伤害。"}}
D.ClientTexts.JournalSection[7616]={Name={["c658079c4f684663:10"]="衰弱"}}
D.ClientTexts.JournalSection[7617]={Name={["aedf9f7ce78aaba5:15"]="召唤骷髅"},Description={["abf99b04a30ee4a5:46"]="控制者达尔隆召唤两名骷髅爪牙。"}}
D.ClientTexts.JournalSection[7618]={Name={["0f39e2eec02147b7:17"]="达尔隆之魂"},Description={["a459a2a77438cec4:96"]="当控制者达尔隆倒下后，他会变成无法被选作攻击目标的鬼魂继续战斗，直到斯卡瓦尔德被击败。"}}
D.ClientTexts.JournalSection[7619]={Name={["a16f742d6bcec8ec:19"]="阶段1：忠实的仆从"}}
D.ClientTexts.JournalSection[7620]={Name={["105d734182cc8b5c:5"]="冲撞"}}
D.ClientTexts.JournalSection[7621]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"},Description={["db3a1e3b7069acdc:83"]="掠夺者因格瓦尔劈砍一名玩家，对目标及与其距离最近的盟友造成物理伤害。"}}
D.ClientTexts.JournalSection[7622]={Name={["3b3fe4e43ef62383:14"]="惊愕怒吼"}}
D.ClientTexts.JournalSection[7623]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[7624]={Name={["c306e7b33e90e158:24"]="阶段2：失败的代价"},Description={["d66cf523243c9612:109"]="当掠夺者因格瓦尔死亡时，他会被巫妖王的仆人召唤者安海尔德复活成亡灵奴隶。"}}
D.ClientTexts.JournalSection[7625]={Name={["410fd4a36639f7e6:9"]="黑暗打击"}}
D.ClientTexts.JournalSection[7626]={Name={["5cf23b0927bf238e:9"]="暗影利斧"}}
D.ClientTexts.JournalSection[7627]={Name={["a487b5e083e439d1:12"]="恐怖咆哮"}}
D.ClientTexts.JournalSection[7628]={Name={["fbef02a2fdc6a49f:9"]="悲哀攻击"},Description={["ee09c79be6fdeb2a:169"]="掠夺者因格瓦尔使用悲哀攻击对一名玩家造成物理伤害，并使其遭受痛苦。受悲哀攻击影响的目标在受到任何治疗时，都会对治疗者造成暗影伤害。"}}
D.ClientTexts.JournalSection[7629]={Name={["88d2f3946a74d93b:25"]="寂妃露琳"}}
D.ClientTexts.JournalSection[7630]={Name={["649cf3f50811e62e:9"]="月光莲"}}
D.ClientTexts.JournalSection[7631]={Name={["804520979049eca0:13"]="星辰弹幕"}}
D.ClientTexts.JournalSection[7632]={Name={["bfe35788bfcb25df:20"]="仇妃夙娥"}}
D.ClientTexts.JournalSection[7633]={Name={["e7dad57d91972430:33"]="暮色降临：双后共舞"},Description={["10ca7ebd368c929a:102"]="在黄昏期间，双后都可行动，但两者都将弃用部分技能并获得以下新技能。"}}
D.ClientTexts.JournalSection[7634]={Name={["3d48583bb59e666a:17"]="梦魇兽"},Description={["b1389d5bff3aa0b2:285"]="露琳从目标的梦魇中招出一头野兽，命令其发起攻击！只有被这头野兽锁定的目标才能攻击到它。治疗这个目标将造成堕落治疗效果。\r\n\r\n该效果只能在黑暗中生效。在黄昏或白天时，目标仍可以攻击梦魇兽，但露琳不会再召唤新的梦魇兽。"}}
D.ClientTexts.JournalSection[7635]={Name={["00fa1fd56934582e:16"]="堕落治疗"}}
D.ClientTexts.JournalSection[7636]={Name={["7b81df7f2943c3b0:17"]="暗夜潜伏者"}}
D.ClientTexts.JournalSection[7637]={Name={["b5daa2a72625d80a:11"]="烈焰刃舞"}}
D.ClientTexts.JournalSection[7638]={Name={["3bf7f74feee1b9a0:15"]="燃情烈焰"}}
D.ClientTexts.JournalSection[7641]={Name={["245ccd4ecade770f:32"]="夜幕降临：露琳之辉"},Description={["3bd9e7997d9268a8:103"]="当魔古双后的房间进入黑夜时，露琳将得到强化并可自由行动，而夙娥的行动将受到更大的限制。"}}
D.ClientTexts.JournalSection[7642]={Name={["bfe35788bfcb25df:20"]="仇妃夙娥"}}
D.ClientTexts.JournalSection[7643]={Name={["8f34c770c8d6f3e3:13"]="太阳之泪"}}
D.ClientTexts.JournalSection[7644]={Name={["1bfb75703ea7de0f:10"]="炽热日光"}}
D.ClientTexts.JournalSection[7645]={Name={["ce6a2b5798b7176e:26"]="白日烈焰：夙娥之怒"},Description={["001770d4cc0e205b:104"]="当魔古双后的房间进入白天时，夙娥将得到强化并可自由行动，而露琳的行动将受到更大的限制。"}}
D.ClientTexts.JournalSection[7646]={Name={["1f3d9a8351965c42:15"]="炽热光辉"}}
D.ClientTexts.JournalSection[7647]={Name={["1bfb75703ea7de0f:10"]="炽热日光"}}
D.ClientTexts.JournalSection[7648]={Name={["88d2f3946a74d93b:25"]="寂妃露琳"}}
D.ClientTexts.JournalSection[7649]={Name={["1a50558e1b4d7485:8"]="霜寒彗星"}}
D.ClientTexts.JournalSection[7650]={Name={["23568a63ca912fb4:10"]="寒冷阴影"}}
D.ClientTexts.JournalSection[7651]={Name={["8cdd31e997ec94e4:12"]="天神之助"}}
D.ClientTexts.JournalSection[7652]={Name={["84f402009bde75c9:14"]="浩劫炼狱"}}
D.ClientTexts.JournalSection[7653]={Name={["88d2f3946a74d93b:25"]="寂妃露琳"},Description={["d3dc41cbadc28e5e:118"]="露琳死后，黄昏结束并重新进入白天，使夙娥得到强化。在白天，夙娥将再次熊熊燃烧并使用炽热光辉。"}}
D.ClientTexts.JournalSection[7654]={Name={["496be02299ee2471:10"]="潮汐之力"}}
D.ClientTexts.JournalSection[7655]={Name={["bfe35788bfcb25df:20"]="仇妃夙娥"},Description={["cd8ffdb64459b9b5:138"]="夙娥死后，黄昏结束并重新进入黑夜，使露琳得到强化。在夜间，月光莲将会再次绽放，梦魇兽也会重新出现。"}}
D.ClientTexts.JournalSection[7656]={Name={["84f402009bde75c9:14"]="浩劫炼狱"}}
D.ClientTexts.JournalSection[7657]={Name={["853ee0c8ec13fbcf:23"]="砮皂：玄牛之韧"}}
D.ClientTexts.JournalSection[7658]={Name={["5d6bc347c310b9c8:20"]="赤精：鹤群冲击"}}
D.ClientTexts.JournalSection[7871]={Name={["e8d0ef4ebde773b7:8"]="风蚀"}}
D.ClientTexts.JournalSection[7659]={Name={["07b87a0fd9856eb2:27"]="玉珑：青龙之精"}}
D.ClientTexts.JournalSection[7660]={Name={["1f125628b9d8eab1:14"]="影袭"},Description={["54a9bb4d2d56c098:56"]="席瓦拉·索格蕾攻击一名玩家，对其造成物理伤害。"}}
D.ClientTexts.JournalSection[7661]={Name={["0409d5390b6f56de:10"]="召唤烈焰"},Description={["59264c3eaf082109:87"]="席瓦拉·索格蕾从附近的火盆中召唤出烈焰，随机对一名玩家造成火焰伤害。"}}
D.ClientTexts.JournalSection[7662]={Name={["8642f95bd21c18e6:16"]="利剑仪祭"},Description={["c29438e328a4dca2:177"]="席瓦拉·索格蕾随机将一名玩家召唤到她的祭坛上并将其献祭。在被献祭期间，三名仪祭引导者将对玩家施放麻痹，使其昏迷，直至引导者被杀。"}}
D.ClientTexts.JournalSection[7664]={Name={["30657e36c28d8185:23"]="雪怒：白虎之敏"},Description={["b4ab4a6caabf9fef:356"]="玩家可以选择雪怒的虚影来引动他的精魂。为此，玩家必须踏遍雪怒所对应的星座。\r\n\r\n完成后，雪怒将会出现，并赐予玩家白虎之敏。受到祝福的玩家的行动速度将变得十分迅捷，以至于所有敌人的移动、施法以及射击速度都像慢动作一样，使得玩家将可以躲开原本无法躲避的技能。"}}
D.ClientTexts.JournalSection[7665]={Name={["fcea0f488e0b9d35:12"]="仪祭打击"}}
D.ClientTexts.JournalSection[7666]={Name={["697204669b0ff5ed:15"]="仪祭引导者"}}
D.ClientTexts.JournalSection[7667]={Name={["14561dedf744f2d8:8"]="麻痹"},Description={["44c5bc961ab4e473:104"]="仪祭引导者锁定席瓦拉献祭的玩家，只要仪祭引导者还活着，目标就将持续昏迷。"}}
D.ClientTexts.JournalSection[7668]={Name={["322e9d78a172116f:16"]="黑暗之影"}}
D.ClientTexts.JournalSection[7669]={Name={["7ae06003728ee0f6:15"]="能量生成器"}}
D.ClientTexts.JournalSection[7670]={Name={["afc9ce90113348d3:25"]="第一阶段：狩猎战利品"}}
D.ClientTexts.JournalSection[7671]={Name={["a2a26594b3ca52c9:14"]="狂野的犀牛"}}
D.ClientTexts.JournalSection[7672]={Name={["b7a3e96eba20a479:14"]="狂乱的狼人"}}
D.ClientTexts.JournalSection[7673]={Name={["3307333206c1dcdb:16"]="巨型冰虫"}}
D.ClientTexts.JournalSection[7674]={Name={["d9df8a69416a2ace:15"]="贪婪的熊怪"}}
D.ClientTexts.JournalSection[7675]={Name={["df3130c913e799d4:21"]="第二阶段：戈托克·苍蹄"}}
D.ClientTexts.JournalSection[7676]={Name={["d8f801c6006a2575:13"]="重伤"}}
D.ClientTexts.JournalSection[7677]={Name={["7c9771d2ef58d23b:4"]="刺伤"}}
D.ClientTexts.JournalSection[7678]={Name={["106184b8cf5b1831:5"]="践踏"}}
D.ClientTexts.JournalSection[7679]={Name={["911d15a1f3862364:11"]="致命伤"}}
D.ClientTexts.JournalSection[7680]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[7681]={Name={["c1aaa8565af73d05:8"]="酸液喷吐"}}
D.ClientTexts.JournalSection[7682]={Name={["037d6df3cc3dc2c8:12"]="毒息"}}
D.ClientTexts.JournalSection[7683]={Name={["72bc228530cce4fc:12"]="酸性溅泼"},Description={["5d5a66a9afa4ae92:58"]="巨型冰虫召唤冰虫攻击玩家。"}}
D.ClientTexts.JournalSection[7684]={Name={["44114a3fc6ca0d72:13"]="冰虫"},Description={["c76238140af34259:40"]="冰虫保护着巨型冰虫。"}}
D.ClientTexts.JournalSection[7685]={Name={["f713e99eaff97ee7:6"]="疯乱"}}
D.ClientTexts.JournalSection[7686]={Name={["bd71f29ca82545a5:14"]="恐惧咆哮"}}
D.ClientTexts.JournalSection[7687]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[7932]={Name={["0677cb60aa0f9f49:8"]="背刺"}}
D.ClientTexts.JournalSection[7688]={Name={["3d7329ea84f46cfd:13"]="枯萎咆哮"}}
D.ClientTexts.JournalSection[7689]={Name={["3f8700b5d2d8e6cc:11"]="圆弧斩"},Description={["f5fa1d7dc48b621e:86"]="戈托克·苍蹄进行险恶的弧形劈砍，对其面前所有的玩家造成物理伤害。"}}
D.ClientTexts.JournalSection[7690]={Name={["04c0331d8f03a4ae:6"]="穿刺"}}
D.ClientTexts.JournalSection[7691]={Name={["aabc2ad918781160:12"]="第一阶段：格拉乌弗"},Description={["c5e6417f2a0fbfcc:222"]="残忍的斯卡迪骑上他的幼龙——格拉乌弗开始战斗。在乘骑状态下，斯卡迪会飞至玩家头顶上方并命令格拉乌弗朝下方玩家喷吐冰冻云团。\r\n\r\n玩家必须使用鱼叉发射器击中格拉乌弗三次才能使斯卡迪降落至地面。"}}
D.ClientTexts.JournalSection[7692]={Name={["844bb156514151e1:13"]="冰冻之云"}}
D.ClientTexts.JournalSection[7693]={Name={["b50bc60e8f9a4537:15"]="鱼叉发射器"},Description={["ce520842e6800bfd:171"]="持有鱼叉的玩家可以使用鱼叉发射器瞄准附近的格拉乌弗并在其进入发射器射程时对其造成物理伤害。\r\n\r\n击杀伊米亚标枪手可获得鱼叉。"}}
D.ClientTexts.JournalSection[7694]={Name={["73dfbdf11e116a46:16"]="伊米亚标枪手"}}
D.ClientTexts.JournalSection[7695]={Name={["106d15b9e671dd46:5"]="投掷"},Description={["522a6e7e80a2a1fb:68"]="伊米亚标枪手将自己手中的武器掷向玩家，造成物理伤害。"}}
D.ClientTexts.JournalSection[7696]={Name={["0b88944c368fc2bd:3"]="结网"}}
D.ClientTexts.JournalSection[7697]={Name={["df52a61125d12068:11"]="掉落鱼叉"},Description={["f3255fab30aacdc4:101"]="当伊米亚标枪手死亡时，他们会掉落一柄鱼叉，玩家可以捡起它并配合鱼叉发射器使用。"}}
D.ClientTexts.JournalSection[7698]={Name={["080fd8896da2bb84:14"]="伊米亚战士"}}
D.ClientTexts.JournalSection[7699]={Name={["a4dca5b265a73ee5:9"]="断筋"}}
D.ClientTexts.JournalSection[7700]={Name={["1c93af97a9332772:6"]="打击"},Description={["65a92d99a480d78a:54"]="伊米亚战士打击一名玩家，对其造成物理伤害。"}}
D.ClientTexts.JournalSection[7701]={Name={["90bbe76d7fa17e28:18"]="伊米亚巫医"}}
D.ClientTexts.JournalSection[7702]={Name={["fb3a039c15b70755:10"]="暗影箭"},Description={["e088f36e4dd707f3:72"]="伊米亚巫医朝一名玩家射出一道黑魔法箭，对其造成暗影伤害。"}}
D.ClientTexts.JournalSection[7703]={Name={["1bba89f47a21b429:6"]="缩小"}}
D.ClientTexts.JournalSection[7704]={Name={["4144000c3424d619:23"]="第二阶段：残忍的斯卡迪"}}
D.ClientTexts.JournalSection[7705]={Name={["b727f51d940c3d9a:9"]="旋风斩"}}
D.ClientTexts.JournalSection[7706]={Name={["0f3efe2a3681e51b:5"]="重压"}}
D.ClientTexts.JournalSection[7707]={Name={["3a76fa41bb77ecb2:13"]="淬毒长矛"}}
D.ClientTexts.JournalSection[7708]={Name={["5e3fde5364c05d0e:20"]="陨落诸王之赐"}}
D.ClientTexts.JournalSection[7709]={Name={["b65a33d79710397a:16"]="亡者嚎叫"}}
D.ClientTexts.JournalSection[7711]={Name={["3d72aa3040710f4f:11"]="灵魂爆裂"},Description={["52bc5f635fcb723a:116"]="恐怖深渊之王拉努夫赋予伊米隆国王一项技能，使其能释放一股爆裂的灵魂能量，对所有玩家造成暗影伤害。"}}
D.ClientTexts.JournalSection[7713]={Name={["883dbf6b02f58520:17"]="召唤灵魂之泉"},Description={["8b615450a5a37d2f:117"]="黑色风暴之王布约恩赋予伊米隆国王一项技能，使其可以召唤一道灵魂之泉，每秒随机对一名玩家造成一次暗影伤害。"}}
D.ClientTexts.JournalSection[7715]={Name={["135d5f121b323dc3:12"]="灵魂打击"}}
D.ClientTexts.JournalSection[7717]={Name={["429dd92168a50548:21"]="召唤复仇之魂"},Description={["1344d18872c1eec3:85"]="野蛮杀戮之王托尔赋予伊米隆国王一项技能，使其可以召唤4个复仇之魂攻击玩家。"}}
D.ClientTexts.JournalSection[7718]={Name={["7c9477dbffcde476:4"]="灾祸"}}
D.ClientTexts.JournalSection[7719]={Name={["410f484237b32727:9"]="黑暗鞭笞"},Description={["1e2de04d99dd583e:73"]="伊米隆国王鞭笞一名玩家，造成相当于其当前生命值一半的伤害。"}}
D.ClientTexts.JournalSection[7720]={Name={["12e35346c54780c7:8"]="恶臭溃烂"}}
D.ClientTexts.JournalSection[7722]={Name={["25225858734627f3:6"]="枯萎"}}
D.ClientTexts.JournalSection[7723]={Name={["6834f9ea392eb08b:9"]="盛气凌人"}}
D.ClientTexts.JournalSection[7724]={Name={["095ed214a1cb008f:8"]="充能"}}
D.ClientTexts.JournalSection[7725]={Name={["439a018a22e62d8d:25"]="临时电荷"}}
D.ClientTexts.JournalSection[7727]={Name={["b87ac349fe81f932:16"]="饱受折磨"},Description={["0b723c4379c89b5e:71"]="阿尔萨斯猛击身后的所有玩家，每秒造成暗影伤害。"}}
D.ClientTexts.JournalSection[7728]={Name={["6c1f8ff43ce92803:18"]="敏捷的爬虫"},Description={["7ce33b65ff45ecbe:105"]="看门者克里克希尔会周期性地召唤出一波敏捷的爬虫和轻快的感染者来攻击玩家。"}}
D.ClientTexts.JournalSection[7731]={Name={["759b8d702d3a38a5:17"]="达卡莱裂肠者"}}
D.ClientTexts.JournalSection[7732]={Name={["00a91f6044852413:6"]="重击"}}
D.ClientTexts.JournalSection[7733]={Name={["5ce67dc5531d5e0c:18"]="达卡莱镰爪龙"}}
D.ClientTexts.JournalSection[7734]={Name={["7c9d4eeeea332e69:4"]="撕裂"}}
D.ClientTexts.JournalSection[7735]={Name={["300fff8fb236dd44:8"]="流体"}}
D.ClientTexts.JournalSection[7737]={Name={["20c3bfdb5090db84:17"]="浸电之水"}}
D.ClientTexts.JournalSection[7738]={Name={["5a955dbd3a2f1692:11"]="静电爆炸"}}
D.ClientTexts.JournalSection[7739]={Name={["5c0e221ab6df2a65:11"]="静电创伤"}}
D.ClientTexts.JournalSection[7740]={Name={["f5eea75b870148a4:10"]="导电"},Description={["09f2b5e8c5724787:120"]="击碎者金罗克的许多技能都可通过导电之水对站在水中的所有玩家造成自然伤害。"}}
D.ClientTexts.JournalSection[7741]={Name={["c5761dd2f3036a53:16"]="专注闪电"}}
D.ClientTexts.JournalSection[7743]={Name={["db6168ea3127bc3b:16"]="闪电裂隙"}}
D.ClientTexts.JournalSection[7744]={Name={["02afbd1f9fc96aa4:9"]="内爆"}}
D.ClientTexts.JournalSection[7747]={Name={["79a00a5101f9b1a8:15"]="雷霆投掷"}}
D.ClientTexts.JournalSection[7748]={Name={["4e7bfe9eda5d90bf:14"]="闪电风暴"}}
D.ClientTexts.JournalSection[7749]={Name={["1dfd515bd4e9859c:15"]="闪电打击"}}
D.ClientTexts.JournalSection[7750]={Name={["b020b02b9b98cf84:13"]="纠缠凝视"}}
D.ClientTexts.JournalSection[7751]={Name={["b020b02b9b98cf84:13"]="纠缠凝视"}}
D.ClientTexts.JournalSection[7753]={Name={["f5eea75b870148a4:10"]="导电"}}
D.ClientTexts.JournalSection[7754]={Name={["f5eea75b870148a4:10"]="导电"}}
D.ClientTexts.JournalSection[7755]={Name={["21d1ad1018db2639:8"]="时间之步"},Description={["7d37984ddc7dba04:88"]="时光领主埃博克穿梭时空，随机冲撞一名玩家并对其造成物理伤害。"}}
D.ClientTexts.JournalSection[7756]={Name={["c42384fe4e04388d:11"]="虚空位移"}}
D.ClientTexts.JournalSection[7757]={Name={["87ee4b0722d65884:16"]="反射护盾"}}
D.ClientTexts.JournalSection[7758]={Name={["627e917f166beb5c:10"]="心能魔像"}}
D.ClientTexts.JournalSection[7759]={Name={["c33e582a623415d7:15"]="大型心能魔像"}}
D.ClientTexts.JournalSection[7760]={Name={["7da04ad79e7083c0:17"]="巨型心能魔像"}}
D.ClientTexts.JournalSection[7761]={Name={["f47580cd8e790f94:10"]="物质交换"},Description={["71949dc3a716b5c2:234"]="不断抽离敌方目标的体内物质。当该效果结束时，目标会与其距离最远的盟友交换位置，并造成等同于目标最大生命值的奥术伤害，由交换位置的双方均摊。由目标盟友所承受的伤害部分每秒都会持续增加。"}}
D.ClientTexts.JournalSection[7762]={Name={["3923f1d44646b6c5:10"]="黑暗意志"}}
D.ClientTexts.JournalSection[7763]={Name={["9a96d809c4e5a6dc:10"]="电离反应"}}
D.ClientTexts.JournalSection[7764]={Name={["f5eea75b870148a4:10"]="导电"}}
D.ClientTexts.JournalSection[7765]={Name={["9c653a3d3689011a:16"]="急速链接"}}
D.ClientTexts.JournalSection[7766]={Name={["badc385b9dfc8c5e:17"]="剧烈爆炸"}}
D.ClientTexts.JournalSection[7767]={Name={["31872ac2d43a991f:9"]="心能之泉"}}
D.ClientTexts.JournalSection[7768]={Name={["4969d9c87cc3b9c3:11"]="猩红追击"}}
D.ClientTexts.JournalSection[7769]={Name={["fa7add98db1e29ef:12"]="强化魔像"}}
D.ClientTexts.JournalSection[7770]={Name={["0d6239914ba1db0a:13"]="爆炸猛击"}}
D.ClientTexts.JournalSection[7771]={Name={["b962d7a961f3696c:16"]="震荡干涉"}}
D.ClientTexts.JournalSection[7772]={Name={["d5c5dafcbffbae63:11"]="心能虹吸"}}
D.ClientTexts.JournalSection[7773]={Name={["d3703f657709f736:9"]="全力之击"}}
D.ClientTexts.JournalSection[7774]={Name={["6611757cb3ea9b75:14"]="心能驱动"},Description={["1edeefbe274b0e2b:324"]="心能魔像需要心能驱动才能活动或使用技能。心能容量受魔像体型的限制，体型越大的魔像可容纳的心能就越多。黑暗意志的心能容量最高，但它的大部分技能只有在心能容量达到一定水平时才能使用。\r\n\r\n击败任意体型的心能魔像都会导致其体内的心能随机流向其他拥有足够容量的魔像。"}}
D.ClientTexts.JournalSection[7775]={Name={["06c97db85149bf89:17"]="严重损毁"},Description={["7eb20e409facc151:131"]="在10人难度中，某些心能魔像已经遭到严重损毁。这些魔像仍然能够吸收心能，但无法活动或使用技能。"}}
D.ClientTexts.JournalSection[7776]={Name={["365ca44b61eb170a:16"]="意志之触"}}
D.ClientTexts.JournalSection[7777]={Name={["6d05a5cf21758904:30"]="呼风唤雨：魁兹扎尔"},Description={["c2338a318535c4de:104"]="在英雄难度中，魁兹扎尔将与罗沙克一起攻击玩家。他将从上方召唤闪电风暴随机攻击玩家。"}}
D.ClientTexts.JournalSection[7778]={Name={["acde7b3251fc6947:22"]="破冰之战：玳刃"},Description={["7d702701817d711c:101"]="在英雄难度中，玳刃将与魁兹扎尔一起攻击玩家。他将从上方随机冻结玩家并将其打碎。"}}
D.ClientTexts.JournalSection[7779]={Name={["694fec5e695ddd0d:29"]="熔火星耀：罗沙克"},Description={["05510e814a510820:176"]="在英雄难度中，罗沙克将与玳刃一起攻击玩家。他会对所能找到的最大一群玩家施放脱缰烈焰。如果他找不到任何玩家群，则将随机对一名目标施放此技能。"}}
D.ClientTexts.JournalSection[7780]={Name={["ccaff14e35ee18db:13"]="旋风"}}
D.ClientTexts.JournalSection[7781]={Name={["cd393f4fb262bf82:10"]="冰刺"}}
D.ClientTexts.JournalSection[7783]={Name={["0f393c8a5d4ec22b:5"]="嘶鸣"}}
D.ClientTexts.JournalSection[7804]={Name={["4367943492f834c7:11"]="急速冰寒"}}
D.ClientTexts.JournalSection[7805]={Name={["4367943492f834c7:11"]="急速冰寒"}}
D.ClientTexts.JournalSection[7806]={Name={["82072350f8748dd7:18"]="激活序列"}}
D.ClientTexts.JournalSection[7807]={Name={["356694023cb9ceed:7"]="狂暴"}}
D.ClientTexts.JournalSection[7808]={Name={["7158e9b094a2709b:13"]="墨格瑞拉之怒"}}
D.ClientTexts.JournalSection[7809]={Name={["d906589b610f3b56:11"]="九头蛇狂乱"}}
D.ClientTexts.JournalSection[7810]={Name={["2eb73cb7a7dd557a:10"]="虚空撕裂"}}
D.ClientTexts.JournalSection[7811]={Name={["9b805628123d9995:13"]="红光"}}
D.ClientTexts.JournalSection[7812]={Name={["f73f90fd6e7f9c5c:11"]="强光"}}
D.ClientTexts.JournalSection[7813]={Name={["7ec7d5ec9db289e3:8"]="蓝光"}}
D.ClientTexts.JournalSection[7814]={Name={["6b0b183fe9dfffd6:13"]="命令头盔"}}
D.ClientTexts.JournalSection[7815]={Name={["6b0b183fe9dfffd6:13"]="命令头盔"}}
D.ClientTexts.JournalSection[7816]={Name={["2eb9391a3d5c01f5:10"]="虚空浮龙"}}
D.ClientTexts.JournalSection[7817]={Name={["0592e4c764ba1cee:11"]="虚空之刺"}}
D.ClientTexts.JournalSection[7818]={Name={["3b8c0f7092ce79f3:11"]="压制"}}
D.ClientTexts.JournalSection[7819]={Name={["9b805628123d9995:13"]="红光"}}
D.ClientTexts.JournalSection[7820]={Name={["f73f90fd6e7f9c5c:11"]="强光"}}
D.ClientTexts.JournalSection[7821]={Name={["7ec7d5ec9db289e3:8"]="蓝光"}}
D.ClientTexts.JournalSection[7822]={Name={["4aee437ccb1d8043:15"]="导电之水"},Description={["3b9255dc67a2b769:228"]="当金罗克用雷霆投掷破坏一座雕像后，里面将涌出水流，在雕像脚下形成一个越来越大的水塘。这些水塘对战斗至关重要。站在水塘中的玩家将获得流体的增益效果，但导电将对其造成更高的自然伤害。"}}
D.ClientTexts.JournalSection[7826]={Name={["4fd9559fd146e6ea:9"]="踢龟壳"},Description={["c5ac5eb8cb2f9d75:191"]="这个额外的动作按钮可让你将一只被击败的旋龟踢过房间。靠近龟壳，然后让龟壳位于你和你的目标之间以进行瞄准。被龟壳击中的敌人将受到龟壳震荡效果的影响。"}}
D.ClientTexts.JournalSection[7933]={Name={["2f64b8ef51c7873e:14"]="刺客印记"},Description={["911a8fbc9923602f:45"]="库卡隆刺客会锁定一名非坦克目标。"}}
D.ClientTexts.JournalSection[7827]={Name={["a976217dca9dc30a:13"]="巢穴守卫"},Description={["65e126d85df1bfad:118"]="在英雄难度的季鹍之战中，某些季鹍的巢穴内将出现巢穴守卫。巢穴守卫将攻击任何试图干扰巢穴的玩家。"}}
D.ClientTexts.JournalSection[7828]={Name={["9eb2a695224a9570:11"]="利爪打击"},Description={["4989940c4caea8ab:92"]="巢穴守卫用双爪打击敌人，对180度范围内的所有敌人造成物理伤害。"}}
D.ClientTexts.JournalSection[7829]={Name={["52f72faa89177b93:18"]="变异畸体"}}
D.ClientTexts.JournalSection[7830]={Name={["30ed0a6503e9c594:12"]="完全变异"},Description={["3b1ef9b720b09924:147"]="当一名玩家获得5个有益变异时，将进入完全变异状态，并可对普利莫修斯造成全额伤害。在此之后获得的额外变异都将为有害变异。"}}
D.ClientTexts.JournalSection[7831]={Name={["3765f2ffc8ffb798:12"]="突变之池"},Description={["52a8002c22594d67:90"]="当活化液体死亡时，有极低几率留下一个突变之池，可使普利莫修斯或玩家发生变异。"}}
D.ClientTexts.JournalSection[7832]={Name={["fb522354fe8d7917:26"]="变异普利莫修斯（突变）"}}
D.ClientTexts.JournalSection[7833]={Name={["8f9ef6b3509c776c:22"]="变异玩家（突变）"}}
D.ClientTexts.JournalSection[7834]={Name={["ef91ff1351e78d7a:8"]="饲料池"}}
D.ClientTexts.JournalSection[7835]={Name={["2866afb5d38840f8:14"]="伊卡罗斯的教训"}}
D.ClientTexts.JournalSection[7837]={Name={["6611757cb3ea9b75:14"]="心能驱动"},Description={["9a604d4ff056aa7e:327"]="心能魔像需要心能驱动才能活动或使用技能。心能容量受魔像体型的限制，体型越大的魔像可容纳的心能就越多。黑暗意志的心能容量最高，但它的大部分技能只有在心能容量达到一定水平时才能使用。\r\n\r\n击败任意体型的心能魔像都会导致其体内的心能流向周围距离最近并拥有足够容量的魔像。"}}
D.ClientTexts.JournalSection[7840]={Name={["875fa4e295049fc7:7"]="尖啸"}}
D.ClientTexts.JournalSection[7841]={Name={["4fb675880c0e6525:11"]="渐燃之怒"}}
D.ClientTexts.JournalSection[7856]={Name={["48ff477867eaedc9:14"]="感染之爪"}}
D.ClientTexts.JournalSection[7857]={Name={["07b67730825daf11:15"]="原始营养"}}
D.ClientTexts.JournalSection[7858]={Name={["aeee658a21bab2b7:11"]="刺心之匕"}}
D.ClientTexts.JournalSection[7859]={Name={["74edfa01d7f61154:11"]="意志之力"},Description={["1ba1c1eaa389d6cf:119"]="心灵之眼望向一名随机玩家，在意志之力施法完毕之后击退所有仍然留在凝视范围内的玩家。"}}
D.ClientTexts.JournalSection[7860]={Name={["7cd676788eaf2a75:7"]="闪避"}}
D.ClientTexts.JournalSection[7861]={Name={["ec59ea9ceb2a7ad1:16"]="霜冻坚韧"}}
D.ClientTexts.JournalSection[7862]={Name={["ec59ea9ceb2a7ad1:16"]="霜冻坚韧"}}
D.ClientTexts.JournalSection[7863]={Name={["b962d7a961f3696c:16"]="震荡干涉"}}
D.ClientTexts.JournalSection[7864]={Name={["b962d7a961f3696c:16"]="震荡干涉"}}
D.ClientTexts.JournalSection[7865]={Name={["e2490c10182a4301:10"]="湮灭"}}
D.ClientTexts.JournalSection[7866]={Name={["ace8d5db215ee54c:14"]="恐角之魂"},Description={["c21b4ab32ff81a88:41"]="赫利东的恐怖咆哮唤醒了一头恐角之魂。"}}
D.ClientTexts.JournalSection[7867]={Name={["9718dfdbebc8cef2:8"]="脆弱链接"},Description={["aebd96184a07b351:91"]="恐角之魂与潘达利亚之间的链接十分脆弱。任何针对恐角之魂的攻击都会将其击退。"}}
D.ClientTexts.JournalSection[7868]={Name={["c06c46abb07c5b18:12"]="恐怖凝视"},Description={["6446400e80920acd:95"]="恐角之魂凝视一名玩家。只有被凝视的玩家才能看见恐角之魂并与之互动。"}}
D.ClientTexts.JournalSection[7872]={Name={["246ac4bf184b22da:13"]="上古毒瘴"}}
D.ClientTexts.JournalSection[7873]={Name={["518c7f6e8a538bdf:14"]="上古屏障"},Description={["a0b221b2ab3fe1cb:253"]="每当上古毒瘴吸收治疗量时，都将在玩家身上生成一个上古屏障，为其吸收相当于其所吸收治疗量的伤害值。上古屏障吸收的伤害值不会超过玩家最大生命值的100%。\r\n\r\n该效果可以吸收高空坠落伤害。"}}
D.ClientTexts.JournalSection[7874]={Name={["e54601f2cf582441:11"]="无尽怒气"},Description={["426164933ae134e4:125"]="当马尔考罗克未进入血之怒状态时，他将随时间推移获得怒气。\r\n\r\n当马尔考罗克的怒气达到100时，他将吸收上古毒瘴并进入血之怒状态。"}}
D.ClientTexts.JournalSection[7875]={Name={["a044515485b65847:9"]="血之怒"}}
D.ClientTexts.JournalSection[7882]={Name={["d31c9898c09bb093:15"]="散逸能量"}}
D.ClientTexts.JournalSection[7883]={Name={["3f8700b5d2d8e6cc:11"]="圆弧斩"}}
D.ClientTexts.JournalSection[7884]={Name={["17915a9f8d6450b0:11"]="震地猛击"}}
D.ClientTexts.JournalSection[7885]={Name={["76afc5d120dd7d3e:12"]="鲁克·石趾"}}
D.ClientTexts.JournalSection[7886]={Name={["0ac6715c13af0741:14"]="蚀骨回旋踢"}}
D.ClientTexts.JournalSection[7887]={Name={["f6316f8d9e36ec4e:13"]="蚀骨酒"}}
D.ClientTexts.JournalSection[7888]={Name={["0f3b5ed0157fca8d:5"]="对冲"}}
D.ClientTexts.JournalSection[7889]={Name={["477f8306cf8fef15:10"]="禾·软足"}}
D.ClientTexts.JournalSection[7892]={Name={["f746ab40cc354c17:14"]="毒物大师"}}
D.ClientTexts.JournalSection[7893]={Name={["0aebebb21f734843:13"]="致命剧毒"}}
D.ClientTexts.JournalSection[7894]={Name={["57214d7e86b427e9:13"]="速效药膏"}}
D.ClientTexts.JournalSection[7895]={Name={["92750c89909aa3d2:16"]="亚煞极之息"}}
D.ClientTexts.JournalSection[7896]={Name={["307344c18a339302:18"]="库卡隆之力"}}
D.ClientTexts.JournalSection[7897]={Name={["caf7bd32fd052895:15"]="聚爆能量"}}
D.ClientTexts.JournalSection[7898]={Name={["c8fafb630c121392:17"]="无情突袭"}}
D.ClientTexts.JournalSection[7899]={Name={["71f6273f876fb2f6:11"]="致命打击"}}
D.ClientTexts.JournalSection[7901]={Name={["e701c839c07ee826:7"]="锁喉"}}
D.ClientTexts.JournalSection[7902]={Name={["0f85b97cba92ebeb:5"]="凿击"}}
D.ClientTexts.JournalSection[7904]={Name={["c6d780d1ea2f5046:14"]="孙·柔心"}}
D.ClientTexts.JournalSection[7905]={Name={["91dd7c8c0c8da0ef:7"]="煞能灼烧"}}
D.ClientTexts.JournalSection[7906]={Name={["b5e9c237992186c6:15"]="暗言术：蛊"}}
D.ClientTexts.JournalSection[7907]={Name={["06ffa25950f47bf4:8"]="灾祸"}}
D.ClientTexts.JournalSection[7908]={Name={["1b000f68d955c8ef:13"]="碎甲重击"}}
D.ClientTexts.JournalSection[7909]={Name={["7c9d3d04e833eead:4"]="怒气"},Description={["e2d804cbf1a729dc:176"]="纳兹戈林将军的部分技能需要消耗怒气。纳兹戈林将军将在战斗中通过使用各种技能来获得怒气。\r\n\r\n纳兹戈林将军会优先使用怒气消耗最高的技能。"}}
D.ClientTexts.JournalSection[7910]={Name={["c15c2d4a22af40a7:15"]="英勇冲击"}}
D.ClientTexts.JournalSection[7911]={Name={["a61a57af31d88c86:10"]="余震"}}
D.ClientTexts.JournalSection[7912]={Name={["578bce684c04fecb:14"]="库卡隆军旗"}}
D.ClientTexts.JournalSection[7913]={Name={["81c09678e8331695:7"]="斩杀"}}
D.ClientTexts.JournalSection[7914]={Name={["b6a61fe651ae9f7d:7"]="战歌"}}
D.ClientTexts.JournalSection[7915]={Name={["add89e362d07fe23:7"]="姿态"},Description={["ec1472a3ca1c7e44:54"]="纳兹戈林将军会在战斗中使用多种姿态。"}}
D.ClientTexts.JournalSection[7916]={Name={["5a455c5fc682d3c8:12"]="战斗姿态"}}
D.ClientTexts.JournalSection[7917]={Name={["7cd7f6e80972b1f7:15"]="狂暴姿态"}}
D.ClientTexts.JournalSection[7918]={Name={["f0a1609cf79fd963:15"]="防御姿态"}}
D.ClientTexts.JournalSection[7919]={Name={["d2b2a0a4d84d80e3:11"]="碎骨重锤"}}
D.ClientTexts.JournalSection[7920]={Name={["61dfcab410544e47:14"]="库卡隆部队"},Description={["367057d2ad2dc4ef:119"]="纳兹戈林将军会在战斗中召唤他的部队前来支援。\r\n\r\n在生命值降至10%时，纳兹戈林将军会额外召唤一波部队。"}}
D.ClientTexts.JournalSection[7921]={Name={["879b97885cbbb8e7:17"]="奥格瑞玛死忠份子"},Description={["1537140d62cfcbe4:70"]="纳兹戈林将军会在开始阶段率领一队忠诚的奥格瑞玛蛮兵加入战斗。"}}
D.ClientTexts.JournalSection[7922]={Name={["cd62a2425c46ef11:17"]="库卡隆铁刃战士"},Description={["97b3f96a8880bb2f:46"]="库卡隆铁刃战士手握一把凶狠的双手大剑。"}}
D.ClientTexts.JournalSection[7923]={Name={["a2f349b25757a6e3:17"]="库卡隆织魔者"},Description={["312a82f137d37360:44"]="库卡隆织魔者掌握着奥术的力量。"}}
D.ClientTexts.JournalSection[7924]={Name={["f1d5c537f5730404:16"]="库卡隆刺客"},Description={["ae874034c7a6e397:64"]="库卡隆刺客能从阴影中打击敌人最薄弱的环节。"}}
D.ClientTexts.JournalSection[7925]={Name={["6ed0ec54a2863257:17"]="库卡隆战争萨满"},Description={["162fc4c43defb4db:47"]="库卡隆战争萨满擅长支援盟友。"}}
D.ClientTexts.JournalSection[7926]={Name={["57f20252667f61e1:9"]="钢铁风暴"}}
D.ClientTexts.JournalSection[7927]={Name={["46efdd13e26cf5a0:9"]="破釜沉舟"}}
D.ClientTexts.JournalSection[7928]={Name={["d8cb8407ac2557bc:11"]="奥术震击"}}
D.ClientTexts.JournalSection[7929]={Name={["c728b8359b9f3168:10"]="魔法打击"}}
D.ClientTexts.JournalSection[7930]={Name={["7a1b5bf3e6a79128:13"]="动荡闪现"},Description={["49a8e94eca7a4413:35"]="随机向一个方向传送1-2次。"}}
D.ClientTexts.JournalSection[7931]={Name={["ae1a077ae45e6fa3:7"]="潜行"}}
D.ClientTexts.JournalSection[7934]={Name={["57bc4352687ed813:11"]="大地之盾"}}
D.ClientTexts.JournalSection[7935]={Name={["ff6ca8aa886a51ed:18"]="强化治疗链"}}
D.ClientTexts.JournalSection[7936]={Name={["c514d60c04b687f1:16"]="治疗之潮图腾"}}
D.ClientTexts.JournalSection[7937]={Name={["2ec47fab6290b596:10"]="冷静期"}}
D.ClientTexts.JournalSection[7938]={Name={["3601502de915475a:7"]="毁灭者"}}
D.ClientTexts.JournalSection[7939]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["8dbea135cab488aa:315"]="玩家将同时与三位堕落的守护者——酒仙鲁克·石趾、潜行者禾·软足及牧师孙·柔心战斗。\r\n\r\n在生命值降至66%和33%时，每位守护者都会施放背水一战，召唤其阵亡盟友的灵魂对团队发动全新的强大攻势，直至那些灵魂都被击败。"}}
D.ClientTexts.JournalSection[7940]={Name={["3ac996a795465d1c:17"]="背水一战"},Description={["5c485487e93bac16:216"]="在生命值降至66%和33%时，禾·软足召唤其兄弟的邪恶形态成为苦痛的化身，该化身将锁定拥有苦痛印记的团队成员。\r\n\r\n一旦该灵魂被击败，禾·软足将返回并与玩家战斗。"}}
D.ClientTexts.JournalSection[7941]={Name={["af7e4014d7211d5f:13"]="苦痛印记"}}
D.ClientTexts.JournalSection[7942]={Name={["3ac996a795465d1c:17"]="背水一战"},Description={["acbf5f53432a2f0c:193"]="在生命值降至66%和33%时，孙·柔心召唤其守护者的邪恶形态成为颓丧的化身和绝望的化身。\r\n\r\n一旦这两个灵魂都被击败，孙·柔心将返回并与玩家战斗。"}}
D.ClientTexts.JournalSection[7943]={Name={["919e0a6a3d77ed47:16"]="情感具现"},Description={["71ee74d4fbaf4799:194"]="颓丧的化身和绝望的化身专注于其本身的负面情绪，制造出煞魔实体来攻击玩家。对情感具象造成的任何伤害也会转移给其召唤者。"}}
D.ClientTexts.JournalSection[7944]={Name={["a2b5570f860e4248:15"]="冥思之刺"}}
D.ClientTexts.JournalSection[7946]={Name={["801c0a435052524e:14"]="库卡隆狙击手"}}
D.ClientTexts.JournalSection[7947]={Name={["948cc980aaa2ca99:12"]="猎人印记"},Description={["76034048e9f7ea65:43"]="库卡隆狙击手会锁定一名非坦克目标。"}}
D.ClientTexts.JournalSection[7948]={Name={["105af072a10b4fbf:5"]="射击"}}
D.ClientTexts.JournalSection[7949]={Name={["b093779bf6955e4e:10"]="多重射击"}}
D.ClientTexts.JournalSection[7950]={Name={["e63e3199da7c3e42:17"]="亚煞极的精华"}}
D.ClientTexts.JournalSection[7951]={Name={["383ed2a7c0f12708:9"]="湮没"}}
D.ClientTexts.JournalSection[7952]={Name={["12daadc3b42064a4:16"]="活性腐化物"},Description={["7b915397e78057a4:70"]="震地猛击将使地面渗出活性腐化物并攻击玩家。"}}
D.ClientTexts.JournalSection[7953]={Name={["5a6b656044ac3dd7:8"]="受难"}}
D.ClientTexts.JournalSection[7954]={Name={["6e43fc95594a0ad4:14"]="黑暗冥想"}}
D.ClientTexts.JournalSection[7956]={Name={["3ac996a795465d1c:17"]="背水一战"},Description={["d2682d8102b6e9a4:205"]="在生命值降至66%和33%时，鲁克·石趾召唤其挚友的邪恶形态成为困苦的化身、悔恨的化身和阴郁的化身。\r\n\r\n一旦这三个灵魂都被击败，鲁克·石趾将返回并与玩家战斗。"}}
D.ClientTexts.JournalSection[7957]={Name={["642506f2d610a8c7:15"]="腐蚀震击"}}
D.ClientTexts.JournalSection[7958]={Name={["ee2e26614dbd5d2e:13"]="大地污染"}}
D.ClientTexts.JournalSection[7959]={Name={["978ca248f6ab05a1:13"]="炼狱打击"}}
D.ClientTexts.JournalSection[7960]={Name={["a4b85e2692b263e9:24"]="第一阶段：黑暗中的哀嚎"}}
D.ClientTexts.JournalSection[8071]={Name={["10616b4acc67bb61:5"]="钉刺"},Description={["cc42557e919f3eb7:73"]="琥珀巨蝎钉刺目标，使其每秒受到自然伤害。"}}
D.ClientTexts.JournalSection[7961]={Name={["bfbc259b6e6e5e36:22"]="第二阶段：血性狂乱！"}}
D.ClientTexts.JournalSection[7962]={Name={["6652244b3065ae92:12"]="恐惧咆哮"}}
D.ClientTexts.JournalSection[7963]={Name={["e6b4b3a3f81ed574:16"]="震耳尖啸"}}
D.ClientTexts.JournalSection[7964]={Name={["b125aa579b4bedda:8"]="龙尾扫击"}}
D.ClientTexts.JournalSection[7965]={Name={["8f0e073309d4d156:10"]="震爆"}}
D.ClientTexts.JournalSection[7966]={Name={["8f1cfbacde773def:14"]="暗影虚弱"},Description={["7faa1451b99aa138:185"]="当痛苦的化身攻击目标时，将会对目标叠加暗影虚弱，使痛苦印记对其造成的伤害提高。此外，将痛苦印记转移给其他目标时，将对所有玩家叠加一层暗影虚弱。该效果可以叠加。"}}
D.ClientTexts.JournalSection[7967]={Name={["717649473861050e:8"]="鲜血淋漓"},Description={["0b06db5e734f3117:204"]="当玩家的生命值低于50%时，嗜血的索克会嗅到他们散发出的血腥味。如果有数量大于等于全团人数一半的带有鲜血淋漓效果的玩家相互位于10码范围内，则浓烈的血腥味会令索克陷入血性狂乱。"}}
D.ClientTexts.JournalSection[7968]={Name={["6a324d0913c9d606:14"]="库卡隆狱卒"},Description={["712552b409e8c3ff:176"]="索克陷入血性狂乱后震耳欲聋的大吼引来附近一名狱卒的注意。在击败他之后，你可以获得一把监狱钥匙，并用它来释放一名加尔鲁什的囚犯。"}}
D.ClientTexts.JournalSection[7969]={Name={["ad118129208564f6:14"]="战俘"},Description={["b9034e1c8eccb949:113"]="加尔鲁什在其潘达利亚战役期间俘虏了一些囚犯，他们就被囚禁在野兽旁边的笼子里，渴望着自由。"}}
D.ClientTexts.JournalSection[7973]={Name={["8957fec5d14a3e4a:16"]="酸性灌注"},Description={["4ab559519304855a:126"]="当阿考里克吸引到索克的注意力之后，这头强大的恐龙会将他吞噬，并吸收蜥蜴人的酸性能力。这将终止索克的血性狂乱效果。"}}
D.ClientTexts.JournalSection[7974]={Name={["b4baa782d016cb97:17"]="冰霜灌注"},Description={["ab718b013621b06e:124"]="当水语者苟莱引起索克的注意力之后，这头强大的恐龙会将他吞噬，并吸收锦鱼人的流水之力。这将终止索克的血性狂乱。"}}
D.ClientTexts.JournalSection[7975]={Name={["b4b720d9b2030c86:17"]="烈焰灌注"},Description={["1b28cb6c29bd1e07:126"]="当战神蒙塔克引起索克的注意力之后，这头强大的恐龙会将他吞噬，并吸收野牛人的烈焰之力。这将终止索克的血性狂乱。"}}
D.ClientTexts.JournalSection[7976]={Name={["f9b138d168161d52:14"]="腐蚀之血"}}
D.ClientTexts.JournalSection[7977]={Name={["af70212ca78306bd:10"]="酸性吐息"}}
D.ClientTexts.JournalSection[7978]={Name={["0bd37815f744a5f4:14"]="冰冻吐息"}}
D.ClientTexts.JournalSection[7979]={Name={["48e3ce3a084a5d9b:8"]="冰冻之血"}}
D.ClientTexts.JournalSection[7980]={Name={["fd7cbb46b10b8cdd:6"]="锁定"},Description={["5670d8ccb7b61f0b:64"]="索克不再受坦克嘲讽，并随机锁定远处的一名玩家。"}}
D.ClientTexts.JournalSection[7981]={Name={["a7d2cd13a3796d6e:11"]="血性狂乱"},Description={["0ad94ed5f233a296:223"]="索克因饥饿而怒吼，将正前方的敌人击飞并陷入血性狂乱。所有靠近索克的恐怖巨口的玩家都将被立刻吞噬。\r\n\r\n索克的速度在血性狂乱期间将逐渐加快且免疫嘲讽效果。"}}
D.ClientTexts.JournalSection[7982]={Name={["7aaf541be8f9936a:15"]="灼热吐息"}}
D.ClientTexts.JournalSection[7983]={Name={["d54cceaa431a0447:12"]="炽燃之血"}}
D.ClientTexts.JournalSection[7984]={Name={["75cf05a2e28240ed:14"]="山谷之泪"},Description={["fa065773d918e018:50"]="身为水元素的伊墨苏斯会直接攻击玩家。"}}
D.ClientTexts.JournalSection[7985]={Name={["91d45612fa916201:7"]="煞能箭"}}
D.ClientTexts.JournalSection[7987]={Name={["106310f658002e9f:5"]="漩涡"}}
D.ClientTexts.JournalSection[7988]={Name={["f9b0fdd761354550:14"]="腐蚀冲击"}}
D.ClientTexts.JournalSection[7989]={Name={["2ecfe61fba74ec3c:18"]="膨胀腐蚀"}}
D.ClientTexts.JournalSection[7991]={Name={["dbe7db2c34f07487:10"]="渗透煞能"}}
D.ClientTexts.JournalSection[7992]={Name={["105f45f113c1a5ba:5"]="分裂"},Description={["06235f5a545f37f9:255"]="在生命值降为0时，伊墨苏斯将变得不稳定并喷出大量邪煞软泥怪和被污染的软泥怪，并试图在房间中央的水池里重塑形体。\r\n\r\n每击杀一个邪煞软泥怪或将一个被污染的软泥怪的生命值回满，伊墨苏斯的腐蚀值就会减少1点。"}}
D.ClientTexts.JournalSection[7993]={Name={["7952559f56ca99ea:9"]="邪煞软泥怪"},Description={["065851920f038505:163"]="在不稳定状态下，伊墨苏斯每拥有4个单位腐蚀值就会形成一个邪煞软泥怪。在邪煞软泥怪重新融合进中央水池前将其消灭，伊墨苏斯就将失去一个单位的腐蚀值。"}}
D.ClientTexts.JournalSection[7994]={Name={["195106d21ef0d6bf:10"]="煞能残渣"}}
D.ClientTexts.JournalSection[7995]={Name={["9f34095aa2e6a973:18"]="被污染的软泥怪"},Description={["fee815ae2e4d475b:262"]="在不稳定状态下，伊墨苏斯每失去4个单位腐蚀值就会形成一个被污染的软泥怪。在被污染的软泥怪重新融合进中央水池前将其生命值回满，它将被净化，并使伊墨苏斯失去一个单位的腐蚀值。"}}
D.ClientTexts.JournalSection[7996]={Name={["b7623f5caaabbbf7:10"]="凝固"},Description={["aa874da96d87aab4:58"]="随着被污染的软泥怪的生命值提高，它的速度会逐渐降低。"}}
D.ClientTexts.JournalSection[7997]={Name={["ce5cf56ea32eabed:15"]="净化残渣"}}
D.ClientTexts.JournalSection[7998]={Name={["cdb0de0f89ed0376:11"]="煞能迸发"}}
D.ClientTexts.JournalSection[7999]={Name={["91dc03bb85f3cd28:7"]="邪煞池"}}
D.ClientTexts.JournalSection[8000]={Name={["dbe7db2c34f07487:10"]="渗透煞能"}}
D.ClientTexts.JournalSection[8001]={Name={["dc205727cb776616:19"]="卡拉克西英杰"}}
D.ClientTexts.JournalSection[8002]={Name={["519caa151627598c:16"]="英杰的决意"}}
D.ClientTexts.JournalSection[8003]={Name={["6211dd0f0d274ef2:12"]="准备战斗"},Description={["1d5370cc7b3fd9d9:338"]="拥有此光环的卡拉克西英杰即为下一个加入战斗的英杰。\r\n\r\n在战斗开始前，将有3名卡拉克西英杰拥有此光环。在战斗开始后，这3名英杰将加入战斗。同时，另一名英杰将获得此光环，表明他将是下一个加入战斗者。\r\n\r\n每当一名新的卡拉克西英杰加入战斗，就会一名未激活的卡拉克西英杰获得此光环。"}}
D.ClientTexts.JournalSection[8004]={Name={["144481a391be7dd8:21"]="掠风者克尔鲁克"}}
D.ClientTexts.JournalSection[8005]={Name={["e4d10342a91f235f:12"]="血脉暴露"},Description={["578cb0906d6cc9e1:213"]="掠风者克尔鲁克使用锋利的刀刃将受害者的血管暴露出来，使其更容易受到毒心者夏克里尔的攻击伤害。\r\n\r\n每层血脉暴露效果可使来自毒心者夏克里尔的所有伤害提高10%。"}}
D.ClientTexts.JournalSection[8006]={Name={["0f85b97cba92ebeb:5"]="凿击"},Description={["6dc219b041a56adf:97"]="掠风者克尔鲁克使其当前坦克目标瘫痪。该攻击紧接毁伤。"}}
D.ClientTexts.JournalSection[8007]={Name={["58580cca094ec4a3:8"]="毁伤"},Description={["9d7d33620955dcfd:72"]="掠风者克尔鲁克同时使用两把武器进行毁灭性的攻击。"}}
D.ClientTexts.JournalSection[8008]={Name={["253a19ccb6a0447f:14"]="死从天降"}}
D.ClientTexts.JournalSection[8009]={Name={["d2660aefbfb3ccde:20"]="毒心者夏克里尔"}}
D.ClientTexts.JournalSection[8010]={Name={["66843327000f6fb0:21"]="操纵者卡兹提克"}}
D.ClientTexts.JournalSection[8011]={Name={["6c735538a01f71ff:14"]="至尊者柯尔凡"}}
D.ClientTexts.JournalSection[8012]={Name={["ddcf1e0c877e37bf:15"]="明澈者伊约库克"}}
D.ClientTexts.JournalSection[8013]={Name={["1545672e90d3717b:15"]="暴食蝗卡诺兹"}}
D.ClientTexts.JournalSection[8014]={Name={["e135a3ef8ffa56a8:19"]="觅血者斯基尔"}}
D.ClientTexts.JournalSection[8015]={Name={["0b187ddb13cf6d46:19"]="切割者里卡尔"}}
D.ClientTexts.JournalSection[8016]={Name={["0c53e000269bb5b1:19"]="虫群卫士希赛克"}}
D.ClientTexts.JournalSection[8072]={Name={["b093779bf6955e4e:10"]="多重射击"},Description={["81e53fd1544f7214:69"]="虫群卫士希赛克随机向若干玩家射击，造成物理伤害。"}}
D.ClientTexts.JournalSection[8017]={Name={["25a4c90e7f5ddf2f:20"]="金莲的羁绊"}}
D.ClientTexts.JournalSection[8034]={Name={["a2b0574f014ff720:14"]="毒素注射"},Description={["a2d5619d6a9af98a:102"]="当夏克里尔加入战斗时，他会从三种毒素中随机选择一种给玩家注射：红色，蓝色或黄色。"}}
D.ClientTexts.JournalSection[8035]={Name={["019f826d9f017324:18"]="脆弱打击"}}
D.ClientTexts.JournalSection[8036]={Name={["a55d4fcb58e10b30:14"]="选择催化药剂"},Description={["5a0e78756cc24746:184"]="毒心者夏克里尔随机选择一种催化药剂，并使用与之颜色相匹配的毒素攻击所有团队成员。该催化药剂可使所有目标身上的毒素按照本身的类型发生反应。"}}
D.ClientTexts.JournalSection[8037]={Name={["c993bb4d857123d6:21"]="催化反应：红色"}}
D.ClientTexts.JournalSection[8038]={Name={["fc027f3a15c436d5:22"]="催化反应：蓝色"}}
D.ClientTexts.JournalSection[8039]={Name={["3bc26dcef796718f:24"]="催化反应：黄色"}}
D.ClientTexts.JournalSection[8040]={Name={["2554154e8e049ce9:24"]="催化反应：橙色"},Description={["cb66093529d71a5e:192"]="当黄色或红色毒素与此催化药剂发生反应时，将产生一个向外爆发的火环。玩家无法看见自己脚下的火环，也不需要作出应对；但他们必须躲避其他盟友产生的火环。"}}
D.ClientTexts.JournalSection[8041]={Name={["27e8e30a87eb1817:24"]="催化反应：紫色"}}
D.ClientTexts.JournalSection[8042]={Name={["7cafe7a3f5044648:23"]="催化反应：绿色"}}
D.ClientTexts.JournalSection[8043]={Name={["c7b321f227d1a0a7:15"]="饥饿的恐虫"},Description={["da8746c9ec43fcf4:109"]="当操纵者卡兹提克加入战斗时，会召唤这些饥饿的恐虫。任意一只死亡后，卡兹提克将召唤新恐虫。"}}
D.ClientTexts.JournalSection[8044]={Name={["f8892afa1ed98637:6"]="吞噬"}}
D.ClientTexts.JournalSection[8045]={Name={["fea169197f90a980:11"]="活体吞噬"},Description={["372d64537e6c5910:100"]="饥饿的恐虫会立即杀死所有过于靠近的玩家。这一过程将使饥饿的恐虫的能量值回满。"}}
D.ClientTexts.JournalSection[8046]={Name={["0abf1a30b349b173:10"]="厚壳"},Description={["3901570bc22292b8:184"]="未处于进食状态的饥饿的恐虫免疫所有伤害。\r\n\r\n当击败克尔鲁克后，玩家所获得的死从天降技能将击碎饥饿的恐虫的厚壳。"}}
D.ClientTexts.JournalSection[8047]={Name={["7c9abb61067bb54a:4"]="蜕变"},Description={["ad1da109a23fbb70:102"]="一头饥饿的恐虫在能量值全满时将发生蜕变。这将使饥饿的恐虫蜕变为成年恐虫。"}}
D.ClientTexts.JournalSection[8048]={Name={["32e71570499b5467:14"]="成年恐虫"},Description={["337a0ed37683c4ae:113"]="成年恐虫会忽视正常的操纵指令，并使用其新获得的技能：横扫，来攻击附近的所有玩家。"}}
D.ClientTexts.JournalSection[8049]={Name={["106310ad57fe2e1a:5"]="横扫"}}
D.ClientTexts.JournalSection[8050]={Name={["5b2138f696987d55:9"]="催眠术"},Description={["797d6ce14ada94ac:147"]="卡兹提克随机选择一名团队成员并迫使其走向一头饥饿的恐虫。如果受害者走到恐虫身边，他将遭到活体吞噬。"}}
D.ClientTexts.JournalSection[8051]={Name={["4ba2285e26287a9b:15"]="音波发射"}}
D.ClientTexts.JournalSection[8052]={Name={["051a2772785a9265:13"]="琥珀庇佑"}}
D.ClientTexts.JournalSection[8128]={Name={["eb86a3b987635bf8:18"]="碎地者哈洛姆"}}
D.ClientTexts.JournalSection[8053]={Name={["a1eb613cb0817b9d:10"]="盾击"}}
D.ClientTexts.JournalSection[8054]={Name={["e9909024ec101bc9:14"]="恶意突袭"}}
D.ClientTexts.JournalSection[8055]={Name={["ec3056d3360e8666:9"]="测算"},Description={["a00dd5f4207fdb79:300"]="当明澈者伊约库克加入战斗时，他将感知所有玩家的综合属性，并为每个目标标上测算结果。\r\n\r\n这些测算结果将使用不同的图形、颜色和数字表示。\r\n\r\n具体图形包括：\r\n- 螳螂妖\r\n- 长剑\r\n- 法杖\r\n- 战鼓\r\n- 炸弹\r\n\r\n具体颜色包括：\r\n- 红色\r\n- 紫色\r\n- 蓝色\r\n- 绿色\r\n- 黄色\r\n\r\n具体数字可分为1到5。"}}
D.ClientTexts.JournalSection[8056]={Name={["5df9d61a0972cb71:8"]="削弱"}}
D.ClientTexts.JournalSection[8057]={Name={["af716d60e15cdcab:27"]="疯狂测算：炎界"}}
D.ClientTexts.JournalSection[8058]={Name={["0f71a853e144e790:5"]="闪击"},Description={["667d9a786a76a489:94"]="卡诺兹随机冲向团队中的任意目标。位于其冲锋路线上的所有目标都将受到晕头转向的影响。"}}
D.ClientTexts.JournalSection[8059]={Name={["912f86a9fb233d70:8"]="晕头转向"}}
D.ClientTexts.JournalSection[8060]={Name={["8935ac47c000921c:9"]="投掷琥珀"}}
D.ClientTexts.JournalSection[8061]={Name={["7c97d45718f80934:4"]="挥砍"}}
D.ClientTexts.JournalSection[8062]={Name={["52c93c4c96a9008f:12"]="血祭"}}
D.ClientTexts.JournalSection[8063]={Name={["aeb8ba97e7e02518:17"]="基因变异"}}
D.ClientTexts.JournalSection[8064]={Name={["0fe76f68a2153957:9"]="注射"}}
D.ClientTexts.JournalSection[8065]={Name={["75560e65888e11ea:13"]="琥珀寄生虫"},Description={["a0d583e567795142:114"]="琥珀寄生虫拥有转基因效果，将在生成时随机锁定一名玩家。琥珀寄生虫会对锁定的目标使用进食。"}}
D.ClientTexts.JournalSection[8066]={Name={["fd02726ddd9fd33e:20"]="转基因"},Description={["1ddb7baac20a177b:97"]="里卡尔的生物学技能使这些寄生虫能够每10秒完全再生一次。"}}
D.ClientTexts.JournalSection[8067]={Name={["7c96b939bbd8633e:4"]="进食"}}
D.ClientTexts.JournalSection[8068]={Name={["adfac5c3b6a4f9fa:20"]="变异：琥珀巨蝎"}}
D.ClientTexts.JournalSection[8069]={Name={["7c95316c33b25c9f:4"]="爪击"},Description={["3a2eed71fca38c3a:57"]="琥珀巨蝎可以用一只爪子进行猛击，造成100%的伤害。"}}
D.ClientTexts.JournalSection[8070]={Name={["106310ad57fe2e1a:5"]="横扫"},Description={["9ebf15bf910539e0:147"]="琥珀巨蝎用两只爪子横扫，对其正前方区域内的所有目标造成150%的伤害。对受钉刺效果影响的目标伤害翻倍。"}}
D.ClientTexts.JournalSection[8073]={Name={["0b885d7c302cfa25:3"]="瞄准"}}
D.ClientTexts.JournalSection[8074]={Name={["3a7dbd63796079e2:18"]="英杰之力"},Description={["a3bdeb79a27ef906:244"]="当一名英杰被击败后，玩家可以获得阵亡英杰的力量并运用自如。每名英杰的力量只能供一名玩家获取，每名玩家在同一场战斗中也只能获得一次英杰的力量。\r\n\r\n每个英杰的力量只能由特定的职责角色获取。"}}
D.ClientTexts.JournalSection[8075]={Name={["1046f818caaca71d:5"]="飞掠"}}
D.ClientTexts.JournalSection[8076]={Name={["68657e70a1da5221:25"]="药剂大师"}}
D.ClientTexts.JournalSection[8077]={Name={["3ce452d7a6fd0566:15"]="傀儡主宰"}}
D.ClientTexts.JournalSection[8078]={Name={["020897edd54e792a:13"]="琥珀主宰"}}
D.ClientTexts.JournalSection[8079]={Name={["29b9d8d60debe92f:9"]="足智多谋"}}
D.ClientTexts.JournalSection[8080]={Name={["6cbdaecd7a51367c:10"]="脚力劲健"}}
D.ClientTexts.JournalSection[8081]={Name={["c0d2a14c47427e61:12"]="嗜血"}}
D.ClientTexts.JournalSection[8082]={Name={["8422dfcdaedc6388:12"]="科学狂人"}}
D.ClientTexts.JournalSection[8083]={Name={["ae0d116d58bed106:11"]="复眼视界"}}
D.ClientTexts.JournalSection[8119]={Name={["28abaa6efaedf6cb:10"]="灵魂链接"},Description={["501ad35778bd683c:65"]="造成的伤害将由碎地者哈洛姆和缚潮者卡德里斯共同分担。"}}
D.ClientTexts.JournalSection[8120]={Name={["a0415dbd7872ace4:9"]="嗜血"}}
D.ClientTexts.JournalSection[8121]={Name={["0b28f2ad384d890c:20"]="黯牙与血爪"},Description={["946700f5c27d4ba2:83"]="黯牙与血爪是黑暗萨满骑乘的座狼，会凶狠地保护他们的主人。"}}
D.ClientTexts.JournalSection[8122]={Name={["106310ad57fe2e1a:5"]="横扫"}}
D.ClientTexts.JournalSection[8123]={Name={["7c9d4eeeea332e69:4"]="撕裂"}}
D.ClientTexts.JournalSection[8124]={Name={["1e8f65c1c6d911b2:6"]="图腾"},Description={["707cc28e51cb5edd:67"]="黑暗萨满会在战斗中施放图腾，为自己赋予新技能。"}}
D.ClientTexts.JournalSection[8125]={Name={["ffb71443a65ad53c:15"]="毒雾图腾"},Description={["b2883e51c17f2a1a:161"]="毒雾图腾可使碎地者哈洛姆获得剧毒之雾技能，并使缚潮者卡德里斯获得剧毒风暴技能。黑暗萨满在生命值降至85%时会施放毒雾图腾。"}}
D.ClientTexts.JournalSection[8126]={Name={["49e66a706498b5c1:15"]="污流图腾"},Description={["4c23ed305a8d7e97:162"]="污流图腾可使碎地者哈洛姆获得污秽水流技能，并使缚潮者卡德里斯获得污水喷涌技能。黑暗萨满在生命值降至65%时会施放污流图腾。"}}
D.ClientTexts.JournalSection[8127]={Name={["2c1bb5b4dddf8ec9:13"]="灰火图腾"},Description={["a0c1d3c37f9f78f0:157"]="灰火图腾可使碎地者哈洛姆获得余烬之墙技能，并使缚潮者卡德里斯获得坠落余烬技能。黑暗萨满在生命值降至50%时会施放灰火图腾。"}}
D.ClientTexts.JournalSection[8129]={Name={["278d8c1a511d5137:16"]="冰霜风暴打击"}}
D.ClientTexts.JournalSection[8130]={Name={["3c823e4920a0f0f4:9"]="剧毒之雾"}}
D.ClientTexts.JournalSection[8131]={Name={["099747a233adb437:8"]="中毒反应"}}
D.ClientTexts.JournalSection[8132]={Name={["dc3536a7b91e8940:10"]="污秽水流"}}
D.ClientTexts.JournalSection[8133]={Name={["70212684ff12ef89:9"]="余烬之墙"},Description={["27ddbfa628a4ae3f:104"]="召唤一排原地不动的余烬元素攻击附近的所有敌人。该技能来自灰火图腾。"}}
D.ClientTexts.JournalSection[8134]={Name={["97a07c5c64ebe4f1:17"]="缚潮者卡德里斯"}}
D.ClientTexts.JournalSection[8135]={Name={["cb5792f93bdeb95a:14"]="冰霜风暴箭"}}
D.ClientTexts.JournalSection[8136]={Name={["cd3c91c18dea4032:10"]="剧毒风暴"}}
D.ClientTexts.JournalSection[8137]={Name={["502c69e348db887e:12"]="剧毒旋风"}}
D.ClientTexts.JournalSection[8138]={Name={["bf2bf24a00c8f885:10"]="污水喷涌"}}
D.ClientTexts.JournalSection[8139]={Name={["fee5ceb5657602e8:9"]="污秽软泥怪"},Description={["6390fe2498ab16cb:30"]="污秽软泥怪表面布满了秽物。"}}
D.ClientTexts.JournalSection[8140]={Name={["173a69f4cfc7aef7:8"]="秽物"}}
D.ClientTexts.JournalSection[8141]={Name={["17504c7efb1fad2f:10"]="坠落余烬"}}
D.ClientTexts.JournalSection[8142]={Name={["d0df173da37e5f36:15"]="锈铁图腾"},Description={["79c50f237b210054:160"]="锈铁图腾可使碎地者哈洛姆获得钢铁之坟技能，并使缚潮者卡德里斯获得钢铁囚笼技能。黑暗萨满在生命值降至95%时会施放锈铁图腾。"}}
D.ClientTexts.JournalSection[8143]={Name={["b517500f5a5b8438:8"]="钢铁之坟"}}
D.ClientTexts.JournalSection[8144]={Name={["4f0b5c58ba336093:10"]="钢铁囚笼"}}
D.ClientTexts.JournalSection[8145]={Name={["d6e1fd06c549ee21:15"]="复仇打击"}}
