D.ClientTexts.JournalSection[8158]={Name={["48d0e3152449702e:14"]="玉火吐息"}}
D.ClientTexts.JournalSection[8159]={Name={["74e685b05fbaa383:12"]="玉火之箭"},Description={["b4e041eaa72745a5:72"]="发射数支玉火之箭，在冲击点生成玉火烈焰。"}}
D.ClientTexts.JournalSection[8160]={Name={["11b568eda1782254:13"]="玉火烈焰"}}
D.ClientTexts.JournalSection[8189]={Name={["90107c6668ea0497:10"]="地震冲击"},Description={["7fce148f38fab0e6:63"]="地震冲击可将玩家击退一大段距离。"}}
