D.ClientTexts.JournalSection[8164]={Name={["33382694bbdd7bf3:12"]="强震"}}
D.ClientTexts.JournalSection[8165]={Name={["f65ed2cf04cf4d54:6"]="冲锋"}}
D.ClientTexts.JournalSection[8166]={Name={["d9a5512bca924056:13"]="幽灵猛击"}}
