D.ClientTexts.JournalSection[8168]={Name={["dc0fcc372ad9481a:18"]="裂变闪电"}}
D.ClientTexts.JournalSection[8169]={Name={["61b0f58dc3fa997c:10"]="真气弹幕"}}
D.ClientTexts.JournalSection[8170]={Name={["267d0f38c31b0025:7"]="敏捷"}}
D.ClientTexts.JournalSection[8171]={Name={["cfe1636de86a81f4:10"]="熔岩重碾"}}
D.ClientTexts.JournalSection[8172]={Name={["d0327d7d36abe006:11"]="燃烧之魂"}}
D.ClientTexts.JournalSection[8173]={Name={["70bb69ba9830b769:10"]="烈焰之池"}}
D.ClientTexts.JournalSection[8174]={Name={["e957a96c80ff86fb:12"]="上古之火"}}
D.ClientTexts.JournalSection[8175]={Name={["405b9e2ee04bd957:12"]="无尽苦难"}}
D.ClientTexts.JournalSection[8177]={Name={["c5f9dae5443b2440:29"]="全线出击：突击模式"},Description={["c91f93d55270bcfc:50"]="钢铁战蝎在突击模式下可自由移动。"}}
D.ClientTexts.JournalSection[8178]={Name={["85baf1af299205e8:28"]="攻坚克难：强攻模式"}}
D.ClientTexts.JournalSection[8179]={Name={["e8f72bf6dc72d4e9:10"]="地火突刺"}}
D.ClientTexts.JournalSection[8180]={Name={["d1e407c12eca0874:17"]="攻城炮火"}}
D.ClientTexts.JournalSection[8181]={Name={["32a668f6ade1e657:8"]="回旋锯刃"}}
D.ClientTexts.JournalSection[8182]={Name={["23d6d9f316496d9a:9"]="激光灼烧"}}
