D.ClientTexts.JournalSection[8185]={Name={["360a7eda51aebdeb:10"]="烈焰爆发"}}
D.ClientTexts.JournalSection[8187]={Name={["baca9c3f76bb2b5a:15"]="地震"}}
D.ClientTexts.JournalSection[8188]={Name={["52f4ddd75e5ecf92:12"]="迫击炮"}}
