D.ClientTexts.JournalSection[8190]={Name={["9dcf6c3325f386ac:11"]="切割激光"}}
D.ClientTexts.JournalSection[8191]={Name={["17ada78bce1fbb00:12"]="爆裂焦油"}}
D.ClientTexts.JournalSection[8192]={Name={["64e0b36ef59d0b0b:13"]="迫击弹幕"}}
D.ClientTexts.JournalSection[8194]={Name={["7c7d080975baa6e0:21"]="攻城匠师黑索"}}
D.ClientTexts.JournalSection[8195]={Name={["17584843bf435d42:14"]="发射锯刃"},Description={["a3ba82243537af25:134"]="攻城匠师黑索随机向一名玩家发射一枚磁化锯刃。锯刃将在原地盘旋，直至被激活的电磁体移除。"}}
D.ClientTexts.JournalSection[8196]={Name={["1604ce1a13054959:13"]="锯齿劈斩"}}
D.ClientTexts.JournalSection[8197]={Name={["32c1d1e5686220ce:19"]="电荷冲击"}}
D.ClientTexts.JournalSection[8198]={Name={["b950b70412a431e7:19"]="自动修复射线"}}
D.ClientTexts.JournalSection[8199]={Name={["3cf96e2d6da97dce:18"]="自动伐木机"},Description={["d67b2f7141c659d4:76"]="攻城匠师黑索进入战斗后，会周期性地召唤自动伐木机加入战斗。"}}
D.ClientTexts.JournalSection[8200]={Name={["4af86cf960ddc346:13"]="反应装甲"}}
D.ClientTexts.JournalSection[8201]={Name={["253a19ccb6a0447f:14"]="死从天降"}}
D.ClientTexts.JournalSection[8202]={Name={["4757510e86e0832b:15"]="装配流水线"},Description={["3250852c41cf6d07:551"]="攻城匠师黑索会周期性地在其工作室的装配流水线上开始制作一套武器。\r\n\r\n零散的武器将通过房间西北部的传送带进入房间，然后通过东北部墙上的装配机，最后在东南部传送带上整合完毕并开始攻击玩家。\r\n\r\n玩家可以使用输送管道到达西北部的传送带，攻击并摧毁零散的武器。当玩家摧毁一件武器后，剩余的武器将受到保护并无法再被摧毁。"}}
D.ClientTexts.JournalSection[8203]={Name={["4ae8dbd49d4903c1:22"]="物质提纯光束"}}
D.ClientTexts.JournalSection[8204]={Name={["3472096c1af5699b:22"]="震波飞弹炮台"}}
D.ClientTexts.JournalSection[8205]={Name={["984b836617d1184b:16"]="震波飞弹"}}
D.ClientTexts.JournalSection[8206]={Name={["adc632b32d2b95dc:14"]="输送管道"},Description={["ed93f72235256f27:151"]="输送管道位于攻城匠师黑索工作室的西部边缘。玩家可以跳进这些管道，到达工作室西北边的传送带。"}}
D.ClientTexts.JournalSection[8207]={Name={["eba53924302dcc67:18"]="图像识别"}}
D.ClientTexts.JournalSection[8208]={Name={["9ef21c820bb46e5b:11"]="激光炮台"}}
D.ClientTexts.JournalSection[8209]={Name={["1ab05b3fdc89c30a:11"]="过热"}}
D.ClientTexts.JournalSection[8210]={Name={["f55b668f86975c76:13"]="电磁体"}}
D.ClientTexts.JournalSection[8211]={Name={["ad3eb6f2569cee17:13"]="电磁振荡"}}
D.ClientTexts.JournalSection[8212]={Name={["ae306b9ecc1f3a87:11"]="蛛形地雷"},Description={["17106c2c6778c499:73"]="装配好的蛛形地雷会跳下传送带并随机锁定一名玩家。"}}
D.ClientTexts.JournalSection[8213]={Name={["94ff83da7ee59fc1:9"]="引爆！"}}
D.ClientTexts.JournalSection[8214]={Name={["1ce97cd184c798b4:14"]="磨合阶段"}}
D.ClientTexts.JournalSection[8215]={Name={["ff619b8d33eb6f28:15"]="诺鲁什的试炼"},Description={["e3416e41c0fa0fd0:127"]="诺鲁什会将所有玩家封入一个检疫空间，使他们面对并战胜其自身的腐蚀值。只有通过挑战，玩家才能在地下城中更进一步。"}}
D.ClientTexts.JournalSection[8216]={Name={["559c2d1fdd0387ce:19"]="腐蚀混合物"}}
D.ClientTexts.JournalSection[8218]={Name={["a592beeb9478d5c4:14"]="怒意宣泄"}}
D.ClientTexts.JournalSection[8219]={Name={["04254ac6733d2f0b:11"]="盲目憎恨"}}
D.ClientTexts.JournalSection[8220]={Name={["267e1eed04ab3faa:10"]="内省"}}
D.ClientTexts.JournalSection[8221]={Name={["5d1859ed9341480e:14"]="冷静的试炼"},Description={["af182163736317e6:293"]="输出型玩家将面对冷静的试炼。要完成此挑战，玩家必须击败腐化物形成的各种元素。只要任何一只元素被击败，它就会回到现实世界。\r\n\r\n如果挑战失败，所有剩余的腐蚀元素将被一次性投放到现实世界。"}}
D.ClientTexts.JournalSection[8222]={Name={["6318e55d20637a68:14"]="信赖的试炼"},Description={["baaf5f1fe03ea042:299"]="治疗型玩家将面对信赖的试炼。要完成此挑战，玩家必须击败一个大型腐化物。治疗者在内省时，可得到数位盟友的支援。\r\n\r\n如果挑战失败，一只腐蚀具象将会被投放到现实世界。如果挑战成功，则将清除玩家的所有腐蚀值，并使其返回现实世界。"}}
D.ClientTexts.JournalSection[8223]={Name={["e0b0296870120273:16"]="自信的试炼"}}
D.ClientTexts.JournalSection[8224]={Name={["a0a13081ad2a81d8:25"]="腐蚀具象"},Description={["3ff432baa8cfa93d:105"]="这些煞能生物会反复施放撕裂实体，对施法者面前锥形区域内的所有敌人造成暗影伤害。"}}
D.ClientTexts.JournalSection[8225]={Name={["1de49555f4717322:19"]="腐蚀精华"}}
D.ClientTexts.JournalSection[8227]={Name={["2d53d8c4fa1e5435:17"]="大型腐化物"}}
D.ClientTexts.JournalSection[8230]={Name={["dcda09e627243c81:17"]="巨型腐化物"}}
D.ClientTexts.JournalSection[8231]={Name={["e46c3433434ca3de:19"]="逸出的腐化物"},Description={["d0f1e78171b58820:111"]="每当玩家在冷静的试炼中成功击败一只腐蚀元素，它就将会回到现实世界。"}}
D.ClientTexts.JournalSection[8232]={Name={["a0a13081ad2a81d8:25"]="腐蚀具象"}}
D.ClientTexts.JournalSection[8233]={Name={["1de49555f4717322:19"]="腐蚀精华"}}
D.ClientTexts.JournalSection[8238]={Name={["b1911e1bdce41be0:18"]="冷嘲热讽"}}
D.ClientTexts.JournalSection[8239]={Name={["2e4ef0198d2f439a:19"]="纠缠腐蚀"}}
D.ClientTexts.JournalSection[8241]={Name={["fe5344d9fb696804:6"]="融合"}}
D.ClientTexts.JournalSection[8242]={Name={["38198dad5c682516:12"]="泰坦猛击"}}
D.ClientTexts.JournalSection[8243]={Name={["dd908bfa3ca1edbb:10"]="腐蚀术"}}
D.ClientTexts.JournalSection[8244]={Name={["1c4b747559a38c42:14"]="投掷腐化"}}
D.ClientTexts.JournalSection[8245]={Name={["91ffa73ff20699d2:17"]="腐蚀爆发"}}
D.ClientTexts.JournalSection[8246]={Name={["1b0daf8b539f6540:18"]="穿透腐蚀"}}
D.ClientTexts.JournalSection[8248]={Name={["ab601a535382d0c0:18"]="腐化物残渣"}}
D.ClientTexts.JournalSection[8249]={Name={["bf05a6d8b75dca5f:15"]="驱逐腐蚀"}}
D.ClientTexts.JournalSection[8667]={Name={["a0415dbd7872ace4:9"]="嗜血"}}
D.ClientTexts.JournalSection[8252]={Name={["dd908bfa3ca1edbb:10"]="腐蚀"},Description={["d933a56f672b0038:125"]="玩家在战斗开始时拥有75点腐蚀值。腐蚀值越高，玩家对腐蚀混合物造成的伤害就越少。"}}
D.ClientTexts.JournalSection[8253]={Name={["18700ffdb2e3ab3e:8"]="净化"},Description={["e6e82abe3e9fa437:231"]="腐蚀值为0的玩家将进入净化状态。得到净化的治疗角色将获得治疗加成，坦克角色将受到更少伤害，伤害输出角色将造成更多伤害。\r\n\r\n净化状态将一直持续到玩家再次获得腐蚀值为止。"}}
D.ClientTexts.JournalSection[8255]={Name={["102a07b9a38afa68:5"]="傲气值"},Description={["da614a95a0dfa47e:214"]="玩家开始战斗时，傲气值为0。被傲之煞或其爪牙的技能击中一次，玩家就获得5点傲气值。\r\n\r\n当玩家的傲气值达到25、50、75和100时，傲气冲天会对该玩家造成额外效果。"}}
D.ClientTexts.JournalSection[8256]={Name={["3f4a36becacfeaa7:13"]="傲气冲天"}}
D.ClientTexts.JournalSection[8257]={Name={["1df68ea7c37e8766:13"]="傲气迸发"}}
D.ClientTexts.JournalSection[8258]={Name={["1cba1062470394af:10"]="投影"}}
D.ClientTexts.JournalSection[8259]={Name={["0fa5596e58b4efed:10"]="放逐"}}
D.ClientTexts.JournalSection[8260]={Name={["79a9a7f73e432744:15"]="傲慢标记"}}
D.ClientTexts.JournalSection[8261]={Name={["6d22accfd4833b76:12"]="受损自尊"}}
D.ClientTexts.JournalSection[8262]={Name={["fac8fbe00181120b:20"]="傲慢具象"},Description={["791d43d544f5d8fa:69"]="傲之煞周期性地召唤傲慢具象来攻击玩家。"}}
D.ClientTexts.JournalSection[8263]={Name={["3581836387710dc0:12"]="嘲弄冲击"}}
D.ClientTexts.JournalSection[8265]={Name={["1160e407e39e4a6c:15"]="本我具象"},Description={["14cd367e25df7a15:216"]="傲之煞令最多5名玩家反省自身的行为，在其位置制造出一个本我具象。随着本我具象的每一跳，傲之煞都将锁定傲气值更高一级的玩家。傲之煞只锁定傲气值达到25、50和75点的目标。"}}
D.ClientTexts.JournalSection[8266]={Name={["68f5eed82ee91777:15"]="腐化囚笼"}}
D.ClientTexts.JournalSection[8267]={Name={["1f8c71fe7cb85da3:9"]="释放"}}
D.ClientTexts.JournalSection[8268]={Name={["0de5e6d89d936a91:15"]="泰坦之赐"}}
D.ClientTexts.JournalSection[8269]={Name={["3045967b78061d1c:16"]="泰坦之力"}}
D.ClientTexts.JournalSection[8270]={Name={["5b76b9a5a0733b98:8"]="压制"}}
D.ClientTexts.JournalSection[8271]={Name={["6701a135868bf560:8"]="遗言"},Description={["0addfe69547ad836:64"]="当傲慢具象死亡时，将使周围距离最近的2名玩家获得5点傲气值。"}}
D.ClientTexts.JournalSection[8272]={Name={["86217330e219106b:10"]="具象"}}
D.ClientTexts.JournalSection[8281]={Name={["9d2cd335f54b13a0:10"]="光球"}}
D.ClientTexts.JournalSection[8282]={Name={["b194db9ea424d937:14"]="伸展打击"}}
D.ClientTexts.JournalSection[8283]={Name={["f1f25f202ca8b5c9:6"]="阿考里克"},Description={["edf4adf202b87b0f:156"]="阿考里克和他的一些邪刃蜥蜴人同胞被加尔鲁什俘虏了。被释放后，他会祈求克洛斯的神圣命令驯服附近的一头恐龙。\r\n\r\n其后果……难以预料。"}}
D.ClientTexts.JournalSection[8284]={Name={["509283e554235fca:17"]="水语者苟莱"},Description={["fbd06513fb206640:168"]="水语者苟莱和一群墨鳃潭居民被加尔鲁什俘虏了。被释放后，水语者苟莱会命令他的手下协助你，并随机治疗附近玩家。"}}
D.ClientTexts.JournalSection[8285]={Name={["c7a462059b2be91c:15"]="战神蒙塔克"},Description={["daa1c828e7af7f95:175"]="战神蒙塔克和他的火誓者被加尔鲁什俘虏了。被释放后，附近单位的武器会燃烧，并使其有一定几率在攻击命中后造成额外的火焰伤害。"}}
D.ClientTexts.JournalSection[8286]={Name={["5b7ba78143248f5a:8"]="过载"}}
D.ClientTexts.JournalSection[8287]={Name={["b0de6b3455f4d89b:10"]="蓄势待发"},Description={["b5247e89b7d150f0:112"]="在磨合阶段结束后，蛛形地雷将不再受到昏迷、定身和诱捕效果的影响，且速度提高。"}}
D.ClientTexts.JournalSection[8288]={Name={["eaab19084234e6bf:21"]="第一阶段：正统部落"},Description={["25e53092b4ff2137:230"]="加尔鲁什率领着正统部落，运用新式武器和攻城机器消灭所有入侵者。在战斗过程中，正统部落加入战斗的频率越来越高。该阶段将一直持续到加尔鲁什的生命值降至10%。"}}
D.ClientTexts.JournalSection[8289]={Name={["acded8fb5f9151d6:17"]="加尔鲁什·地狱咆哮"},Description={["f42b23e4c796128d:23"]="正统部落的酋长。"}}
D.ClientTexts.JournalSection[8290]={Name={["2ff3a715ed7e89d0:9"]="亵渎"}}
D.ClientTexts.JournalSection[8291]={Name={["d4afaec002f7ea85:19"]="地狱咆哮的战歌"}}
D.ClientTexts.JournalSection[8292]={Name={["44356d8527147d56:18"]="库卡隆战争使者"},Description={["c8caa091e027c360:91"]="战争使者从四周涌入房间。随着战斗的推进，战争使者加入战斗的频率会越来越高。"}}
D.ClientTexts.JournalSection[8293]={Name={["a4dca5b265a73ee5:9"]="断筋"}}
D.ClientTexts.JournalSection[8294]={Name={["43cdf0bb13cf8412:16"]="先知狼骑"},Description={["94be8f4ea613f6df:114"]="先知加入战斗的频率低于蛮兵，但他们加入战斗的频率也会随着时间的推移而越来越高。"}}
D.ClientTexts.JournalSection[8295]={Name={["46e05b28afc08d83:13"]="先祖狂怒"}}
D.ClientTexts.JournalSection[8296]={Name={["9ee3283fb625213c:18"]="先祖治疗链"}}
D.ClientTexts.JournalSection[8297]={Name={["2fd75e2cb5d68249:14"]="闪电链"}}
D.ClientTexts.JournalSection[8298]={Name={["9cd6ed5fb318063c:13"]="攻城技师"}}
D.ClientTexts.JournalSection[8300]={Name={["fe80cec4529aff19:16"]="库卡隆钢铁之星"},Description={["9209d2568663361f:102"]="被攻城技师激活后，钢铁之星将滚过整个房间，猛烈撞上对面的墙壁。"}}
D.ClientTexts.JournalSection[8301]={Name={["9bcf81f5d938d9a0:14"]="钢铁之星冲击"},Description={["481519b793eb5282:83"]="对其路径上的所有玩家或库卡隆造成大量伤害并将其击退。"}}
D.ClientTexts.JournalSection[8302]={Name={["9ebef1617ebc9c78:17"]="钢铁之星爆炸"}}
D.ClientTexts.JournalSection[8303]={Name={["2cbec0485dcf6abd:16"]="护物心切"}}
D.ClientTexts.JournalSection[8304]={Name={["e288a283e1d478d0:16"]="亵渎武器"},Description={["a2a3c4f362283aaa:124"]="亚煞极的力量从亵渎武器上渗出，随着其生命值的下降，亵渎之地的影响范围也会逐渐缩小。"}}
D.ClientTexts.JournalSection[8305]={Name={["12737282491435f7:28"]="阶段转换：亚煞极之境"}}
D.ClientTexts.JournalSection[8306]={Name={["dc5542427f37f7af:10"]="歼灭"}}
D.ClientTexts.JournalSection[8307]={Name={["3cfb0d08c014c66b:24"]="第二阶段：亚煞极之力"},Description={["f7073bbe11f3014f:100"]="在吸收了亚煞极的能量后，加尔鲁什的生命值将会回满，同时亚煞极之血会赋予他新的力量。"}}
D.ClientTexts.JournalSection[8333]={Name={["86187d084152b80f:7"]="冰霜恐惧"}}
D.ClientTexts.JournalSection[8308]={Name={["50e55a9e1c16932b:18"]="腐蚀漩涡"}}
D.ClientTexts.JournalSection[8309]={Name={["151b4e46914d9227:27"]="强化腐蚀漩涡"}}
D.ClientTexts.JournalSection[8310]={Name={["16e090bd6073a508:16"]="亚煞极的爪牙"}}
D.ClientTexts.JournalSection[8311]={Name={["4bcae6368e049391:15"]="亚煞极之触"},Description={["f0eb760f0ce21882:215"]="加尔鲁什用亚煞极之触折磨玩家。被触碰的玩家会试图传播亚煞极之触。当玩家的最大生命值降至20%时，亚煞极之触会被移除。\r\n\r\n当加尔鲁什的能量达到50点时，亚煞极之触将得到强化。"}}
D.ClientTexts.JournalSection[8312]={Name={["a5d53ade839bd795:24"]="强化亚煞极之触"},Description={["b07cdef4fa8a02df:256"]="在能量达到50点时，加尔鲁什会使用强化亚煞极之触折磨玩家，将其变成一只煞魔，被变形的玩家免疫失控状态且生命值提高。被触碰的玩家会试图传播亚煞极之触。当玩家的最大生命值降至20%时，亚煞极之触会被移除。"}}
D.ClientTexts.JournalSection[8313]={Name={["2ff3a715ed7e89d0:9"]="亵渎"}}
D.ClientTexts.JournalSection[8314]={Name={["e288a283e1d478d0:16"]="亵渎武器"},Description={["a2a3c4f362283aaa:124"]="亚煞极的力量从亵渎武器上渗出，随着其生命值的下降，亵渎之地的影响范围也会逐渐缩小。"}}
D.ClientTexts.JournalSection[8315]={Name={["0ea59dbd0cd913d4:18"]="强化亵渎"},Description={["d8bbdd061dcc77e5:132"]="在能量达到75点时，加尔鲁什将制造出一件拥有亚煞极之力的强化亵渎武器，使其无法被摧毁并能逐渐恢复生命值。"}}
D.ClientTexts.JournalSection[8316]={Name={["c882a6ed848672e8:15"]="绝望之握"}}
D.ClientTexts.JournalSection[8319]={Name={["ca639fb95d821a4c:18"]="第三阶段：我的世界！"},Description={["d1a2286907ccf214:134"]="在生命值第二次降至10%时，加尔鲁什会吸收亚煞极剩余的力量，能量全满，获得治疗并强化其所有技能。"}}
D.ClientTexts.JournalSection[8320]={Name={["151b4e46914d9227:27"]="强化腐蚀漩涡"}}
D.ClientTexts.JournalSection[8321]={Name={["16e090bd6073a508:16"]="亚煞极的爪牙"}}
D.ClientTexts.JournalSection[8322]={Name={["a5d53ade839bd795:24"]="强化亚煞极之触"},Description={["05144cc48f353115:245"]="加尔鲁什使用强化亚煞极之触折磨玩家，将其变成一只煞魔，被变形的玩家将免疫失控状态，且生命值提高。被触碰的玩家会试图传播亚煞极之触。当玩家的最大生命值降至20%时，亚煞极之触会被移除。"}}
D.ClientTexts.JournalSection[8323]={Name={["0ea59dbd0cd913d4:18"]="强化亵渎"}}
D.ClientTexts.JournalSection[8324]={Name={["228cfb957a1db6ec:24"]="强化绝望之握"}}
D.ClientTexts.JournalSection[8325]={Name={["37fe790cbd9c04a7:16"]="绝望之破"}}
D.ClientTexts.JournalSection[8326]={Name={["b6bfde9f46949620:20"]="亚煞极之佑"},Description={["1cce787105e6f6a8:131"]="免疫伤害。击败煞魔爪牙可以驱散该效果。在亚煞极的护佑下，加尔鲁什将吸收亚煞极之心中的能量。"}}
D.ClientTexts.JournalSection[8327]={Name={["4e5eacbcd48141e9:12"]="恐惧的化身"},Description={["35264d1c832b1385:103"]="首见于永春台，击败所有恐惧的化身后，加尔鲁什身上的亚煞极之佑将会消散。"}}
D.ClientTexts.JournalSection[8328]={Name={["1a15e27ce0ecd463:13"]="猜忌的化身"},Description={["559fa5929853e451:104"]="首见于青龙寺，击败所有猜忌的化身后，加尔鲁什身上的亚煞极之佑将会消散。"}}
D.ClientTexts.JournalSection[8329]={Name={["dfa814a6dd5ba693:15"]="颓丧的化身"},Description={["d412c45f613a64c4:104"]="首见于朱鹤寺，击败所有颓丧的化身后，加尔鲁什身上的亚煞极之佑将会消散。"}}
D.ClientTexts.JournalSection[8330]={Name={["6303441d906be126:15"]="腐化闪电链"}}
D.ClientTexts.JournalSection[8331]={Name={["77cc2565f2780df0:13"]="苦痛相连"},Description={["2863bba31cab77ee:42"]="困苦的化身，悔恨的化身和阴郁的化身共享生命值。"}}
D.ClientTexts.JournalSection[8334]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["09fb877b56e64fe4:453"]="伊墨苏斯在战斗开始时拥有100点腐蚀值，由一个可见的能量条显示。本场战斗的目标就是净化伊墨苏斯，将他的腐蚀等级归零。每次伊墨苏斯的生命值降到零时，他将分裂出一群黑色的邪煞软泥怪和含水的被污染的软泥怪。在每次分裂后，伊墨苏斯将重塑形体并根据团队应对两种软泥怪的效率损失一定的生命值和腐蚀值。\r\n\r\n该过程将反复循环直至伊墨苏斯得到净化，即其腐蚀值降低至10以下。"}}
D.ClientTexts.JournalSection[8349]={Name={["4058fef9ffd776c6:9"]="临终之赐"},Description={["252bb1e756dd4dae:61"]="诺鲁什在死亡时，会净化所有玩家，令他们的傲气值降到零。"}}
D.ClientTexts.JournalSection[8350]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["cb8d9e3c72d6cd23:433"]="玩家触发了库卡隆藏宝室的自毁机制，不久之后防御系统就会摧毁所有的宝物和被困在藏宝室里的所有人。玩家必须通过击败宝箱里的敌人来释放被禁锢的泰坦能量，为四个手动超控杆充能，从而关闭防御系统。\r\n\r\n战斗开始后，四个房间中有两个房间可以立即进入，但另一侧的两个房间暂时被锁住了，需要玩家手动控制超控杆来解锁。激活并拉动四个超控杆之后，战斗结束。"}}
D.ClientTexts.JournalSection[8351]={Name={["f0d05d5d2b9873a0:19"]="大型货箱"},Description={["9133b5603e65a97d:136"]="这些大型货箱里装着饱经战火的野蛮生物。有大量泰坦能量在为它们供能，想要击败它们需要花费大量精力。"}}
D.ClientTexts.JournalSection[8352]={Name={["e45004060cf792df:21"]="韶天长者议会"}}
D.ClientTexts.JournalSection[8353]={Name={["c210820bf02991d0:16"]="螳螂妖指挥官"}}
D.ClientTexts.JournalSection[8354]={Name={["fc4c754428640069:17"]="结实的货箱"},Description={["b01fed7f595a497e:125"]="这些结实的货箱里装着经验丰富的敌人。有中量泰坦能量在为它们供能，想要击败它们需要小心谨慎。"}}
D.ClientTexts.JournalSection[8355]={Name={["e638ddc061d11265:18"]="改良的心能魔像"}}
D.ClientTexts.JournalSection[8356]={Name={["774b55044a6e9e57:19"]="魔古暗影祭师"},Description={["1a82086c3664f74b:164"]="一个强大的韶天大祭师的灵魂出现并保护他的护命匣。对大祭师所造成的任何伤害都将对护命匣造成同等伤害，击败两者中的任何一个都能同时消灭另一个敌人。"}}
D.ClientTexts.JournalSection[8357]={Name={["6888c8c717ea8110:19"]="扎尔提克琥珀祭司"}}
D.ClientTexts.JournalSection[8358]={Name={["cfa283a630881bf5:19"]="赛特提克御风者"}}
D.ClientTexts.JournalSection[8359]={Name={["e65ceea5b16940ea:23"]="轻型货箱"},Description={["6c7f9cd515038738:126"]="这些小货箱里装着敌人的前线部队。有少量泰坦能量在为它们供能，并可以被较少的玩家击败。"}}
D.ClientTexts.JournalSection[8360]={Name={["ca765029e25f3312:17"]="复生的魔古石像"}}
D.ClientTexts.JournalSection[8361]={Name={["c74b527965c2535c:9"]="骨灰坛"}}
D.ClientTexts.JournalSection[8362]={Name={["62fcd5516005ab72:15"]="魁麟守护者"}}
D.ClientTexts.JournalSection[8363]={Name={["8af3fbc15ffe1958:18"]="瑟里提克投弹手"}}
D.ClientTexts.JournalSection[8364]={Name={["44a9ca496a0adc20:21"]="琥珀包裹的恐虫"}}
D.ClientTexts.JournalSection[8365]={Name={["fd8f780595b6a0e4:17"]="库尔提克战争召唤者"}}
D.ClientTexts.JournalSection[8366]={Name={["b14fa514a9bbecbb:21"]="熊猫人遗物箱"},Description={["74056eee125892d1:142"]="这些小货箱里装着稀有的熊猫人遗物。没有泰坦能量在为它们供能，但有强大的熊猫人幽灵在守护着它们。"}}
D.ClientTexts.JournalSection[8367]={Name={["4712692cf4a9b19b:22"]="百步之刃"}}
D.ClientTexts.JournalSection[8368]={Name={["4daebd6b6567c330:22"]="鸣水之杖"}}
D.ClientTexts.JournalSection[8369]={Name={["b8c8ebc30ec01f2a:18"]="燃怒之爪"}}
D.ClientTexts.JournalSection[8370]={Name={["f40526d9ebd71184:15"]="魔古能量符文"}}
D.ClientTexts.JournalSection[8371]={Name={["64fc17db5684294e:14"]="斗转乾坤"}}
D.ClientTexts.JournalSection[8372]={Name={["31ff692a4abab04d:21"]="腥红重构"}}
D.ClientTexts.JournalSection[8373]={Name={["f05c2daee985a5f5:7"]="折磨"}}
D.ClientTexts.JournalSection[8375]={Name={["3f240176e8ce0aab:7"]="残渣"}}
D.ClientTexts.JournalSection[8376]={Name={["0421e16c8261cb41:9"]="旋转风暴"}}
D.ClientTexts.JournalSection[8377]={Name={["51ca7d590733a00e:16"]="女皇之怒"}}
D.ClientTexts.JournalSection[8379]={Name={["30fa08a97d9228e0:11"]="硬化血肉"}}
D.ClientTexts.JournalSection[8380]={Name={["281d1b1b4d93ac90:11"]="生命火花"}}
D.ClientTexts.JournalSection[8381]={Name={["52ee5404d4c850db:15"]="血肉撕咬"}}
D.ClientTexts.JournalSection[8383]={Name={["69002286c62fed55:11"]="疾风炸弹"}}
D.ClientTexts.JournalSection[8384]={Name={["6098cade04987ae3:22"]="浓缩信息素"}}
D.ClientTexts.JournalSection[8385]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[8386]={Name={["3884379eb537ca8d:23"]="上古酒仙之灵"},Description={["e108d52f5635b488:90"]="在生命值较低时，上古酒仙之灵允许玩家消耗武器的祝福。"}}
D.ClientTexts.JournalSection[8387]={Name={["237968e5e3c0b368:7"]="投掷酒桶"}}
D.ClientTexts.JournalSection[8388]={Name={["92408ff6f95469ed:12"]="火焰之息"}}
D.ClientTexts.JournalSection[8389]={Name={["e337581fc444a302:20"]="睿智织雾者之灵"},Description={["19f02df010a63515:87"]="在生命值较低时，睿智织雾者之灵允许玩家消耗武器的祝福。"}}
D.ClientTexts.JournalSection[8390]={Name={["51ddc7b1366700fc:16"]="神鹤疾风腿"}}
D.ClientTexts.JournalSection[8391]={Name={["1b2b7db00d7d0cd3:24"]="无名踏风者之灵"},Description={["d9002cc1ec9a1066:91"]="在生命值较低时，无名踏风者之灵允许玩家消耗武器的祝福。"}}
D.ClientTexts.JournalSection[8392]={Name={["74067288bad25e8f:9"]="设置炸药"}}
D.ClientTexts.JournalSection[8393]={Name={["ea9469930272d10c:18"]="岩石之力"}}
D.ClientTexts.JournalSection[8394]={Name={["ac8e5271558106ba:13"]="返回岩石形态"}}
D.ClientTexts.JournalSection[8395]={Name={["716300d7031b028e:14"]="困苦的化身"}}
D.ClientTexts.JournalSection[8396]={Name={["7fce322af78c7c1d:14"]="悔恨的化身"}}
D.ClientTexts.JournalSection[8397]={Name={["1a4a6efc1e36254f:13"]="阴郁的化身"}}
D.ClientTexts.JournalSection[8398]={Name={["b0783d055db93d4e:8"]="吊钩"},Description={["5c07a466f2ddf4a9:98"]="在战斗中，玩家可使用货箱吊钩从货仓底层到达货仓主层。"}}
D.ClientTexts.JournalSection[8399]={Name={["87af65b93c096cec:14"]="繁花铺道"}}
D.ClientTexts.JournalSection[8400]={Name={["075454b70d8ebdee:11"]="傲气光环"}}
D.ClientTexts.JournalSection[8401]={Name={["ec778bc2973a75e3:18"]="检疫措施"},Description={["8010d92893bafa6d:127"]="如果腐蚀混合物变得太过危险，诺鲁什别无选择只能启动该区域的安全设备摧毁范围内的所有生命体。"}}
D.ClientTexts.JournalSection[8402]={Name={["f4d4648f23e139fa:12"]="绝望深渊"}}
D.ClientTexts.JournalSection[8403]={Name={["8d231a773982aed0:12"]="怒气迸发"}}
D.ClientTexts.JournalSection[8404]={Name={["c5f4aad31642bab4:14"]="禁忌魔法"}}
D.ClientTexts.JournalSection[8406]={Name={["284abc5e8b6eeaab:12"]="大地碎片"}}
D.ClientTexts.JournalSection[8407]={Name={["4bb2864ba0805874:15"]="投掷炸弹"}}
D.ClientTexts.JournalSection[8408]={Name={["1386bbcbec6470e8:10"]="超载"},Description={["f17c1f22c7537375:124"]="当被激活的武器抵达组装线时，攻城匠师黑索将超载其中一件武器，强化其能力和效率。"}}
D.ClientTexts.JournalSection[8409]={Name={["133faeabb76a1c3a:24"]="超载的导弹炮台"},Description={["644dcf6555596c2a:161"]="超载后，震波飞弹炮台将会持续对平台发射密集震波飞弹和震波能量进行轰炸，直至炮台被玩家摧毁。"}}
D.ClientTexts.JournalSection[8410]={Name={["bb6c92cc52e879df:22"]="超载的激光炮台"},Description={["434cc3e95761b27a:117"]="超载后，攻城匠师黑索的激光炮台将会射出分裂射线，形成3处高热同心弧。"}}
D.ClientTexts.JournalSection[8411]={Name={["1a4c97591f75e5fa:24"]="超载的电磁体"},Description={["eaf15baaa26db6df:118"]="超载后，电磁体会阶段性改变磁性，将玩家或锯刃引向或推离电磁体。"}}
D.ClientTexts.JournalSection[8412]={Name={["20071f5b07893d28:23"]="超载的蛛形地雷"},Description={["b0afc1141171d5f9:156"]="超载后，蛛形地雷将在内部激活构造矩阵，使其在被摧毁后可以生成两枚全新的地雷。"}}
D.ClientTexts.JournalSection[8413]={Name={["fe135f40f2009323:6"]="崩裂"},Description={["dc07f2a1579aeff2:128"]="混合物在生命值降至50%时，每损失10%生命值，它都会放出逸出的腐蚀具象。"}}
D.ClientTexts.JournalSection[8414]={Name={["bc92cd153cd51614:12"]="残渣烙印"}}
D.ClientTexts.JournalSection[8415]={Name={["bc787e5dc6cc9ea6:12"]="衰竭"}}
D.ClientTexts.JournalSection[8417]={Name={["a7ef2e3fdc02604a:22"]="第一阶段：把她打下来！"},Description={["7fb8bd8e23543ef3:260"]="督军扎伊拉派出手下最精锐的龙喉士兵参战。两名守卫监视并保护着高处塔楼上的防空火炮。击败这些守卫可以让玩家获得防空火炮的控制权。\r\n\r\n两次时机恰到好处的火炮射击就可以击落迦拉卡斯。"}}
D.ClientTexts.JournalSection[8418]={Name={["e41cadf1339e2caa:37"]="第二阶段：迦拉卡斯，末裔"}}
D.ClientTexts.JournalSection[8419]={Name={["d36eac5f929399f6:13"]="辐射烈焰"}}
D.ClientTexts.JournalSection[8420]={Name={["bcc4726534853ad8:17"]="迦拉克隆之焰"}}
D.ClientTexts.JournalSection[8421]={Name={["fbccab1fa72046f2:16"]="高阶军官"}}
D.ClientTexts.JournalSection[8422]={Name={["9e94fc8fb5d7dcb0:21"]="首席炮兵达戈林"}}
D.ClientTexts.JournalSection[8423]={Name={["29fd82a7878eb2de:24"]="中将库古克"}}
D.ClientTexts.JournalSection[8424]={Name={["72d54d70cae5b6b5:19"]="高等执法官萨诺克"}}
D.ClientTexts.JournalSection[8425]={Name={["e6704dbef3fbfc17:14"]="“毒蛇”高贾拉"}}
D.ClientTexts.JournalSection[8426]={Name={["ce97b1bf5b75cac0:20"]="龙喉黑锋追猎者"},Description={["2367c5779a85c3cc:170"]="在高贾拉的命令下，这些潜行单位将从随机目标身后的阴影中现身，疯狂背刺。任何在其攻击范围内的玩家都会受到大量物理伤害。"}}
D.ClientTexts.JournalSection[8427]={Name={["bb11b1c2899e233f:12"]="步兵"}}
D.ClientTexts.JournalSection[8428]={Name={["dd5d9a659dff89f4:20"]="龙喉碎骨者"},Description={["717806efc1c901e0:129"]="这些致命的战士将向远处的阵营领袖冲锋，使其昏迷。当目标昏迷时，他们将持续对目标发动致命攻击。"}}
D.ClientTexts.JournalSection[8429]={Name={["3bf03b7ec97c19d3:21"]="龙喉火箭手"},Description={["5049b6c715b19642:141"]="这些致命的弓箭手对随机玩家射出烈焰箭矢。击中后将造成火焰伤害，然后燃烧地面并对站立其上的所有玩家造成伤害。"}}
D.ClientTexts.JournalSection[8430]={Name={["6c566df5d0e27780:14"]="龙喉步兵"},Description={["313990a838d325a3:114"]="龙喉步兵涌入战场，以毁灭性的攻击粉碎敌人。他们还会朝远处的敌人投掷威力巨大的战斧。"}}
D.ClientTexts.JournalSection[8431]={Name={["9deb776bc912cc58:20"]="龙喉潮汐萨满"},Description={["594e1f725996064f:105"]="龙喉潮汐萨满会对盟友施放治疗法术，并召唤汹涌的潮汐奔涌攻击敌人。"}}
D.ClientTexts.JournalSection[8432]={Name={["c348e43c12dc412d:19"]="龙喉斩风者"},Description={["a7fde2db3d8afa6e:147"]="骑在始祖龙身上的龙喉斩风者会对随机玩家扔出旋风斧，造成物理伤害。他们还会网住随机玩家，将其定身在原地。"}}
D.ClientTexts.JournalSection[8433]={Name={["827ad6f8c16b41ef:18"]="不稳定的腐蚀"}}
D.ClientTexts.JournalSection[8434]={Name={["0c7da1ec10da0f33:9"]="魔古箱子"}}
D.ClientTexts.JournalSection[8435]={Name={["da576991279ec78e:11"]="螳螂妖箱子"}}
D.ClientTexts.JournalSection[8436]={Name={["0c7da1ec10da0f33:9"]="魔古箱子"}}
D.ClientTexts.JournalSection[8437]={Name={["da576991279ec78e:11"]="螳螂妖箱子"}}
D.ClientTexts.JournalSection[8438]={Name={["0c7da1ec10da0f33:9"]="魔古箱子"}}
D.ClientTexts.JournalSection[8439]={Name={["da576991279ec78e:11"]="螳螂妖箱子"}}
D.ClientTexts.JournalSection[8440]={Name={["eacc8bad491fa610:9"]="自惑"}}
D.ClientTexts.JournalSection[8441]={Name={["8bc43bfb882102f4:19"]="剧毒利刃"}}
D.ClientTexts.JournalSection[8442]={Name={["557f63741e0fc00d:11"]="毒性云雾"}}
D.ClientTexts.JournalSection[8443]={Name={["e7b230e1abb7bab4:12"]="毒液诅咒"},Description={["c9b27f9a0e8e6fcf:130"]="当高贾拉生命值过低时，她的毒液诅咒就会生效。她将变成一条毒蛇，在被击败之前持续施放毒箭弹幕。"}}
D.ClientTexts.JournalSection[8444]={Name={["c471102e7e5df1dd:16"]="粉碎顺劈"}}
D.ClientTexts.JournalSection[8445]={Name={["e281b9d7068c77b2:13"]="碎骨者的召唤"}}
D.ClientTexts.JournalSection[8446]={Name={["105af072a10b4fbf:5"]="射击"},Description={["6fcd95be284ec8ed:56"]="达戈林对附近的随机玩家射击，造成严重伤害。"}}
D.ClientTexts.JournalSection[8447]={Name={["14ef9d9b3cb6854c:11"]="弹幕压制"}}
D.ClientTexts.JournalSection[8448]={Name={["c47fcb1ff01671dc:11"]="雷霆一击"},Description={["47ebfccd9a77d572:93"]="库古克的强力践踏震碎地面，使附近玩家的移动速度降低。该效果可以叠加。"}}
D.ClientTexts.JournalSection[8449]={Name={["3f8700b5d2d8e6cc:11"]="圆弧斩"}}
D.ClientTexts.JournalSection[8460]={Name={["10e0e6a4de411c03:5"]="祖印"}}
D.ClientTexts.JournalSection[8461]={Name={["a63cb00c3b0daf6d:9"]="项林"}}
D.ClientTexts.JournalSection[8462]={Name={["fc29930468510571:7"]="君威"}}
D.ClientTexts.JournalSection[8463]={Name={["e07072a6fe6ae30d:12"]="暗影箭雨"}}
D.ClientTexts.JournalSection[8464]={Name={["09f95165640e9586:6"]="昆达"}}
D.ClientTexts.JournalSection[8465]={Name={["cee2a541528a66c2:8"]="碎地"}}
D.ClientTexts.JournalSection[8466]={Name={["f0e54baa8df6fb57:10"]="熔岩之拳"}}
D.ClientTexts.JournalSection[8467]={Name={["375318bbbcf37bfa:11"]="玉火风暴"}}
D.ClientTexts.JournalSection[8468]={Name={["752599c95fc58018:8"]="龙威显赫"}}
D.ClientTexts.JournalSection[8469]={Name={["7b510c841f88a829:13"]="不稳定的火花"}}
D.ClientTexts.JournalSection[8470]={Name={["8a2c3ec1fa04fb68:12"]="酸性血液"}}
D.ClientTexts.JournalSection[8471]={Name={["23fb1c4fd34f4836:15"]="血腥爆裂"}}
D.ClientTexts.JournalSection[8472]={Name={["7c9c6c6593835456:4"]="捕掠"}}
D.ClientTexts.JournalSection[8473]={Name={["1d095e2be93a6ca0:14"]="变异缺陷"},Description={["d8f83b0fd6fe0d80:141"]="在英雄难度下，被变异的玩家会受到变异缺陷影响。如果玩家没能在变异缺陷持续时间内对琥珀寄生虫使用捕掠，那么该玩家将会死亡。"}}
D.ClientTexts.JournalSection[8474]={Name={["002c139bdc59f1f2:9"]="急速射击"}}
D.ClientTexts.JournalSection[8475]={Name={["1046f818caaca71d:5"]="飞掠"}}
D.ClientTexts.JournalSection[8476]={Name={["7afc8a5022efac73:24"]="充能的防御矩阵"}}
D.ClientTexts.JournalSection[8477]={Name={["41ac84c96d92268e:15"]="被吞噬的勇气"}}
D.ClientTexts.JournalSection[8478]={Name={["9b28754f7e376dda:13"]="被吞噬的信念"}}
D.ClientTexts.JournalSection[8479]={Name={["ddeb492fb2d59244:12"]="被吞噬的希望"}}
D.ClientTexts.JournalSection[8480]={Name={["6330d3c45e84cfc5:18"]="虚无腐蚀"},Description={["b44f54c3006b014c:98"]="虚无腐蚀潜伏在煞魔领域内，立即杀死接触到的玩家。"}}
D.ClientTexts.JournalSection[8481]={Name={["badfb00968e34bb2:14"]="信息素云团"}}
D.ClientTexts.JournalSection[8482]={Name={["1739618974ad4a3a:8"]="邪恶链接"},Description={["e1b2ecb86cea49b7:81"]="从冷静的试炼中被释放的生物将会把自己受到的伤害复制给腐蚀混合物。"}}
D.ClientTexts.JournalSection[8484]={Name={["f202c53fe3827316:6"]="盟友"}}
D.ClientTexts.JournalSection[8485]={Name={["d5eebc4c3be3c871:22"]="希尔瓦娜斯·风行者"},Description={["9c3ca5e0bb442993:86"]="希尔瓦娜斯·风行者的利箭极其精准地射向敌人，偶尔会唤醒死者为其作战。"}}
D.ClientTexts.JournalSection[8486]={Name={["b44bc9ce2e6efa2f:23"]="大法师艾萨斯·夺日者"}}
D.ClientTexts.JournalSection[8487]={Name={["f16c51dc44e8c105:11"]="烈焰风暴"}}
D.ClientTexts.JournalSection[8488]={Name={["cee2a541528a66c2:8"]="断骨"}}
D.ClientTexts.JournalSection[8489]={Name={["c514d60c04b687f1:16"]="治疗之潮图腾"}}
D.ClientTexts.JournalSection[8490]={Name={["99e5e94ac63ad845:16"]="洛瑟玛·塞隆"},Description={["489879d6ed4402d7:125"]="洛瑟玛挥舞辛多雷巨剑与疯狂冲锋的敌人奋勇作战，还会用手中的附魔强弓将漏网之鱼悉数击杀。"}}
D.ClientTexts.JournalSection[8532]={Name={["9e4edfd09b4307dd:19"]="龙喉掌旗官"}}
D.ClientTexts.JournalSection[8533]={Name={["06ce27de5ef68a41:18"]="库卡隆投石车"}}
D.ClientTexts.JournalSection[8534]={Name={["495dd1b17e27e7dc:11"]="猩红强酸"}}
D.ClientTexts.JournalSection[8535]={Name={["53aeebaaa202c215:14"]="拆毁小队"},Description={["295366e6a4b9ec41:137"]="拆毁小队会试图攻破防空塔的大门。如果不对其加以保护，破门进程就会被打断。"}}
