D.ClientTexts.JournalSection[8581]={Name={["e3e44e8b1ad46b46:14"]="迸发！"}}
D.ClientTexts.JournalSection[8582]={Name={["6f9746593c20c9c4:11"]="饥饿的雪人"}}
D.ClientTexts.JournalSection[8583]={Name={["7b94775a3d04dbaf:12"]="摧枯拉朽"}}
D.ClientTexts.JournalSection[8584]={Name={["20feb1c7750e93b2:14"]="被囚禁的洞穴蝙蝠"}}
D.ClientTexts.JournalSection[8585]={Name={["c8ed3a7ed7e93c85:14"]="吸血狂乱"}}
D.ClientTexts.JournalSection[8586]={Name={["7a79bd2d0ae9a318:20"]="龙喉始祖幼龙"},Description={["d17065fc432a3bc5:62"]="龙喉始祖幼龙会对正前方锥形区域内的敌人引导一道烈焰吐息。"}}
D.ClientTexts.JournalSection[8587]={Name={["7a79bd2d0ae9a318:20"]="龙喉始祖幼龙"},Description={["d17065fc432a3bc5:62"]="龙喉始祖幼龙会对正前方锥形区域内的敌人引导一道烈焰吐息。"}}
D.ClientTexts.JournalSection[8620]={Name={["06b9a46a64db524f:7"]="戈杜哈"}}
D.ClientTexts.JournalSection[8621]={Name={["f123225f6ab73ec8:10"]="玛格莫拉图斯"},Description={["f303965deb9f80fe:62"]="玛格莫拉图斯用大地和烈焰的力量对玩家发动猛烈攻击。"}}
D.ClientTexts.JournalSection[8622]={Name={["55de9e97953f1e82:27"]="鲁因纳逊，大地仆从"}}
D.ClientTexts.JournalSection[8623]={Name={["c6acd15274aadf99:12"]="熔火冲击"}}
D.ClientTexts.JournalSection[8624]={Name={["51d8e13453a5a431:12"]="粉碎大地"}}
D.ClientTexts.JournalSection[8625]={Name={["72133066b7fc21a3:10"]="蛮力猛击"}}
D.ClientTexts.JournalSection[8626]={Name={["c5bb16a3346be692:26"]="卡拉米特，烈焰仆从"}}
D.ClientTexts.JournalSection[8627]={Name={["12074731add03e10:13"]="舞动之焰"}}
D.ClientTexts.JournalSection[8628]={Name={["7e1c7c00ec844873:9"]="火焰风暴"}}
D.ClientTexts.JournalSection[8629]={Name={["1b5e8f279f52efb8:6"]="灼烧"}}
D.ClientTexts.JournalSection[8630]={Name={["d8ef1d3c04ec23b9:12"]="熔岩蔽天"}}
D.ClientTexts.JournalSection[8631]={Name={["d920bb8bfa32c114:15"]="熔岩元素"}}
D.ClientTexts.JournalSection[8632]={Name={["d8ef1d3c04ec23b9:12"]="熔岩蔽天"}}
D.ClientTexts.JournalSection[8633]={Name={["2bfa9f9fe4c72140:15"]="熔火之怒"}}
D.ClientTexts.JournalSection[8634]={Name={["4ab1138e1e28de4f:15"]="凋零之焰"}}
D.ClientTexts.JournalSection[8635]={Name={["153bee0834f3619d:9"]="熔渣猛击"}}
D.ClientTexts.JournalSection[8636]={Name={["4d1ef3d1a600cede:13"]="元素聚焦"}}
D.ClientTexts.JournalSection[8637]={Name={["cc201e16aa6f7195:16"]="晶焰图腾"}}
D.ClientTexts.JournalSection[8638]={Name={["f00f3bc14bd6cda4:15"]="烈日图腾"}}
D.ClientTexts.JournalSection[8639]={Name={["a90fdf595a8767d4:21"]="剃刀沼泽血纹卫士"}}
D.ClientTexts.JournalSection[8640]={Name={["68b2b2d65719c517:11"]="阴冷打击"}}
D.ClientTexts.JournalSection[8641]={Name={["92e53477d772c7f6:18"]="剃刀沼泽狩猎大师"}}
D.ClientTexts.JournalSection[8642]={Name={["bf8947cc172192ef:19"]="毒箭弹幕"}}
D.ClientTexts.JournalSection[8643]={Name={["9ce50f51fbb2a0ae:20"]="剃刀沼泽狩猎者"}}
D.ClientTexts.JournalSection[8672]={Name={["cfcbb6f356f2f994:9"]="生命吸取"}}
D.ClientTexts.JournalSection[8673]={Name={["610057ea6df8d283:15"]="烈焰侍从"}}
D.ClientTexts.JournalSection[8674]={Name={["9e6916f6029cd4af:7"]="地狱火"}}
D.ClientTexts.JournalSection[8675]={Name={["52fbb99742b1e8fe:16"]="元素束缚"}}
D.ClientTexts.JournalSection[8676]={Name={["b5fc4d6dffdee164:24"]="剧毒倾泻水晶"}}
D.ClientTexts.JournalSection[8677]={Name={["85cbc28ba5f0f412:17"]="剧毒倾泻"}}
D.ClientTexts.JournalSection[8678]={Name={["082bbe3797d331fe:19"]="潮汐风暴水晶"}}
D.ClientTexts.JournalSection[8679]={Name={["71ece295570c15f8:12"]="潮汐风暴"}}
D.ClientTexts.JournalSection[8680]={Name={["dfd999c72eb45a9a:20"]="熔岩恶火水晶"}}
D.ClientTexts.JournalSection[8681]={Name={["9de9a025c60edc5c:13"]="熔岩恶火"}}
D.ClientTexts.JournalSection[8682]={Name={["85c2014ec6bf47e1:18"]="水晶之令"},Description={["061b5115a99e4a7e:199"]="卡尔加在水晶操控方面的力量空前强大，使其可以号令强大的水晶体在战斗中协助她。这些水晶体无法被攻击。\r\n\r\n卡尔加同时最多控制2个水晶体。"}}
D.ClientTexts.JournalSection[8683]={Name={["4ea1c94727d32fee:11"]="琥珀监牢"},Description={["1d173a6cf029f6c3:199"]="瑟拉提克琥珀诱捕者随机将一名玩家囚禁于琥珀内，使其昏迷直到被救出。\r\n\r\n玩家可以打碎琥珀监牢并救出困于其中的盟友。摧毁监牢的玩家将受到残渣的影响。"}}
D.ClientTexts.JournalSection[8684]={Name={["3f240176e8ce0aab:7"]="残渣"}}
D.ClientTexts.JournalSection[8814]={Name={["39f9d47585e31082:26"]="第一阶段：黑石熔炉"},Description={["5ad6f2504195ef9b:102"]="黑手会将熔火炉渣倾倒进房间里，这些炉渣会随着战斗进程缓慢侵占玩家的战斗空间。"}}
D.ClientTexts.JournalSection[8816]={Name={["3a978dd5edc9ebd4:25"]="第二阶段：武器库"},Description={["3dd696bd729e0db8:79"]="黑手坐拥大量致命的攻城武器，并且会从楼上平台召来援军。"}}
D.ClientTexts.JournalSection[8817]={Name={["9099bca62ebb1717:14"]="死亡标记"}}
D.ClientTexts.JournalSection[8818]={Name={["7ac659ec75ec9351:23"]="第三阶段：钢铁熔炉"},Description={["0d6e633aa7f3a9f7:63"]="钢铁熔炉已在黑石熔炉被摧毁后得到硬化。"}}
D.ClientTexts.JournalSection[8819]={Name={["1efa45ac907758a3:10"]="过热"}}
D.ClientTexts.JournalSection[8835]={Name={["0d2b9386710a9f85:9"]="四风呼啸"},Description={["7ba0092d6938ec34:116"]="施法者制造出一股强劲旋风向四个方向移动。旋风会对触碰到的敌人造成自然伤害。"}}
D.ClientTexts.JournalSection[8836]={Name={["e5ef9e787e2676bd:12"]="穿刺突击"},Description={["1ccd5795c4077e5c:79"]="施法者奋力一击，对其目标造成大量的物理伤害。"}}
D.ClientTexts.JournalSection[8837]={Name={["ee22bf03404c8b62:13"]="回旋利刃"},Description={["2f2b9c2783b3e488:87"]="施法者召唤出回旋利刃，对其行进路线上的所有敌人造成物理伤害。"}}
D.ClientTexts.JournalSection[8838]={Name={["ac85d9dac905c785:11"]="散刃"}}
D.ClientTexts.JournalSection[8839]={Name={["e8dc1d6785175bd2:8"]="风墙"},Description={["fe65f8c875830caf:150"]="兰吉特随机向一名敌人的位置掷出风之飞轮，落地后形成一道旋转的风墙。风墙对其范围内的所有敌人造成自然伤害。"}}
D.ClientTexts.JournalSection[8840]={Name={["105d734182cc8b5c:5"]="猛击"},Description={["020efc0f2e5f5b34:77"]="施法者猛击地面，对区域内的所有敌人造成大量物理伤害。"}}
D.ClientTexts.JournalSection[8841]={Name={["0f2e7e157cafc9e0:5"]="爆能"}}
D.ClientTexts.JournalSection[8842]={Name={["b9149c7e479ebf43:8"]="充能"}}
D.ClientTexts.JournalSection[8849]={Name={["ce322d1ec349f597:11"]="穿刺护甲"}}
D.ClientTexts.JournalSection[8850]={Name={["7057a450e4e5358d:10"]="太阳耀斑"}}
D.ClientTexts.JournalSection[8851]={Name={["17f6945f1f849c0e:6"]="飞羽"}}
D.ClientTexts.JournalSection[8852]={Name={["18a6bac856f038c1:8"]="扔下"},Description={["3bc5537fd3c996de:72"]="高阶贤者维里克斯召唤一名拜日狂信徒攫取一名玩家并将他们扔下露台。"}}
D.ClientTexts.JournalSection[8853]={Name={["73cf3721427d5ad0:9"]="眩光"}}
D.ClientTexts.JournalSection[8854]={Name={["70147a368051181f:10"]="日光冲击"}}
D.ClientTexts.JournalSection[8855]={Name={["c6d8b5bcb362d739:9"]="护盾"}}
D.ClientTexts.JournalSection[8856]={Name={["16b62766f4aa2155:11"]="势大力沉"},Description={["14c69fdc703e9425:139"]="屠夫的所有标准自动攻击都能对5码范围内离主目距离最近的目标触发第二次攻击。如果没有发现目标，则由主目标承受第二次攻击。"}}
D.ClientTexts.JournalSection[8857]={Name={["5b0c090848ea6a4d:10"]="切肉刀"}}
D.ClientTexts.JournalSection[8858]={Name={["384c3b422a8a22c3:13"]="捶肉槌"}}
D.ClientTexts.JournalSection[8859]={Name={["f6a91ff5c64c0874:6"]="顺劈斩"}}
D.ClientTexts.JournalSection[8860]={Name={["992dc76b75f39db8:14"]="旋转跳劈"},Description={["188413c7ca51651e:149"]="当屠夫的能量值达到100点时，他将发动旋转跳劈，击退所有玩家，向远处一群玩家冲锋并在到达时顺劈目标。"}}
D.ClientTexts.JournalSection[8861]={Name={["aa15071a78facb1f:13"]="龟裂创伤"}}
D.ClientTexts.JournalSection[8862]={Name={["fe1564c3a6c630d4:6"]="狂暴"},Description={["317faafdbed053a2:113"]="当屠夫的生命值降至30%时，他将狂暴。在狂暴状态下的屠夫，其伤害值将提高10%，攻击速度提高30%。"}}
D.ClientTexts.JournalSection[9224]={Name={["9a465fa2ac403943:12"]="穿刺护甲"}}
D.ClientTexts.JournalSection[9225]={Name={["68545ead0b4c399e:9"]="阳炎打击"}}
D.ClientTexts.JournalSection[9226]={Name={["875fa4e295049fc7:7"]="尖啸"}}
D.ClientTexts.JournalSection[9251]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["5d8037f3d93a0746:381"]="加尔鲁什召唤库卡隆战士加入战斗，与此同时，攻城技师会启动钢铁之星来碾压场内的玩家和兽人。\r\n\r\n当加尔鲁什的生命值低至10%时，他会吸取亚煞极之心的能量。他会周期性将所有玩家带入亚煞极之境，玩家在这个阶段必须阻止加尔鲁什吸取心脏能量。\r\n\r\n当他的生命值第二次达到10%时，他会完成吸取心脏的能量，并强化他的技能，直到战斗结束。"}}
D.ClientTexts.JournalSection[9252]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[9253]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[9254]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[9256]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["f499c6e32c0eb636:219"]="锻造大师戈杜哈会召唤出两个强大的元素生物来拖延时间。\r\n\r\n当锻造大师遭受重创时，玛格莫拉图斯会从熔炉里逃出来并攻击玩家。玛格莫拉图斯会周期性地召唤熔岩元素来协助他。"}}
D.ClientTexts.JournalSection[9257]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[9258]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[9259]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[9260]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["6d169448991d934b:146"]="兰吉特对飞轮的使用可谓得心应手，他能制造快速旋转移动的风墙来造成伤害。玩家需要不停地移动来躲避那些风墙，以免遭受不必要的伤害。"}}
D.ClientTexts.JournalSection[9264]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["475af7ab24cb03a2:139"]="阿拉卡纳斯站在大片日光辐射区域的中心位置，以引导光线的方式来吸收太阳能量。一旦吸收到，便会为自己恢复生命值。"}}
D.ClientTexts.JournalSection[9268]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["dc1bdd6a4bcd563b:172"]="鲁克兰就在铺有灰烬堆的平台外盘旋。这只炽烈的火鸟会制造太阳耀斑来追击玩家。这些太阳耀斑会一直追着玩家直到被击杀为止，它们被击杀时会发生爆炸，并激活附近的灰烬堆。"}}
D.ClientTexts.JournalSection[9272]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["a2a8339365862806:128"]="高阶贤者维里克斯会激活强大的聚焦射线来烧灼地面攻击敌人，同时他也会召唤防护构装体进场保护他。"}}
D.ClientTexts.JournalSection[9276]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["943de05fe9f6fe4c:220"]="守奴人库鲁斯托会用极具碾压性的力量攻击玩家队伍，并使其脚下的地面崩裂。\r\n\r\n他会周期性召唤被俘的矿工来为他作战，但其中一些奴隶会倒戈支持玩家队伍，趁此机会获得自由。"}}
D.ClientTexts.JournalSection[9277]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[9278]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[9310]={Name={["27e76645c9f8fb1c:16"]="狼之狡黠"}}
D.ClientTexts.JournalSection[9279]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[9280]={Name={["cc2a5cb647c65d91:19"]="守奴人库鲁斯托"},Description={["9a483a23c48b14f2:88"]="库鲁斯托疯狂地攻击玩家，并会周期性召唤被俘的矿工加入战斗。"}}
D.ClientTexts.JournalSection[9281]={Name={["018cc5bed5da4171:10"]="地面碾压"}}
D.ClientTexts.JournalSection[9282]={Name={["edab9eca75f1fe97:13"]="凶猛咆哮"}}
D.ClientTexts.JournalSection[9283]={Name={["e42fc802a402fe2f:8"]="狂野猛击"}}
D.ClientTexts.JournalSection[9284]={Name={["3e6c4848cd8f8639:14"]="呼叫矿工"}}
D.ClientTexts.JournalSection[9285]={Name={["9a699ff8c6aaa641:13"]="被俘的矿工"},Description={["757d0656fa345a9f:99"]="被俘的矿工被迫为他们的主人作战，但某些矿工可能会在注意到你的阵营后，转而与你并肩战斗。"}}
D.ClientTexts.JournalSection[9286]={Name={["43b0b721fb5f681a:15"]="挫伤打击"}}
D.ClientTexts.JournalSection[9287]={Name={["6c415aaa67e1b64f:12"]="重压跳跃"}}
D.ClientTexts.JournalSection[9288]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["da9b5979226234cc:183"]="屠夫的攻击冷酷无情，他会用极具毁灭性的双持武器劈砍敌人。他的主要攻击技能针对聚集在一起的敌人，所以想要对付他的攻击，站位是关键。"}}
D.ClientTexts.JournalSection[9289]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[9290]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[9291]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[9292]={Name={["a50785bbf62c26c6:27"]="第一阶段：狂乱的锻造大师"},Description={["02b00440d9483ddb:90"]="戈杜哈使用熔岩突袭玩家，并匆忙召唤出元素来保护他。"}}
D.ClientTexts.JournalSection[9293]={Name={["5de76cf264066fd1:22"]="第二阶段：熔岩之灾"},Description={["c600376535582e7c:85"]="当戈杜哈遭受重伤后，强大的元素生物玛格莫拉图斯会逃出并制造灾难。"}}
D.ClientTexts.JournalSection[9294]={Name={["5b810a5c11785ad9:8"]="综述"}}
D.ClientTexts.JournalSection[9295]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[9296]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[9297]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[9298]={Name={["417ca3c8f685ac47:22"]="第一阶段：凶猛之足"},Description={["b4a07d9b27b7f09e:27"]="达玛克徒步开始战斗。"}}
D.ClientTexts.JournalSection[9299]={Name={["6705e92dec97428e:15"]="兽王达玛克"}}
D.ClientTexts.JournalSection[9300]={Name={["03b6bba3108b3dd8:23"]="第二阶段：驾驭野兽"},Description={["552c34969caf3a3d:45"]="兽王达玛克跳到最近的原兽背上。"}}
D.ClientTexts.JournalSection[9301]={Name={["555fc63c43983c21:9"]="虐牙"}}
D.ClientTexts.JournalSection[9302]={Name={["f05c791a56d2edc5:9"]="恐翼"}}
D.ClientTexts.JournalSection[9303]={Name={["489ad9197ea2ad60:11"]="碎铁"}}
D.ClientTexts.JournalSection[9304]={Name={["135e4309be6ba9b6:9"]="弗特莱"}}
D.ClientTexts.JournalSection[9305]={Name={["ae2721245e566ef7:7"]="长矛钉刺"}}
D.ClientTexts.JournalSection[9306]={Name={["b1e920e11e29936c:11"]="召唤兽群"}}
D.ClientTexts.JournalSection[9307]={Name={["33038dd3c8021166:9"]="兽群"}}
D.ClientTexts.JournalSection[9308]={Name={["a8e1a632e02d9da1:10"]="血之气息"}}
D.ClientTexts.JournalSection[9311]={Name={["41fc0f79f9557b46:16"]="双头飞龙之魂"}}
D.ClientTexts.JournalSection[9312]={Name={["ea35d0e925f26a36:13"]="灼热余烬"}}
D.ClientTexts.JournalSection[9313]={Name={["da383cd594f9cadc:13"]="烈焰灌注"}}
D.ClientTexts.JournalSection[9314]={Name={["343e480db2e446ba:14"]="雷象之怒"}}
D.ClientTexts.JournalSection[9315]={Name={["5d6bc849fa61fd54:19"]="裂蹄之心"}}
