D.ClientTexts.JournalSection[9586]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["ee8fb99b7a8917e6:368"]="独眼魔双子会在能量达到特定阶段时使用特殊技能攻击玩家。能量达到33点时，一名独眼魔会使用他的特殊武器攻击。能量达到66点时，一名独眼魔会进行一次强力咆哮。最终，当能量达到100点时，一名独眼魔会发起一次强力的全团攻击。\r\n\r\n两名独眼魔之间的距离越远，他们的急速就会越高，施法时间也越短。相对的，玩家对其各个技能的应对时间也越短。"}}
