D.ClientTexts.JournalSection[9636]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["cec34bab266af0d4:364"]="这场战斗的目标是摧毁铸造厂的大型熔炉。玩家必须先关闭爆裂熔炉的温度调节器，这会释放出山脉之心。炽热的怒炎之灵是熔炉强大力量的来源。此后元素尊者会加入战斗，并通过引导光束来控制狂暴的怒炎之灵。一旦玩家击败了所有的元素尊者，山脉之心就会重获自由，并直接和玩家进行战斗。"}}
