D.ClientTexts.JournalSection[9707]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["66ccaa50cb0efbc7:224"]="当生命值降至60%时，尼托格·雷塔会撤退到火车远端的突击队火炮上。玩家必须消灭不断涌入战场的士兵来获得黑石军火，并用来摧毁尼托格的大炮。一旦摧毁大炮后，就会直面尼托格了。"}}
