D.ClientTexts.JournalSection[9759]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["9c5588cc5950a659:167"]="纳利什利用幽灵来攻击敌人，召唤出强大的虚空能量，并周期性地将玩家放逐到异位面中。在那里，玩家必须击败并夺回自己的灵魂以逃出生天。"}}
