D.ClientTexts.JournalSection[9823]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["35733cee72bd7b49:98"]="警戒者使用炽燃射线在地面上进行切割，并投掷手臂上的盾牌来突袭敌人。"}}
D.ClientTexts.JournalSection[9824]={Name={["7dd0deba6e94227d:10"]="神圣之盾"}}
D.ClientTexts.JournalSection[9825]={Name={["90052088ac2b41c1:16"]="圣洁之光"}}
D.ClientTexts.JournalSection[9826]={Name={["e00fc0717379464c:16"]="聖化打擊"}}
D.ClientTexts.JournalSection[9827]={Name={["41ff26e469ace387:14"]="神圣之地"}}
D.ClientTexts.JournalSection[9828]={Name={["7c96aa25b9ef28ec:4"]="命运"}}
D.ClientTexts.JournalSection[9829]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["cedf6ba01fe5affb:184"]="元素师戈洛克会投掷熔岩石块来轰击敌人。他会周期性地召唤不稳定的熔渣元素，这些元素会缓慢朝熔炉移动。一旦不稳定的熔渣元素接近到熔炉，就会获得毁灭性的能量。"}}
D.ClientTexts.JournalSection[9830]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["abb80a437d55bd18:170"]="缚魂者尼娅米肆意扭曲奥金顿虔信者的灵魂，命其为她作战。在与这些灵魂战斗时，玩家还需要提防致命的环形法术：灵魂容器。"}}
D.ClientTexts.JournalSection[9831]={Name={["0de275ba18543955:15"]="缚魂者尼娅米"}}
D.ClientTexts.JournalSection[9832]={Name={["77432b698649bd74:9"]="心灵尖刺"}}
D.ClientTexts.JournalSection[9833]={Name={["b5f16ee9247bf006:15"]="暗言术：痛"}}
D.ClientTexts.JournalSection[9834]={Name={["16af681a37a1a3e9:10"]="灵魂容器"}}
D.ClientTexts.JournalSection[9835]={Name={["1f0c111625c4692b:11"]="分裂的残魂"}}
D.ClientTexts.JournalSection[9836]={Name={["f8eac37af47d62e9:15"]="恶毒的仲裁者"}}
D.ClientTexts.JournalSection[9837]={Name={["c1bc3e028c1c04fb:15"]="仲裁者之锤"}}
D.ClientTexts.JournalSection[9838]={Name={["7225754e7272d009:11"]="光辉之怒"}}
D.ClientTexts.JournalSection[9839]={Name={["defb5206fedd91cb:12"]="扭曲的魔导师"}}
D.ClientTexts.JournalSection[9840]={Name={["2d524b20c376539b:10"]="奥术箭"}}
D.ClientTexts.JournalSection[9841]={Name={["2d524b2fc37753c8:10"]="奥术炸弹"}}
D.ClientTexts.JournalSection[9842]={Name={["d32712b380a592f6:15"]="邪恶的防御者"},Description={["70dfe296c919177d:71"]="邪恶的防御者装备有盾牌和单手锤，他们会狂热地保护缚魂者尼娅米。"}}
D.ClientTexts.JournalSection[9843]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["e00a0a9e91acce71:279"]="与汉斯加尔和弗兰佐克的战斗发生在一条黑石组装线上。\r\n\r\n每当生命值降低到某个特定阶段，两名孪生兽人中的一名会跳出战场，前去激活工厂生产线来协助战斗。传送带会运出灼热的黑铁矿石，而头顶上的大型冲压机会不时碾压玩家。"}}
D.ClientTexts.JournalSection[9844]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[9845]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[9846]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[9847]={Name={["c9d015a6e010b1f5:11"]="烈焰打击"}}
D.ClientTexts.JournalSection[9848]={Name={["7e9e8ecef194b261:15"]="断脊背摔"}}
D.ClientTexts.JournalSection[9849]={Name={["0d4450d5ee8f43c2:8"]="激动"},Description={["56c1c671b060b760:263"]="当汉斯加尔或弗兰佐克受到伤害时，他们的怒气值也会持续增长。\r\n\r\n随着怒气值的增长，激动效果也会得到强加，提高其造成的近战伤害，增加碎颅者丢出的飞锤数，缩短干扰怒吼的施法时间，并在泰山压顶期间获得更多次的跳跃。"}}
D.ClientTexts.JournalSection[9850]={Name={["b2391c68454ca9a5:12"]="血脉相连"}}
D.ClientTexts.JournalSection[9851]={Name={["0aa34bf7edb9673c:13"]="炽燃板甲"}}
D.ClientTexts.JournalSection[9852]={Name={["cd6c076f8f6fcb7a:14"]="灼热燃烧"}}
D.ClientTexts.JournalSection[9853]={Name={["919c5e6daf13a3b2:15"]="螺旋打桩"}}
D.ClientTexts.JournalSection[9855]={Name={["040018c91bb3e510:18"]="折脊碎椎"}}
D.ClientTexts.JournalSection[9856]={Name={["a61a57af31d88c86:10"]="余震"}}
D.ClientTexts.JournalSection[9857]={Name={["c0799a402bde861d:7"]="弗兰佐克"}}
D.ClientTexts.JournalSection[9858]={Name={["97efeb221f1926bb:14"]="干扰怒吼"}}
