D.ClientTexts.JournalSection[9899]={Name={["7a23e76fc980d776:18"]="狂莽突击"}}
D.ClientTexts.JournalSection[9900]={Name={["90cad06839fc091d:24"]="奥术愤怒：偏移"},Description={["cd444a49a72466da:206"]="奥术愤怒除了造成普通效果外，被打上烙印的玩家还不能移动到距离被标记点的10码范围以外。试图离开被标记区域的玩家会被传送到他们原来的地方。"}}
D.ClientTexts.JournalSection[9901]={Name={["bb5ad7282d8d4ba5:33"]="毁灭共鸣：偏移"},Description={["3667bc5452ccfbdd:91"]="毁灭共鸣除了造成普通效果，其影响范围还会在30秒内扩大至原来的两倍。"}}
D.ClientTexts.JournalSection[9902]={Name={["5ce86bc65ada50b5:24"]="混沌标记：偏移"},Description={["43446dfdef28a68e:77"]="除了受到普通混沌标记的效果，受影响的目标还会被传送至随机位置。"}}
D.ClientTexts.JournalSection[9903]={Name={["d59f39fb664a9e5a:22"]="奥能新星：偏移"},Description={["6455d381ddd29050:86"]="奥能新星除了造成普通效果，在爆炸时还会将玩家推向外侧。"}}
D.ClientTexts.JournalSection[9905]={Name={["019a9ec0aba5b02d:25"]="奥术愤怒：强固"},Description={["e3dee6823cf5cb4f:96"]="奥术愤怒除了造成普通效果，在每次弹跳之后的弹跳范围只会降低25%。"}}
D.ClientTexts.JournalSection[9906]={Name={["7e2b7d80deed0fa5:34"]="毁灭共鸣：强固"},Description={["f4fd26b0ae9d9e67:70"]="除了造成普通效果，毁灭共鸣将持续2分钟。"}}
D.ClientTexts.JournalSection[9907]={Name={["516ba5de09f14e95:25"]="混沌标记：强固"},Description={["e39d2b909ee9eb01:63"]="除了受到普通混沌标记的效果，目标还会被定身。"}}
D.ClientTexts.JournalSection[9908]={Name={["e0fc3ab328396a30:23"]="奥能新星：强固"}}
D.ClientTexts.JournalSection[9910]={Name={["9c0133e9190da8c6:23"]="奥术愤怒：复制"},Description={["58729e68efe07e21:94"]="奥术愤怒除了造成普通效果，在首次弹跳之后会额外在一名玩家身上打下烙印。"}}
D.ClientTexts.JournalSection[9911]={Name={["9d4b62a9945b443e:32"]="毁灭共鸣：复制"},Description={["bdfc9336b12fd5bf:123"]="毁灭共鸣除了造成普通效果，在引爆或效果结束时会在附近产生两次毁灭共鸣。"}}
D.ClientTexts.JournalSection[9912]={Name={["0709db87922bfb2e:23"]="混沌标记：复制"}}
D.ClientTexts.JournalSection[9913]={Name={["9655371c7a14f449:21"]="奥能新星：复制"}}
