D.ClientTexts.JournalSection[9946]={Name={["77ab5cd4bbd1d4ad:26"]="位移的奥术畸兽"},Description={["04d05f30e3f95627:51"]="元首马尔高克会召唤一头位移的奥术畸兽。"}}
D.ClientTexts.JournalSection[9947]={Name={["3d9e1352a9c69a17:25"]="强化的奥术畸兽"},Description={["6294a7ae9b19b2f1:50"]="元首马尔高克会召唤一头强化的奥术畸兽。"}}
