D.ClientTexts.JournalSection[9960]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["a19a6874baca04c3:218"]="奥尔高格会利用他所储存的黑石矿石来攻击敌人。当黑石矿石消耗殆尽后，奥尔高格会开始暴走，疯狂搜寻新的黑石矿石来获得补充。一旦奥尔高格补满黑石矿石后，心满意足的他会停止滚动，并重新与玩家交战。"}}
D.ClientTexts.JournalSection[9961]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[9962]={Name={["3c1991e950918c9e:7"]="治疗者"}}
