D.ClientTexts.JournalSection[9964]={Name={["c8c9cd15e37edd78:13"]="疯狂进食"},Description={["88775890a3fd19bd:117"]="当自身的黑石矿石存量耗尽时，奥尔高格会在房间内疯狂地滚动，在寻找可吞食的矿物时碾压任何挡路者。"}}
D.ClientTexts.JournalSection[9965]={Name={["6cf28eaa871388d9:21"]="大地震颤"}}
D.ClientTexts.JournalSection[9966]={Name={["7dd4e708df245d37:11"]="如饥似渴"}}
D.ClientTexts.JournalSection[9967]={Name={["e6f7f74b09921de2:21"]="不稳定的炉渣爆炸"}}
D.ClientTexts.JournalSection[9968]={Name={["7a491342e58b15bb:11"]="翻滚之怒"}}
D.ClientTexts.JournalSection[9969]={Name={["0eddc3835f7aedfe:17"]="饱餐的屠杀者"},Description={["0c2616ba1bbb8091:83"]="吃饱之后的奥尔高格会使用他储存的矿物来释放强大的技能攻击他的敌人。"}}
D.ClientTexts.JournalSection[9970]={Name={["950b0a50a7b68b5f:16"]="呕吐黑石"}}
D.ClientTexts.JournalSection[9971]={Name={["010164c48f1312f3:11"]="酸液洪流"}}
