D.ClientTexts.JournalSection[9976]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["84c61d38894a5f0f:247"]="布兰肯斯波是从悬槌崖底被感染的水域中冒出来的，其散播出来的真菌蔓延若不加控制便会疯狂生长。玩家必须装备火焰喷射器来控制这些滑溜溜的苔藓，期间还要对付布兰肯斯波苏醒时制造出来的真菌生物。"}}
