D.ClientTexts.JournalSection[10055]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["59b0eaf299928673:316"]="常规方法无法击败泰克图斯。他会产生能量，当能量达到100时他会引发地质剧变。在地质剧变结束之前将泰克图斯的生命值降至0会使其碎裂，分裂成两个泰克图斯碎片。否则，泰克图斯会治疗自己并重新产生能量。\r\n\r\n每个泰克图斯碎片碎裂时会分裂成4个泰克图斯微粒。玩家需要杀死全部8个泰克图斯微粒来击败泰克图斯。"}}
D.ClientTexts.JournalSection[10056]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
