D.ClientTexts.JournalSection[10060]={Name={["406c71ded3ed31db:24"]="泰克图斯，活体之山"},Description={["7b46378760e64114:57"]="泰克图斯以完全形态进入战斗，能够造成全额伤害。"}}
D.ClientTexts.JournalSection[10061]={Name={["485df1555fb4f06e:24"]="拜夜缚地者"}}
D.ClientTexts.JournalSection[10062]={Name={["6e3b4db503a92a76:22"]="拜夜狂战士"}}
D.ClientTexts.JournalSection[10063]={Name={["ff2dd9049ccabe15:13"]="泰克图斯碎片"},Description={["0d827efc7b1bcd71:125"]="碎裂之后，泰克图斯的残骸会分裂成两个泰克图斯碎片。\r\n\r\n泰克图斯碎片拥有和泰克图斯一样的技能，但造成的伤害较低。"}}
D.ClientTexts.JournalSection[10064]={Name={["ff885327cf5213ea:12"]="泰克图斯微粒"},Description={["0fe256abcdfb4470:177"]="碎裂之后，泰克图斯碎片的残骸会分裂成四个泰克图斯微粒。\r\n\r\n泰克图斯微粒不再需要被碎裂。玩家杀死所有的微粒之后就能取得战斗的胜利。"}}
