D.ClientTexts.JournalSection[10090]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["9799387a8ca85abf:266"]="枯木在攻击玩家团队时会变得越来越脱水，不断消耗所储存的水源能量。当枯木的水源能量耗尽时，他会将自己扎根地下，同时引导周围湖边的小水滴为自己恢复活力。玩家可在那些小水滴抵达枯木根前摧毁它们，阻碍其恢复活力。"}}
D.ClientTexts.JournalSection[10091]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10092]={Name={["3c1991e950918c9e:7"]="治疗者"}}
