D.ClientTexts.JournalSection[10095]={Name={["7f2659fbeaf51e4a:11"]="脆弱表皮"}}
D.ClientTexts.JournalSection[10096]={Name={["4167268757c533bc:11"]="焦灼之息"}}
D.ClientTexts.JournalSection[10097]={Name={["60f87aea661ffbf5:15"]="失控蔓生"}}
D.ClientTexts.JournalSection[10098]={Name={["60f87aea661ffbf5:15"]="失控蔓生"},Description={["0e09b42309efe29e:105"]="当小水滴接触到失控蔓生时，后者会活化并开始攻击附近的玩家。"}}
D.ClientTexts.JournalSection[10100]={Name={["c71a5ee536ed04aa:15"]="小水滴"},Description={["fc0fc27c2ce469e1:127"]="从附近湖水中凝聚而成的小水滴会朝着枯木直线移动。每颗小水滴会为枯木恢复25点水源能量。"}}
D.ClientTexts.JournalSection[10101]={Name={["430be1789f9e9973:12"]="水之爆发"}}
D.ClientTexts.JournalSection[10102]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["870994884624fa5b:282"]="阿扎凯尔有两种作战方式：与玩家直接交战或者从恶魔世界阿古斯召唤援军，他会交替以这两种方式进行战斗。在阿扎凯尔召唤援军时他不能被攻击，因此玩家需要尽快杀死从传送门里出现的恶魔，以免被不断侵入的恶魔大军淹没。"}}
