D.ClientTexts.JournalSection[10139]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["55700f66704cdaaf:497"]="诺鲁什将所有玩家关进检疫空间中，并且从每位玩家身上提取一部分腐蚀来制造一个腐蚀混合物。这场战斗的目标是摧毁这个腐蚀混合物。\r\n\r\n要想对混合物造成全额伤害，玩家必须降低自己的腐蚀等级。为此，玩家可以与房间内存在的净化光芒互动并开始自省。自省的玩家会被拖入另一位面，在那里，他们必须面对一场针对其职责类型的挑战。挑战成功后，玩家将得到净化并可以对混合物造成全额伤害。"}}
D.ClientTexts.JournalSection[10140]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10141]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10142]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10143]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["fcbc39fda9fee896:404"]="每当玩家被傲之煞或其爪牙的任何技能击中一次，就会获得5点傲气值。诺鲁什会周期性地对部分玩家施加保护以免除该效果。玩家的傲气值越高，傲之煞的技能就会对其触发危险性越高的效果。\r\n\r\n当傲之煞的生命值降至30%时，它会消灭诺鲁什，但诺鲁什会在临死前清除所有玩家身上的傲气值。从这个阶段开始，玩家必须在被自身的傲气压倒之前击败傲之煞。"}}
