D.ClientTexts.JournalSection[10177]={Name={["066e218792600262:13"]="奥术师乔拉"},Description={["c6a1b2820378c577:86"]="塔隆戈尔腐蚀奥术师乔拉对秩序与创造的热情，获得毁灭术士的能力。"}}
