D.ClientTexts.JournalSection[10183]={Name={["4980bb2b48478a2c:15"]="守备官伊露恩"},Description={["d844c6af55f456e0:82"]="塔隆戈尔腐蚀守备官伊露恩对恶魔的炽热仇恨，获得恶魔学识术士的能力。"}}
