D.ClientTexts.JournalSection[10194]={Name={["2ed97ad413202c83:12"]="滑溜溜的苔藓"}}
D.ClientTexts.JournalSection[10195]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["60c96ab3fa36d6d8:366"]="玩家将突袭库卡隆重兵防守的塔楼，督军扎伊拉骑着她的始祖幼龙迦拉卡斯盘旋在空中。与此同时，联军的爆破师会炸开附近塔楼的大门，允许一支突击小队进入塔楼并且占领它。当两座塔楼都被占领之后，可以使用每座塔楼顶上的对空火炮来击落迦拉卡斯并开始最后的战斗。"}}
D.ClientTexts.JournalSection[10196]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10197]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10198]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10199]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["60c96ab3fa36d6d8:366"]="玩家将突袭库卡隆重兵防守的塔楼，督军扎伊拉骑着她的始祖幼龙迦拉卡斯盘旋在空中。与此同时，联军的爆破师会炸开附近塔楼的大门，允许一支突击小队进入塔楼并且占领它。当两座塔楼都被占领之后，可以使用每座塔楼顶上的对空火炮来击落迦拉卡斯并开始最后的战斗。"}}
D.ClientTexts.JournalSection[10200]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10201]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10202]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10203]={Name={["4a46a7e7e95b4dbc:12"]="死尸之息"}}
D.ClientTexts.JournalSection[10204]={Name={["ce58be8512e31bdc:15"]="爆裂灌注"}}
D.ClientTexts.JournalSection[10205]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["836b86532e5a8e30:286"]="钢铁战蝎会使用炮弹、激光和炸弹攻击玩家，同时积聚能量。当能量全满时，它会转入强攻模式，将它的爪子钻入地底，无法移动并使用新的攻击手段。钢铁战蝎的战斗会在上述两个阶段中转换，直到战斗结束。"}}
D.ClientTexts.JournalSection[10206]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10207]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10208]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10209]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["6d90d3d0792aed45:189"]="哈洛姆与卡德里斯带着邪恶的战狼开始战斗。这两位强大的黑暗萨满共享生命值，并会放置腐化图腾，在他们受到伤害的同时为其赋予不同的技能。"}}
D.ClientTexts.JournalSection[10210]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10211]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10212]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10232]={Name={["5702f7e04804f729:9"]="第15区"}}
D.ClientTexts.JournalSection[10213]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["9251ede8e7fa745b:228"]="纳兹戈林将军是一位强大的战士。他会使用不同技能攻击玩家来产生怒气，并周期性地使用消耗怒气的技能来进行强力的攻击。在整场战斗的过程中，由三种不同类型的库卡隆步兵组成的援军将协助将军作战。"}}
D.ClientTexts.JournalSection[10214]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10215]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10216]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10217]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["193b7ed2548cf2af:440"]="战斗开始时，马尔考罗克的平台被毒瘴所覆盖。毒瘴会吸收所有玩家进行的治疗，并转化成一个伤害吸收屏障。马尔考罗克会连续三次猛击地面，制造三个大型锥形区域，随后这三个区域会同时爆发出黑暗能量。\r\n\r\n马尔考罗克吸入毒瘴，进入血之怒状态，强化他的近战攻击，但在此阶段玩家可以正常治疗。随着马尔考罗克将毒瘴排出体外，战斗将进入新的循环，直至他被击败。"}}
D.ClientTexts.JournalSection[10218]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10219]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10220]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10221]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["aac138ba3ffde54d:303"]="与攻城匠师黑索的战斗将在一条武器组装线上进行。每次流水线启动后，都会有三个武器配件被运送出来。玩家需要使用附近的管道来跳上流水线，并摧毁其中一个配件。剩下的两个配件会被激活并攻击玩家，直至被流水线运走。"}}
D.ClientTexts.JournalSection[10222]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10223]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10224]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10225]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10226]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10227]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10228]={Name={["13f0c3c6f149e417:20"]="拜夜行尸"},Description={["114b61c25ed49b75:236"]="史诗难度中，拜夜行尸会徒劳地走向屠夫尝试最后一搏。行尸会在碰到屠夫或玩家时爆炸，留下一滩白鬼硫酸，一直持续到战斗结束。"}}
D.ClientTexts.JournalSection[10230]={Name={["daba90f6b8c564c7:9"]="白鬼炸弹"}}
D.ClientTexts.JournalSection[10231]={Name={["5702f7df4804f728:9"]="第14区"}}
D.ClientTexts.JournalSection[10233]={Name={["73cf3721427d5ad0:9"]="眩光"}}
D.ClientTexts.JournalSection[10234]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["bb6ef4af3fda7250:409"]="索克会在两种模式中切换。战斗开始时，他会越来越频繁地施放震耳尖啸，对全团造成严重伤害。当他感觉到有一群严重受伤的玩家集中在一起时，他会陷入血性狂乱，开始追逐随机玩家，并一口吞下任何挡路的玩家。在血性狂乱阶段，索克会跑得越来越快。玩家需要击败一名库卡隆狱卒并且释放一名囚犯来让索克吞下，随后索克会获得强化，但是血性狂乱阶段也随之结束。"}}
D.ClientTexts.JournalSection[10235]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10236]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10237]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10238]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["4606e852db40b4f9:97"]="高尔山站在台座顶端，偶尔还会在战斗中召唤能量导管来为自己提供防护。"}}
D.ClientTexts.JournalSection[10239]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10240]={Name={["4e3d4d159f733c7e:18"]="折铁者高尔山"}}
D.ClientTexts.JournalSection[10241]={Name={["7152878894c7aab9:12"]="能量导管"}}
D.ClientTexts.JournalSection[10242]={Name={["ee4ffa8fc7a0765c:12"]="钢剑"}}
D.ClientTexts.JournalSection[10243]={Name={["d747a05681512055:12"]="刃片新星"}}
D.ClientTexts.JournalSection[10244]={Name={["2b4da74ae6c41047:14"]="磁石尖刺"}}
D.ClientTexts.JournalSection[10245]={Name={["b45768637a266c34:16"]="雷霆贯耳"}}
D.ClientTexts.JournalSection[10246]={Name={["114179d92924d8dc:13"]="电磁脉冲"}}
D.ClientTexts.JournalSection[10247]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10248]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10249]={Name={["fab2eca4d25011a5:11"]="岩石吐息"}}
D.ClientTexts.JournalSection[10250]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["2c3bc50150540d50:269"]="战斗开始时，会有三名卡拉克西英杰与玩家作战，其他六名英杰会暂时留在上方平台观察战斗。每当有一名英杰被击败，另外两名英杰的生命值都会回满，与此同时会有一名新的英杰加入战斗。玩家需要击败全部九名英杰来结束战斗。"}}
D.ClientTexts.JournalSection[10251]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10252]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10253]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10254]={Name={["edd9cb15f7834068:13"]="抡锤猛击"}}
D.ClientTexts.JournalSection[10255]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["19a6a343b1838830:134"]="奇拉克开战时左右两侧会各有一头畸形龙兽，他还会用多种毒物和炼金制品来强化盟友，消灭敌人。"}}
D.ClientTexts.JournalSection[10411]={Name={["22ef0c20e1a8695f:17"]="活力之水"}}
D.ClientTexts.JournalSection[10256]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10257]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10258]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10260]={Name={["0fd389c79a085f6e:5"]="奇拉克"}}
D.ClientTexts.JournalSection[10262]={Name={["a798d23c616be3e3:19"]="畸形龙人"}}
D.ClientTexts.JournalSection[10263]={Name={["09eda62769108572:14"]="巨兽扫击"}}
D.ClientTexts.JournalSection[10264]={Name={["e5bf5db7b8f72680:20"]="衰弱桎梏"}}
D.ClientTexts.JournalSection[10265]={Name={["d45827a33d2b402a:17"]="恢复药水"}}
D.ClientTexts.JournalSection[10266]={Name={["a16f6f51f0782b4a:14"]="邪血药水"}}
D.ClientTexts.JournalSection[10267]={Name={["1233081bd805663c:8"]="爆发"}}
D.ClientTexts.JournalSection[10268]={Name={["7c7439fb67a74958:8"]="新方案！"}}
D.ClientTexts.JournalSection[10269]={Name={["325d4fa091d280a9:18"]="怒不可遏"}}
D.ClientTexts.JournalSection[10270]={Name={["849488fca67aa499:17"]="毒气药膏"}}
D.ClientTexts.JournalSection[10271]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["58d5283248ba4cd5:171"]="在派出数波低级随从后，萨贝克指挥官会骑着残暴的双头飞龙——铁钩碎天兽进行俯冲。一旦双头飞龙遭到重创，萨贝克就会解散坐骑，并开始地面攻击。"}}
D.ClientTexts.JournalSection[10272]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10273]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10274]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10276]={Name={["391a8bc15ad78b10:31"]="萨贝克，铁军指挥官"}}
D.ClientTexts.JournalSection[10277]={Name={["a8653e5b59060246:7"]="铁斧"}}
D.ClientTexts.JournalSection[10278]={Name={["52c6178200c4f61d:10"]="钢铁掠夺者"}}
D.ClientTexts.JournalSection[10279]={Name={["9c5c129120ce3a30:13"]="灌魔铁斧"}}
D.ClientTexts.JournalSection[10281]={Name={["c8ba0050604a6d9f:17"]="铁钩碎天兽"},Description={["92f828484d12b73b:35"]="指挥官萨贝克凶狠残暴的双头飞龙坐骑。"}}
D.ClientTexts.JournalSection[10282]={Name={["f0796c56d1cb011f:18"]="致燃之息"}}
D.ClientTexts.JournalSection[10283]={Name={["b515fafcf6630835:8"]="钢铁之怒"}}
D.ClientTexts.JournalSection[10284]={Name={["f4f7c51a70cdb043:11"]="毒害喷吐"}}
D.ClientTexts.JournalSection[10285]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["248ce72b62e70246:179"]="怒翼会从黑石塔深处一跃而起，伏击窄桥上的玩家。她的主要攻击方式是烈焰吐息和烈焰冲击，可一旦遭到重创，她就会落下来和敌人进行面对面的交战。"}}
D.ClientTexts.JournalSection[10286]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10287]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10288]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10289]={Name={["d37f2d59510fa1d8:8"]="怒翼"}}
D.ClientTexts.JournalSection[10290]={Name={["28a3ecaa203c6987:13"]="噬体火焰"}}
D.ClientTexts.JournalSection[10291]={Name={["0e1752682285456f:9"]="熔岩喷吐"}}
D.ClientTexts.JournalSection[10292]={Name={["e500f665061c454a:11"]="撕裂之爪"}}
D.ClientTexts.JournalSection[10293]={Name={["7e1c7c00ec844873:9"]="火焰风暴"}}
D.ClientTexts.JournalSection[10294]={Name={["d031b3b9013232c0:11"]="燃烧之怒"}}
D.ClientTexts.JournalSection[10307]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["bf3eb95b0f6915ec:195"]="扎伊拉开始会和玩家进行地面交战，可一旦遭受重创便会撤到始祖幼龙身上，并飞行一段时间。在接下来的战斗中，玩家小队必须同时对付扎伊拉和那些俯冲并喷吐烈焰的始祖幼龙。"}}
D.ClientTexts.JournalSection[10412]={Name={["06aba2eedc1ce401:10"]="潮汐涌动"}}
D.ClientTexts.JournalSection[10308]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10309]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[10310]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[10312]={Name={["52f44fcdd50cc750:31"]="扎伊拉，龙喉氏族督军"}}
D.ClientTexts.JournalSection[10313]={Name={["f12e77f926e1f75e:16"]="毁灭重击"}}
D.ClientTexts.JournalSection[10314]={Name={["6dab4eca53c7fae1:15"]="回旋之刃"}}
D.ClientTexts.JournalSection[10315]={Name={["535093c753ee5f20:16"]="黑铁旋风"}}
D.ClientTexts.JournalSection[10316]={Name={["9e25a0ee1c81a45b:20"]="烬鳞铁翼龙"},Description={["73bcf1bc79c86497:75"]="在战斗的后期阶段，这些始祖幼龙会俯冲并灼烧整个作战区域。"}}
D.ClientTexts.JournalSection[10317]={Name={["7f4d8210471f4b53:13"]="灼热吐息"}}
D.ClientTexts.JournalSection[10318]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
