D.ClientTexts.JournalSection[10323]={Name={["1407c12283ba41d9:9"]="熔渣冲击"}}
D.ClientTexts.JournalSection[10324]={Name={["fd7cbb46b10b8cdd:6"]="锁定"},Description={["f9f66a4e11764ed1:67"]="熔渣元素会锁定一个随机目标，并集中使用法术攻击该目标。"}}
D.ClientTexts.JournalSection[10325]={Name={["e08cbfc9f7d7f30c:11"]="护盾消失"},Description={["debc9faa204b4583:76"]="元素尊者的减伤护盾效果消失后十分脆弱。"}}
D.ClientTexts.JournalSection[10326]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[10327]={Name={["3c1991e950918c9e:7"]="治疗者"}}
