D.ClientTexts.JournalSection[10330]={Name={["bb35241d1c642bc8:9"]="热能冲击"}}
D.ClientTexts.JournalSection[10331]={Name={["40e7452491083429:10"]="火枪射击"}}
D.ClientTexts.JournalSection[10332]={Name={["a6087a9f8169cb7a:13"]="黑石突击队火炮"}}
D.ClientTexts.JournalSection[10335]={Name={["e0925887a84be9ea:16"]="黑石手雷"}}
