D.ClientTexts.JournalSection[10340]={Name={["d917d79c0485e8ad:11"]="奥术之伤"}}
D.ClientTexts.JournalSection[10341]={Name={["2d52106dbc987c3a:10"]="奥术重击"}}
D.ClientTexts.JournalSection[10343]={Name={["d6e7907c8b688e03:12"]="窒息灰烬"}}
D.ClientTexts.JournalSection[10344]={Name={["ad06dadfbc664566:14"]="榴弹火炮"}}
D.ClientTexts.JournalSection[10345]={Name={["32539d5527fa294a:14"]="炮弹"}}
D.ClientTexts.JournalSection[10346]={Name={["44488b0ed7c3326d:13"]="灼烧光环"}}
D.ClientTexts.JournalSection[10347]={Name={["ca1f99b64f39e953:16"]="防御削弱"}}
D.ClientTexts.JournalSection[10348]={Name={["ca1f99b64f39e953:16"]="防御削弱"}}
D.ClientTexts.JournalSection[10404]={Name={["3933dfae2cfba6e1:14"]="热血咆哮"},Description={["bbae0cec9eb31579:137"]="观众的满意程度将通过热血咆哮来体现。随着观众满意程度的提高，整个团队都将获得众望所归效果，全员造成的伤害都会提高。"}}
D.ClientTexts.JournalSection[10405]={Name={["5b810a5c11785ad9:8"]="综述"}}
