D.ClientTexts.JournalSection[10676]={Name={["0d4450d5ee8f43c2:8"]="激动"},Description={["1c6d60715e61d09e:259"]="当汉斯加尔或弗兰佐克受到伤害时，他们的怒气值也会持续增长。\r\n\r\n随着怒气值的增长，激动效果也会得到加强，提高其造成的近战伤害，增加碎颅者丢出的飞锤数，缩短干扰怒吼的施法时间，并通过跳跺获得更多次的跳跃。"}}
D.ClientTexts.JournalSection[10677]={Name={["5702f8224806f7a7:9"]="第35区"}}
D.ClientTexts.JournalSection[10678]={Name={["3cc55be10791c214:15"]="邪脉深渊魔"},Description={["cd697a5c96aa3605:69"]="这些邪能生物会锁定一个目标，并进行无情地追击。"}}
D.ClientTexts.JournalSection[10679]={Name={["6eec655fe9a46c40:14"]="困兽犹斗"},Description={["6d93f9e2fd192bc9:198"]="卡加斯会用锁链投掷将团队成员甩到竞技场看台上去。一旦到了看台上，团队成员就可以攻击观众了，直到悬槌扫荡者再将他们打下看台，或是把他们的尸体丢回竞技场中去。"}}
D.ClientTexts.JournalSection[10680]={Name={["5702f8224806f7a7:9"]="第35区"}}
D.ClientTexts.JournalSection[10681]={Name={["5702f8244806f7a9:9"]="第37区"}}
