D.ClientTexts.JournalSection[10854]={Name={["e26ff30e864daea1:18"]="炮击模式"},Description={["c5edf6c136e9152c:155"]="一位女武神用舰上的主炮向码头射出一片弹幕。\r\n\r\n在发射出第一片弹幕后，主炮向码头发起又一轮规模更大的狂轰滥炸。"}}
