D.ClientTexts.JournalSection[10740]={Name={["ab429459ec18dc20:13"]="怒翼雏龙"},Description={["56544622b45c2caf:70"]="当生命值降到70%时，怒翼会召唤出一大群雏龙来攻击玩家的队伍。"}}
D.ClientTexts.JournalSection[10741]={Name={["1ea80eb2086d30dd:19"]="黑铁龙骑兵"},Description={["c62ba188f24e5a35:114"]="当扎伊拉的生命值降到60%时，她会撤到附近一个始祖幼龙的背上，此时龙骑兵也会下来攻击玩家的队伍。"}}
D.ClientTexts.JournalSection[10742]={Name={["cadccd4a57286bdb:13"]="穿刺投掷"}}
