D.ClientTexts.JournalSection[10800]={Name={["b966eb1b4ffaf458:17"]="第一阶段：破坏"},Description={["d4bca06e743dcaad:81"]="玩家必须关闭爆裂熔炉两侧的温度调节器才能将其关闭。"}}
D.ClientTexts.JournalSection[10801]={Name={["b4a2db5a75a4afff:24"]="第二阶段：脱困"},Description={["8d1d564a2c904b43:141"]="山脉之心逃出了爆裂熔炉！为了阻止山脉之心毁灭一切，元素尊者加入了战斗。"}}
D.ClientTexts.JournalSection[10802]={Name={["5b79abce0c7150e5:19"]="第三阶段：自由！"},Description={["c6114cf7849b73bc:86"]="击败所有元素尊者后，山脉之心将攻击见到的所有生物。"}}
D.ClientTexts.JournalSection[10803]={Name={["99f6ebd0f8d85685:13"]="保安"}}
