D.ClientTexts.JournalSection[10811]={Name={["7d340d7028c17c4f:12"]="饥饿的狼"},Description={["0f548c30961cd5f3:63"]="被释放后，狼群中每一头饥饿的狼都将锁定一个不同的目标。"}}
D.ClientTexts.JournalSection[10812]={Name={["5dcddc3d306942c6:14"]="双头恐惧飞龙"},Description={["a2651de022e2ada5:77"]="被释放后，恐惧飞龙将飞上天空，并用酸液喷射攻击敌人。"}}
