D.ClientTexts.JournalSection[11006]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["5d12f4b7f18d1dea:444"]="血魔吞噬受到致命伤害的玩家灵魂。被吞噬的玩家将进入血魔的胃里，血魔的胃里充斥着被禁锢的幽魂。这些幽魂会不断试图逃到外部世界，攻击玩家团队。在血魔胃中的玩家可以伤害这些幽魂，在其逃离之前削弱或者击败它们。 \r\n\r\n每个成功逃脱或者被杀死的幽魂都会降低血魔的能量。当血魔的能量降低至0时，他会开始施放灵魂盛宴，重新储存灵魂能量，并重新开始攻击。"}}
