D.ClientTexts.JournalSection[11091]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["20f7055d918af1ee:366"]="扎昆会轮流使用战斧和双拳攻击，在切换过程中，他的技能也会发生变化。在战斗中，扎昆会试图生成邪能水晶，但玩家可以自己吸收能量以阻止其得逞。无论出现何种结果，扎昆的部分技能在击中水晶或吸收了潜伏能量的玩家时，都会触发大爆炸。"}}
D.ClientTexts.JournalSection[11092]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[11093]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
