D.ClientTexts.JournalSection[11095]={Name={["0f1aa94eaaaaa79b:5"]="武装"},Description={["e99b6c4a7efabb23:117"]="战斗开始时扎昆会装备斧头。这个阶段扎昆会缓慢挥舞他的斧头，对单个目标造成近战伤害。"}}
D.ClientTexts.JournalSection[11096]={Name={["00f948442ab41fad:8"]="邪能横扫"}}
D.ClientTexts.JournalSection[11098]={Name={["41a9918bae131f82:8"]="玷污"}}
D.ClientTexts.JournalSection[11102]={Name={["b42185f0fc88860b:13"]="邪能爆破"}}
D.ClientTexts.JournalSection[11103]={Name={["02e7836bbb34c972:9"]="邪能喷泉"},Description={["448f90b58de868a2:99"]="在其他裂隙都被吸收后，最后一条轰鸣的裂隙将立即转化为邪能水晶。"}}
D.ClientTexts.JournalSection[11104]={Name={["4a424bfeaa56ae09:10"]="邪能水晶"}}
D.ClientTexts.JournalSection[11105]={Name={["045a44ed31086f4a:11"]="邪恶之触"}}
D.ClientTexts.JournalSection[11106]={Name={["945f1980af3d03f7:12"]="全副武装"}}
D.ClientTexts.JournalSection[11107]={Name={["fb7ec137d7471ef6:6"]="激怒"}}
D.ClientTexts.JournalSection[11110]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["d540a2d2af2f7a51:126"]="考莫克会周期性跳进最近的邪能能量之池，并根据他跳入的池子在短时间内强化它的某一项技能。"}}
