D.ClientTexts.JournalSection[11124]={Name={["56163826451e00d9:14"]="变异仇恨"},Description={["a679be91beacefb6:152"]="考莫克会根据上一次跳入的能量之池的类型而对当前坦克使用不同的技能。被这些技能命中之后还会造成邪能之触的效果。"}}
