D.ClientTexts.JournalSection[11280]={Name={["47dc19f12f3513e8:13"]="邪能腐蚀"},Description={["5da64adc6d3303fb:182"]="在整场战斗中，整个团队都会受到邪能腐蚀的影响。邪能腐蚀叠加越多，目标受到的伤害就越高。\r\n\r\n在邪能腐蚀达到100时，目标会被燃烧军团控制。"}}
