D.ClientTexts.JournalSection[11376]={Name={["c8a7f589f8dba13e:16"]="阴暗构造体"},Description={["1ac1123e2a2f893f:96"]="这些扭曲的灵魂残渣移动到血魔的胃部中央位置时会被释放到外部世界，并获得强化。"}}
D.ClientTexts.JournalSection[11377]={Name={["3f2d2884a77b3ff7:15"]="苦痛精华"},Description={["b437214056fecce1:171"]="意志被血魔束缚的德莱尼灵魂。这个灵魂移动到胃部的中央时会受到彻底的腐蚀并且被释放到外部世界。治疗这个灵魂直到其生命值全满，帮助它摆脱血魔的掌控。"}}
