D.ClientTexts.JournalSection[11401]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["88e27c216e2843a0:582"]="玩家需要在抵挡攻城大师玛塔克及其军队的同时，调转堡垒庭院内的巨型地狱火炮以轰击坚固的堡垒大门。\r\n\r\n在这场战斗中，敌人会源源不断地向玩家冲锋。每隔一段时间，敌方还会派出一台巨型攻城武器来摧毁火炮以及保护它的玩家。摧毁攻城武器会掉落邪火弹药。玩家可以将弹药搬运至地狱火炮，使其向强化地狱火之门持续发射地狱火炮弹。\r\n\r\n一旦玩家成功攻破强化地狱火之门，攻城大师玛塔克的部队将退回堡垒中。"}}
D.ClientTexts.JournalSection[11402]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[11403]={Name={["3c1991e950918c9e:7"]="治疗者"}}
