D.ClientTexts.JournalSection[11407]={Name={["9424b647db80d5d2:11"]="钢铁龙骑兵"},Description={["fb772c3db7128eaa:87"]="这些难缠的敌人挥舞着锐利的长柄武器，对攻城大师玛塔克唯命是从。"}}
