D.ClientTexts.JournalSection[11442]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["94f247b0f1f1f605:457"]="战斗开始后，索克雷萨会控制缚魂构装体。\r\n\r\n当玩家将缚魂构装体的生命值降至0后，索克雷萨的灵魂会被构装体弹出，与此同时一名玩家可以控制构装体。此时萨格雷士兵将涌入大厅，随索克雷萨的灵魂一起试图重夺构装体的控制权。当玩家控制的构装体生命值降低至0后，玩家将被弹出，索克雷萨会再次控制构装体，重新开始战斗循环。\r\n\r\n玩家必须消灭索克雷萨的灵魂才能结束战斗。"}}
