D.ClientTexts.JournalSection[11506]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["d7c017c443b20687:326"]="暗影领主艾斯卡利用幻象迷惑团队成员，附近的安苏之眼正是看穿这些虚假扭曲的鸦人伎俩的关键。玩家可通过和团队成员传递安苏之眼，来应对艾斯卡和他的爪牙的特殊攻击。\r\n\r\n艾斯卡会周期性地飞上天空，并引导一股强劲的邪能光束；同时其爪牙也会俯冲攻击地面目标。"}}
D.ClientTexts.JournalSection[11507]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[11508]={Name={["3c1991e950918c9e:7"]="治疗者"}}
