D.ClientTexts.JournalSection[11534]={Name={["0d835991433ad208:12"]="他的最后一搏"},Description={["291a5f7f2c921b7c:157"]="生命值降至30%时，朱倍尔索斯会开始施放邪恶打击。在本体死亡后，朱倍尔索斯的镜像会继续骚扰玩家，从暗影中攻击他们。"}}
D.ClientTexts.JournalSection[11536]={Name={["f405f36cf780d9c5:12"]="她的最后一搏"},Description={["ccfa98fb3cc51cee:155"]="生命值降至30%时，迪亚·暗语会被黑暗吞噬，使用死灵印记影响剩余的一半敌人。彻底陷入疯狂之后，她不再使用暗影收割。"}}
D.ClientTexts.JournalSection[11537]={Name={["0d835991433ad208:12"]="他的最后一搏"},Description={["084cd65fc01f1362:80"]="生命值降至30%时，古尔图格会开始施放污血，直至他被击败。"}}
D.ClientTexts.JournalSection[11538]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["513489f42fa5d5f7:122"]="每名议会成员都有一种特殊技能，只会在生命值低于30%时使用。这些效果会一直持续到战斗结束。"}}
