D.ClientTexts.JournalSection[11544]={Name={["d201edbc0fb95d45:15"]="噬魂者"},Description={["a20bacf3c3c011f6:225"]="被击败的玩家并不会立即被杀死。血魔会将他们的灵魂吞进胃里消化。最近被血魔吞噬过的玩家会受到血魔的腐化效果，如果他们再次死亡则会失去自己的灵魂。"}}
D.ClientTexts.JournalSection[11545]={Name={["5702f8054805f76c:9"]="第29区"}}
D.ClientTexts.JournalSection[11546]={Name={["5702f81d4806f7a2:9"]="第30区"}}
D.ClientTexts.JournalSection[11547]={Name={["f63ab740b3c09e5f:13"]="腐化的灵魂"},Description={["4d51d8ee76fb4c2b:223"]="当玩家被血魔杀死后，他们灵魂的碎片被留在了血魔的体内并且受到了严重的腐化，变成了一个邪恶的，吞噬生命的怪物。只有摧毁这个灵魂的碎片才能释放被血魔吞噬的玩家。"}}
