D.ClientTexts.JournalSection[11599]={Name={["2396ae6b27dbccca:28"]="第三阶段：扭曲虚空"},Description={["525819cf019c9a96:86"]="当阿克蒙德的生命值降低至40%时，他会召唤扭曲虚空的力量来摧毁他的敌人。"}}
D.ClientTexts.JournalSection[11600]={Name={["cc70f3f2d00d86b9:22"]="恶魔法术：混乱之雨"},Description={["5ed7829e62229bd1:80"]="当阿克蒙德的生命值降低至25%时，他会召唤巨大的陨石来摧毁德拉诺。"}}
