D.ClientTexts.JournalSection[11680]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["d697974218cb56e7:483"]="祖霍拉克的房间中盘踞着两座传送门：一座的能量来自虚空，另一座的则来自燃烧军团的邪能魔法。祖霍拉克会首先激活邪能传送门，获得邪能技能并召唤第一批小鬼以及先锋阿基里奥。\r\n\r\n在阿基里奥被击败后，祖霍拉克将激活虚空传送们，获得虚空技能并召唤不稳定的空灵魔和奥姆努斯。\r\n\r\n一旦奥姆努斯被击败，祖霍拉克将获得邪能及虚空能量，并在这两大元素间快速切换。在生命值降至20%时，他会完全吸收两座传送门的能量。此时，玩家必须迅速将其击败。"}}
