D.ClientTexts.JournalSection[11701]={Name={["aa46dfd017ac11c9:17"]="能量迸发"},Description={["3f6e335fd83e9fea:149"]="在战斗中，祖霍拉克将狂野的邪能及虚空能量聚集到他的召唤大厅中，使它们失控暴走，并将它们混合产生致命后果。"}}
