D.ClientTexts.JournalSection[11719]={Name={["e707c7b48d738a29:12"]="活体暗影"},Description={["14519ed39e8208a2:139"]="活体暗影周期性地从虚空传送门中涌出并攻击玩家。\r\n\r\n传送门中每出现一个活体暗影，它们的涌入速度都会加快。"}}
D.ClientTexts.JournalSection[11720]={Name={["5702f8624808f823:9"]="第53区"}}
