D.ClientTexts.JournalSection[11738]={Name={["b406819378e7f5ce:25"]="第一阶段：军团的烈焰"},Description={["9f93aa17568db2ec:86"]="祖霍拉克已被邪能污染，他会召唤燃烧军团的爪牙，并使用邪能魔法攻击。"}}
D.ClientTexts.JournalSection[11739]={Name={["0e117b926507fb87:23"]="第二阶段：虚空之握"},Description={["8450151fadab86ec:102"]="祖霍拉克开启虚空传送门，召唤其他虚空生物并从虚空中抽取力量。"}}
D.ClientTexts.JournalSection[11740]={Name={["ee97de31e314f08a:22"]="第四阶段：撕裂"},Description={["77c4406cfd9c3f9f:134"]="祖霍拉克完全吸收了虚空和邪能传送门的力量，阻止更多生物涌入，并迅速失控。"}}
D.ClientTexts.JournalSection[11741]={Name={["5702f8224806f7a7:9"]="第35区"}}
