D.ClientTexts.JournalSection[11838]={Name={["f8d33f798aeffd8a:17"]="毁灭之力"},Description={["9fb900168671c095:87"]="邪能领主的部分技能在击中具有潜伏能量的玩家时会触发爆炸。"}}
D.ClientTexts.JournalSection[11839]={Name={["a249b6615a152206:19"]="裂隙与水晶"},Description={["c618afd5f34c7938:116"]="扎昆在附近地面上制造出轰鸣的裂隙。如果没有人站在裂隙上将其吸收，则会生成邪能水晶。"}}
