D.ClientTexts.JournalSection[11846]={Name={["3e1723cde50d0370:14"]="地狱火炮"},Description={["b6a9e85810c5cc97:291"]="在战斗开始时，玩家可使用两门地狱火炮。攻城大师玛塔克的部队将源源不断地从地狱火堡垒中涌出，阻挠玩家使用这两门火炮。\r\n\r\n地狱火炮将使用储备的邪火弹药持续轰击强化地狱火之门。"}}
