D.ClientTexts.JournalSection[12044]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["78ecfd868e79f923:234"]="赫娅受到启迪者奥米尔和索斯坦的加护，具体的加护取决于她所靠近的秘法师。在她受到加护时，她会获得一系列对应的技能，并会随着时间而强化。将赫娅移出其中一个秘法师的范围将会使对应的加护慢慢减弱。"}}
