D.ClientTexts.JournalSection[12067]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["aa4bb9c60188211d:212"]="提拉宋以血精灵形态开始战斗，但会在战斗中途变形为两种恶魔形态的其中之一，并获得新的技能。提拉宋每周会选择不一样的恶魔形态。"}}
