D.ClientTexts.JournalSection[12075]={Name={["bd1914770db607a6:15"]="恶魔形态：浩劫"},Description={["43e2c7a18c1cf8a0:129"]="提拉宋变身为浩劫恶魔。他使用新能力将他的怒火汇聚成一道邪能光束，并周期性地对整个队伍造成献祭伤害。"}}
D.ClientTexts.JournalSection[12077]={Name={["5702f7dc4804f725:9"]="第11区"}}
D.ClientTexts.JournalSection[12080]={Name={["a9a211522e04e741:19"]="恶魔形态：复仇"},Description={["0e2630c0e9f0123d:149"]="提拉宋变身为复仇恶魔。他会丢出战刃，战刃会以邪能锁链相连并在整个战斗区域内飞行。此外，狂怒冲击会被邪能岩弹所替代。"}}
