D.ClientTexts.JournalSection[12386]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["2f806a55796b8bc4:268"]="格雷泽会在两种状态间转换。在第一个状态下，他会跟随玩家，并生成能量区域干扰玩家的走位。在第二个状态下，他会传送到房间中央，并引导猛烈的能量光束，直到玩家用附近的透镜让光束折射，击中他脆弱的背部。"}}
D.ClientTexts.JournalSection[12423]={Name={["326fab1a77ffffe7:18"]="元素共鸣"},Description={["8465c06d902b4db2:104"]="艾萨拉之怒拥有强大的魔法能量，在使用魔法打击敌人时会留下后续效果。"}}
