D.ClientTexts.JournalSection[12498]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["7d0bc4a10002012a:321"]="当顾问拉图修斯传送到区域里以黑暗魔法进行攻击时，拉文凯斯会与玩家开战。一旦拉文凯斯的生命值降至20%，拉图修斯会现出他的真面目：恐惧魔王丹塔利纳克斯。拉文凯斯的视线不再受到蒙蔽，他会召唤先祖的灵魂强化玩家，从而击败丹塔利纳克斯并将军团彻底逐出黑鸦堡垒。"}}
