D.ClientTexts.JournalSection[12664]={Name={["0f7356456dd77958:5"]="聚焦"},Description={["fdaf173048f974d1:210"]="格雷泽将视线汇聚成一道光束，追踪一名随机玩家。如果引导这道光束击中格雷泽的背部，可以将其击昏，并使其在昏迷期间受到额外的伤害。\r\n\r\n当格雷泽汇聚光束时，整个房间会周期性地受到辐射的影响。"}}
D.ClientTexts.JournalSection[12665]={Name={["0f601eb0cc4f6567:5"]="余烬"},Description={["8c5398d6803d324f:87"]="余烬会随机选择目标。如果余烬经过熔岩，就会获得热量吸收效果，提高它的伤害。"}}
D.ClientTexts.JournalSection[12666]={Name={["5702f7dc4804f725:9"]="第11区"}}
D.ClientTexts.JournalSection[12667]={Name={["5702f7dd4804f726:9"]="第12区"}}
D.ClientTexts.JournalSection[12668]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["f908f5c5c2e17912:154"]="审判官托蒙托鲁姆会吸收玩家的能量并随机打开牢房。这些牢笼会释放出额外的敌人，玩家必须处理这些敌人，以免被敌人的攻势淹没。"}}
D.ClientTexts.JournalSection[12669]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[12670]={Name={["3c1991e950918c9e:7"]="治疗者"}}
