D.ClientTexts.JournalSection[12675]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["92dcfe4ef18ea54b:133"]="阿努贝斯特会攻击玩家并且召唤各种甲虫来助战。玩家必须迅速清理他的爪牙，以免被虫群淹没。"}}
