D.ClientTexts.JournalSection[12684]={Name={["09d6822938b81b00:16"]="迅猛甲虫"},Description={["71ed6393368f6cc8:169"]="在英雄难度下，迅猛甲虫会在战斗中潜地并锁定附近的玩家。当它们接触到玩家或者死亡时会爆炸，产生一个起泡软泥池。"}}
D.ClientTexts.JournalSection[12685]={Name={["5702f7dc4804f725:9"]="第11区"}}
D.ClientTexts.JournalSection[12686]={Name={["d6b00f9d4bff1a54:16"]="气体爆炸"},Description={["5833419f95470a2c:109"]="气体泡泡爆炸时，会对所有敌人造成冰霜伤害，伤害量相当于气泡剩余的可吸收伤害量。"}}
