D.ClientTexts.JournalSection[12870]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["4d1ffadd99cf81f2:145"]="邪能领主贝图格会周期性地使玩家飞到紫罗兰监狱的边缘，并选中一个玩家进行处决。必须解救处决的目标，否则该玩家将会死亡。"}}
D.ClientTexts.JournalSection[12871]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[12872]={Name={["3c1991e950918c9e:7"]="治疗者"}}
