D.ClientTexts.JournalSection[12880]={Name={["bbb19b05f91da51e:11"]="打开牢房"},Description={["661538af4cc07258:53"]="审判官会在战斗期间打开数个牢房。"}}
D.ClientTexts.JournalSection[12881]={Name={["abe6681d3b4c610c:16"]="牢房3-3x468"}}
D.ClientTexts.JournalSection[12882]={Name={["7c9120a8afe10a61:19"]="恶魔卫士歼灭者"},Description={["fcef9c1ecc886c21:73"]="清除威胁值并向随机的敌人冲锋，造成大量的物理伤害。"}}
D.ClientTexts.JournalSection[12883]={Name={["9a047a1ab0ceb885:20"]="影月技师"},Description={["f565adbe28bc0187:91"]="随机对敌人投掷炸弹，并在地上埋设地雷。此外，还会周期性地沉默一个随机的施法者。"}}
D.ClientTexts.JournalSection[12884]={Name={["d55f261776ad0912:17"]="影月术士"},Description={["7058057738a2496a:51"]="强化恶魔同伴，大幅提高其造成的伤害。"}}
D.ClientTexts.JournalSection[12885]={Name={["183149908944e5e3:19"]="牢房3-4x8-5x02"}}
D.ClientTexts.JournalSection[12888]={Name={["3ff77e7057b3a3bb:21"]="魔古山藏秘者"},Description={["7d9ea3c4a42afbf1:29"]="缓慢地将所有敌人变成石头。"}}
D.ClientTexts.JournalSection[12889]={Name={["5702f7fc4805f763:9"]="第20区"}}
D.ClientTexts.JournalSection[12890]={Name={["5702f7fd4805f764:9"]="第21区"}}
D.ClientTexts.JournalSection[12891]={Name={["5702f7fe4805f765:9"]="第22区"}}
D.ClientTexts.JournalSection[12892]={Name={["63412a8c24e8b06b:19"]="牢房3-0x68-1x0"}}
D.ClientTexts.JournalSection[12893]={Name={["7ef1eb7fc34f8976:18"]="无面虚空法师"},Description={["f5c1e3690b1d24b0:57"]="周期性地对随机敌人的位置发射暗影冲撞。"}}
D.ClientTexts.JournalSection[12894]={Name={["4583201ba707dfce:24"]="虚空暴君"},Description={["1864d8730bed5780:60"]="向前方发动顺劈斩，周期性地使附近所有敌人恐惧。"}}
D.ClientTexts.JournalSection[12895]={Name={["7569a2aac3550005:18"]="疯狂的夺心者"},Description={["1e5c8ba2f2719ab7:85"]="对随机敌人及其10码内的所有目标造成大量暗影伤害。"}}
D.ClientTexts.JournalSection[12896]={Name={["abd43e10f563c307:16"]="牢房3-2x024"}}
D.ClientTexts.JournalSection[12897]={Name={["2e4ef0198d2f439a:19"]="纠缠腐蚀"},Description={["5e091a77d0ebeb14:78"]="死亡时对随机敌人施加一道光环，在持续时间结束后爆炸。"}}
D.ClientTexts.JournalSection[12898]={Name={["0fe6ebf49a6ee029:19"]="巨型石魁麟"},Description={["1c42f5ef6146aa64:47"]="对目标造成大量物理伤害。"}}
D.ClientTexts.JournalSection[12899]={Name={["5702f7ff4805f766:9"]="第23区"}}
D.ClientTexts.JournalSection[12900]={Name={["5702f8004805f767:9"]="第24区"}}
