D.ClientTexts.JournalSection[12905]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["ac1f537ac2ebe0dd:244"]="玩家在断桥的位置与克洛苏斯交战。在战斗过程中，克洛苏斯会不断毁坏桥梁，迫使玩家的可行动范围逐渐缩小。如果克洛苏斯没有被及时击败，玩家将失去立足之地，最后坠入大海而丧命。"}}
D.ClientTexts.JournalSection[12906]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[12907]={Name={["3c1991e950918c9e:7"]="治疗者"}}
