D.ClientTexts.JournalSection[12932]={Name={["1ad34413543d19ea:7"]="技能"}}
D.ClientTexts.JournalSection[12933]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["57757ae58be6343e:179"]="塔丽克萨和她的邪能契约通过力量与火焰执行古尔丹的意志。每个恶魔使徒的存在都会强化其他的使徒。最好的策略是想办法把他们分开。"}}
D.ClientTexts.JournalSection[12934]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
D.ClientTexts.JournalSection[12935]={Name={["3c1991e950918c9e:7"]="治疗者"}}
D.ClientTexts.JournalSection[12936]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[12937]={Name={["a39cfafa0643cf61:11"]="邪能契约"}}
D.ClientTexts.JournalSection[12938]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["2d23676f5f6fb128:98"]="麦兰杜斯会用各种剑招让敌人寸步难行，配合高超的魔法，展现出令人生畏的战斗力。"}}
D.ClientTexts.JournalSection[12939]={Name={["63470d24fac96deb:13"]="伤害输出者"}}
