D.ClientTexts.JournalSection[12955]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["80bb0ec41247263d:209"]="在整场战斗中，时间的流逝速度会不断变化。这些变化会对玩家的移动和技能产生一定影响。时空畸体对时间的流逝极其敏感，其技能可能会受到剧烈影响。"}}
D.ClientTexts.JournalSection[12956]={Name={["10692d869ec5e909:5"]="坦克"}}
D.ClientTexts.JournalSection[12957]={Name={["3c1991e950918c9e:7"]="治疗者"}}
