D.ClientTexts.JournalSection[12969]={Name={["c21b460f17731472:8"]="梦境之中"},Description={["718bd771c4af873a:308"]="在萨维斯达到95%和60%的生命值时，伊瑟拉之梦会让一半的队员进入梦境之中。受到影响的玩家会陷入沉睡，但他们的梦境幻影会继续对抗萨维斯。梦境幻影消亡时，玩家的真身就会苏醒。玩家清醒后，会清除梦境幻影积累的所有梦魇腐蚀。"}}
D.ClientTexts.JournalSection[12970]={Name={["3f4dc199d9ec9d9a:19"]="梦魇腐蚀"},Description={["0e7af13f37ce494e:206"]="萨维斯的许多法术会在命中目标时对其传播梦魇腐蚀。玩家的腐蚀值越高，就越容易被梦魇控制。任何玩家如果被彻底腐蚀，萨维斯就可以控制他们。"}}
D.ClientTexts.JournalSection[12971]={Name={["97240da166f1c62c:30"]="第一阶段：坠入疯狂"}}
