D.ClientTexts.JournalSection[13015]={Name={["74741fddfe9ac000:8"]="清扫器"},Description={["54cba4e262f37561:264"]="这些小型奥术清扫器几乎坚不可摧，可以用来清理垃圾。它们很喜欢毒性薄片，但那些薄片可以立即摧毁清扫器。如果周围没有薄片，它们也会清扫奥术渗流池。清理时清扫器会获得能量。如果清扫器的能量达到最大值，就会产生爆炸。"}}
D.ClientTexts.JournalSection[13016]={Name={["5702f7e34804f72c:9"]="第18区"}}
