D.ClientTexts.JournalSection[13022]={Name={["74555dec40596bf1:18"]="衰减时间粒子"},Description={["81019f0e01027e6f:148"]="扭曲暗夜井里的时间结构，对区域内的所有玩家造成伤害。死亡时会留下一个时光裂隙并分裂成破碎时间粒子。"}}
D.ClientTexts.JournalSection[13023]={Name={["5702f7df4804f728:9"]="第14区"}}
D.ClientTexts.JournalSection[13025]={Name={["5b810a5c11785ad9:8"]="综述"},Description={["d74e65cdf38c025e:261"]="占星师艾塔乌斯在他自己修建的观星台中战斗。在90%、60%和30%剩余生命值时，他会启动他的观星台，把整个团队发射出去，穿越虚空，俯瞰不同的世界，虹吸这些世界的能量，从而用不同的方式强化他的技能。"}}
